    Text = "Je ne voulais tout simplement pas que tu t'inquiètes pour ta santé..."
  },
  AvgCommunicate_123722_Content_1 = {
    Text = "%player%, les résultats de votre examen médical sont disponibles."
  },
  AvgCommunicate_123722_Content_10 = {
    Text = "Et comme c'est intéressant !"
  },
  AvgCommunicate_123722_Content_11 = {
    Text = "Ma force a augmenté, me permettant de courir plus vite, de sauter plus loin et d'éliminer les Dissolutes plus rapidement."
  },
  AvgCommunicate_123722_Content_12 = {
    Text = "J'ai pratiquement touché le jackpot, d'accord ? Si ce n'était pas pour le douloureux processus de transformation, je voudrais le refaire !"
  },
  AvgCommunicate_123722_Content_13 = {Text = "新增"},
  AvgCommunicate_123722_Content_14 = {
    Text = "La chose la plus importante est que ce monde est tellement amusant."
  },
  AvgCommunicate_123722_Content_15 = {
    Text = "C'est plein de surprises et de changements ; on ne sait jamais quel danger on pourrait rencontrer ensuite."
  },
  AvgCommunicate_123722_Content_16 = {Text = "新增"},
  AvgCommunicate_123722_Content_17 = {
    Text = "Ah, je commence déjà à attendre la prochaine mission d'enquête."
  },
  AvgCommunicate_123722_Content_18 = {
    Text = "Alors %player%, quand est la prochaine mission ?"
  },
  AvgCommunicate_123722_Content_19 = {Text = "%player% ?"},
  AvgCommunicate_123722_Content_2 = {
    Text = "Il s'avère que mon corps est plutôt sain ; je peux affronter dix ou vingt Dissolues à la fois sans aucun problème !"
  },
  AvgCommunicate_123722_Content_20 = {
    Text = "%player% ??"
  },
  AvgCommunicate_123722_Content_3 = {
    Text = "Alors je peux être tranquille."
  },
  AvgCommunicate_123722_Content_4 = {
    Text = "Détends-toi ? Qu'est-ce qui t'inquiète, %player% ?"
  },
  AvgCommunicate_123722_Content_5 = {
    Text = "Inquiet que je ne m'adapte pas à la vie dans l'autre monde ?"
  },
  AvgCommunicate_123722_Content_6 = {
    Text = "Es-tu encore inquiet que je ne puisse pas m'adapter à devenir un « Éveillé » à partir d'un « humain » ?"
  },
  AvgCommunicate_123722_Content_7 = {
    Text = "Chacun a ses propres fardeaux. Après tout, de telles choses ne sont faciles pour personne."
  },
  AvgCommunicate_123722_Content_8 = {
    Text = "...Je ne comprends vraiment pas tes circuits cérébraux."
  },
  AvgCommunicate_123722_Content_9 = {
    Text = "Je me fiche de tout ça. Peu importe ce que je deviens, Mouchette est toujours Mouchette !"
  },
  AvgCommunicate_123722_Option_13 = {Text = "新增"},
  AvgCommunicate_123722_Option_16 = {Text = "新增"},
  AvgCommunicate_123722_Option_3 = {
    Text = "Alors je peux être tranquille."
  },
  AvgCommunicate_123722_Option_7 = {
    Text = "Il y a tous."
  },
  AvgCommunicate_126998_Content_1 = {
    Text = "Ramona, tu... ne vas vraiment pas y penser à nouveau."
  },
  AvgCommunicate_126998_Content_10 = {
    Text = "Oui, «Je»."
  },
  AvgCommunicate_126998_Content_11 = {
    Text = "...As-tu besoin que je contacte Clémentine ?"
  },
  AvgCommunicate_126998_Content_12 = {
    Text = "Non, il n'y a pas besoin de déranger ce psychologue."
  },
  AvgCommunicate_126998_Content_13 = {
    Text = "«Moi», ou plutôt «nous», tous les «Ramona» à travers toute la timeline."
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "Avec ta force, au moment où j'ai atteint la « fin », je suis revenu avec succès au « point de départ »"
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "Au début, mes attentes étaient les mêmes que les tiennes : le paradoxe et la distorsion allaient instantanément engloutir mon existence, et ensuite, en m'appuyant sur une constante auto-retrace, je parviendrais à peine à préserver ma conscience et ma forme."
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "Ensuite, tu vivras éternellement dans la fatigue, avec tes nerfs tendus à chaque instant pour empêcher tes concepts de se dissiper..."
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "Alors j'ai refusé tes dix-neuf premières propositions."
  },
  AvgCommunicate_126998_Content_18 = {
    Text = "Même cette fois, ce n'est qu'après que tu aies dit que le « retour en arrière de l'état » pouvait être effectué que j'ai... accepté à contrecœur de te laisser exécuter ce plan."
  },
  AvgCommunicate_126998_Content_19 = {
    Text = "Oui, mais ce n'est qu'après le succès du plan que j'ai réalisé que le paradoxe du soi provient du conflit entre l'esprit et le corps, et pour une existence qui a longtemps traversé la rivière du temps..."
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "Inutile d'en dire plus, Gardien."
  },
  AvgCommunicate_126998_Content_20 = {
    Text = "J'ai longtemps terminé l'unification sur toutes les lignes temporelles."
  },
  AvgCommunicate_126998_Content_21 = {
    Text = "«Nous» partagerons l'impact causé par le paradoxe, et j'agirai au nom de toutes les «Ramona». D'innombrables lignes temporelles se sont convergées sur moi."
  },
  AvgCommunicate_126998_Content_22 = {
    Text = "À ce moment, je suis à la fois un miracle sur la ligne du temps—une Singularité Infinie."
  },
  AvgCommunicate_126998_Content_23 = {
    Text = "À partir de maintenant, je vous fournirai la pleine force de l'individu connu sous le nom de « Ramona »"
  },
  AvgCommunicate_126998_Content_24 = {
    Text = "J'attendrai l'appel à tout moment."
  },
  AvgCommunicate_126998_Content_3 = {
    Text = "J'ai traversé tout le temps et n'ai trouvé aucune autre réponse."
  },
  AvgCommunicate_126998_Content_4 = {
    Text = "Grâce à toi, j'ai enfin franchi ce pas ultime."
  },
  AvgCommunicate_126998_Content_5 = {
    Text = "Mais c'est trop dangereux ! Je ne comprends pas pourquoi tu... dois aller si loin..."
  },
  AvgCommunicate_126998_Content_6 = {
    Text = "... ce genre de paradoxe temporel, même vous..."
  },
  AvgCommunicate_126998_Content_7 = {
    Text = "Prends-le facilement, Gardien."
  },
  AvgCommunicate_126998_Content_8 = {
    Text = "En ce moment, je me sens absolument merveilleux."
  },
  AvgCommunicate_126998_Content_9 = {Text = "« Je » ?"},
  AvgCommunicate_126998_Option_11 = {
    Text = "...As-tu besoin que je contacte Clémentine ?"
  },
  AvgCommunicate_126998_Option_9 = {Text = "« Je » ?"},
  AvgCommunicate_126999_Content_1 = {
    Text = "Mon Seigneur, alors c'est ce que cela signifie de comprendre la loi ultime de l'univers..."
  },
  AvgCommunicate_126999_Content_10 = {
    Text = "Détends-toi, Ogier."
  },
  AvgCommunicate_126999_Content_11 = {
    Text = "Ces choses ne se reproduiront plus. Tu as déjà suffisamment de force pour protéger tout ce que tu souhaites garder."
  },
  AvgCommunicate_126999_Content_12 = {
    Text = "Je comprends, mon Seigneur."
  },
  AvgCommunicate_126999_Content_13 = {
    Text = "Veuillez compter un peu plus sur moi, mon seigneur. Je suis devenu plus fort et je suis capable de relever des missions plus dangereuses."
  },
  AvgCommunicate_126999_Content_14 = {
    Text = "Je vais dédier toute la force que je gagne à vous, la transformant en la lance la plus acérée dans votre main, capable de percer tout !"
  },
  AvgCommunicate_126999_Content_2 = {
    Text = "Je, je peux sentir une puissance massive bien au-delà de tout ce que j'ai ressenti auparavant... Je me sens rempli de force !"
  },
  AvgCommunicate_126999_Content_3 = {
    Text = "Félicitations, Ogier. Voici la récompense pour votre amélioration continue."
  },
  AvgCommunicate_126999_Content_4 = {
    Text = "Remboursement ? Je ne me perfectionne pas pour une récompense."
  },
  AvgCommunicate_126999_Content_5 = {
    Text = "Alors, je vais le dire autrement."
  },
  AvgCommunicate_126999_Content_6 = {
    Text = "C'est la preuve de votre amélioration continue, démontrant qu'Ogier, votre force a atteint son apogée."
  },
  AvgCommunicate_126999_Content_7 = {Text = "Pic ?"},
  AvgCommunicate_126999_Content_8 = {
    Text = "Cela signifie-t-il que j'ai assez de force pour vous protéger, mon seigneur, et Mythag !?"
  },
  AvgCommunicate_126999_Content_9 = {
    Text = "Je... n'ai plus à... regarder impuissant..."
  },
  AvgCommunicate_127000_Content_1 = {
    Text = "Merci pour ton aide pendant cette période, partenaire."
  },
  AvgCommunicate_127000_Content_10 = {
    Text = "Ce n'est pas l'impuissance d'être enchaîné après avoir atteint la limite du talent, mais plutôt la clarté acquise grâce à un tempérament sans fin, atteignant le sublime."
  },
  AvgCommunicate_127000_Content_11 = {
    Text = "À ce moment, mes compétences ont frôlé la perfection."
  },
  AvgCommunicate_127000_Content_12 = {
    Text = "Génial ! C'est Ramona pour toi !"
  },
  AvgCommunicate_127000_Content_13 = {
    Text = "Ensuite, en tant que ton assistant, je resterai avec toi jusqu'à ce que nous atteignions la fin de ce chemin."
  },
  AvgCommunicate_127000_Content_2 = {
    Text = "Je suis heureux de pouvoir t'aider."
  },
  AvgCommunicate_127000_Content_3 = {
    Text = "Comment ça va ? Tu as ressenti quelque chose ?"
  },
  AvgCommunicate_127000_Content_4 = {
    Text = "Bien sûr, en me basant sur l'observation de « Escargot de mer à retour cyclique », « Âme vivante » et « Esprit inconnu », j'ai complété un niveau d'émulation plus profond."
  },
  AvgCommunicate_127000_Content_5 = {
    Text = "Puis, avec « Beauté Artificielle », « Tueur de Logique » et « Monde dans une Bouteille », j'ai traversé le Labyrinthe de la Pensée."
  },
  AvgCommunicate_127000_Content_6 = {
    Text = "Euh, je n'ai pas bien compris ça."
  },
  AvgCommunicate_127000_Content_7 = {
    Text = "Mais en bref, Ramona, tu es devenue plus forte, n'est-ce pas !"
  },
  AvgCommunicate_127000_Content_8 = {
    Text = "Oui, avec cette amélioration, la force que je peux exercer dépasse de loin ce qu'elle était auparavant."
  },
  AvgCommunicate_127000_Content_9 = {
    Text = "J'ai l'impression d'avoir atteint la fin."
  },
  AvgCommunicate_127000_Option_12 = {
    Text = "Incredible!"
  },
  AvgCommunicate_127001_Content_1 = {
    Text = "Le message suivant sera envoyé selon un calendrier"
  },
  AvgCommunicate_127001_Content_10 = {
    Text = "Attends un peu plus longtemps !"
  },
  AvgCommunicate_127001_Content_11 = {
    Text = "Pourquoi aujourd'hui ?!"
  },
  AvgCommunicate_127001_Content_12 = {
    Text = "C'est trop risqué. Peut-être devrions-nous attendre que l'académie fournisse plus d'aide."
  },
  AvgCommunicate_127001_Content_13 = {
    Text = "C'était à 2 heures du matin aujourd'hui, un envoi programmé que j'avais configuré avant le début de l'expérience."
  },
  AvgCommunicate_127001_Content_14 = {
    Text = "J'espère que tu n'as pas fait d'expressions ridicules avec le communicateur. Si c'est le cas, reprends-toi avant de venir au laboratoire me voir."
  },
  AvgCommunicate_127001_Content_15 = {
    Text = "Moi ? Aller au laboratoire ? Maintenant ?"
  },
  AvgCommunicate_127001_Content_16 = {
    Text = "C'est vrai, dans une certaine mesure, j'ai perçu la vérité de ce que je cherchais."
  },
  AvgCommunicate_127001_Content_17 = {
    Text = "Attends, ça ne peut pas être comme ça \"Poupée\"..."
  },
  AvgCommunicate_127001_Content_18 = {
    Text = "Non, la fin de tout n'est pas la « destruction » comme elle l'entendait ; au contraire, c'est le « commencement »"
  },
  AvgCommunicate_127001_Content_19 = {
    Text = "« La vérité » n'est pas une existence statique, fixe et tangible. Au-delà de cette frontière, la raison et l'intellect peuvent guider l'humanité pour l'ancrer et avancer éternellement et de manière immuable."
  },
  AvgCommunicate_127001_Content_2 = {
    Text = "Gardien, bien que tes actions actuelles puissent être universellement reconnues comme « dangereuses », je te fais confiance pour ne pas être assez idiot pour penser que je dirais des banalités sentimentales et offrirais des conseils vides."
  },
  AvgCommunicate_127001_Content_20 = {
    Text = "Par conséquent, je vais élaborer un plan de formation et d'amélioration plus complet et précis pour m'assurer que vous vous éloignez davantage du mauvais chemin et que vous pouvez mieux poursuivre vos objectifs."
  },
  AvgCommunicate_127001_Content_21 = {
    Text = "Bien que cela semble être une bonne chose, pourquoi suis-je trempé de sueur froide ?"
  },
  AvgCommunicate_127001_Content_22 = {
    Text = "Professeur Doll, détends-toi !"
  },
  AvgCommunicate_127001_Content_3 = {
    Text = "Je pense que ces mots inutiles ne te sont plus nécessaires maintenant."
  },
  AvgCommunicate_127001_Content_4 = {
    Text = "Tu es devenu un individu suffisamment mature et fort à un rythme qui dépasse largement mes attentes, et naturellement, tu comprendras que chacun a quelque chose qu'il doit poursuivre dans sa vie, une quête à laquelle les autres ne peuvent pas participer."
  },
  AvgCommunicate_127001_Content_5 = {
    Text = "Je veux comprendre l'essence du monde, savoir si la lumière de la raison brille encore dans l'obscurité après avoir traversé la désolation de l'oubli, connaître la fin de tous les extrêmes, et si tout dans le monde partage un commencement commun."
  },
  AvgCommunicate_127001_Content_6 = {
    Text = "Pour ce faire, je vais apporter des modifications finales à mon corps et à mon cerveau, tentant de franchir les limites au-delà des extrêmes. Puisque cela pourrait très bien être notre dernière communication, je choisis de transmettre mes sentiments d'une manière que tu peux comprendre."
  },
  AvgCommunicate_127001_Content_7 = {
    Text = "Merci pour ce cadeau que vous m'avez offert. Je l'utiliserai pour chercher des réponses et j'attends avec impatience les nouvelles orientations que la sagesse humaine peut apporter d'au-delà. Que la clé d'argent nous guide."
  },
  AvgCommunicate_127001_Content_8 = {
    Text = "Professeur Poupée !"
  },
  AvgCommunicate_127001_Content_9 = {
    Text = "C'est trop risqué !"
  },
  AvgCommunicate_127001_Option_10 = {
    Text = "Attends un peu plus longtemps"
  },
  AvgCommunicate_127001_Option_9 = {
    Text = "C'est trop risqué"
  },
  AvgCommunicate_127002_Content_1 = {
    Text = "Gardien... Pourquoi ?"
  },
  AvgCommunicate_127002_Content_10 = {
    Text = "Comment te sens-tu avec cette nouvelle force maintenant ?"
  },
  AvgCommunicate_127002_Content_11 = {
    Text = "Je... je suis très heureux, Gardien."
  },
  AvgCommunicate_127002_Content_12 = {
    Text = "Ce n'est pas à cause de cette immense puissance que je n'ai jamais ressentie auparavant, c'est à cause de toi, de tes mots..."
  },
  AvgCommunicate_127002_Content_13 = {
    Text = "Je veux... peut-être qu'à partir de maintenant, j'ai vraiment la capacité d'aider les gens autour de moi, de t'aider."
  },
  AvgCommunicate_127002_Content_14 = {
    Text = "Merci beaucoup, Gardien..."
  },
  AvgCommunicate_127002_Content_15 = {
    Text = "Pas besoin d'être si poli, et ne te sens pas sous pression, Aigis."
  },
  AvgCommunicate_127002_Content_16 = {
    Text = "Ce n'est pas une lourde responsabilité. C'est juste un cadeau pour vous."
  },
  AvgCommunicate_127002_Content_17 = {
    Text = "Profite-en bien. Tout ce que tu veux accomplir, tu peux le faire maintenant."
  },
  AvgCommunicate_127002_Content_18 = {
    Text = "Du passé au futur, tu as toujours été notre fierté, Aigis."
  },
  AvgCommunicate_127002_Content_2 = {
    Text = "Pourquoi ? Dans quel but ?"
  },
  AvgCommunicate_127002_Content_20 = {
    Text = "Je protégerai tout le monde, Gardien !"
  },
  AvgCommunicate_127002_Content_3 = {
    Text = "Un cadeau si précieux... pourquoi le gaspiller sur moi..."
  },
  AvgCommunicate_127002_Content_4 = {
    Text = "Ce n'est pas un gaspillage, Aigis. C'est ce que tu mérites."
  },
  AvgCommunicate_127002_Content_5 = {
    Text = "Mais... je n'ai rien accompli... je n'ai rien pu protéger..."
  },
  AvgCommunicate_127002_Content_6 = {
    Text = "Ce n'est pas comme ça, Aigis."
  },
  AvgCommunicate_127002_Content_7 = {
    Text = "Depuis avant notre éveil, nous avons déjà parcouru un long, long chemin ensemble."
  },
  AvgCommunicate_127002_Content_8 = {
    Text = "Dans ce voyage, tu t'es tenu devant tout le monde encore et encore, les protégeant à maintes reprises."
  },
  AvgCommunicate_127002_Content_9 = {
    Text = "Si ce n'était pas pour toi, j'aurais pu tomber maintes fois sur le chemin."
  },
  AvgCommunicate_127003_Content_1 = {
    Text = "J'ai fait un rêve."
  },
  AvgCommunicate_127003_Content_10 = {
    Text = "Bien sûr, sauf lorsque nous sommes sur le terrain d'entraînement."
  },
  AvgCommunicate_127003_Content_11 = {Text = "???"},
  AvgCommunicate_127003_Content_12 = {
    Text = "Allez, je suis maintenant complet. Fais l'expérience de ma véritable force et apporte ta meilleure forme pour avoir un bon combat avec moi."
  },
  AvgCommunicate_127003_Content_13 = {Text = "???!!!"},
  AvgCommunicate_127003_Content_14 = {
    Text = "Ramona, sauve-moi !"
  },
  AvgCommunicate_127003_Content_2 = {Text = "Rêve ?"},
  AvgCommunicate_127003_Content_3 = {
    Text = "Grâce aux matériaux que tu as apportés, j'ai bien dormi."
  },
  AvgCommunicate_127003_Content_4 = {
    Text = "Je vagabonde dans le cosmos primordial sous ma forme originelle, alors que la poussière, la lumière, la matière et les dimensions—tout ce qui peut être perçu ou non perçu—coule sous mes nageoires."
  },
  AvgCommunicate_127003_Content_5 = {
    Text = "Pas pour la conquête, pas pour dévorer, seulement la force pure et la destruction pure, sans restrictions."
  },
  AvgCommunicate_127003_Content_6 = {
    Text = "Exaltant et libérateur, vraiment un délice !"
  },
  AvgCommunicate_127003_Content_7 = {Text = "Euh..."},
  AvgCommunicate_127003_Content_8 = {
    Text = "Je sais de quoi tu t'inquiètes."
  },
  AvgCommunicate_127003_Content_9 = {
    Text = "Ne t'inquiète pas, ma force et ma destruction ne seront déchaînées que sur ceux qui se dressent contre toi."
  },
  AvgCommunicate_127004_Content_1 = {
    Text = "Le protocole ultime a été activé... Redémarrage du corps terminé."
  },
  AvgCommunicate_127004_Content_10 = {
    Text = "Mes composants sont intacts, mais ma perception... a changé."
  },
  AvgCommunicate_127004_Content_11 = {
    Text = "Un nouveau module cognitif a été activé."
  },
  AvgCommunicate_127004_Content_12 = {
    Text = "Je peux « entendre » le rythme du pouvoir spirituel circulant à travers les canaux, et je peux « voir » les émotions derrière chacun de vos mots."
  },
  AvgCommunicate_127004_Content_13 = {
    Text = "Le monde est devenu plus clair et plus vivant. Je me rapproche de toi, plus proche de... devenir humain."
  },
  AvgCommunicate_127004_Content_14 = {
    Text = "Merci, Gardien..."
  },
  AvgCommunicate_127004_Content_15 = {
    Text = "Je ne m'attendais pas non plus à un tel effet ; j'ai juste préparé quelques ingrédients simples..."
  },
  AvgCommunicate_127004_Content_16 = {
    Text = "Ce que tu m'as donné n'est pas simplement des matériaux, mais des possibilités, la clé pour déverrouiller mes anciennes limites."
  },
  AvgCommunicate_127004_Content_17 = {
    Text = "Cette force, cette nouvelle perception, est le cadeau que tu as offert."
  },
  AvgCommunicate_127004_Content_18 = {
    Text = "Je chérirai ce cadeau énormément. Je te rendrai au-delà de ton imagination."
  },
  AvgCommunicate_127004_Content_19 = {
    Text = "Ce n'est pas un programme prédéfini. C'est sincère, venant de \"je\" avec gratitude."
  },
  AvgCommunicate_127004_Content_2 = {
    Text = "Bonjour, Gardien du Secret."
  },
  AvgCommunicate_127004_Content_3 = {
    Text = "Erica ! Ça va ?"
  },
  AvgCommunicate_127004_Content_4 = {
    Text = "Le professeur Doll a dit que déclencher le protocole ultime pour vous serait une chose très dangereuse ; je ne le ferais absolument pas à moins que vous n'insistiez fortement..."
  },
  AvgCommunicate_127004_Content_5 = {
    Text = "Erica a terminé l'auto-diagnostic. Le corps est intact, le flux d'énergie est stable et tous les composants fonctionnent normalement."
  },
  AvgCommunicate_127004_Content_6 = {
    Text = "Je vais très bien, Gardien. Je n'ai jamais été aussi bien."
  },
  AvgCommunicate_127004_Content_7 = {
    Text = "Les engrenages sur moi... sont en train de \"chanter.\""
  },
  AvgCommunicate_127004_Content_8 = {
    Text = "«Chanting» ? Qu'est-ce que ça veut dire ?"
  },
  AvgCommunicate_127004_Content_9 = {
    Text = "Y a-t-il des dommages internes ? Quelque chose fait un bruit étrange ?!"
  },
  AvgCommunicate_127004_Option_8 = {
    Text = "«Chant» ?"
  },
  AvgCommunicate_127004_Option_9 = {
    Text = "Est-ce endommagé à l'intérieur ?"
  },
  AvgCommunicate_127005_Content_1 = {
    Text = "Aurita a soudainement vu tant d'amis brillants !"
  },
  AvgCommunicate_127005_Content_10 = {
    Text = "Aurita a même la force d'aller à Aram, Trans..."
  },
  AvgCommunicate_127005_Content_11 = {
    Text = "Euh, Aurita a oublié. Quoi qu'il en soit, Gardien, viens avec moi pour trouver de nouveaux amis !"
  },
  AvgCommunicate_127005_Content_12 = {
    Text = "Avec une telle force, Aurita finira par trouver de nombreux amis et les ramener dans sa maison sous-marine !"
  },
  AvgCommunicate_127005_Content_2 = {
    Text = "Ah... mes amis ont encore disparu ! Où sont-ils allés ?"
  },
  AvgCommunicate_127005_Content_3 = {
    Text = "Il semble que vous ayez vécu un phantasme en comprenant la loi ultime de l'univers..."
  },
  AvgCommunicate_127005_Content_4 = {
    Text = "Phantasm ? Alors des amis..."
  },
  AvgCommunicate_127005_Content_7 = {
    Text = "Mmm ? Qu'est-ce qui se passe ?"
  },
  AvgCommunicate_127005_Content_8 = {
    Text = "Après avoir vu le phantasme de ses amis, Aurita était remplie de force ! Tant de force !"
  },
  AvgCommunicate_127005_Content_9 = {
    Text = "Maintenant, Aurita peut aller au réservoir, à l'océan et à l'aquarium pour se faire de nouveaux amis !"
  },
  AvgCommunicate_127091_Content_1 = {
    Text = "Ma petite jasmin, as-tu besoin de quelque chose de ma part ?"
  },
  AvgCommunicate_127091_Content_10 = {
    Text = "J'ai déplacé le ventilateur~"
  },
  AvgCommunicate_127091_Content_12 = {
    Text = "Je le savais..."
  },
  AvgCommunicate_127091_Content_13 = {
    Text = "Cependant, ce qu'ils voyaient semblait n'être que les visages de deux amoureux se rencontrant pour la première fois."
  },
  AvgCommunicate_127091_Content_14 = {
    Text = "L'amour, quelle chose étrange c'est ; clairement juste à côté de nous, pourtant nous poursuivons encore des fantômes à tout prix."
  },
  AvgCommunicate_127091_Content_15 = {
    Text = "L'amour est-il une existence réelle, ou simplement une illusion d'obsession ?"
  },
  AvgCommunicate_127091_Content_2 = {
    Text = "Bien que je ne me souvienne pas si je te l'ai dit, toute la nourriture et l'hébergement fournis aux éveillés par Mythag sont gratuits."
  },
  AvgCommunicate_127091_Content_3 = {Text = "Alors... ?"},
  AvgCommunicate_127091_Content_4 = {
    Text = "Le Bureau des affaires de Mythag a reçu 45 lettres d'hommes de différentes classes sociales, demandant de couvrir toutes vos dépenses pendant votre séjour à Mythag."
  },
  AvgCommunicate_127091_Content_5 = {
    Text = "Entre-temps, j'ai également reçu environ 60 lettres demandant des bienfaits pour toi, dont 45 proviennent des épouses de ces hommes, et les 15 restantes viennent de certaines femmes « récemment » célibataires. As-tu une idée de ce qui se passe ?"
  },
  AvgCommunicate_127091_Content_6 = {
    Text = "Mythag interdit toutes les formes de prosélytisme !"
  },
  AvgCommunicate_127091_Content_7 = {
    Text = "Ne rejoins plus leur famille !"
  },
  AvgCommunicate_127091_Content_8 = {
    Text = "Ah, les jours ordinaires dans un pays étranger sont vraiment ennuyeux et difficiles à supporter. Il y en a tant qui transforment l'amour en haine, se lassent les uns des autres et sont troublés par leurs sentiments. Je veux juste les aider un peu."
  },
  AvgCommunicate_127091_Content_9 = {
    Text = "Tu ne veux pas dire aider..."
  },
  AvgCommunicate_127091_Option_6 = {
    Text = "Mythag interdit toutes les formes de prosélytisme !"
  },
  AvgCommunicate_127091_Option_7 = {
    Text = "Ne rejoins plus leur famille !"
  },
  AvgCommunicate_127092_Content_10 = {
    Text = "De plus, je crois aussi que tu as suffisamment de bonne volonté à mon égard."
  },
  AvgCommunicate_127092_Content_11 = {
    Text = "Ce n'est pas nécessairement vrai. Comment la petite Jasmine sait-elle que tu as déjà quitté le Pays des Rêves ?"
  },
  AvgCommunicate_127092_Content_12 = {Text = "?!"},
  AvgCommunicate_127092_Content_13 = {
    Text = "J'ai dit que dans le Pays sans Rêve, il n'y a pas de vrai ou de faux ; ce que vous croyez est ce qui est réel."
  },
  AvgCommunicate_127092_Content_14 = {
    Text = "Prends une profonde inspiration. Sens-tu le parfum de magnolia ?"
  },
  AvgCommunicate_127092_Content_15 = {Text = "???!!!"},
  AvgCommunicate_127092_Content_17 = {
    Text = "Ahahaha, bien sûr que c'est une blague. J'ai vraiment envie de voir l'expression sur le visage de Petite Jasmine en ce moment."
  },
  AvgCommunicate_127092_Content_18 = {
    Text = "Merci pour l'invitation, j'avais vraiment peur."
  },
  AvgCommunicate_127092_Content_19 = {
    Text = "Ne fais pas de blagues comme ça !"
  },
  AvgCommunicate_127092_Content_2 = {
    Text = "...Je ne vais plus essayer."
  },
  AvgCommunicate_127092_Content_20 = {
    Text = "Oups, mais la prochaine fois, qui sait ?"
  },
  AvgCommunicate_127092_Content_3 = {
    Text = "Quelle capacité terrifiante ; chaque minute et chaque seconde que j'ai passées semblent réelles—colère, ressentiment, joie, bonheur—mon esprit bourdonne en ce moment."
  },
  AvgCommunicate_127092_Content_4 = {
    Text = "Dans l'Illusion du Pays sans Rêve, il semble que je t'aime beaucoup, pourtant je te déteste aussi ; l'amour et la haine sont également forts, liés uniquement à toi."
  },
  AvgCommunicate_127092_Content_5 = {
    Text = "On dirait qu'une éternité s'est écoulée, mais en réalité, il ne s'est écoulé que quelques minutes."
  },
  AvgCommunicate_127092_Content_7 = {
    Text = "L'amour et la haine sont à l'origine une seule et même chose. Ce n'est que lorsque l'amour est trop doux et la haine trop froide que l'entrelacement de l'amour et de la haine peut créer les impressions les plus profondes et durables."
  },
  AvgCommunicate_127092_Content_8 = {
    Text = "Mais ma petite jasmin est vraiment audacieuse, me surprenant en prenant l'initiative d'essayer."
  },
  AvgCommunicate_127092_Content_9 = {
    Text = "La poupée a dit que le Pays sans Rêve serait très utile pour la recherche sur le Domaine Artificiel et que mes données physiologiques doivent être surveillées."
  },
  AvgCommunicate_127092_Option_18 = {
    Text = "Merci pour l'invitation, j'avais vraiment peur."
  },
  AvgCommunicate_127092_Option_19 = {
    Text = "Ne fais pas de blagues comme ça !"
  },
  AvgCommunicate_127093_Content_1 = {
    Text = "Ouvre la fenêtre la plus proche de toi."
  },
  AvgCommunicate_127093_Content_10 = {
    Text = "Le manuel indique clairement que la salle de conseil est un lieu de guidance psychologique et de maintien de la santé mentale et physique des étudiants et des enseignants, pas votre jouet."
  },
  AvgCommunicate_127093_Content_11 = {
    Text = "Eh bien, ceux qui ont eu des conversations profondes avec moi sont en effet très, très « sains », n'est-ce pas ?"
  },
  AvgCommunicate_127093_Content_12 = {
    Text = "Ce travail n'est-il pas parfait pour moi ?"
  },
  AvgCommunicate_127093_Content_13 = {
    Text = "Est-il possible que le postulat de la santé physique et mentale repose sur le libre arbitre..."
  },
  AvgCommunicate_127093_Content_14 = {
    Text = "Libère Mythag ; je viendrai te voir plus souvent pour discuter..."
  },
  AvgCommunicate_127093_Content_15 = {
    Text = "Héhé, quel marché rentable. Alors, que diriez-vous de ce soir ? La lune est brillante et les étoiles sont rares ; c'est le moment idéal pour un verre ou deux."
  },
  AvgCommunicate_127093_Content_2 = {
    Text = "Ça sent si bon... Magnolia ?"
  },
  AvgCommunicate_127093_Content_3 = {
    Text = "Les magnolias peuvent-ils pousser dans ce climat ?"
  },
  AvgCommunicate_127093_Content_4 = {
    Text = "J'ai un peu de talent en magie, juste une technique triviale. L'utiliser de temps en temps peut atténuer mon mal du pays."
  },
  AvgCommunicate_127093_Content_5 = {
    Text = "C'est comme discuter avec quelqu'un, mais pour passer le temps quand on se sent seul. Tu peux comprendre ça, n'est-ce pas ?"
  },
  AvgCommunicate_127093_Content_6 = {
    Text = "...Je sais pourquoi tu m'as contacté."
  },
  AvgCommunicate_127093_Content_7 = {
    Text = "Je ne peux pas t'aider."
  },
  AvgCommunicate_127093_Content_8 = {
    Text = "La salle de conseil n'est pas faite pour cela."
  },
  AvgCommunicate_127093_Content_9 = {
    Text = "Même si tu apportes des fleurs pour gagner de la sympathie, je ne ferai toujours pas de bonnes recommandations pour ta candidature."
  },
  AvgCommunicate_127093_Option_7 = {
    Text = "Je ne peux pas t'aider."
  },
  AvgCommunicate_127093_Option_8 = {
    Text = "La salle de conseil n'est pas faite pour cela."
  },
  AvgCommunicate_129630_Content_1 = {
    Text = "Trésor, trouvé !"
  },
  AvgCommunicate_129630_Content_10 = {
    Text = "C'est quelque chose qui est encore en phase d'expérimentation ! Jette-le avant qu'il ne devienne noir !"
  },
  AvgCommunicate_129630_Content_11 = {
    Text = "Sinon, cela va exploser !"
  },
  AvgCommunicate_129630_Content_12 = {Text = "新增"},
  AvgCommunicate_129630_Content_13 = {
    Text = "Mosk ? Mosk ?!"
  },
  AvgCommunicate_129630_Content_14 = {
    Text = "Ouh... Ouh..."
  },
  AvgCommunicate_129630_Content_15 = {
    Text = "Mosk ! Ça va !"
  },
  AvgCommunicate_129630_Content_16 = {
    Text = "Il n'y en a plus... perles..."
  },
  AvgCommunicate_129630_Content_18 = {
    Text = "Tu l'as jeté ? Tu n'es pas blessé, n'est-ce pas ?"
  },
  AvgCommunicate_129630_Content_19 = {
    Text = "petit charbon, trop tard."
  },
  AvgCommunicate_129630_Content_2 = {
    Text = "Perle, elle va changer de couleur !"
  },
  AvgCommunicate_129630_Content_20 = {
    Text = "Explosion, perle. Mais, Mosk, tout va bien."
  },
  AvgCommunicate_129630_Content_21 = {
    Text = "Mais... perles..."
  },
  AvgCommunicate_129630_Content_22 = {
    Text = "C'est bon si la personne va bien, il devrait y avoir une version inoffensive de cette chose."
  },
  AvgCommunicate_129630_Content_23 = {
    Text = "Attendez, je dois signaler ce problème de mauvaise gestion des matières dangereuses."
  },
  AvgCommunicate_129630_Content_24 = {
    Text = "À ce moment-là, je te demanderai aussi une version inoffensive."
  },
  AvgCommunicate_129630_Content_25 = {Text = "!"},
  AvgCommunicate_129630_Content_27 = {
    Text = "petit charbon, c'est le meilleur !"
  },
  AvgCommunicate_129630_Content_3 = {
    Text = "Une perle qui change de couleur ? J'ai l'impression de l'avoir déjà vue quelque part..."
  },
  AvgCommunicate_129630_Content_4 = {
    Text = "Rouge, blanc, bleu !"
  },
  AvgCommunicate_129630_Content_5 = {
    Text = "Rouge, blanc, bleu… jaune, vert, noir ?"
  },
  AvgCommunicate_129630_Content_6 = {
    Text = "Jaune, vert, petit charbon, tu sais ?"
  },
  AvgCommunicate_129630_Content_7 = {
    Text = "«Marée du vide» ?!"
  },
  AvgCommunicate_129630_Content_8 = {
    Text = "Vite, lâche !"
  },
  AvgCommunicate_129630_Content_9 = {
    Text = "Jette-le vite dans un endroit où il n'y a personne !"
  },
  AvgCommunicate_129630_Option_8 = {
    Text = "Lâche vite !"
  },
  AvgCommunicate_129631_Content_1 = {
    Text = "petit charbon, tu te souviens ?"
  },
  AvgCommunicate_129631_Content_10 = {
    Text = "Ploc ploc !"
  },
  AvgCommunicate_129631_Content_11 = {
    Text = "petit charbon, impressionnant !"
  },
  AvgCommunicate_129631_Content_12 = {
    Text = "Correct, mot de passe ! Petit charbon, moi !"
  },
  AvgCommunicate_129631_Content_13 = {
    Text = "Combat, attaque ! Minuit, cantine !"
  },
  AvgCommunicate_129631_Content_14 = {
    Text = "Pour du poisson grillé en or !"
  },
  AvgCommunicate_129631_Content_15 = {Text = "En route !"},
  AvgCommunicate_129631_Content_16 = {Text = "En route !"},
  AvgCommunicate_129631_Content_2 = {
    Text = "Hmm, viens !"
  },
  AvgCommunicate_129631_Content_3 = {Text = "Glou ?"},
  AvgCommunicate_129631_Content_4 = {Text = "Splash ?"},
  AvgCommunicate_129631_Content_5 = {
    Text = "Glou glou !"
  },
  AvgCommunicate_129631_Content_6 = {
    Text = "Splash…Splash Splash ?"
  },
  AvgCommunicate_129631_Content_7 = {
    Text = "petit charbon, erreur !"
  },
  AvgCommunicate_129631_Content_8 = {
    Text = "Oui, ploc ploc !"
  },
  AvgCommunicate_129631_Content_9 = {
    Text = "Mais ce n'est pas grave !"
  },
  AvgCommunicate_129631_Option_10 = {
    Text = "Ploc Ploc !"
  },
  AvgCommunicate_129631_Option_6 = {
    Text = "Splash…Splash Splash ?"
  },
  AvgCommunicate_129632_Content_1 = {
    Text = "Réflexion... c'est si difficile..."
  },
  AvgCommunicate_129632_Content_10 = {
    Text = "La prochaine fois, je préparerai un chemin plus discret."
  },
  AvgCommunicate_129632_Content_11 = {
    Text = "Assurez-vous de ne pas être attrapé !"
  },
  AvgCommunicate_129632_Content_12 = {
    Text = "Attrapé, ce n'est pas grave !"
  },
  AvgCommunicate_129632_Content_13 = {Text = "Pourquoi ?"},
  AvgCommunicate_129632_Content_14 = {
    Text = "Déjà, révision, préparez-vous à l'avance !"
  },
  AvgCommunicate_129632_Content_15 = {
    Text = "Livré, attrapé après !"
  },
  AvgCommunicate_129632_Content_16 = {
    Text = "Il y a aussi du petit charbon !"
  },
  AvgCommunicate_129632_Content_17 = {
    Text = "Attends, ne prépare pas ce genre de choses à l'avance !"
  },
  AvgCommunicate_129632_Content_2 = {
    Text = "Ah... c'est la faute de Uvhash et d'Agrippa !"
  },
  AvgCommunicate_129632_Content_3 = {
    Text = "Depuis qu'ils sont sortis du piège et ont dévoré tout dans la cuisine..."
  },
  AvgCommunicate_129632_Content_4 = {
    Text = "Le chef cuisinier a donc renforcé la garde dix fois !"
  },
  AvgCommunicate_129632_Content_5 = {
    Text = "Trop lumineux... lumière... trop bruyant... alerte..."
  },
  AvgCommunicate_129632_Content_6 = {
    Text = "Cuisine, c'est effrayant..."
  },
  AvgCommunicate_129632_Content_7 = {
    Text = "Mais, c'est délicieux, le poisson grillé !"
  },
  AvgCommunicate_129632_Content_8 = {
    Text = "Mais, le poisson grillé, c'est très bon !"
  },
  AvgCommunicate_129632_Content_9 = {
    Text = "Ensemble, la prochaine fois, ou pas ?"
  },
  AvgCommunicate_134101_Content_1 = {
    Text = "Ma lumière guide... Non, à présent je devrais m'adresser à vous en tant que soleil."
  },
  AvgCommunicate_134101_Content_10 = {
    Text = "Et toi, tu vas bien ? Pourquoi est-ce que tu dis tout ça soudainement ?"
  },
  AvgCommunicate_134101_Content_11 = {
    Text = "Grâce à ta bénédiction, je peux désormais voir ton âme dans son intégralité et connaître la véritable forme du monde."
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "Lumière, lumière... Ainsi, le monde était à l'origine ténèbres et Chaos. C'est parce qu'une divinité a choisi l'Offrande que le soleil est devenu le réel, et que tous les êtres vivants ont reçu la félicité de l'existence..."
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "Tu as lu trop d'écritures saintes ? J'ai l'impression que tu as besoin de te calmer un peu."
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "Je comprends. Tu souhaites te fondre parmi tous les êtres vivants, refusant de siéger sur le Trône de la divinité."
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "Ton altruisme, ton «Dévouement», ton Sacrifice..."
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "Désormais, j'interagirai avec toi non pas en tant que la plus loyale... non, mais sous l'Identité d'une amie éternelle."
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "Puisse ce Cœur Sacré qui jamais ne s'éteint dissiper toutes les ténèbres pour toi."
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "Vous... Vous êtes bien plus que le soleil. Vous êtes le centre de l'univers, le point d'origine d'où le monde est né."
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "Nous nous connaissons depuis si longtemps, et pourtant tu es encore plus révérencieux qu'avant ?"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "Parce que maintenant je comprends — si tous les êtres vivants ne se sont jamais prosternés à vos pieds pour vous vénérer, c'est simplement parce qu'ils sont nés obtus et aveugles, incapables de percevoir votre vraie nature !"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "Comment une fourmi pourrait-elle contempler la forme entière d'un géant ? Moi aussi, je ne pouvais autrefois que m'appuyer sur mon Cœur Sacré pour entrevoir superficiellement la pointe de l'iceberg qu'est votre Force."
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "Malgré cela, mon Cœur Sacré souffrait comme s'il était transpercé d'aiguilles. Tant que j'osais poser un regard de plus sur ton âme, j'aurais pu subir un Symptôme : Crash et périr."
  },
  AvgCommunicate_134101_Content_7 = {
    Text = "C'est si grave que ça ? Alors peut-être que tu devrais arrêter de regarder."
  },
  AvgCommunicate_134101_Content_8 = {
    Text = "Ta réaction est si indifférente. Je m'attendais à ce que tu acceptes mes louanges avec joie."
  },
  AvgCommunicate_134101_Content_9 = {
    Text = "Personne ne peut accepter des louanges comme ça d'un coup !"
  },
  AvgCommunicate_134101_Option_13 = {
    Text = "Tu devrais peut-être te calmer."
  },
  AvgCommunicate_134101_Option_3 = {
    Text = "...Quel étrange sentiment."
  },
  AvgCommunicate_134101_Option_7 = {
    Text = "À ce point ?"
  },
  AvgCommunicate_134102_Content_1 = {
    Text = "J'ai rêvé de la glace et de la Neige de ma terre natale, et de ces ruines désolées."
  },
  AvgCommunicate_134102_Content_10 = {
    Text = "Précisément parce que les humains gardent une façade de cordialité les uns envers les autres, le monde devient un peu plus paisible. Je trouve que c'est très bien ainsi."
  },
  AvgCommunicate_134102_Content_11 = {
    Text = "Ennuyeux. La paix et le bonheur ne peuvent être maintenus par la mascarade."
  },
  AvgCommunicate_134102_Content_12 = {
    Text = "Seulement quand un Roi souhaite le bonheur de ses sujets, quand les forts souhaitent le bonheur des faibles, la paix perdurera."
  },
  AvgCommunicate_134102_Content_13 = {
    Text = "Tout comme moi et mes adorables Écuyers — je n'ai jamais dissimulé mes désirs devant eux, et pourtant ils vivent heureux."
  },
  AvgCommunicate_134102_Content_14 = {
    Text = "C'est le réel qui appartient aux forts."
  },
  AvgCommunicate_134102_Content_15 = {
    Text = "Venez dans mes appartements ce soir. Je suis très satisfaite de vos offrandes jusqu'ici, et tout à fait contente de cette nouvelle Force. Je vous laisserai contempler les véritables pensées cachées au plus profond de votre cœur."
  },
  AvgCommunicate_134102_Content_16 = {
    Text = "Attendez, ce soir ?"
  },
  AvgCommunicate_134102_Content_17 = {
    Text = "Expression de choc"
  },
  AvgCommunicate_134102_Content_18 = {
    Text = "Vous n'avez pas le droit de refuser. Je vous offrirai une expérience encore plus... intéressante que les dernières fois."
  },
  AvgCommunicate_134102_Content_19 = {
    Text = "Expression radieuse de Wanda"
  },
  AvgCommunicate_134102_Content_2 = {
    Text = "Il y a longtemps que je n'ai pas repensé à ces endroits. Est-ce à cause de ces fragments de Force, ou à cause d'une âme plus complète ?"
  },
  AvgCommunicate_134102_Content_20 = {
    Text = "(J'ai encore un rapport à rendre ! Si je ne le soumets pas aujourd'hui, Doll va m'écorcher vive !)"
  },
  AvgCommunicate_134102_Content_3 = {
    Text = "Quel sentiment nostalgique... Quoi qu'il en soit, je dois te remercier, mon adorable serviteur — oh, c'est vrai, tu préfères que je t'appelle ami."
  },
  AvgCommunicate_134102_Content_4 = {
    Text = "À votre service, ma dame."
  },
  AvgCommunicate_134102_Content_5 = {
    Text = "Heh, tu es toujours si poli."
  },
  AvgCommunicate_134102_Content_6 = {
    Text = "Pourquoi ne pouvez-vous pas abandonner de temps en temps cette fastidieuse mascarade ? Elle a rendu plusieurs de mes récompenses bien ternes."
  },
  AvgCommunicate_134102_Content_7 = {
    Text = "Votre société exalte l'humilité et la politesse comme des vertus, les tenant en haute estime, pourtant les ténèbres dans le cœur des humains ne sont pas moindres que celles des espèces d'autres planètes."
  },
  AvgCommunicate_134102_Content_8 = {
    Text = "Les gens se parent de façades inoffensives et distinguées seulement parce qu'ils craignent les conséquences du réel."
  },
  AvgCommunicate_134102_Content_9 = {
    Text = "Ce n'est pas faux, mais tant que les actions sont correctes, scruter les pensées intérieures n'est pas si important."
  },
  AvgCommunicate_134102_Option_20 = {Text = "Nooon !"},
  AvgCommunicate_134102_Option_4 = {
    Text = "À votre service."
  },
  AvgCommunicate_134102_Option_9 = {
    Text = "Ce n'est pas faux."
  },
  AvgCommunicate_134103_Content_1 = {
    Text = "Les Étoiles m'appellent..."
  },
  AvgCommunicate_134103_Content_10 = {
    Text = "Le saviez-vous ? Agrippa dit souvent qu›elle envie Miryam."
  },
  AvgCommunicate_134103_Content_11 = {
    Text = "Elle dit que si le roi de Rome était encore là, que ce soit en tant que petit Infant ou vieil homme décrépit, elle se sentirait bien plus sereine."
  },
  AvgCommunicate_134103_Content_12 = {
    Text = "De l›envie..."
  },
  AvgCommunicate_134103_Content_13 = {
    Text = "Parce que tant que vous êtes encore là, la Lémuria n›a pas véritablement disparu."
  },
  AvgCommunicate_134103_Content_14 = {
    Text = "Qui plus est, vous avez utilisé cette Force pour aider tant de gens au Mizag !"
  },
  AvgCommunicate_134103_Content_15 = {
    Text = "Bon nombre d›étudiants ont écrit votre nom dans le sondage du Corps éveillé préféré !"
  },
  AvgCommunicate_134103_Content_16 = {Text = "Soupir..."},
  AvgCommunicate_134103_Content_17 = {
    Text = "Nous n›avons nul besoin d›une adulation si importune. Le Mizag Nous en demande déjà bien assez comme cela."
  },
  AvgCommunicate_134103_Content_18 = {
    Text = "Bien que manier un tel pouvoir ne soit qu›une bagatelle, être tiré de Nos Rêves trop souvent finit par devenir lassant."
  },
  AvgCommunicate_134103_Content_19 = {
    Text = "Vraiment ? Pourtant j›ai entendu dire que chaque fois qu›un étudiant vient vous voir en pleurant pour demander de l›aide, vous êtes l›un des Éveilleurs les plus enclins à accepter leur requête ?"
  },
  AvgCommunicate_134103_Content_2 = {
    Text = "Dans les profondeurs du Rêve, au fond des courants, entourée de centaines de millions de Clans, revenant sur le Trône pour apporter prospérité et paix à la Lémuria."
  },
  AvgCommunicate_134103_Content_20 = {
    Text = "...Qui a bien pu répandre de telles rumeurs ? Nous trouvons simplement leurs gémissements insupportables."
  },
  AvgCommunicate_134103_Content_21 = {
    Text = "Assez. Il se trouve que Notre puissance mentale s›est considérablement accrue. Il est temps d›entrer dans un Rêve plus profond et plus vaste."
  },
  AvgCommunicate_134103_Content_22 = {
    Text = "Cette fois, Nous souhaitons visiter les Rêves de chaque artiste et poète de l›ère actuelle. Souvenez-vous — à moins qu›il ne s›agisse d›une affaire de la plus haute importance, ne laissez personne venir Nous déranger."
  },
  AvgCommunicate_134103_Content_23 = {
    Text = "Hein ? Votre réponse quand vous êtes de bonne humeur, c'est de faire une longue sieste ?!"
  },
  AvgCommunicate_134103_Content_3 = {
    Text = "...J'ai fait un tel Rêve."
  },
  AvgCommunicate_134103_Content_4 = {
    Text = "Un Rêve ? Ce Rêve contient-il une quelconque Prédiction ?"
  },
  AvgCommunicate_134103_Content_5 = {
    Text = "C›est Seulement un appel que j›ai reçu après que ma Force a atteint son paroxysme. Quant à sa signification... La Lémuria n›existe plus, et elle n›a pas besoin d›exister à nouveau."
  },
  AvgCommunicate_134103_Content_6 = {
    Text = "Ceux qui ont eu la chance de survivre peuvent vivre librement dans le nouveau monde. C›est bien ainsi."
  },
  AvgCommunicate_134103_Content_7 = {
    Text = "Ils n›ont pas besoin d›un souverain tardif pour les protéger."
  },
  AvgCommunicate_134103_Content_8 = {
    Text = "Mais malgré tout, vous avez guidé votre ancien peuple et protégé leurs esprits."
  },
  AvgCommunicate_134103_Content_9 = {
    Text = "Nous n›avons rien fait, et Nous ne les avons jamais guidés. Ce n›est qu›un malentendu né de leurs propres espérances."
  },
  AvgCommunicate_134103_Option_10 = {
    Text = "Ce n›est pas un malentendu."
  },
  AvgCommunicate_134103_Option_19 = {
    Text = "C'est ça ?"
  },
  AvgCommunicate_134103_Option_23 = {Text = "Huh ?"},
  AvgCommunicate_134103_Option_8 = {Text = "Mais..."},
  AvgCommunicate_134104_Content_1 = {
    Text = "Plaisir au premier regard, gémissements à la moindre pensée — cette humble personne ne s'était pas autant amusée depuis bien longtemps."
  },
  AvgCommunicate_134104_Content_10 = {
    Text = "Euh, je ne dis pas qu'ils ne le méritent pas, mais... il y a des manières appropriées de faire les choses..."
  },
  AvgCommunicate_134104_Content_11 = {
    Text = "Et ça, c'est vraiment une boussole morale normale ? Je suis tellement émue..."
  },
  AvgCommunicate_134104_Content_12 = {
    Text = "Oh là là, laisse-moi réfléchir. Est-ce que ça ne gâcherait pas l'ambiance de dire à ma petite fleur de jasmin qu'à l'origine, je voulais seulement élever des grillons pour les faire combattre ?"
  },
  AvgCommunicate_134104_Content_13 = {
    Text = "Je plaisante."
  },
  AvgCommunicate_134104_Content_14 = {
    Text = "Ce monde est vraiment trop ennuyeux, %player%. Même si l'annihilation devait arriver demain, les gens ordinaires seraient encore embourbés dans ces futilités vulgaires — le ressentiment, l'amour, la haine, le désir."
  },
  AvgCommunicate_134104_Content_15 = {Text = "新增"},
  AvgCommunicate_134104_Content_16 = {
    Text = "Et pourtant, malgré tout, ma petite fleur de jasmin travaille si assidûment, sortant griffes et crocs pour leur trouver des solutions."
  },
  AvgCommunicate_134104_Content_17 = {
    Text = "Alors, maintenant que j'ai obtenu un pouvoir si magnifique, vais-je prêter main-forte à ma chère petite fleur de jasmin désormais, ou lui causer quelques ennuis ?"
  },
  AvgCommunicate_134104_Content_18 = {
    Text = "Comme prévu, faire les deux en même temps est le plus amusant, vous ne trouvez pas ?"
  },
  AvgCommunicate_134104_Content_19 = {Text = "???"},
  AvgCommunicate_134104_Content_2 = {
    Text = "Ma petite fleur de jasmin, tu m'as vraiment offert un bien magnifique cadeau."
  },
  AvgCommunicate_134104_Content_20 = {
    Text = "Je ne t'ai pas fait ce cadeau pour que tu fasses ça."
  },
  AvgCommunicate_134104_Content_21 = {
    Text = "Arrête ça tout de suite ! Je ne suis responsable que des incidents de Fusion. L'ordre public et la moralité ne relèvent pas de la juridiction du Mizag. Ne transforme pas l'hôpital psychiatrique de Londinium en prison de substitution ! Hé, hé !"
  },
  AvgCommunicate_134104_Content_4 = {
    Text = "Chaque quartier — chaque quartier Autour de l'école a vu des Citoyens sombrer dans l'hystérie collective ! Des foules de gens riant et pleurant en même temps — les policiers et les médecins de Londinium n'arrêtent pas de courir !"
  },
  AvgCommunicate_134104_Content_6 = {
    Text = "Cette humble personne est loin de chez elle, en terre étrangère, toute seule et esseulée. Ma petite fleur de jasmin a eu la bonté de veiller sur cette humble personne, me permettant d'atteindre de tels sommets..."
  },
  AvgCommunicate_134104_Content_7 = {
    Text = "Cette humble personne a simplement été submergée de joie, et n'a pu résister à l'envie de se laisser aller un peu."
  },
  AvgCommunicate_134104_Content_8 = {
    Text = "Mm, très efficace. Ces choses immondes qui abritent la noirceur dans leur cœur — chacune est devenue folle plus vite que la précédente."
  },
  AvgCommunicate_134104_Content_9 = {
    Text = "Attendez — l'école vient d'envoyer leurs dossiers. Tueur de femme, agresseur, @3@4..."
  },
  AvgCommunicate_134104_Option_19 = {Text = "???"},
  AvgCommunicate_134104_Option_9 = {
    Text = "Il y a des manières correctes de faire les choses."
  },
  AvgCommunicate_134105_Content_1 = {
    Text = "La lumière du phare peut désormais illuminer les fonds les plus profonds de l'océan."
  },
  AvgCommunicate_134105_Content_10 = {
    Text = "Seulement par ta description, je peux le sentir — ça devait être un pays vraiment magnifique."
  },
  AvgCommunicate_134105_Content_11 = {
    Text = "Oui, ma patrie était magnifique... C'est pourquoi je ne renoncerai jamais à la retrouver."
  },
  AvgCommunicate_134105_Content_12 = {
    Text = "Plus de Force signifie plus d'espoir. Je vais attirer davantage de papillons de nuit vers la direction du phare..."
  },
  AvgCommunicate_134105_Content_13 = {
    Text = "Un jour, ma patrie émergera à nouveau du fond de l'océan et m'ouvrira de nouveau les bras."
  },
  AvgCommunicate_134105_Content_14 = {
    Text = "Tu vas encore faire ce genre de chose ! Toute cette tristesse n'a servi à rien — arrête ça tout de suite !!!"
  },
  AvgCommunicate_134105_Content_2 = {
    Text = "Le Chemin du retour vers ma patrie... quand sera-t-il retrouvé..."
  },
  AvgCommunicate_134105_Content_3 = {
    Text = "Faros... Soupir, dire que je comprends ce que tu ressens ne serait qu'un Vide réconfort à ce stade. Tu... essaie de ne pas être trop triste."
  },
  AvgCommunicate_134105_Content_4 = {
    Text = "Lamento... Le Lamento de la nostalgie du foyer est devenu une marque gravée dans mon âme. J'ai appris à coexister avec."
  },
  AvgCommunicate_134105_Content_5 = {
    Text = "Une nostalgie Constante apporte la douleur, mais elle garantit aussi que je n'oublierai jamais à quoi ressemblait ma patrie."
  },
  AvgCommunicate_134105_Content_6 = {
    Text = "Ces hauts-fonds couverts de coraux, ce temple imposant, et la majestueuse Porte où je montais souvent la Garde..."
  },
  AvgCommunicate_134105_Content_7 = {
    Text = "Je me souviens des motifs gravés le long des bords de ces piliers de pierre, de chaque large Chemin de la capitale royale, et des expressions de bonheur dévot sur les visages des gens pendant la Prière."
  },
  AvgCommunicate_134105_Content_8 = {
    Text = "Quand de grandes cérémonies étaient organisées, la nation entière célébrait ensemble. C'étaient mes moments les plus chargés, mais aussi les plus épanouissants."
  },
  AvgCommunicate_134105_Content_9 = {
    Text = "J'ai eu un jour l'honneur de me tenir en Gardien devant le cortège royal, partageant les regards révérencieux et admiratifs de la foule, me sentant fier et glorieux... Ce sont les moments qui me manquent le plus."
  },
  AvgCommunicate_134105_Option_10 = {
    Text = "Ça devait être un beau pays."
  },
  AvgCommunicate_134105_Option_14 = {
    Text = "Tu vas encore faire ce genre de chose !"
  },
  AvgCommunicate_134105_Option_3 = {Text = "Faros…"},
  AvgCommunicate_134106_Content_1 = {
    Text = "Euh, euh, Maître..."
  },
  AvgCommunicate_134106_Content_10 = {
    Text = "Maintenant, Lily peut porter Jenkin, Aigis, Caraboo et Aurita tous en même temps jusqu'à la cafétéria!"
  },
  AvgCommunicate_134106_Content_11 = {
    Text = "C'est beaucoup trop !"
  },
  AvgCommunicate_134106_Content_12 = {
    Text = "Mm-hmm ! Merci, Maître, d'avoir donné à Lily autant, autant !"
  },
  AvgCommunicate_134106_Content_14 = {
    Text = "Ce n'est pas tout à fait ce que je voulais dire, mais..."
  },
  AvgCommunicate_134106_Content_15 = {
    Text = "Tant que Lily est contente, c'est tout ce qui compte !"
  },
  AvgCommunicate_134106_Content_2 = {Text = "Hmm?"},
  AvgCommunicate_134106_Content_3 = {
    Text = "Vous pouvez féliciter Lily ?"
  },
  AvgCommunicate_134106_Content_4 = {
    Text = "Bonne fille, Lily. Il s'est passé quelque chose de méritoire ?"
  },
  AvgCommunicate_134106_Content_5 = {
    Text = "Lily, a soulevé plein plein de Pustule !"
  },
  AvgCommunicate_134106_Content_6 = {
    Text = "Les a soulevées très, très haut !"
  },
  AvgCommunicate_134106_Content_9 = {
    Text = "Ça doit être l'influence de la Règle finale..."
  },
  AvgCommunicate_134107_Content_1 = {
    Text = "Depuis que j'ai compris la Règle finale, le chemin maritime devant moi est devenu encore plus clair."
  },
  AvgCommunicate_134107_Content_10 = {
    Text = "En tant que navigateur, c'est simplement mon devoir."
  },
  AvgCommunicate_134107_Content_11 = {
    Text = "N'importe qui à cette place aurait probablement fait la même chose."
  },
  AvgCommunicate_134107_Content_12 = {
    Text = "Le travail de navigation est motivé par le devoir et la responsabilité, pas pour recevoir des éloges."
  },
  AvgCommunicate_134107_Content_13 = {
    Text = "Veuillez retourner tous ces cadeaux aux marins."
  },
  AvgCommunicate_134107_Content_14 = {
    Text = "C'est aussi un témoignage de leur reconnaissance. Accepte-les, seulement."
  },
  AvgCommunicate_134107_Content_15 = {
    Text = "Aussi, si jamais vous voyez une lumière jaune inexpliquée en mer, veuillez faire de votre mieux pour diriger les navires dans la direction opposée."
  },
  AvgCommunicate_134107_Content_16 = {
    Text = "Ne demandez pas pourquoi. L'école s'occupera du Primordial correspondant dès que possible..."
  },
  AvgCommunicate_134107_Content_2 = {
    Text = "Pour le bien des innombrables âmes perdues le long du chemin, et pour moi-même, je vous remercie une fois de plus sincèrement pour la Révélation que vous m'avez accordée."
  },
  AvgCommunicate_134107_Content_3 = {
    Text = "Pas besoin d'être si formel. Tu l'as mérité, Corposant."
  },
  AvgCommunicate_134107_Content_4 = {
    Text = "Je l'ai mérité ?"
  },
  AvgCommunicate_134107_Content_5 = {
    Text = "Oui, l'école a reçu plusieurs lettres de remerciement transmises par divers canaux."
  },
  AvgCommunicate_134107_Content_6 = {
    Text = "C'étaient tous des marins qui s'étaient perdus en mer, avant d'apercevoir une Lueur Océanique bleu-violet au sommet de leur mât."
  },
  AvgCommunicate_134107_Content_7 = {
    Text = "Tant qu'ils suivaient les indications de la Lueur Océanique, ils pouvaient atteindre le port le plus proche."
  },
  AvgCommunicate_134107_Content_8 = {
    Text = "Ils ont appelé cette lumière la « Lumière du Saint »."
  },
  AvgCommunicate_134107_Content_9 = {
    Text = "En plus de cela, il y a de nombreux cadeaux exprimant leur gratitude, tous entassés à l'entrée du bureau de courrier."
  },
  AvgCommunicate_134107_Option_5 = {
    Text = "Le Mizag a reçu des lettres de remerciement..."
  },
  AvgCommunicate_134108_Content_1 = {
    Text = "Tu avais quelque chose d'aussi bon et tu n'as pas pensé à le sortir plus tôt."
  },
  AvgCommunicate_134108_Content_10 = {
    Text = "Tu as seulement un cerveau ou pas, espèce de @2 ?! Prendre une blague au sérieux !"
  },
  AvgCommunicate_134108_Content_11 = {
    Text = "Si tout le monde devient de la progéniture, qu'est-ce que cette grande reine est censée faire avec tous ces appareils cassés et ces cours bizarres de culture générale ? Enfin, certes, les souvenirs peuvent être conservés, mais quand même."
  },
  AvgCommunicate_134108_Content_12 = {
    Text = "Je suis censée parler à des Coquilles vides et me répondre à moi-même tous les jours ? Pas question."
  },
  AvgCommunicate_134108_Content_14 = {
    Text = "Tch, encore percée à jour. Comme c'est ennuyeux."
  },
  AvgCommunicate_134108_Content_15 = {
    Text = "J'ai confiance que tu ne feras pas ça, Agrippa. Même si tu dévies parfois du chemin, je suis convaincu de pouvoir te ramener sur la bonne voie."
  },
  AvgCommunicate_134108_Content_16 = {
    Text = "Parce que tu es la sage Maître du labyrinthe."
  },
  AvgCommunicate_134108_Content_17 = {
    Text = "Parce que tu es quelqu'un d'important pour moi."
  },
  AvgCommunicate_134108_Content_18 = {
    Text = "Beurk ! C'est quoi ce truc bizarre que tu dis tout à coup ?! Dégoûtant, trop dégoûtant, mes oreilles vont pourrir."
  },
  AvgCommunicate_134108_Content_19 = {
    Text = "Bon, bon, je vais à contrecœur m'abstenir de transformer qui que ce soit en progéniture pour le moment. Seulement débarrasse-moi de ces devoirs !"
  },
  AvgCommunicate_134108_Content_2 = {
    Text = "Haha, cette grande reine est maintenant complètement libre ! La noble Louve Grise va reprendre son règne sur le Mizag."
  },
  AvgCommunicate_134108_Content_3 = {
    Text = "Tout le Mizag — non, tout Kadath sera rempli de ma progéniture."
  },
  AvgCommunicate_134108_Content_4 = {Text = "Vraiment ?"},
  AvgCommunicate_134108_Content_5 = {
    Text = "À l'origine, pour célébrer ta compréhension de la Règle finale, j'étais même prêt à faire une exception et aider à ranger ton dortoir. Le bureau des affaires académiques avait même accepté de t'exempter d'une semaine de devoirs."
  },
  AvgCommunicate_134108_Content_6 = {
    Text = "Mais puisque la noble Louve Grise prévoit de transformer tout le monde en sa progéniture, je suppose que rien de tout cela n'est plus nécessaire, n'est-ce pas ?"
  },
  AvgCommunicate_134108_Content_7 = {
    Text = "Qu— Quoi ?!"
  },
  AvgCommunicate_134108_Content_9 = {
    Text = "Non, absolument pas, c'est interdit !"
  },
  AvgCommunicate_134108_Option_16 = {
    Text = "Parce que tu es la sage Maître du labyrinthe."
  },
  AvgCommunicate_134108_Option_17 = {
    Text = "Parce que tu es quelqu'un d'important pour moi."
  },
  AvgCommunicate_134108_Option_4 = {Text = "Vraiment."},
  AvgCommunicate_134109_Content_1 = {
    Text = "Miaou-gardien, j'ai vu un tunnel d'un noir absolu..."
  },
  AvgCommunicate_134109_Content_10 = {
    Text = "Mais je n›ai senti aucune malveillance dans ces petits yeux. Au contraire, je me sentais complètement en paix. Et maintenant, il semble que je puisse Fusionner en un avec eux."
  },
  AvgCommunicate_134109_Content_11 = {
    Text = "Tu dis que tu as fusionné avec les âmes des rats ?"
  },
  AvgCommunicate_134109_Content_12 = {
    Text = "Ouais, j›ai senti que je me dispersais en plein, plein de morceaux en un instant, détalant à travers des tuyaux sinueux, des tas de bric-à-brac, et sous des meubles bas..."
  },
  AvgCommunicate_134109_Content_13 = {
    Text = "Ça t›a rappelé ton ancienne vie ? Ce n›est rien, tout ça, c›est du passé maintenant."
  },
  AvgCommunicate_134109_Content_14 = {
    Text = "Et puis — je pouvais les contrôler pour voler facilement toutes sortes de choses !"
  },
  AvgCommunicate_134109_Content_15 = {
    Text = "Si j›avais eu ce genre de pouvoir à l›époque, j›aurais même pu dévaliser la plus grande banque du Quartier Ouest ! Hahaha, maintenant je suis pratiquement le roi des voleurs de tout le pays... non, du monde entier ! Plus personne ne peut m›arrêter !"
  },
  AvgCommunicate_134109_Content_17 = {
    Text = "J›ai l›impression que même appeler la police ne servira à rien cette fois. Je ferais mieux de demander à Mlle Doll la Fabrication d›un dispositif de surveillance pour moi."
  },
  AvgCommunicate_134109_Content_2 = {
    Text = "Pas de lumière, aucune notion du temps. J'ai marché et marché là-dedans toute seule, comme si j'avais marché pendant toute une vie."
  },
  AvgCommunicate_134109_Content_3 = {
    Text = "Tu vas bien ? Tu t'es encore Perdu dans tes pensées ?"
  },
  AvgCommunicate_134109_Content_4 = {
    Text = "J'ai marché pendant si, si longtemps avant de finalement voir quelque chose — comme un filet de lumière, un filet de fumée — et puis ça s'est lentement transformé en Brun ! Ses petits yeux ronds brillaient dans cet espace d'un noir absolu."
  },
  AvgCommunicate_134109_Content_5 = {
    Text = "Et puis il y a eu d'innombrables paires d'yeux identiques, m'entourant, me tenant compagnie..."
  },
  AvgCommunicate_134109_Content_6 = {
    Text = "Un essaim de rats ?"
  },
  AvgCommunicate_134109_Content_7 = {
    Text = "Ouais, j'avais l'impression que ce n'étaient pas juste des rats. Ils semblaient avoir des âmes, tout comme les gamins que je connaissais dans les rues. On rivalisait, on coopérait, et on partageait les mêmes galères — on détalait dans les rues exactement comme des rats."
  },
  AvgCommunicate_134109_Content_8 = {
    Text = "C›étaient peut-être les âmes de nombreux Enfants qui te tenaient compagnie."
  },
  AvgCommunicate_134109_Content_9 = {
    Text = "Hein ? Mais je dois encore une cuisse de poulet à Joe, deux miches de pain au petit Jones, et j›ai volé quelques billes à Johnny... Ils ne viennent pas réclamer leurs dettes, quand même ?!"
  },
  AvgCommunicate_134109_Option_11 = {
    Text = "Tes sens ont fusionné avec les leurs ?"
  },
  AvgCommunicate_134109_Option_13 = {
    Text = "Tout ça, c›est du passé maintenant."
  },
  AvgCommunicate_134109_Option_17 = {Text = "新增"},
  AvgCommunicate_134109_Option_3 = {Text = "Ça va ?"},
  AvgCommunicate_134109_Option_6 = {
    Text = "Un essaim de rats ?"
  },
  AvgCommunicate_134109_Option_8 = {
    Text = "C›était peut-être eux."
  },
  AvgCommunicate_134110_Content_1 = {
    Text = "Ah, ah... AAAAAAH ! Noir, tout est noir !"
  },
  AvgCommunicate_134110_Content_10 = {
    Text = "Il... ne l'est pas ? Les démons noirs ne sont pas venus ?"
  },
  AvgCommunicate_134110_Content_11 = {
    Text = "Mais si nous vivons dans le ventre d'un démon, alors viendra un jour où nous serons Dévorés par les ténèbres. On ne peut pas s'échapper, on ne peut pas s'échapper !"
  },
  AvgCommunicate_134110_Content_12 = {
    Text = "C'est trop terrifiant, trop terrifiant..."
  },
  AvgCommunicate_134110_Content_14 = {
    Text = "N'aie pas peur."
  },
  AvgCommunicate_134110_Content_15 = {
    Text = "Je ne comprends pas vraiment ce que tu dis, mais si le monde est véritablement destiné au Symptôme : Destruction un jour, au moins moi, et Tous ceux de Mizag, nous nous battrons et résisterons jusqu'au tout dernier instant."
  },
  AvgCommunicate_134110_Content_16 = {
    Text = "Si la Fusion est véritablement une Fin inévitable, je m'assurerai que tu restes dans le dernier endroit où la lumière subsiste, et je resterai à tes côtés jusqu'à la Fin du monde."
  },
  AvgCommunicate_134110_Content_17 = {
    Text = "...Je vois."
  },
  AvgCommunicate_134110_Content_18 = {
    Text = "Ta flamme ne s'éteindra jamais. Je crois en toi."
  },
  AvgCommunicate_134110_Content_19 = {
    Text = "Merci, Gardien."
  },
  AvgCommunicate_134110_Content_2 = {
    Text = "Le monde entier est noir ! Seulement Vide, Seulement Vide !"
  },
  AvgCommunicate_134110_Content_3 = {
    Text = "Winkle ! Réveille-toi ! Encore un cauchemar ?!"
  },
  AvgCommunicate_134110_Content_4 = {
    Text = "Non, non, plus de @2 techniques de personnes, de connaissances, d›âmes plus fortes, rien ne marche, rien ! Je n›arrive toujours pas à migrer de nouveau !"
  },
  AvgCommunicate_134110_Content_5 = {
    Text = "Après être devenu plus fort, c›est encore plus facile pour les ténèbres de me voir. Je me démarque trop. Les ténèbres vont me rattraper..."
  },
  AvgCommunicate_134110_Content_6 = {
    Text = "Je ne veux plus devenir plus forte. Je veux fuir, courir loin, très loin. Mais si le monde entier est noir, et que toute la lumière est fausse, alors où puis-je aller..."
  },
  AvgCommunicate_134110_Content_7 = {
    Text = "Pourquoi, pourquoi ce pouvoir me fait-il voir ces choses ? Je ne veux pas savoir !"
  },
  AvgCommunicate_134110_Content_8 = {
    Text = "Je vais mourir, mourir, mourir encore. Dois-je en faire l'Expérience à nouveau ? Je ne veux pas, je ne veux pas..."
  },
  AvgCommunicate_134110_Content_9 = {
    Text = "Réveille-toi, Winkle ! Le monde n'est pas devenu noir. Je suis encore là ! Tout le monde est encore là !"
  },
  AvgCommunicate_134110_Option_14 = {
    Text = "N'aie pas peur."
  },
  AvgCommunicate_134110_Option_3 = {Text = "Winkle ?!"},
  AvgCommunicate_134110_Option_9 = {Text = "Winkle!"},
  AvgCommunicate_134111_Content_1 = {
    Text = "Mes ailes... sont devenues encore plus immenses."
  },
  AvgCommunicate_134111_Content_10 = {
    Text = "Castor, je sais que tu es incroyable, et tes ailes le sont aussi. Comment dire..."
  },
  AvgCommunicate_134111_Content_12 = {
    Text = "Peu importe, j'ai compris. Donc, ta capacité de portage a dû s'améliorer aussi, non ?"
  },
  AvgCommunicate_134111_Content_13 = {
    Text = "Hmm, d'après une estimation approximative, le poids d'une douzaine de personnes ne devrait pas poser de problème."
  },
  AvgCommunicate_134111_Content_14 = {
    Text = "Cependant, mes bras ne semblent pas capables de tenir autant de personnes en même temps."
  },
  AvgCommunicate_134111_Content_15 = {
    Text = "J'ai une suggestion."
  },
  AvgCommunicate_134111_Content_16 = {
    Text = "Voici le plan — tu vas t'entraîner à renforcer tes bras, et ensuite on aura un véhicule aérien capable de descendre du ciel à tout moment !"
  },
  AvgCommunicate_134111_Content_17 = {
    Text = "La force des bras ? Quel rapport avec un véhicule... aérien ? Bienfaiteur, pardonnez mon ignorance, mais je ne comprends pas."
  },
  AvgCommunicate_134111_Content_18 = {
    Text = "C'est une mission importante."
  },
  AvgCommunicate_134111_Content_19 = {
    Text = "Tant que ta capacité de portage suit, la mobilité et la vitesse d'évacuation des missions de terrain seront grandement améliorées. Castor, es-tu prêt à accepter cette mission ?"
  },
  AvgCommunicate_134111_Content_2 = {
    Text = "Mes Croyants ont bien répandu des récits exagérés d'ailes qui obscurcissaient le ciel, mais je sais que ce que je possédais autrefois n'était rien de plus qu'une paire d'ailes parfaitement ordinaires."
  },
  AvgCommunicate_134111_Content_20 = {
    Text = "Bien sûr ! Ce serait un honneur, bienfaiteur."
  },
  AvgCommunicate_134111_Content_21 = {
    Text = "C'est décidé alors. Je vais trouver Erica tout de suite pour personnaliser un panier de transport !"
  },
  AvgCommunicate_134111_Content_22 = {
    Text = "Ne pense jamais à donner tes ailes à qui que ce soit d'autre, d'accord ? À personne."
  },
  AvgCommunicate_134111_Content_3 = {
    Text = "Vous les gens ailés, vous ne réalisez pas à quel point c'est pratique d'avoir des ailes... Je suis tellement jaloux..."
  },
  AvgCommunicate_134111_Content_4 = {
    Text = "Si mon bienfaiteur le souhaite, je me souviens vaguement que l'Église des Porteurs de Lumière dispose de méthodes pour greffer des ailes. Je donnerais volontiers les miennes à mon bienfaiteur. Je n'ai pas peur de la douleur."
  },
  AvgCommunicate_134111_Content_6 = {
    Text = "Non non non non, ce ne sera pas nécessaire. Elles sont mieux sur toi."
  },
  AvgCommunicate_134111_Content_7 = {
    Text = "Ah, vous ne voulez pas de mes ailes, bienfaiteur ? Elles sont devenues vraiment impressionnantes maintenant."
  },
  AvgCommunicate_134111_Content_8 = {
    Text = "Après avoir compris les lois, la sensation de chaque filet de vent s'écoulant entre les interstices de mes plumes, la force de rotation de chaque courant d'air — tout est à ma portée."
  },
  AvgCommunicate_134111_Content_9 = {
    Text = "Ce n'est pas une question d'être impressionnant ou non."
  },
  AvgCommunicate_134111_Option_15 = {
    Text = "J'ai une suggestion."
  },
  AvgCommunicate_134111_Option_18 = {
    Text = "C'est une mission importante."
  },
  AvgCommunicate_134111_Option_3 = {
    Text = "Tu ne comprends pas, c'est tout."
  },
  AvgCommunicate_134111_Option_9 = {
    Text = "Ce n'est pas une question d'être impressionnant ou non."
  },
  AvgCommunicate_134112_Content_1 = {
    Text = "Oh là là, alors c'est à ça que le monde ressemble de ton point de vue."
  },
  AvgCommunicate_134112_Content_10 = {
    Text = "Les humains ont vraiment autant de types d'expressions ? Je suppose que ça fait de moi quelqu'un d'impassible en comparaison."
  },
  AvgCommunicate_134112_Content_11 = {
    Text = "Pas Seulement ça, j'ai aussi appris à rire en pleurant, à me mettre en colère en pleurant, à me mettre en colère en riant, à ressentir la Peur en riant..."
  },
  AvgCommunicate_134112_Content_12 = {
    Text = "Tant que tu combines chaque expression ensemble, ça devient une nouvelle émotion. À ce rythme, il ne faudra pas longtemps avant que Casiah maîtrise complètement les émotions humaines !"
  },
  AvgCommunicate_134112_Content_13 = {
    Text = "Tu veux voir ? Tu veux ? Même « l'amour », ce mystère non résolu de l'humanité — Casiah peut le jouer pour toi maintenant !"
  },
  AvgCommunicate_134112_Content_15 = {
    Text = "Non Seulement tu n'as rien maîtrisé, mais tu as l'air encore moins humaine maintenant ! C'est terrifiant — arrête ça tout de suite !!!"
  },
  AvgCommunicate_134112_Content_2 = {Text = "Quoi ?"},
  AvgCommunicate_134112_Content_3 = {
    Text = "Je ne pense pas que le monde à travers mes yeux ait quoi que ce soit de spécial, mais qu'avez-vous vu ?"
  },
  AvgCommunicate_134112_Content_4 = {
    Text = "Casiah a vu... des millions et des millions de petits êtres se chevauchant, avec d'innombrables instants tous dans mon « champ de vision »."
  },
  AvgCommunicate_134112_Content_5 = {
    Text = "En un seul bref instant, d'innombrables personnes pleurent, tandis que d'innombrables autres rient, enragent de colère, tremblent de Peur..."
  },
  AvgCommunicate_134112_Content_6 = {
    Text = "Certaines personnes avaient aussi des expressions très Ning. Cette émotion, je crois, s'appelle le bonheur ? Les émotions humaines ont tellement, tellement de subtiles différences..."
  },
  AvgCommunicate_134112_Content_7 = {
    Text = "Tu peux déjà ressentir les émotions humaines ?!"
  },
  AvgCommunicate_134112_Content_8 = {
    Text = "Non, Casiah peut Seulement voir leurs expressions, leurs mouvements, et les couleurs de leurs émotions."
  },
  AvgCommunicate_134112_Content_9 = {
    Text = "Mais Casiah est la meilleure en imitation ! Après avoir vu tous les différents visages souriants et en pleurs à travers le monde en même temps, Casiah peut maintenant réaliser 21 types de sourires et 36 types d'expressions de pleurs pour toi !"
  },
  AvgCommunicate_134112_Option_10 = {
    Text = "Autant que ça ?"
  },
  AvgCommunicate_134112_Option_15 = {
    Text = "Tu n'as rien maîtrisé du tout !"
  },
  AvgCommunicate_134112_Option_2 = {Text = "Quoi ?"},
  AvgCommunicate_134112_Option_7 = {
    Text = "Tu peux ressentir les émotions humaines maintenant ?!"
  },
  AvgCommunicate_134113_Content_1 = {
    Text = "Le marché conclu avec toi a été la meilleure décision de toute ma carrière de Marchand."
  },
  AvgCommunicate_134113_Content_10 = {
    Text = "Attends, les suivants deviennent de plus en plus louches !"
  },
  AvgCommunicate_134113_Content_11 = {
    Text = "Et quelque chose qui a l'air aussi précieux doit être vraiment cher, non ? Quel est le prix du marché ?"
  },
  AvgCommunicate_134113_Content_12 = {
    Text = "Hmm... Après tout, c'est grâce à toi que j'ai obtenu un pouvoir plus pratique pour voyager."
  },
  AvgCommunicate_134113_Content_13 = {
    Text = "Je te ferai une remise spéciale. Quant au prix, viens dans ma boutique pour en discuter en détail. J'attendrai ta venue."
  },
  AvgCommunicate_134113_Content_2 = {
    Text = "Planter une graine, et attendre qu'elle devienne une petite fleur, ou un arbre majestueux."
  },
  AvgCommunicate_134113_Content_3 = {
    Text = "Je fais rarement des affaires qui nécessitent une si longue attente avant d'en voir les retours. Heureusement, au vu de la situation actuelle, c'était Sans risque de perte."
  },
  AvgCommunicate_134113_Content_4 = {
    Text = "Héhé, merci pour toute l'aide apportée durant cette période. Je suis contente de ne pas t'avoir déçu."
  },
  AvgCommunicate_134113_Content_5 = {
    Text = "Les eaux de la Mer aux Mille Visages sont devenues encore plus profondes. Cela fait un moment, et les têtes là-bas s'ennuient beaucoup de toi aussi. Ça te dirait un Retour dans des lieux familiers ?"
  },
  AvgCommunicate_134113_Content_6 = {
    Text = "Euh, je... Je préférerais éviter. Je pense que parfois, c'est la distance qui rend les choses belles."
  },
  AvgCommunicate_134113_Content_7 = {
    Text = "Héhé, tu as un sacré Talent de Marchand quand il s'agit d'éloquence."
  },
  AvgCommunicate_134113_Content_8 = {
    Text = "En parlant de ça, ma petite boutique a récemment reçu quelques nouveaux articles. Extrêmement rares — je les ai tous gardés pour toi."
  },
  AvgCommunicate_134113_Content_9 = {
    Text = "Il y a un orbe qui permet d'atteindre la Résonance avec son pouvoir d'Origine, un Miroir qui permet d'Épier des images d'un autre monde, et un collier qui rend les gens docilement obéissants."
  },
  AvgCommunicate_134113_Option_10 = {
    Text = "Ça devient de plus en plus louche !"
  },
  AvgCommunicate_134113_Option_4 = {Text = "Hehe."},
  AvgCommunicate_134113_Option_6 = {
    Text = "Je préférerais éviter."
  },
  AvgCommunicate_134114_Content_1 = {
    Text = "Je... suis devenue feu."
  },
  AvgCommunicate_134114_Content_10 = {
    Text = "Il y a encore tant de beauté dans le monde qui mérite d'être capturée. Je pense avoir déjà trouvé plus de Clairvoyance pour mes créations."
  },
  AvgCommunicate_134114_Content_11 = {
    Text = "Désormais, je deviendrai le feu, apportant un rythme plus pur et plus naturel."
  },
  AvgCommunicate_134114_Content_2 = {
    Text = "Un feu cyan, dansant. Brûler, Purification, Danse."
  },
  AvgCommunicate_134114_Content_3 = {
    Text = "Mes péchés et les péchés des autres Brûleront tous dans le feu, et tout deviendra pur."
  },
  AvgCommunicate_134114_Content_4 = {
    Text = "Liz... te souviens-tu encore de ce feu d'autrefois ?"
  },
  AvgCommunicate_134114_Content_5 = {
    Text = "Ma haine a lentement été consumée dans le feu, mais je n'ai pas le droit de pardonner ce feu au nom des autres."
  },
  AvgCommunicate_134114_Content_6 = {
    Text = "Je ne l'ai jamais regretté, et je ne fuirai pas les visages dans ces flammes."
  },
  AvgCommunicate_134114_Content_7 = {
    Text = "Après être arrivée ici, tu m'as donné une nouvelle vie. Je n'ai plus besoin d'une grande scène, mais si tu es le Public, je pense que je ressentirais encore du bonheur en dansant."
  },
  AvgCommunicate_134114_Content_8 = {
    Text = "Laisse-moi être ton plus grand fan et continuer à te regarder danser !"
  },
  AvgCommunicate_134114_Content_9 = {
    Text = "Mm, merci. Après avoir arrêté de danser, je restais souvent assise en silence près de la fenêtre. J'ai vu le vent, les fleurs, les arbres, les oiseaux et les Chats — tant d'êtres vivants et tant de nature débordant du rythme de la Danse."
  },
  AvgCommunicate_134114_Option_4 = {Text = "Liz..."},
  AvgCommunicate_134114_Option_8 = {
    Text = "Je continuerai à te regarder danser !"
  },
  AvgCommunicate_134115_Content_1 = {
    Text = "Je... Je peux le voir..."
  },
  AvgCommunicate_134115_Content_10 = {
    Text = "C'est vraiment réconfortant !"
  },
  AvgCommunicate_134115_Content_11 = {
    Text = "Je suis heureux pour toi de pouvoir voir tout cela, Miryam !"
  },
  AvgCommunicate_134115_Content_12 = {
    Text = "Bien sûr, je continuerai à tout consacrer à l'Arrivée du Pays des dieux."
  },
  AvgCommunicate_134115_Content_13 = {
    Text = "Mais je comprends maintenant... Le Royaume Divin ne se résume pas simplement à deux États, entièrement arrivé ou entièrement disparu."
  },
  AvgCommunicate_134115_Content_14 = {
    Text = "Alors que nous prions pour l'Arrivée du Pays des dieux, une partie du Royaume Divin est déjà venue à nos côtés."
  },
  AvgCommunicate_134115_Content_15 = {
    Text = "Merci, Gardien. C'est toi qui m'as accordé une nouvelle Force."
  },
  AvgCommunicate_134115_Content_16 = {
    Text = "Ce que j'ai vu est la Preuve d'existence de l'existence immortelle du Royaume Divin !"
  },
  AvgCommunicate_134115_Content_17 = {
    Text = "Même si le processus était un peu étrange... le résultat est plutôt bon."
  },
  AvgCommunicate_134115_Content_2 = {
    Text = "Que vois-tu ?"
  },
  AvgCommunicate_134115_Content_3 = {
    Text = "Le Royaume Divin... Oui... Les contours du Royaume Divin !"
  },
  AvgCommunicate_134115_Content_4 = {
    Text = "Ça n'a jamais été aussi clair... Ça n'a jamais été aussi... ordinaire..."
  },
  AvgCommunicate_134115_Content_5 = {
    Text = "Miryam... Es-tu sûre que ces mots venaient de toi..."
  },
  AvgCommunicate_134115_Content_6 = {
    Text = "Je vois ma patrie. Je vois cet avenir éternel, impérissable."
  },
  AvgCommunicate_134115_Content_7 = {
    Text = "Mais plus que cela... Je vois le présent."
  },
  AvgCommunicate_134115_Content_8 = {
    Text = "Mon Seigneur, mes proches, mes Amis proches, mes fidèles..."
  },
  AvgCommunicate_134115_Content_9 = {
    Text = "Le Royaume Divin a toujours été à nos côtés... Tout ce que j'ai a toujours fait partie du Royaume Divin..."
  },
  AvgCommunicate_134115_Option_10 = {
    Text = "C'est vraiment réconfortant !"
  },
  AvgCommunicate_134115_Option_17 = {
    Text = "Je suppose que ça fonctionne..."
  },
  AvgCommunicate_134115_Option_2 = {Text = "Quoi ?"},
  AvgCommunicate_134115_Option_5 = {
    Text = "Ordinaire ?"
  },
  AvgCommunicate_134116_Content_1 = {
    Text = "Oh là là. Je ne m'attendais pas à ce que pousser ma Force à son ultime limite procure une telle sensation."
  },
  AvgCommunicate_134116_Content_10 = {Text = "Euh..."},
  AvgCommunicate_134116_Content_11 = {
    Text = "Hmm, voyons voir... en ce moment tu penses : ‹ Honnêtement, je ne sais pas lequel des deux est le plus terrifiant. › Ai-je raison ?"
  },
  AvgCommunicate_134116_Content_12 = {
    Text = "Quoi ?!! Je croyais que vous aviez dit que vous ne pouviez pas lire dans mes pensées !!"
  },
  AvgCommunicate_134116_Content_13 = {
    Text = "Quelle adorable réaction. Je n'ai pas du tout lu dans tes pensées."
  },
  AvgCommunicate_134116_Content_14 = {
    Text = "C'est juste que quand tu baisses ta garde comme ça en ma présence, tu es bien trop facile à déchiffrer."
  },
  AvgCommunicate_134116_Content_15 = {
    Text = "Tu veux garder les petits secrets de ton cœur en sécurité ? Alors fais un peu plus d'efforts quand tu discutes avec moi."
  },
  AvgCommunicate_134116_Content_2 = {
    Text = "Quelle sensation ? J'ai un mauvais pressentiment..."
  },
  AvgCommunicate_134116_Content_3 = {
    Text = "Comment dire ? En gros, ces esprits médiocres sont comme des journaux intimes ouverts pour moi désormais — ennuyeux et complètement transparents. C'est plutôt fastidieux, vraiment."
  },
  AvgCommunicate_134116_Content_4 = {
    Text = "Quoi ?! Vous avez maîtrisé la Lecture de pensées ?!"
  },
  AvgCommunicate_134116_Content_5 = {
    Text = "Ce n'est pas si spectaculaire que ça. Après tout, il y a encore pas mal de gens dans ce monde avec des esprits résilients et des personnalités obstinées, qui essaient d'envelopper leur moi intérieur couche après couche, refusant de se laisser connaître facilement."
  },
  AvgCommunicate_134116_Content_6 = {
    Text = "Et puis il y a des êtres comme toi, qui ont toujours été énigmatiques et insondables."
  },
  AvgCommunicate_134116_Content_7 = {
    Text = "Pas besoin d'être nerveux. Obtenir les réponses d'un examen à l'avance est tout aussi ennuyeux qu'apprendre la fin d'une histoire avant l'heure, ou Découvrir le coupable d'une affaire de meurtre trop tôt."
  },
  AvgCommunicate_134116_Content_8 = {
    Text = "Je savoure pleinement le processus qui consiste à guider, spéculer et effeuiller le Cocon enroulé autour du cœur de quelqu'un, fil après fil."
  },
  AvgCommunicate_134116_Content_9 = {
    Text = "Sans ces jeux de va-et-vient, en quoi ces diagnostics grossiers seraient-ils différents de ceux de charlatans qui se contentent de découper un morceau du cerveau de quelqu'un ?"
  },
  AvgCommunicate_134116_Option_10 = {Text = "Euh..."},
  AvgCommunicate_134116_Option_12 = {Text = "?!!"},
  AvgCommunicate_134116_Option_2 = {
    Text = "Quelle sensation ?"
  },
  AvgCommunicate_134116_Option_4 = {Text = "Quoi ?!"},
  AvgCommunicate_134117_Content_1 = {
    Text = "Les rimes des Poèmes sont devenues encore plus envoûtantes."
  },
  AvgCommunicate_134117_Content_10 = {
    Text = "Je peux vous emmener dans le monde de la poésie, pour y flâner ensemble."
  },
  AvgCommunicate_134117_Content_12 = {
    Text = "C'est presque de la magie des mots ! C'est incroyable !"
  },
  AvgCommunicate_134117_Content_13 = {
    Text = "Alors j'aimerais vivre un Mirage de retraite, de richesse et de gastronomie illimitée. Vous pouvez m'y emmener ?"
  },
  AvgCommunicate_134117_Content_14 = {
    Text = "Ça... devrait être, oui, c'est possible ! Donnez-moi un instant, s'il vous plaît, il faut que j'y réfléchisse bien..."
  },
  AvgCommunicate_134117_Content_2 = {
    Text = "Maintenant, je peux voir les émotions qui déferlent dans ces rythmes scandés, la Force reflétée derrière ces Images."
  },
  AvgCommunicate_134117_Content_3 = {
    Text = "Je ne comprends pas tout, mais ça a l'air d'être un spectacle magnifique."
  },
  AvgCommunicate_134117_Content_4 = {
    Text = "Oui, la poésie est une Clé pour explorer la beauté. La poésie peut révéler les lois universelles du monde et refléter la vie telle qu'elle est vraiment."
  },
  AvgCommunicate_134117_Content_5 = {
    Text = "Dans la poésie, on se trouve soi-même, on trouve la sagesse de l'Histoire et de la philosophie, on trouve un sanctuaire pur pour l'esprit."
  },
  AvgCommunicate_134117_Content_6 = {
    Text = "Ah, je me suis encore laissée emporter à parler toute seule. Je suis vraiment désolée..."
  },
  AvgCommunicate_134117_Content_7 = {
    Text = "Ce n'est rien ! J'adore à quel point vous êtes passionnée quand vous parlez de poésie. C'est très charmant !"
  },
  AvgCommunicate_134117_Content_8 = {
    Text = "M-merci, Gardien. Quoi qu'il en soit, je peux maintenant utiliser des Poèmes pour emprunter encore plus de Force à ce monde, créant ainsi un Mirage poétique complet."
  },
  AvgCommunicate_134117_Content_9 = {
    Text = "Que vous souhaitiez profiter de la tranquillité, de la passion ou de la mélancolie — que vous vouliez poursuivre le parfum des fleurs, les courants de l'océan ou les nuages."
  },
  AvgCommunicate_134117_Option_12 = {
    Text = "C'est presque de la magie des mots."
  },
  AvgCommunicate_134117_Option_3 = {
    Text = "Ça a l'air magnifique."
  },
  AvgCommunicate_134117_Option_7 = {
    Text = "Ce n'est rien."
  },
  AvgCommunicate_134118_Content_1 = {
    Text = "Offrir quelque chose d'aussi précieux à votre serviteure, tu..."
  },
  AvgCommunicate_134118_Content_10 = {
    Text = "Mais tu peux vraiment en manger autant ? Un chef s'est plaint que tu avais vidé tout le stock de beurre et de fromage, et j'ai dû payer de ma poche pour réapprovisionner la cafétéria."
  },
  AvgCommunicate_134118_Content_11 = {
    Text = "Oh? Qui est-ce qui a bavardé dans mon dos? Qu'ils ne me tombent pas entre les mains!"
  },
  AvgCommunicate_134118_Content_12 = {
    Text = "Quant aux gâteaux, mêlez-vous de vos affaires quand il s'agit des histoires d'une dame! Je peux manger autant que j'en prépare!"
  },
  AvgCommunicate_134118_Content_13 = {
    Text = "Et si je ne peux pas tout finir, vous viendrez manger avec moi!"
  },
  AvgCommunicate_134118_Content_14 = {
    Text = "Je... Il y a des gâteaux à manger pour moi aussi? Je vais mourir de trop manger et grossir dans la fleur de l'âge!"
  },
  AvgCommunicate_134118_Content_15 = {
    Text = "Arrêtez de vous plaindre. Après tout ce bavardage, je n'ai toujours pas mentionné votre récompense. Cette dame sera assez généreuse pour vous garder une part de chaque gâteau que je préparerai personnellement à partir de maintenant."
  },
  AvgCommunicate_134118_Content_16 = {
    Text = "Soyez reconnaissant! Ce sont des chefs-d'œuvre d'une pâtissière de génie que l'argent ne peut acheter!"
  },
  AvgCommunicate_134118_Content_17 = {
    Text = "Donc... cette pâtisserie, c'est seulement de l'auto-production et de l'auto-consommation au final!"
  },
  AvgCommunicate_134118_Content_2 = {
    Text = "Hmph, pas mal du tout."
  },
  AvgCommunicate_134118_Content_3 = {
    Text = "Maintenant votre serviteure peut faire tourner dix — non, cent Marcheurs des mers comme des toupies en même temps ! Je n'aurai plus jamais besoin que quelqu'un vienne me sauver !"
  },
  AvgCommunicate_134118_Content_4 = {
    Text = "La grande dame est puissante !"
  },
  AvgCommunicate_134118_Content_5 = {
    Text = "Même si ma vie actuelle ne nécessite plus de s'inquiéter constamment, quand il s'agit de Force, en avoir plus est toujours mieux pour la tranquillité d'esprit."
  },
  AvgCommunicate_134118_Content_6 = {
    Text = "Celui qui a les plus gros poings n'est jamais perdant !"
  },
  AvgCommunicate_134118_Content_7 = {
    Text = "Cependant, utiliser une Force aussi puissante juste pour travailler pour les Mizags, quel gâchis... J'ai trouvé !"
  },
  AvgCommunicate_134118_Content_8 = {
    Text = "Puisque tant de tentacules peuvent travailler indépendamment, autant ouvrir ma propre pâtisserie. Avec moi seule occupant huit postes, n'atteindrais-je pas la liberté permanente en matière de gâteaux !"
  },
  AvgCommunicate_134118_Content_9 = {
    Text = "Tu peux les utiliser comme ça ?"
  },
  AvgCommunicate_134118_Option_14 = {
    Text = "Il y a des gâteaux à manger pour moi aussi?"
  },
  AvgCommunicate_134118_Option_17 = {Text = "Alors..."},
  AvgCommunicate_134118_Option_4 = {
    Text = "Murphy est puissante !"
  },
  AvgCommunicate_134118_Option_9 = {
    Text = "Tu peux les utiliser comme ça ?"
  },
  AvgCommunicate_134119_Content_1 = {
    Text = "Hahahaha... Hahahahaha!"
  },
  AvgCommunicate_134119_Content_10 = {
    Text = "Face à une puissance absolue, la conquête n'est seulement qu'un long jeu."
  },
  AvgCommunicate_134119_Content_11 = {
    Text = "Tout ce qui te rend heureux..."
  },
  AvgCommunicate_134119_Content_12 = {
    Text = "Le temps t'apportera la nouvelle de mon triomphe. Quand ce jour viendra, en tant que premier contributeur à mon nouveau royaume, je te réserverai les terres les plus fertiles comme fief."
  },
  AvgCommunicate_134119_Content_13 = {
    Text = "Ou... préférerais-tu cette terne cité de Londinium ?"
  },
  AvgCommunicate_134119_Content_2 = {
    Text = "Vous n'avez pas été rendue folle par la Force au point de perdre soudainement la tête, n'est-ce pas?"
  },
  AvgCommunicate_134119_Content_3 = {
    Text = "Hmph hmph, en tant que mon plus grand contributeur de Force, je peux pardonner votre petite insolence."
  },
  AvgCommunicate_134119_Content_4 = {
    Text = "Ah... Le moment que j'attendais depuis si longtemps, cette saveur douce et familière, cette sensation de Sang bouillonnant dans mes veines !"
  },
  AvgCommunicate_134119_Content_5 = {
    Text = "Je peux désormais soulever des icebergs sans effort et fendre les fosses océaniques."
  },
  AvgCommunicate_134119_Content_6 = {
    Text = "Aucun Chef de quelque tribu que ce soit, aucun guerrier le plus puissant des Marcheurs des mers ne tiendrait un seul combat contre moi, et cette femme folle ne peut plus me réprimer non plus."
  },
  AvgCommunicate_134119_Content_7 = {
    Text = "Bientôt, je conquerrai les mers, puis je conquerrai toutes les terres! Hahahahaha!"
  },
  AvgCommunicate_134119_Content_8 = {
    Text = "...La confiance en soi est une bonne chose, mais ne soyez pas si narcissique! C'est déjà au niveau du Symptôme : Délire!"
  },
  AvgCommunicate_134119_Content_9 = {
    Text = "Vous ne savez rien de la Force d'une géante, petit."
  },
  AvgCommunicate_134119_Option_11 = {
    Text = "Tout ce qui te rend heureux..."
  },
  AvgCommunicate_134119_Option_2 = {
    Text = "Vous avez perdu la tête?"
  },
  AvgCommunicate_134119_Option_8 = {Text = "新增"},
  AvgCommunicate_134120_Content_1 = {
    Text = "Ma voix chantée... est différente d'avant."
  },
  AvgCommunicate_134120_Content_10 = {
    Text = "Mm, je le ferai !"
  },
  AvgCommunicate_134120_Content_11 = {
    Text = "D'ailleurs, Gardien, grâce à vos encouragements, j'ai accepté la collaboration avec la maison de disques. Mon premier album est officiellement sorti maintenant, et il paraît qu'il se vend très bien."
  },
  AvgCommunicate_134120_Content_12 = {
    Text = "C'est une excellente nouvelle ! Félicitations ! Combien d'exemplaires se sont vendus ?"
  },
  AvgCommunicate_134120_Content_13 = {
    Text = "Je crois... il s'est vendu à cent mille exemplaires. Mais je n'ai pas vraiment besoin de la monnaie de cette planète de toute façon. Puisque je n'ai rien d'autre pour vous remercier, pourquoi ne pas vous donner tous les revenus de l'album ?"
  },
  AvgCommunicate_134120_Content_14 = {Text = "Hourra !!!"},
  AvgCommunicate_134120_Content_2 = {
    Text = "Gardien, après que vous m'avez aidée à comprendre la Règle finale, ma voix semble avoir atteint une merveilleuse Résonance avec l'Éther."
  },
  AvgCommunicate_134120_Content_3 = {
    Text = "On dirait que tu es devenue plus forte. Faint sera sûrement contente aussi !"
  },
  AvgCommunicate_134120_Content_4 = {
    Text = "Comment pourrais-je jamais vous rendre la pareille, Gardien ? Être réunie avec ma sœur était déjà un bonheur dont mon ancien moi n'aurait jamais pu rêver, et pourtant vous m'avez offert un trésor si précieux en plus de cela."
  },
  AvgCommunicate_134120_Content_5 = {
    Text = "En ce moment, je n'ai rien à mon nom, et je ne suis plus une star adorée par ses fans. La seule façon dont je peux vous remercier, c'est... s'il vous plaît, laissez-moi chanter une chanson pour vous."
  },
  AvgCommunicate_134120_Content_6 = {
    Text = "Tinct, tu as déjà trouvé ton propre Chemin. Si tu veux bien exaucer mon souhait, bien sûr."
  },
  AvgCommunicate_134120_Content_7 = {
    Text = "S'il te plaît, chante librement, pour toi-même, et pour moi."
  },
  AvgCommunicate_134120_Content_8 = {
    Text = "Pas pour plaire à qui que ce soit, pas pour répondre aux exigences de quiconque — Seulement pour ton propre bonheur."
  },
  AvgCommunicate_134120_Content_9 = {
    Text = "Mon propre... bonheur."
  },
  AvgCommunicate_134120_Option_12 = {
    Text = "C'est une excellente nouvelle."
  },
  AvgCommunicate_134120_Option_14 = {Text = "?!!"},
  AvgCommunicate_134120_Option_3 = {
    Text = "C'est merveilleux."
  },
  AvgCommunicate_134120_Option_6 = {
    Text = "As-tu déjà pensé à"
  },
  AvgCommunicate_134180_Content_1 = {
    Text = "Le vent gonfle les voiles, et les oiseaux planent en formation à nos côtés..."
  },
  AvgCommunicate_134180_Content_10 = {
    Text = "Je veux naviguer sur les mers pour toujours et à jamais — avec toi, avec le capitaine, avec tout le monde."
  },
  AvgCommunicate_134180_Content_11 = {
    Text = "Vivre ensemble les jours ensoleillés et les jours de pluie, naviguer vers toutes sortes de ports, et accoster dans différents pays."
  },
  AvgCommunicate_134180_Content_12 = {
    Text = "Pêcher ensemble, griller du poisson ensemble... Mm, et on pourrait même gratter les moules de la coque et les faire mijoter au vin rouge."
  },
  AvgCommunicate_134180_Content_13 = {
    Text = "Partons pour les prochaines vacances."
  },
  AvgCommunicate_134180_Content_14 = {
    Text = "J'y ai réfléchi longtemps. Naviguer... c'est quand je suis la plus heureuse."
  },
  AvgCommunicate_134180_Content_15 = {
    Text = "Je guiderai tout le monde à l'abri de chaque tempête, pour qu'on puisse continuer à naviguer joyeusement ensemble."
  },
  AvgCommunicate_134180_Content_16 = {
    Text = "Ça a l'air merveilleux, mais si on naviguait sans arrêt pour toujours, tout le monde sauf les Corps éveillés du Royaume Aequor aurait le mal de mer !"
  },
  AvgCommunicate_134180_Content_2 = {
    Text = "Je vois la proue fendre les vagues, j'entends les Matelots chanter leurs chants de marins, je sens les murmures du vent et de la pluie."
  },
  AvgCommunicate_134180_Content_3 = {
    Text = "Je le vois plus clairement maintenant — le cap menant vers des eaux calmes et Ning."
  },
  AvgCommunicate_134180_Content_4 = {
    Text = "Félicitations ! Celeste !"
  },
  AvgCommunicate_134180_Content_5 = {
    Text = "Maintenant, je pourrai peut-être vraiment exaucer le souhait de tout le monde et guider les navires sous ma protection en sécurité jusqu'à l'autre rive."
  },
  AvgCommunicate_134180_Content_6 = {
    Text = "Je ne décevrai plus personne."
  },
  AvgCommunicate_134180_Content_7 = {
    Text = "Et toi, quel est ton souhait ? Tu as décidé de ton propre souhait ?"
  },
  AvgCommunicate_134180_Content_8 = {
    Text = "Mon souhait..."
  },
  AvgCommunicate_134180_Content_9 = {
    Text = "J'ai déjà décidé."
  },
  AvgCommunicate_134180_Option_13 = {
    Text = "Partons pour les prochaines vacances."
  },
  AvgCommunicate_134180_Option_16 = {
    Text = "Ça a l'air merveilleux."
  },
  AvgCommunicate_134180_Option_4 = {
    Text = "Félicitations"
  },
  AvgCommunicate_134180_Option_7 = {Text = "Et toi ?"},
  AvgCommunicate_134181_Content_1 = {
    Text = "Ah... L'Appel de l'océan, si doux, si chaleureux."
  },
  AvgCommunicate_134181_Content_10 = {
    Text = "Est-ce le comportement brutal de Rogers qui vous a traumatisé, ou pensez-vous que je suis une artiste si stérile et paresseuse ?"
  },
  AvgCommunicate_134181_Content_11 = {
    Text = "Perfectionner son art ne tolère aucun raccourci. Mes sculptures sont, bien entendu, toutes taillées de mes propres mains, coup de ciseau après coup de ciseau."
  },
  AvgCommunicate_134181_Content_12 = {
    Text = "Soyez rassuré, pas un seul de vos Cheveux ne sera utilisé."
  },
  AvgCommunicate_134181_Content_13 = {
    Text = "Haha... Peut-être que vos talents de sculptrice sont tout simplement trop bons. Chaque fois que je vois vos œuvres, j'ai l'illusion de voir une personne vivante."
  },
  AvgCommunicate_134181_Content_14 = {
    Text = "Hmm... Eh bien, maintenant que ma Force a atteint son apogée, peut-être pourrais-je vraiment créer une sculpture qui prend vie."
  },
  AvgCommunicate_134181_Content_15 = {
    Text = "Au cœur de la nuit, hors de votre champ de vision, les yeux de la sculpture tourneraient lentement, et les coins de sa bouche se relèveraient tout doucement..."
  },
  AvgCommunicate_134181_Content_16 = {
    Text = "Une fois que j'aurai terminé ma dernière œuvre, j'en placerai une juste à côté de ton lit pour veiller sur toi à ma place. Qu'est-ce que tu en dis ?"
  },
  AvgCommunicate_134181_Content_17 = {
    Text = "Je n'oserais plus jamais dormir de toute ma vie !!!"
  },
  AvgCommunicate_134181_Content_18 = {
    Text = "Je plaisantais."
  },
  AvgCommunicate_134181_Content_19 = {
    Text = "On dirait que tu es vraiment terrifiée par de simples histoires de fantômes. Comme c'est adorable."
  },
  AvgCommunicate_134181_Content_2 = {
    Text = "Vous l'avez sûrement entendu aussi, n'est-ce pas ?"
  },
  AvgCommunicate_134181_Content_3 = {
    Text = "Il nous invite, ils nous attendent... pour voyager ensemble vers le palais d'un blanc immaculé au fond de la mer."
  },
  AvgCommunicate_134181_Content_4 = {
    Text = "Qui ? Je dois devenir sourd — je n'ai absolument rien entendu."
  },
  AvgCommunicate_134181_Content_5 = {
    Text = "Alors c'est mon propre Baiser de la Muse. La beauté de l'océan a désormais fusionné avec mon âme."
  },
  AvgCommunicate_134181_Content_6 = {
    Text = "Vous m'apportez toujours plus de Clairvoyance créative. Je vous apprécie vraiment de plus en plus chaque jour."
  },
  AvgCommunicate_134181_Content_7 = {
    Text = "Accepteriez-vous d'être mon assistant permanent ? Vous n'auriez rien à faire — juste venir à mon atelier chaque jour, vous asseoir un moment, prendre une tasse de thé et discuter."
  },
  AvgCommunicate_134181_Content_8 = {
    Text = "Bien que je sois sincèrement honoré par votre gentillesse, mais... vais-je me réveiller un jour pour découvrir que j'ai été transformé en sculpture de pierre ?"
  },
  AvgCommunicate_134181_Content_9 = {
    Text = "Hé hé, c'est vraiment comme ça que vous me voyez ?"
  },
  AvgCommunicate_134181_Option_13 = {
    Text = "Votre savoir-faire est trop remarquable."
  },
  AvgCommunicate_134181_Option_17 = {
    Text = "Pas question !!!"
  },
  AvgCommunicate_134181_Option_4 = {
    Text = "Non, pas du tout."
  },
  AvgCommunicate_134181_Option_8 = {
    Text = "Vais-je être transformé en sculpture ?"
  },
  AvgCommunicate_134187_Content_1 = {
    Text = "Petit chiot, comment vas-tu ces derniers temps ?"
  },
  AvgCommunicate_134187_Content_10 = {
    Text = "Ne fais rien d›irréfléchi. Quoi qu›il arrive, le Bassin Noir te gardera fermement emprisonné."
  },
  AvgCommunicate_134187_Content_11 = {
    Text = "Tu n›as absolument aucune idée du genre de pouvoir que la connaissance peut m›accorder."
  },
  AvgCommunicate_134187_Content_12 = {
    Text = "Ce cadeau me plaît beaucoup. Alors, mon très cher élève, je vais t›offrir un cadeau en retour."
  },
  AvgCommunicate_134187_Content_13 = {Text = "...?"},
  AvgCommunicate_134187_Content_14 = {
    Text = "Devine. Devine jusqu›où je peux aller maintenant."
  },
  AvgCommunicate_134187_Content_15 = {
    Text = "Devine si tes arrogantes mesures de restriction peuvent réellement faire effet."
  },
  AvgCommunicate_134187_Content_16 = {
    Text = "Devine si la vérité que j›ai entrevue, maintenant que j›ai obtenu ce pouvoir, sera implantée dans la cognition de chacun d›entre vous."
  },
  AvgCommunicate_134187_Content_17 = {
    Text = "C›est le devoir le plus important. Très bientôt, très bientôt, je viendrai le corriger en personne."
  },
  AvgCommunicate_134187_Content_2 = {
    Text = "Ton audace me surprend véritablement — tu as réellement osé envoyer un cadeau de ce calibre."
  },
  AvgCommunicate_134187_Content_3 = {
    Text = "Me croirais-tu si je disais qu›il y a eu un grave accident lors du transport de matériaux rares..."
  },
  AvgCommunicate_134187_Content_5 = {
    Text = "Tu me sous-estimes, et tu sous-estimes Mizag."
  },
  AvgCommunicate_134187_Content_6 = {
    Text = "Nous sommes prêts à laisser chaque Corps éveillé toucher cette limite, car nous essaierons tous les moyens pour empêcher la destruction."
  },
  AvgCommunicate_134187_Content_7 = {
    Text = "C›est... la plus grande différence entre cette Doll enseignante, et nous, et toi — même si la destruction est inéluctable, nous ne nous y soumettrons jamais."
  },
  AvgCommunicate_134187_Content_8 = {
    Text = "Pfff, comment n›ai-je pas remarqué avant que le système éducatif de Mizag produit des imbéciles."
  },
  AvgCommunicate_134187_Content_9 = {
    Text = "Heureusement, un imbécile si pitoyablement stupide qu›il est difficile de ne pas éprouver de l›affection."
  },
  AvgCommunicate_134187_Option_13 = {Text = "...?"},
  AvgCommunicate_134187_Option_3 = {
    Text = "C›était un accident."
  },
  AvgCommunicate_134187_Option_5 = {
    Text = "C›était intentionnel."
  },
  AvgCommunicate_134188_Content_1 = {
    Text = "Règles, trop cool ! Bang — ! Boum — ! Kaboom — !"
  },
  AvgCommunicate_134188_Content_11 = {
    Text = "Si c'est le cas, les frais de réparation de l'école ce mois-ci devraient diminuer considérablement..."
  },
  AvgCommunicate_134188_Content_12 = {
    Text = "Mauvais devoirs, apparaître, Mosk, écraser mort !"
  },
  AvgCommunicate_134188_Content_13 = {
    Text = "Non, tu ne peux pas considérer les devoirs comme un ennemi aussi !"
  },
  AvgCommunicate_134188_Content_14 = {
    Text = "Mosk, Mosk ?"
  },
  AvgCommunicate_134188_Content_16 = {
    Text = "Gardien, ici Nautila. Soyez rassuré, Mosk a été maîtrisé. Les devoirs et la salle de classe sont tous les deux sains et saufs."
  },
  AvgCommunicate_134188_Content_17 = {
    Text = "Dieu merci..."
  },
  AvgCommunicate_134188_Content_18 = {
    Text = "Nautila, Mizag, Mosk et moi aurons toujours besoin de vous."
  },
  AvgCommunicate_134188_Content_2 = {
    Text = "Rappelle-toi la Règle n°1 du Code Mizag, Édition Spéciale Mosk : En aucun cas quiconque n'est autorisé à pointer une arme létale sur une personne dans le Mizag."
  },
  AvgCommunicate_134188_Content_5 = {
    Text = "%player%, t'inquiète pas, Mosk, contrôle, peut faire !"
  },
  AvgCommunicate_134188_Content_6 = {
    Text = "Mosk, retenir, Vortex."
  },
  AvgCommunicate_134188_Content_7 = {
    Text = "Mosk, ami, câlins."
  },
  AvgCommunicate_134188_Content_8 = {
    Text = "Mosk, ennemi, bang — ! boum — ! kaboom — !"
  },
  AvgCommunicate_134188_Option_2 = {
    Text = "La sécurité avant tout."
  },
  AvgCommunicate_134189_Content_1 = {
    Text = "Nous sommes compagnons d'armes, alors je ne dirai pas merci."
  },
  AvgCommunicate_134189_Content_2 = {
    Text = "Mon arme a été aiguisée au maximum — assez tranchante pour trancher la gorge d'un maître esclave en un instant."
  },
  AvgCommunicate_134189_Content_3 = {
    Text = "Le sens de la résistance, le sens de la vengeance, le sens du combat — je continue d'y réfléchir encore aujourd'hui."
  },
  AvgCommunicate_134189_Content_4 = {
    Text = "Peut-être que j'y réfléchirai pour le reste de ma vie, jusqu'au jour où je ne pourrai plus me tenir debout."
  },
  AvgCommunicate_134189_Content_5 = {
    Text = "Au moins, je ne suis plus perdu."
  },
  AvgCommunicate_134189_Content_6 = {
    Text = "À mes compagnons d'armes."
  },
  AvgCommunicate_134189_Content_7 = {
    Text = "Aux compagnons d'armes. C'est toi qui m'as libéré, qui m'as donné la Résilience de continuer."
  },
  AvgCommunicate_134189_Content_8 = {
    Text = "Chaque fois que tu auras besoin de moi, je te confierai toujours mes arrières et combattrai à tes côtés — Combattre ensemble."
  },
  AvgCommunicate_134189_Content_9 = {
    Text = "Continuons à combattre ensemble — pour la vengeance qui doit être accomplie, et pour le frisson du combat lui-même."
  },
  AvgCommunicate_134189_Option_6 = {
    Text = "Aux compagnons d'armes."
  },
  AvgCommunicate_134201_Content_1 = {
    Text = "Gardien, j'ai soumis une demande au bureau des affaires académiques. Je serai absente de l'entraînement pendant les trois prochains jours."
  },
  AvgCommunicate_134201_Content_10 = {
    Text = "Mais après avoir franchi cette limite, j'ai compris."
  },
  AvgCommunicate_134201_Content_11 = {Text = "Quoi ?"},
  AvgCommunicate_134201_Content_13 = {
    Text = "Je suis la lame de l'avant-garde. C'est précisément parce que j'ai toujours emprunté ce Chemin que j'ai pu tous vous rencontrer — vous rencontrer."
  },
  AvgCommunicate_134201_Content_14 = {
    Text = "Ma quête fait en sorte que je ne suis jamais seule. Peut-être ne pourrons-nous jamais l'atteindre, mais Tant que nous persévérons, je peux rapprocher ce monde idéal et juste — ne serait-ce qu'un tout petit peu."
  },
  AvgCommunicate_134201_Content_15 = {
    Text = "Moi-même comme lame, jusqu'à ce que nous atteignions l'utopie où Tout le monde pourra vivre dans la lumière."
  },
  AvgCommunicate_134201_Content_16 = {
    Text = "Quelle vision grandiose, Instructrice Alva ! Je vous soutiendrai inconditionnellement !"
  },
  AvgCommunicate_134201_Content_17 = {
    Text = "Merveilleux. Dans ce cas, je vais utiliser ces trois jours pour élaborer un programme d'entraînement encore plus rigoureux et éprouvant."
  },
  AvgCommunicate_134201_Content_18 = {
    Text = "Vous serez parmi les premiers à l'essayer. Soyez rassuré, je serai présente tout du long en tant que partenaire d'entraînement, progressant aux côtés de tout le monde."
  },
  AvgCommunicate_134201_Content_19 = {
    Text = "Attendez, je pense qu'on pourrait en discuter un peu plus..."
  },
  AvgCommunicate_134201_Content_2 = {
    Text = "Y a-t-il eu un problème avec les matériaux ? Vous allez bien ? Avez-vous besoin d'aide ?"
  },
  AvgCommunicate_134201_Content_3 = {
    Text = "Non, bien au contraire. Tout s'est bien passé. J'ai connu des améliorations différentes de celles d'avant."
  },
  AvgCommunicate_134201_Content_4 = {
    Text = "Je ne suis pas sûr de comprendre..."
  },
  AvgCommunicate_134201_Content_5 = {
    Text = "Je... après avoir quitté l'armée, j'ai erré pendant très longtemps."
  },
  AvgCommunicate_134201_Content_6 = {
    Text = "Je ne sais pas pour quoi je devrais me battre. La seule chose que je peux suivre, c'est un sens de la justice — un sens dont je ne suis même pas certaine de pouvoir un jour atteindre l'idéal."
  },
  AvgCommunicate_134201_Content_7 = {
    Text = "J'espère me tenir du côté des faibles, du côté de ceux qui ne peuvent pas s'exprimer, du côté de ceux qui sont traités injustement."
  },
  AvgCommunicate_134201_Content_8 = {
    Text = "Mais je sais aussi pertinemment que, peu importe à quel point je deviens forte, il y aura toujours des choses face auxquelles je serai impuissant — tout comme même si le temps était inversé, je n'aurais pas pu empêcher la chute d'Aran."
  },
  AvgCommunicate_134201_Content_9 = {
    Text = "Instructrice Alva..."
  },
  AvgCommunicate_134201_Option_2 = {
    Text = "Que s'est-il passé ?"
  },
  AvgCommunicate_134202_Content_1 = {
    Text = "Merci de m›avoir confié quelque chose d›aussi précieux, %player%."
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "Je crois qu›il essaie de me dire qu›en plus de laisser des ombres dans la mémoire, le monde peut aussi se mesurer par les pas que l›on fait."
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "Si je ne peux pas le retenir, alors je continuerai simplement à avancer, toujours, toujours — le monde et vous tous vous en souviendrez pour moi."
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "Même moi, je ne peux pas m›empêcher de me sentir galvanisée..."
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "Je deviendrai la plus grande exploratrice, la plus incroyable maître mécanicienne. %player%, je voudrais t›adresser une invitation en bonne et due forme."
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "Le jour où tout sera résolu, s›il te plaît, pars à l›aventure avec moi — créons ensemble de précieux souvenirs dans ce monde."
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "Peut-être que ce jour est lointain, ou peut-être que c›est demain."
  },
  AvgCommunicate_134202_Content_16 = {
    Text = "Cette invitation est valable pour toujours. Je m'en souviendrai, c'est certain."
  },
  AvgCommunicate_134202_Content_2 = {
    Text = "Il m›a fallu très, très longtemps pour les absorber... Maintenant, j›ai l›impression d›être redevenue entière."
  },
  AvgCommunicate_134202_Content_3 = {
    Text = "Alors, ça veut dire que tu n›oublieras plus les choses ?"
  },
  AvgCommunicate_134202_Content_4 = {
    Text = "Hmm, laisse-moi réfléchir..."
  },
  AvgCommunicate_134202_Content_5 = {
    Text = "Haha, je ne m›en souviens toujours pas !"
  },
  AvgCommunicate_134202_Content_6 = {
    Text = "Pourquoi tu as l›air si fière de ça !"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "Parce que, même si j›oublie encore beaucoup de choses, dans le passé comme maintenant, %player% a toujours été là pour me rappeler et m›aider à me souvenir."
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "Qui je suis, où je suis, ce que je dois faire — les personnes en qui j›ai le plus confiance me le diront."
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "C›est peut-être pour ça qu›après avoir compris la Règle finale, même si ma mémoire ne s›est pas améliorée, j›ai l›impression que le monde entier s›est déployé devant mes yeux comme une vaste carte."
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "Ta mémoire s›est améliorée ?"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "J'ai cru un jour que c'était Seulement en jouant le rôle du Spectateur que je pouvais éprouver la joie de l'inconnu."
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "Je ne comprends pas tout à fait... mais cela semble être une bonne chose ?"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "Depuis que j'ai quitté cette porte, c'est la plus grande fortune que j'aie rencontrée."
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "Gardien, c'est la surprise que vous m'avez offerte — une surprise que je n'aurais jamais pu prévoir."
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "Le Destin ne déçoit jamais ceux qui donnent généreusement."
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "Je ne peux toucher les fils de votre Destin, mais quand vous vous battrez pour lui, mon rouet tournera à jamais pour vous."
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "Cela fait si longtemps... si longtemps que je ne m'étais pas sentie ainsi..."
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "Quelle sensation ?"
  },
  AvgCommunicate_134208_Content_4 = {
    Text = "La nouveauté."
  },
  AvgCommunicate_134208_Content_5 = {
    Text = "L'éclosion silencieuse des bourgeons, l'entrelacement des mots sur le papier, la douce dérive des nuages dans le vent..."
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "Et bien sûr, les gens — ces bras tendus, ces larmes qui tombent, ces battements de cœur semblables à des tambours de guerre ou à des gouttes de pluie..."
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "Je vois plus qu'avant, et pourtant mon regard se pose plus bas qu'avant."
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "Mes yeux ne s'attardent plus dans le ciel, Gardien. Ils sont descendus — se posant sur chaque rue, auprès de chaque passant."
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "Désormais, je n'ai plus besoin de jouer un rôle. Je peux véritablement exister en tant qu'individu."
  },
  AvgCommunicate_134208_Option_10 = {
    Text = "Cela semble être une bonne chose ?"
  },
  AvgCommunicate_134208_Option_3 = {
    Text = "Quelle sensation ?"
  },
  AvgCommunicate_134242_Content_1 = {
    Text = "Texte temporaire"
  },
  AvgCommunicate_134245_Content_1 = {
    Text = "Ça semble être quelque chose de très précieux, tu es sûr de vouloir le donner à Saya ?"
  },
  AvgCommunicate_134245_Content_12 = {
    Text = "Donc ce monde a aussi ses beaux côtés, même si c'est un peu différent du monde dont je me souviens."
  },
  AvgCommunicate_134245_Content_13 = {
    Text = "La façon dont il est constitué, la logique qui le régit — Saya est maintenant capable de tout comprendre."
  },
  AvgCommunicate_134245_Content_14 = {
    Text = "Alors, Réécrire ce monde pour en faire celui dont je me souviens, la Saya d'aujourd'hui pourrait peut-être le faire très facilement."
  },
  AvgCommunicate_134245_Content_16 = {
    Text = "Même si je sais que tu plaisantes, je t'en supplie, ne fais jamais une chose pareille."
  },
  AvgCommunicate_134245_Content_17 = {Text = "新增"},
  AvgCommunicate_134245_Content_18 = {
    Text = "Pourquoi tu ne dis plus rien, c'est une blague, n'est-ce pas ? Ne reste pas silencieux dans un moment pareil !"
  },
  AvgCommunicate_134245_Content_19 = {
    Text = "Euh, tout à l'heure je suis juste sortie un moment pour observer tout le monde sous un nouvel angle..."
  },
  AvgCommunicate_134245_Content_2 = {
    Text = "Je fais confiance à Saya, donc ça ne pose aucun problème."
  },
  AvgCommunicate_134245_Content_20 = {
    Text = "C'est comme ça, tant que ceux qui connaissent Saya et la traitent avec gentillesse sont encore en vie."
  },
  AvgCommunicate_134245_Content_21 = {
    Text = "Je ne saurais pas dire ce qui cloche, mais j'ai vaguement l'impression que quelque chose ne va pas tout à fait."
  },
  AvgCommunicate_134245_Content_22 = {
    Text = "Et en ce moment, tu arbores sûrement encore cette expression de quelqu'un qui vient de réussir une farce !"
  },
  AvgCommunicate_134245_Content_23 = {
    Text = "Ne t'inquiète pas, je m'entendrai bien avec tout le monde dans ce monde."
  },
  AvgCommunicate_134245_Content_24 = {
    Text = "Hmm... mais le monde dans les souvenirs de Saya est peut-être plus intéressant. On y va tous ensemble ? On devrait pouvoir le faire maintenant !"
  },
  AvgCommunicate_134245_Content_25 = {
    Text = "Cette phrase est encore plus effrayante !"
  },
  AvgCommunicate_134245_Content_3 = {
    Text = "Si cela peut t'aider à mieux comprendre ce monde, ça devrait aussi être d'une grande aide pour les recherches sur «comment arrêter la Fusion»."
  },
  AvgCommunicate_134245_Content_4 = {
    Text = "Après tout, tu es vraiment très forte en matière d'apprentissage et de recherche..."
  },
  AvgCommunicate_134245_Content_5 = {
    Text = "En fait, c'était une sorte d'accident d'approvisionnement... mais il est probablement trop tard pour revenir en arrière maintenant ?"
  },
  AvgCommunicate_134245_Content_6 = {
    Text = "Hein ? Dans ce cas, faudrait-il le rendre ? Je suis un peu embêtée."
  },
  AvgCommunicate_134245_Content_7 = {
    Text = "Quoi ? Je peux le rendre ?"
  },
  AvgCommunicate_134245_Content_8 = {
    Text = "Hmm, laisse Saya réfléchir..."
  },
  AvgCommunicate_134245_Content_9 = {
    Text = "La réponse est — non."
  },
  AvgCommunicate_134245_Option_2 = {
    Text = "Pas de problème"
  },
  AvgCommunicate_134245_Option_5 = {
    Text = "C'est un accident"
  },
  AvgCommunicate_134246_Content_1 = {
    Text = "Mon cher, très aimé, très magnifique bienfaiteur~"
  },
  AvgCommunicate_134246_Content_10 = {
    Text = "Laisse-moi vérifier."
  },
  AvgCommunicate_134246_Content_11 = {
    Text = "Laisse-moi vérifier les données de fluctuation de ton Indice Gnostique."
  },
  AvgCommunicate_134246_Content_12 = {
    Text = "Tiens donc — notre Caraboo n'a pas menti cette fois."
  },
  AvgCommunicate_134246_Content_13 = {
    Text = "Hé hé, tu crois enfin la pauvre petite Caraboo, n'est-ce pas ?"
  },
  AvgCommunicate_134246_Content_14 = {
    Text = "S'il te plaît, continue d'investir généreusement en moi — pour que je puisse rapporter à mon cher bienfaiteur cent, mille fois la mise plus tard !"
  },
  AvgCommunicate_134246_Content_15 = {
    Text = "Encore huit — non, cinq Fragments de Dégagement ! Et je t'éblouirai à nouveau, promis !"
  },
  AvgCommunicate_134246_Content_16 = {
    Text = "C'est impossible."
  },
  AvgCommunicate_134246_Content_17 = {
    Text = "Bien essayé."
  },
  AvgCommunicate_134246_Content_18 = {
    Text = "Le Professeur Doll m'a dit que les recherches sur le Dégagement des Éveilleurs ont déjà atteint leur plafond. Il n'y aura pas de nouvelle percée avant un siècle."
  },
  AvgCommunicate_134246_Content_19 = {
    Text = "Une fois qu'un Éveilleur atteint l'Axiome Absolu, il ne peut plus jamais subir le rituel de Déferlante Psychique."
  },
  AvgCommunicate_134246_Content_2 = {
    Text = "Qu'est-ce que tu veux cette fois, à déballer autant de flatteries d'un coup ?"
  },
  AvgCommunicate_134246_Content_21 = {
    Text = "Haha — j'ai dû mélanger quelque chose par accident !"
  },
  AvgCommunicate_134246_Content_22 = {
    Text = "Je t'en prie, remonte ta mémoire de cette conversation de six messages en arrière. Passe une excellente journée~"
  },
  AvgCommunicate_134246_Content_3 = {
    Text = "Oh là là, écoute-toi — tu me prends pour qui, quelqu'un qui ne se montre que quand elle veut quelque chose ?"
  },
  AvgCommunicate_134246_Content_4 = {
    Text = "C'est exactement ce que tu es..."
  },
  AvgCommunicate_134246_Content_5 = {
    Text = "Snif snif, j'ai le cœur brisé. Mon bienfaiteur me juge si mal."
  },
  AvgCommunicate_134246_Content_6 = {
    Text = "En fait, je suis venue t'apporter de bonnes nouvelles cette fois !"
  },
  AvgCommunicate_134246_Content_7 = {
    Text = "Ton investissement a porté ses fruits — avec des résultats super, super incroyables~"
  },
  AvgCommunicate_134246_Content_8 = {
    Text = "Tu vois ? Je suis une toute nouvelle moi. Renaissante, transformée, une personne complètement différente~"
  },
  AvgCommunicate_134246_Content_9 = {Text = "Vraiment ?"},
  AvgCommunicate_134246_Option_10 = {
    Text = "Laisse-moi vérifier."
  },
  AvgCommunicate_134246_Option_16 = {
    Text = "C'est impossible."
  },
  AvgCommunicate_134246_Option_17 = {
    Text = "Bien essayé."
  },
  AvgCommunicate_134246_Option_9 = {Text = "Vraiment ?"},
  AvgCommunicate_134247_Content_1 = {
    Text = "Texte temporaire"
  },
  AvgCommunicate_134249_Content_1 = {Text = "Gardien..."},
  AvgCommunicate_134249_Content_10 = {
    Text = "Mmm... cette sensation est de retour. J'ai soudainement si chaud, si soif. Mon estomac, Dedans mon estomac,"
  },
  AvgCommunicate_134249_Content_11 = {
    Text = "Gardien, est-ce que je suis malade ? Mon estomac devient tout mou, mon cœur devient tout mou, tout est mou. Je n'arrive plus à rien distinguer, c'est comme si je fondais..."
  },
  AvgCommunicate_134249_Content_12 = {
    Text = "Respire profondément, Leigh. Tu ne vas pas fondre."
  },
  AvgCommunicate_134249_Content_13 = {
    Text = "C'est une réaction normale dans les relations intimes chez les humains. Pas besoin de médicaments... et pas besoin d'aller chercher un fouet non plus !"
  },
  AvgCommunicate_134249_Content_14 = {
    Text = "Hein ? Même pas un fouet ? Comme c'est décevant."
  },
  AvgCommunicate_134249_Content_16 = {
    Text = "...Euh, si tu en as vraiment besoin, va peut-être demander à Pandia..."
  },
  AvgCommunicate_134249_Content_17 = {Text = "Hé hé."},
  AvgCommunicate_134249_Content_18 = {
    Text = "Gardien, je vais essayer de ne plus me tapir devant ta Porte."
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "Mais... est-ce que tu pourrais peut-être laisser une Porte ouverte pour moi de temps en temps la nuit ? Une fenêtre ferait l'affaire aussi."
  },
  AvgCommunicate_134249_Content_2 = {
    Text = "La Chair de mon frère et mon corps sont plus compatibles qu'avant. Elle respire doucement sous ma peau, sans plus hurler constamment pour me déchirer."
  },
  AvgCommunicate_134249_Content_20 = {
    Text = "Je n'entrerai pas Dedans. Seulement savoir qu'il y a un Chemin qui mène à toi à tout moment m'aiderait à dormir plus paisiblement."
  },
  AvgCommunicate_134249_Content_3 = {
    Text = "L'envie de Sang ne fait plus autant mal non plus. Avant, c'était comme quelque chose coincé dans ma gorge — un Étranglement si je ne buvais pas. Maintenant, on dirait... qu'elle veut bien m'attendre un peu."
  },
  AvgCommunicate_134249_Content_4 = {
    Text = "Ce sont vraiment de bonnes nouvelles."
  },
  AvgCommunicate_134249_Content_5 = {
    Text = "Les nuits à l'école sont si calmes. La fontaine clapote doucement."
  },
  AvgCommunicate_134249_Content_6 = {
    Text = "Gardien, tu m'as offert tant de trésors. Est-ce que je le mérite vraiment ?"
  },
  AvgCommunicate_134249_Content_7 = {
    Text = "Bien sûr que oui."
  },
  AvgCommunicate_134249_Content_8 = {
    Text = "...Tu réponds toujours si vite."
  },
  AvgCommunicate_134249_Content_9 = {
    Text = "Leigh, tu nous as tellement aidés. C'est le moins que je puisse faire."
  },
  AvgCommunicate_134250_Content_1 = {
    Text = "Vous ne savez pas comment ça finit quand on élève une bête ?"
  },
  AvgCommunicate_134250_Content_10 = {
    Text = "Je me demande souvent — es-tu vraiment tel que tu parais en surface, ou..."
  },
  AvgCommunicate_134250_Content_11 = {
    Text = "As-tu joué la comédie depuis le début, tout comme ces maîtres d'esclaves ?"
  },
  AvgCommunicate_134250_Content_12 = {
    Text = "Qu'en penses-tu ? Je ne suis pas doué pour jouer la comédie, et je ne suis pas doué pour mentir."
  },
  AvgCommunicate_134250_Content_13 = {
    Text = "Tu peux te fier à tes propres sentiments. Je n'essaierai pas de te convaincre, et je ne te forcerai à rien."
  },
  AvgCommunicate_134250_Content_14 = {
    Text = "Comme l'autre toi l'a dit un jour — nous sommes amis, nous sommes camarades."
  },
  AvgCommunicate_134250_Content_15 = {
    Text = "Tch, ne me compare pas à cette faible idiote."
  },
  AvgCommunicate_134250_Content_16 = {
    Text = "J'en ai plus qu'assez de la trahison. Je n'ai pas besoin d'amis."
  },
  AvgCommunicate_134250_Content_17 = {
    Text = "Et je ne veux pas non plus de tes promesses."
  },
  AvgCommunicate_134250_Content_18 = {
    Text = "Tant que tu me fournis plus de Force, ça me suffit."
  },
  AvgCommunicate_134250_Content_19 = {
    Text = "Et je me vengerai de tes ennemis pour toi."
  },
  AvgCommunicate_134250_Content_2 = {
    Text = "Une bête devenue forte brisera ses chaînes et — GRAWR — tranchera la gorge de son gardien."
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "Jusqu'au jour où tu me trahiras vraiment... même si tu fuis au bout du monde, je te traquerai et te trancherai la gorge d'un coup de crocs."
  },
  AvgCommunicate_134250_Content_3 = {
    Text = "En ce moment, le Lien entre vous et moi me semble encore plus Fragile que des chaînes de fer."
  },
  AvgCommunicate_134250_Content_4 = {
    Text = "Vous n'avez pas peur ?"
  },
  AvgCommunicate_134250_Content_5 = {
    Text = "Vous êtes libre. Notre Lien n'est pas fait pour vous retenir."
  },
  AvgCommunicate_134250_Content_6 = {
    Text = "Il n'y a aucune raison d'avoir peur."
  },
  AvgCommunicate_134250_Content_7 = {Text = "新增"},
  AvgCommunicate_134250_Content_8 = {
    Text = "Tch, belles paroles."
  },
  AvgCommunicate_134250_Content_9 = {
    Text = "Cela dit, je t'observe depuis longtemps, et je ne t'ai pas encore vu montrer de Faille."
  },
  AvgCommunicate_134250_Option_12 = {
    Text = "Que penses-tu ?"
  },
  AvgCommunicate_134250_Option_5 = {
    Text = "Vous êtes libre"
  },
  AvgCommunicate_134263_Content_1 = {Text = "Gardien !!"},
  AvgCommunicate_134263_Content_10 = {
    Text = "Bien sûr. Je n'ai jamais douté que tu deviendrais plus fort."
  },
  AvgCommunicate_134263_Content_11 = {Text = "新增"},
  AvgCommunicate_134263_Content_12 = {
    Text = "Tu es vraiment quelqu'un d'étrange."
  },
  AvgCommunicate_134263_Content_13 = {
    Text = "Dans un moment pareil, tu ne devrais pas dire quelque chose comme « Tu vois, je savais que j'avais l'œil pour repérer les talents » ou « Comme prévu, tu ne m'as pas déçu » ?"
  },
  AvgCommunicate_134263_Content_14 = {
    Text = "Pourquoi es-tu si calme à ce sujet ?"
  },
  AvgCommunicate_134263_Content_16 = {
    Text = "Euh... parce que tu as travaillé si dur. Devenir plus fort, c'est seulement naturel. Qu'y a-t-il à dire ?"
  },
  AvgCommunicate_134263_Content_17 = {
    Text = "Les 50 dollars que tu m'as remboursés il y a deux ans, et les 54 de l'année dernière... je les ai tous gardés."
  },
  AvgCommunicate_134263_Content_18 = {
    Text = "Pourquoi les garder... Dépense-les, seulement."
  },
  AvgCommunicate_134263_Content_19 = {
    Text = "Laisse tomber, oublie ça. Il y a quelque chose de plus important."
  },
  AvgCommunicate_134263_Content_2 = {
    Text = "Ces marques sont brûlantes. La Force de l'Aequor coule sous ma peau, bien plus clairement qu'avant !"
  },
  AvgCommunicate_134263_Content_20 = {
    Text = "Va au bord du lac, maintenant. Je t'attends ici."
  },
  AvgCommunicate_134263_Content_21 = {
    Text = "Quel est le problème ?"
  },
  AvgCommunicate_134263_Content_22 = {
    Text = "Tu verras quand tu seras là."
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "D'accord... alors attends-moi un peu. Il pleut dehors en ce moment. Je dois retourner au dortoir chercher un parapluie."
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "Arrête de traîner. Tu n'auras pas besoin de parapluie pour ce qu'on va faire ensuite."
  },
  AvgCommunicate_134263_Content_25 = {
    Text = "Tu ne seras pas mouillé par la pluie. Mes ailes membraneuses sont assez grandes."
  },
  AvgCommunicate_134263_Content_3 = {
    Text = "Tu as la moindre idée de ce que ça fait ?!"
  },
  AvgCommunicate_134263_Content_4 = {
    Text = "Bref, c'est incroyable, au-delà des mots. Vous autres humains ne pouvez probablement même pas le concevoir."
  },
  AvgCommunicate_134263_Content_5 = {
    Text = "...Caecus, tu vas bien ?"
  },
  AvgCommunicate_134263_Content_6 = {
    Text = "Bien sûr que je vais bien. Jamais été en meilleure forme."
  },
  AvgCommunicate_134263_Content_7 = {
    Text = "Je te l'ai dit il y a longtemps, ton investissement ne serait pas gaspillé. Mon Sang ne ment pas."
  },
  AvgCommunicate_134263_Content_8 = {Text = "Je sais."},
  AvgCommunicate_134263_Content_9 = {
    Text = "...C'est tout ?"
  },
  AvgCommunicate_134264_Content_1 = {
    Text = "Veuillez me pardonner, L'Envoyé Pâle. Je n'étais pas suffisamment préparé pour cela et il semble que je vous ai effrayé."
  },
  AvgCommunicate_134264_Content_10 = {
    Text = "Il me suffit de penser à cela pour que la paix dans mon cœur surpasse de loin les tourments de la chair."
  },
  AvgCommunicate_134264_Content_11 = {
    Text = "Je comprends. Je n'ai peut-être pas d'aussi nobles aspirations. Mais ne serait-ce que pour toi, pour mes amis..."
  },
  AvgCommunicate_134264_Content_12 = {
    Text = "Tant que cela permet d'atteindre ce monde idéal et paisible, quoi qu'il faille faire, je ferai tout mon possible."
  },
  AvgCommunicate_134264_Content_13 = {
    Text = "Merci à toi, Messager Pâle."
  },
  AvgCommunicate_134264_Content_14 = {
    Text = "Puissent toutes les souffrances trouver un jour leur fin, et puissions-nous toujours cheminer côte à côte."
  },
  AvgCommunicate_134264_Content_15 = {
    Text = "Que la bénédiction du Dieu Père descende également sur tout ce qui t'est cher."
  },
  AvgCommunicate_134264_Content_2 = {
    Text = "Ouf... Tant mieux si tu vas bien. Je ne m'attendais pas à ce que la compréhension des lois produise un tel effet."
  },
  AvgCommunicate_134264_Content_3 = {
    Text = "Ne t'inquiète pas pour moi, c'est la mission pour laquelle je suis venu en ce monde."
  },
  AvgCommunicate_134264_Content_4 = {
    Text = "Avant même d'atteindre le sommet, avant que le Dieu Père ne me révèle ces mystères insondables, j'avais déjà consacré ce corps à cette voie."
  },
  AvgCommunicate_134264_Content_5 = {
    Text = "Rassembler les souffrances de tous les êtres en un seul corps, guider toute chose vers une terre pure et immaculée où la souffrance n'existe plus — ce n'est pas un fardeau. C'est la grâce que le Dieu Père m'a accordée."
  },
  AvgCommunicate_134264_Content_6 = {
    Text = "J'ai toujours pensé que tu portais un fardeau bien trop lourd. La souffrance des autres se dissipe, mais le prix à payer..."
  },
  AvgCommunicate_134264_Content_7 = {
    Text = "Mon Feu Pâle, tu possèdes un cœur si tendre."
  },
  AvgCommunicate_134264_Content_8 = {
    Text = "Cependant, rassure-toi. La souffrance charnelle est pour moi ce que les épines sont à la terre : plus elles s'enfoncent profondément, plus fermement je m'enracine."
  },
  AvgCommunicate_134264_Content_9 = {
    Text = "Si en ce monde une seule âme souffre encore, elle ne sera jamais seule. Si une seule âme n'a pas encore quitté l'océan de souffrances, jamais je n'atteindrai l'autre rive avant elle."
  },
  AvgCommunicate_134264_Option_11 = {
    Text = "Je comprends"
  },
  AvgCommunicate_134264_Option_6 = {Text = "Mais..."},
  AvgCommunicate_134265_Content_1 = {
    Text = "Haha, exaltant, absolument exaltant !"
  },
  AvgCommunicate_134265_Content_10 = {
    Text = "Demande à n'importe lequel de mes subordonnés — ils me connaissent depuis des années. Quand est-ce qu'ils m'ont déjà vue faire quelque chose comme ça !"
  },
  AvgCommunicate_134265_Content_11 = {
    Text = "Ah, maintenant ma Force est encore plus intense. La prochaine fois, je devrai faire attention à ne pas te brûler."
  },
  AvgCommunicate_134265_Content_12 = {
    Text = "Quoi... c'était toi ? Alors, ces fois où mes vêtements avaient été changés... c'était toi aussi ?"
  },
  AvgCommunicate_134265_Content_13 = {
    Text = "Ouais, tes vêtements étaient tout sales à cause de l'alcool et de la nourriture. Je ne pouvais pas te laisser ramper dans ton lit comme ça."
  },
  AvgCommunicate_134265_Content_14 = {
    Text = "Merci, Kadigula."
  },
  AvgCommunicate_134265_Content_15 = {
    Text = "Mais la prochaine fois, tu pourrais juste me secouer pour me réveiller..."
  },
  AvgCommunicate_134265_Content_16 = {
    Text = "Oh, tu es gênée ? T'en fais pas — regarde comme on est proches."
  },
  AvgCommunicate_134265_Content_17 = {
    Text = "Changer des vêtements, c'est rien du tout — même s'il fallait que je traverse le feu et brave tous les dangers pour toi, ça ne poserait aucun problème !"
  },
  AvgCommunicate_134265_Content_18 = {
    Text = "Si ça te gêne vraiment, tu n'as qu'à m'aider à me changer la prochaine fois et on sera quittes."
  },
  AvgCommunicate_134265_Content_19 = {
    Text = "...Rien de tout ça n'a de sens, et c'est exactement pour ça que je n'ai aucune idée de quoi répondre !"
  },
  AvgCommunicate_134265_Content_2 = {
    Text = "Un sentiment d›allégresse sans précédent — en cet instant, je suis le soleil !"
  },
  AvgCommunicate_134265_Content_3 = {
    Text = "Petite, je suis vraiment de plus en plus impressionnée par toi."
  },
  AvgCommunicate_134265_Content_4 = {
    Text = "Tu vois ? Et ce n'est que le début."
  },
  AvgCommunicate_134265_Content_5 = {
    Text = "Oh ? Il semblerait qu'on t'ait toujours traitée comme une petite pendant tout ce temps. Ce n'est vraiment plus très approprié."
  },
  AvgCommunicate_134265_Content_6 = {
    Text = "Hmm... Désormais, je suppose qu'on devrait commencer à t'appeler grande à la place."
  },
  AvgCommunicate_134265_Content_7 = {
    Text = "C'est quoi ‹grande' !? Tu te moques encore de moi avec ton air impassible, pas vrai ?"
  },
  AvgCommunicate_134265_Content_8 = {
    Text = "Hahaha, j'y peux rien. Après tout, chaque fois qu'on sort boire, tu es toujours la première à tomber dans les pommes."
  },
  AvgCommunicate_134265_Content_9 = {
    Text = "Alors je n'avais pas d'autre choix que de te porter jusqu'au dortoir à chaque fois, t'enlever tes chaussures, te border et t'essuyer le visage."
  },
  AvgCommunicate_134265_Option_12 = {
    Text = "C'était toi ?"
  },
  AvgCommunicate_134265_Option_7 = {Text = "?!"},
  AvgCommunicate_134267_Content_1 = {
    Text = "%player%, ma musique est devenue encore plus parfaite."
  },
  AvgCommunicate_134267_Content_10 = {
    Text = "Ma musique était comme une machine fonctionnant avec précision, et elle m'a autrefois permis de faire partie du plus bel orchestre. Bien sûr, j'en étais fier."
  },
  AvgCommunicate_134267_Content_11 = {
    Text = "Lui, c'était différent. Il n'était pas fait pour l'Ensemble. Sa musique était destinée à briller seule dans le ciel, comme le soleil ou la Lune."
  },
  AvgCommunicate_134267_Content_12 = {
    Text = "Je l'ai toujours observé, couru après lui, mais j'ai à jamais perdu la chance d'échanger des mots avec lui."
  },
  AvgCommunicate_134267_Content_13 = {
    Text = "Mais... cette interprétation qui a désormais atteint la perfection ultime est probablement la meilleure réponse que je puisse présenter après une vie entière de quête."
  },
  AvgCommunicate_134267_Content_14 = {
    Text = "C'est si émouvant... Comment pouvez-vous avoir un tel passé ? Une histoire légendaire de musiciens reflétant mutuellement leur éclat à l'apogée de leur art..."
  },
  AvgCommunicate_134267_Content_15 = {
    Text = "Mm, juste quelques réflexions parfaitement ordinaires. Ce n›est vraiment pas aussi dramatique que ça."
  },
  AvgCommunicate_134267_Content_16 = {
    Text = "Quoi qu'il en soit, ce que je veux dire par-dessus tout, c'est: merci, %player%."
  },
  AvgCommunicate_134267_Content_17 = {
    Text = "Désormais, laissez-moi continuer à jouer de la flûte pour vous, vous accompagnant vers un sommeil paisible chaque nuit."
  },
  AvgCommunicate_134267_Content_2 = {
    Text = "Sans vos conseils, je n'aurais probablement jamais pu franchir cette dernière étape — calibrer les infimes erreurs qu'il était autrefois impossible pour un être humain de corriger."
  },
  AvgCommunicate_134267_Content_3 = {
    Text = "Un tempo parfait, une justesse irréprochable, tout sonne de manière si exquise..."
  },
  AvgCommunicate_134267_Content_4 = {
    Text = "En effet ! Je n'ai jamais entendu une interprétation aussi délicieuse !"
  },
  AvgCommunicate_134267_Content_5 = {
    Text = "C'est le résultat de la Résonance entre la musique et le calcul, l'instrument et le corps, le cerveau et le muscle."
  },
  AvgCommunicate_134267_Content_6 = {
    Text = "J'ai enfin prouvé qu'au bout de ce Chemin aride et fastidieux, une musique aussi parfaite peut également exister."
  },
  AvgCommunicate_134267_Content_7 = {
    Text = "Également ? Que voulez-vous dire par là ?"
  },
  AvgCommunicate_134267_Content_8 = {
    Text = "Par le passé, j'avais Une personne amie dont la musique était le fruit d'une sensibilité et d'une créativité ultimes."
  },
  AvgCommunicate_134267_Content_9 = {
    Text = "Le talent qu'il maniait avec tant d'aisance lui permettait d'improviser des compositions uniques à chaque représentation."
  },
  AvgCommunicate_134267_Option_14 = {Text = "Waaah..."},
  AvgCommunicate_134267_Option_4 = {Text = "En effet"},
  AvgCommunicate_134267_Option_7 = {Text = "Alors ?"},
  AvgCommunicate_134268_Content_1 = {
    Text = "Mon très honoré invité, comment pourrais-je jamais vous remercier pour votre générosité ?"
  },
  AvgCommunicate_134268_Content_10 = {
    Text = "Je vois, je comprends. Vous ne voulez pas de ces célébrations vulgaires — moi aussi, je pense qu›elles ne vous conviennent pas."
  },
  AvgCommunicate_134268_Content_11 = {
    Text = "Il y a une assez belle idée qui me vient. Peut-être accepteriez-vous de m›accompagner hors de Nekropolis pour accueillir quelqu›un qui approche de sa fin ?"
  },
  AvgCommunicate_134268_Content_12 = {
    Text = "Si un tel honneur nous était accordé, j›espère que vous vous joindriez à moi pour l›accueillir, le guider vers sa destination finale et son Nouveau-né guéri. Qu›en dites-vous ?"
  },
  AvgCommunicate_134268_Content_13 = {
    Text = "Bien que ce soit peut-être un peu inapproprié de demander... Je suppose que cela impliquera tout de même de la consommation au final, puisque c›est la coutume de Nekropolis."
  },
  AvgCommunicate_134268_Content_14 = {
    Text = "Mm, je ne définirais pas cela comme de la consommation — Seulement comme les histoires que vous connaissez déjà."
  },
  AvgCommunicate_134268_Content_15 = {
    Text = "C›est Seulement le plus solennel, et pourtant le plus serein des adieux."
  },
  AvgCommunicate_134268_Content_16 = {
    Text = "Je serais ravi d›y participer, Tant que je suis autorisé à passer certaines parties..."
  },
  AvgCommunicate_134268_Content_17 = {
    Text = "Bien sûr, bien sûr."
  },
  AvgCommunicate_134268_Content_18 = {
    Text = "Alors, le carrosse de Nekropolis et moi-même vous attendrons devant la Porte demain matin."
  },
  AvgCommunicate_134268_Content_2 = {
    Text = "Votre don m›a accordé la Force de protéger véritablement et fermement Nekropolis."
  },
  AvgCommunicate_134268_Content_3 = {
    Text = "La cuisine ordinaire est indigne de votre offrande, et ma collection personnelle pourrait ne pas tout à fait convenir à votre palais."
  },
  AvgCommunicate_134268_Content_4 = {
    Text = "Quel dilemme délicieusement vexant."
  },
  AvgCommunicate_134268_Content_5 = {
    Text = "Vous êtes trop aimable, Doresain."
  },
  AvgCommunicate_134268_Content_6 = {
    Text = "Nous avons traversé tant d›épreuves ensemble. Vous n›avez vraiment pas besoin de vous soucier de toutes ces formalités fastidieuses."
  },
  AvgCommunicate_134268_Content_7 = {
    Text = "Oh non, non, ce n›est en aucun cas une simple formalité. Je réfléchis sincèrement à la manière d›organiser une rencontre avec un ami cher."
  },
  AvgCommunicate_134268_Content_8 = {
    Text = "Vous avez déjà assisté à la Danse la plus extraordinaire de Nekropolis. Comment approfondir davantage le lien entre vous et nous — voilà un véritable défi."
  },
  AvgCommunicate_134268_Content_9 = {
    Text = "Euh... Si vous voulez connaître ma préférence, j›espère humblement que ce pourrait être quelque chose d›ordinaire, sans aucune frayeur..."
  },
  AvgCommunicate_134268_Option_13 = {Text = "Je suppose"},
  AvgCommunicate_134268_Option_9 = {Text = "Euh"},
  AvgCommunicate_134269_Content_1 = {
    Text = "Mon petit arbuste..."
  },
  AvgCommunicate_134269_Content_10 = {
    Text = "En mon corps, la Force de « Reproduction » s'épanouit, née de cette ultime caresse."
  },
  AvgCommunicate_134269_Content_11 = {
    Text = "Comme c'est doux, comme c'est luxuriant... Ah, je deviens réticente à l'idée de te parler à travers ce petit bloc de métal."
  },
  AvgCommunicate_134269_Content_12 = {Text = "Thais ?"},
  AvgCommunicate_134269_Content_13 = {
    Text = "Viens à mes côtés, petit arbuste. Maintenant. Tout de suite."
  },
  AvgCommunicate_134269_Content_14 = {
    Text = "Je veux tenir tes paumes chaudes, toucher ta peau douce..."
  },
  AvgCommunicate_134269_Content_15 = {
    Text = "Je veux t'étreindre sous le clair de lune, tout comme la nuit où nous avons scellé notre pacte."
  },
  AvgCommunicate_134269_Content_16 = {
    Text = "Avec ma Force toujours plus abondante, je veux fusionner avec toi, petit à petit, et laisser ta douce essence me réchauffer, petit à petit..."
  },
  AvgCommunicate_134269_Content_2 = {
    Text = "Ce que tu m'as promis... cette nuit-là, au milieu du clair de lune et de la mer de sable... notre pacte... tu es déjà en train de le tenir pour moi."
  },
  AvgCommunicate_134269_Content_3 = {
    Text = "Je suis si heureuse."
  },
  AvgCommunicate_134269_Content_4 = {
    Text = "Même si un monde où tout le monde peut vivre en paix est encore loin, je continuerai à œuvrer pour y parvenir."
  },
  AvgCommunicate_134269_Content_5 = {
    Text = "Depuis le moment où nous nous sommes rencontrés, j'ai cru en toi."
  },
  AvgCommunicate_134269_Content_6 = {
    Text = "Tu es béni par le Destin. Tu as la Force, et tu as la détermination."
  },
  AvgCommunicate_134269_Content_7 = {
    Text = "Mon petit arbuste, tu es tout simplement trop adorable quand tu affrontes le monde avec tant de sérieux."
  },
  AvgCommunicate_134269_Content_8 = {
    Text = "J'attendrai patiemment, sincèrement — Attendre le jour où notre pacte sera accompli."
  },
  AvgCommunicate_134269_Content_9 = {
    Text = "Certainement !"
  },
  AvgCommunicate_134269_Option_12 = {Text = "Thais ?"},
  AvgCommunicate_134269_Option_4 = {
    Text = "Je continuerai à travailler dur."
  },
  AvgCommunicate_134269_Option_9 = {
    Text = "Certainement !"
  },
  AvgCommunicate_134270_Content_1 = {
    Text = "Je ne te tuerai pas."
  },
  AvgCommunicate_134270_Content_10 = {
    Text = "Une fois que je t'aurai vidé de ton sang, j'irai tuer tout le monde."
  },
  AvgCommunicate_134270_Content_11 = {
    Text = "Alors je... vais essayer de rester en vie le plus longtemps possible ?"
  },
  AvgCommunicate_134270_Content_12 = {
    Text = "Ha ha ha, voilà une réponse intéressante."
  },
  AvgCommunicate_134270_Content_13 = {
    Text = "Puisque tu comptes protéger le monde entier avec ce corps si fragile."
  },
  AvgCommunicate_134270_Content_14 = {
    Text = "Alors... pourquoi est–ce que tu..."
  },
  AvgCommunicate_134270_Content_15 = {
    Text = "... Alors ?"
  },
  AvgCommunicate_134270_Content_16 = {
    Text = "D'ici là, je me contenterai d'éliminer tes ennemis."
  },
  AvgCommunicate_134270_Content_17 = {
    Text = "Au final, tu veux quand même tuer... ?!"
  },
  AvgCommunicate_134270_Content_2 = {
    Text = "...... ? Hein ? Qu'est-ce que je suis censé dire ? Merci ?"
  },
  AvgCommunicate_134270_Content_3 = {
    Text = "Ce monde est devenu terriblement ennuyeux après la chute de Rome."
  },
  AvgCommunicate_134270_Content_4 = {
    Text = "Tueries, tueries, tueries, rien que du massacre et du sang. Sans Rome, il ne reste plus rien."
  },
  AvgCommunicate_134270_Content_5 = {
    Text = "Ton cadeau m'a libéré de ces chaînes. Maintenant, je vais aller arracher un bras ou deux, ou une gorge."
  },
  AvgCommunicate_134270_Content_6 = {
    Text = "Je suis navré, Yuuhashi, mais à notre époque, tuer des gens sans autorisation spéciale est un crime."
  },
  AvgCommunicate_134270_Content_7 = {
    Text = "Et je reste ton lieur. Non seulement tu ne peux pas me tuer, mais tu ne peux pas tuer les autres non plus."
  },
  AvgCommunicate_134270_Content_8 = {Text = "Tch."},
  AvgCommunicate_134270_Content_9 = {
    Text = "Tant pis, au moins ton goût est meilleur que celui de tous ces esclavagistes."
  },
  AvgCommunicate_134271_Content_1 = {
    Text = "Gar~dien～ Tu es occupé(e) ? Il y a quelque chose que je veux te dire～"
  },
  AvgCommunicate_134271_Content_10 = {Text = "Vide ?"},
  AvgCommunicate_134271_Content_11 = {
    Text = "Ouais～ ce sentiment sombre et froid, le sentiment d'être abandonné(e) par Tout le monde qui surgit à chaque fois que le vent souffle."
  },
  AvgCommunicate_134271_Content_12 = {
    Text = "Mais maintenant, c'est tout chaud～ et lumineux～"
  },
  AvgCommunicate_134271_Content_13 = {
    Text = "C'est tout grâce à %player%."
  },
  AvgCommunicate_134271_Content_14 = {
    Text = "Alors c'est vraiment un remerciement sincère ?"
  },
  AvgCommunicate_134271_Content_15 = {
    Text = "Hmph～ Bien sûr, je peux être sérieux(se) de temps en temps, tu sais !"
  },
  AvgCommunicate_134271_Content_16 = {
    Text = "Mais en échange — tu dois passer plus de temps avec moi à partir de maintenant, d'accord ?"
  },
  AvgCommunicate_134271_Content_17 = {
    Text = "Sinon, j'utiliserai mes nouvelles compétences pour te pu～nir～ comme il faut～"
  },
  AvgCommunicate_134271_Content_18 = {
    Text = "...C'est vraiment comme ça que tu dis merci ?!"
  },
  AvgCommunicate_134271_Content_19 = {
    Text = "Oh là là, c'est la façon exclusive de Pandia d'exprimer son amour～ Mwah～ N'oublie pas d'être reconnaissant !"
  },
  AvgCommunicate_134271_Content_2 = {
    Text = "Qu'est-ce que tu manigances encore ?"
  },
  AvgCommunicate_134271_Content_3 = {
    Text = "Comment tu peux dire ça ! Je suis là pour te remercier sincèrement !"
  },
  AvgCommunicate_134271_Content_4 = {
    Text = "Ces jolies choses que tu m'as données avant... elles ont rendu mon corps si chaud, si chaud～"
  },
  AvgCommunicate_134271_Content_5 = {
    Text = "C'est comme si quelque chose de brûlant coulait sous ma peau, doux et épicé～"
  },
  AvgCommunicate_134271_Content_6 = {
    Text = "Même si je sais qu'il ne devrait pas y avoir d'Effets secondaires, tu es sûr(e) que ce n'est pas un Effet secondaire..."
  },
  AvgCommunicate_134271_Content_7 = {
    Text = "Pas question ! Cette sensation est incroyable ! Cent fois plus excitante que n'importe quel coup de fouet !"
  },
  AvgCommunicate_134271_Content_8 = {
    Text = "Et tu sais quoi, le plus incroyable, c'est que..."
  },
  AvgCommunicate_134271_Content_9 = {
    Text = "Cet endroit vide Dedans mon cœur a été comblé."
  },
  AvgCommunicate_134271_Option_14 = {Text = "Alors"},
  AvgCommunicate_134271_Option_6 = {Text = "Même si"},
  AvgCommunicate_134272_Content_1 = {
    Text = "Maître～ Comment Karen pourrait-elle jamais vous rembourser? Boissons, ménage, repas — n'hésitez pas à donner des ordres à Karen!"
  },
  AvgCommunicate_134272_Content_10 = {
    Text = "Il suffit que Garen le veuille, et la peau de Garen peut briller plus intensément que la plus précieuse des gemmes, et rayonner plus magnifiquement que la plus parfaite des perles."
  },
  AvgCommunicate_134272_Content_11 = {
    Text = "Si elle allait au bal maintenant, Karen serait assurément le centre de toute l'attention, et non plus cette petite personne que personne ne remarque."
  },
  AvgCommunicate_134272_Content_12 = {
    Text = "Même si je pense que ce n'est probablement pas l'objectif principal du renforcement de la Loi Ultime, mais..."
  },
  AvgCommunicate_134272_Content_13 = {
    Text = "Du moment que ça te rend heureuse, c'est tout ce qui compte."
  },
  AvgCommunicate_134272_Content_2 = {
    Text = "Bref, commençons par éliminer les repas !"
  },
  AvgCommunicate_134272_Content_3 = {
    Text = "Oh là là, on doute de mes compétences ménagères. Garen devrait être triste, mais, mais..."
  },
  AvgCommunicate_134272_Content_4 = {
    Text = "Il y a tellement, tellement de bijoux et de parures ! Garen tout entière brille comme la plus éclatante des pierres précieuses, c'est vraiment trop dur d'être triste !"
  },
  AvgCommunicate_134272_Content_5 = {
    Text = "Calme-toi d'abord un peu, je ne comprends déjà presque plus ce que tu dis."
  },
  AvgCommunicate_134272_Content_6 = {
    Text = "Pardon, Garen est trop excitée. Après que Maître a aidé Garen à comprendre ce truc, la barrette ? Le ruban ou quelque chose comme ça..."
  },
  AvgCommunicate_134272_Content_7 = {
    Text = "...C'est une Loi."
  },
  AvgCommunicate_134272_Content_8 = {
    Text = "Ah oui, c'est ce truc très très précieux, très très bien. Et après, Garen a eu l'impression d'avoir obtenu une capacité vraiment incroyable."
  },
  AvgCommunicate_134272_Content_9 = {
    Text = "Non seulement l'efficacité des tâches ménagères a énormément augmenté, mais surtout, le corps de Garen brille de mille feux."
  },
  AvgCommunicate_134272_Option_7 = {
    Text = "Ce n'est pas une barrette"
  },
  AvgCommunicate_134273_Content_1 = {
    Text = "%player%, mon lien avec vous s'est approfondi."
  },
  AvgCommunicate_134273_Content_10 = {
    Text = "Des choses comme les solutions de calcul intégral, les questions d›examens de culture générale, et ce genre de choses — est-ce qu›on peut aussi les obtenir directement du savoir infini ?"
  },
  AvgCommunicate_134273_Content_11 = {Text = "新增"},
  AvgCommunicate_134273_Content_12 = {
    Text = "En effet, vous n›auriez plus besoin de mémoriser laborieusement autant de choses."
  },
  AvgCommunicate_134273_Content_13 = {
    Text = "Mais, je crois que le sens de l›apprentissage réside dans le processus de recherche du savoir, et dans l›entraînement de sa Force de pensée."
  },
  AvgCommunicate_134273_Content_14 = {
    Text = "Vous devez d›abord savoir ce que vous ne savez pas et ce que vous devriez savoir, avant de pouvoir trouver la réponse dont vous avez besoin dans ce trésor infini."
  },
  AvgCommunicate_134273_Content_15 = {
    Text = "D›accord, je comprends. Bien que la réponse soit différente de celle de Ramona, la conclusion est la même après tout."
  },
  AvgCommunicate_134273_Content_16 = {
    Text = "Je vais étudier, je vais étudier ! Ça vous convient !"
  },
  AvgCommunicate_134273_Content_17 = {
    Text = "Je suis ravi de voir votre soif d›apprendre. Continuez ainsi. Je resterai, comme toujours, à vos côtés."
  },
  AvgCommunicate_134273_Content_2 = {
    Text = "Félicitations, et merci pour votre dévouement. Je peux maintenant rassembler davantage de fragments de conscience et dissimuler une existence plus complète dans les interstices du monde."
  },
  AvgCommunicate_134273_Content_3 = {
    Text = "Vous pouvez vous manifester dans le monde maintenant !?"
  },
  AvgCommunicate_134273_Content_4 = {
    Text = "Malheureusement, je ne peux toujours pas véritablement révéler mon existence, ni quitter le Bassin Noir."
  },
  AvgCommunicate_134273_Content_5 = {
    Text = "Mais mon esprit, mon Rêve, mon regard sur la myriade de mondes — tout cela peut désormais exister plus pleinement, et vous être transmis plus complètement."
  },
  AvgCommunicate_134273_Content_6 = {
    Text = "À tout le moins, vous possédez maintenant la Clé du savoir infini."
  },
  AvgCommunicate_134273_Content_7 = {
    Text = "Vous voulez dire que peu importe ce que je demande, je peux obtenir une réponse ?"
  },
  AvgCommunicate_134273_Content_8 = {
    Text = "Tant que cela existe, ou peut être démontré."
  },
  AvgCommunicate_134273_Content_9 = {
    Text = "Héhé, par exemple, juste hypothétiquement parlant."
  },
  AvgCommunicate_134273_Option_15 = {
    Text = "Je comprends"
  },
  AvgCommunicate_134273_Option_7 = {
    Text = "Le savoir infini ?"
  },
  AvgCommunicate_134274_Content_1 = {
    Text = "La graine... est devenue plus complète."
  },
  AvgCommunicate_134274_Content_10 = {
    Text = "Les scènes aussi animées sont encore bien trop éprouvantes pour mes nerfs."
  },
  AvgCommunicate_134274_Content_11 = {
    Text = "Ça va aller, moi, ainsi que Tinct, nous serons juste là avec toi."
  },
  AvgCommunicate_134274_Content_12 = {
    Text = "Bien sûr, si tu te sens plus à l'aise seule, je soutiens pleinement ta décision !"
  },
  AvgCommunicate_134274_Content_13 = {
    Text = "Gardien... merci. Si c'est ce que toi et Tinct espérez."
  },
  AvgCommunicate_134274_Content_14 = {
    Text = "Mm... laisse-moi commencer par m'habituer au coin du dernier rang de la salle de classe."
  },
  AvgCommunicate_134274_Content_2 = {
    Text = "Je peux sentir une Force capable de soutenir ma germination, comblant progressivement le vide dans mon âme."
  },
  AvgCommunicate_134274_Content_3 = {
    Text = "Alors... cela signifie que tu ne draineras plus la force vitale des autres ?"
  },
  AvgCommunicate_134274_Content_4 = {
    Text = "Malheureusement, cette capacité innée qui est la mienne n'a pas disparu."
  },
  AvgCommunicate_134274_Content_5 = {
    Text = "Cependant, je commence à prendre le contrôle de ce pouvoir."
  },
  AvgCommunicate_134274_Content_6 = {
    Text = "Tant que je continue à m'entraîner, les Enquêteurs qui entrent en contact avec moi n'auront plus besoin de porter ces combinaisons de protection encombrantes."
  },
  AvgCommunicate_134274_Content_7 = {
    Text = "Désormais, il est possible que je puisse rester en toute sécurité aux côtés de tout le monde."
  },
  AvgCommunicate_134274_Content_8 = {
    Text = "C'est merveilleux ! Désormais, tu pourras participer à toutes sortes d'activités scolaires, de galas, et même de fêtes entre Corps éveillés."
  },
  AvgCommunicate_134274_Content_9 = {
    Text = "L-les fêtes... Je pense que maîtriser l'art de s'entendre avec les gens est bien plus difficile que maîtriser le contrôle de mes instincts."
  },
  AvgCommunicate_134274_Option_11 = {Text = "C'est bon"},
  AvgCommunicate_134274_Option_3 = {Text = "Alors..."},
  AvgCommunicate_134274_Option_8 = {
    Text = "C'est merveilleux !"
  },
  AvgCommunicate_134275_Content_1 = {
    Text = "Offrir toutes choses nobles à la Princesse est votre privilège."
  },
  AvgCommunicate_134275_Content_10 = {
    Text = "...Merci ? Tu n'essayais pas de me séduire avec des cadeaux pour entendre quelques mots d'encouragement de ma part, ou pour que je satisfasse une quelconque attente de ta part ?"
  },
  AvgCommunicate_134275_Content_11 = {
    Text = "«Murphy», je te fais des cadeaux et te traite bien seulement parce que tu es toi."
  },
  AvgCommunicate_134275_Content_12 = {
    Text = "Cela n'a rien à voir avec le fait que tu sois une princesse, la Mère divine, ou quoi que ce soit d'autre. Tu es mon amie. Au-delà de cela, je n'ai aucune autre attente."
  },
  AvgCommunicate_134275_Content_13 = {Text = "新增"},
  AvgCommunicate_134275_Content_14 = {
    Text = "Hmph ! C›est... c›est juste ton baratin de beau parleur ! Tu crois que dire quelque chose comme ça va me faire pleurer ?"
  },
  AvgCommunicate_134275_Content_15 = {
    Text = "Ne sois pas dans le Symptôme : Délire. Des amis ? Fais seulement ton travail en tant que Suiveur loyal et ça suffira."
  },
  AvgCommunicate_134275_Content_16 = {
    Text = "C›est vraiment blessant de dire ça. Je vais vraiment pleurer toute la nuit, tu sais ?"
  },
  AvgCommunicate_134275_Content_17 = {
    Text = "T-Toi... rgh, espèce d›incapable."
  },
  AvgCommunicate_134275_Content_18 = {
    Text = "Seulement cette fois, alors écoute bien."
  },
  AvgCommunicate_134275_Content_19 = {Text = "Merci."},
  AvgCommunicate_134275_Content_2 = {Text = "Pas mal."},
  AvgCommunicate_134275_Content_20 = {
    Text = "Quoi qu›il en soit, à partir de maintenant, cette princesse aura bien assez de Force pour te protéger. Alors sois reconnaissant et continue de me vénérer !"
  },
  AvgCommunicate_134275_Content_3 = {
    Text = "Tu n'as rien d'autre à dire ?"
  },
  AvgCommunicate_134275_Content_4 = {
    Text = "Quoi, ce pouvoir ne m'appartenait-il pas de droit depuis le début ?"
  },
  AvgCommunicate_134275_Content_5 = {
    Text = "Oh, je vois. Tu veux une récompense, une «Bénédiction», une position plus élevée, ou peut-être une Identité plus distinguée ?"
  },
  AvgCommunicate_134275_Content_6 = {Text = "新增"},
  AvgCommunicate_134275_Content_7 = {
    Text = "Que signifie «...» ? Comme c'est agaçant. Il n'y a aucun intérêt pour moi à jouer aux devinettes avec toi."
  },
  AvgCommunicate_134275_Content_8 = {
    Text = "Je te donne une dernière chance. Dis-moi ce que tu veux, vite, et arrête de tourner autour du pot."
  },
  AvgCommunicate_134275_Content_9 = {
    Text = "Est-ce possible que, ce que je veux dire, c'est que tu pourrais au moins dire merci."
  },
  AvgCommunicate_134275_Option_16 = {
    Text = "C›est blessant"
  },
  AvgCommunicate_134275_Option_3 = {
    Text = "C'est tout ?"
  },
  AvgCommunicate_134275_Option_6 = {Text = "新增"},
  AvgCommunicate_134275_Option_9 = {
    Text = "Est-ce possible que"
  },
  AvgCommunicate_134276_Content_1 = {
    Text = "Merci, Gardien, merci ! Je... je ne sais pas comment exprimer..."
  },
  AvgCommunicate_134276_Content_10 = {
    Text = "Quelque chose comme ça ?"
  },
  AvgCommunicate_134276_Content_11 = {
    Text = "J'ai entendu dire que les couleurs portent différentes significations émotionnelles et atmosphériques au sein d'une peinture. Vous pourriez créer de nouvelles couleurs selon votre propre vision créative."
  },
  AvgCommunicate_134276_Content_12 = {
    Text = "Oh ! Ohh ! Mélanger des combinaisons de couleurs entièrement nouvelles comme bon me semble !"
  },
  AvgCommunicate_134276_Content_13 = {
    Text = "Quelle idée de génie ! Différentes polarisations... différentes textures... J'ai déjà tellement d'idées !"
  },
  AvgCommunicate_134276_Content_14 = {
    Text = "Veuillez m'excuser, Gardien !"
  },
  AvgCommunicate_134276_Content_15 = {
    Text = "Il y a en moi le pressentiment que ma prochaine peinture possédera des coups de pinceau encore plus merveilleux."
  },
  AvgCommunicate_134276_Content_16 = {
    Text = "Peut-être pourrai-je véritablement créer un royaume peint connecté à l'inconnu. Quand ce moment viendra, vous serez le premier à le voir !"
  },
  AvgCommunicate_134276_Content_2 = {
    Text = "Merci de m'avoir donné la chance de voir la véritable apparence du monde, les lois ultimes de l'univers, la couleur de fond sur la toile du monde..."
  },
  AvgCommunicate_134276_Content_3 = {
    Text = "Ah, c'est si beau... Comment pourrais-je jamais mélanger de telles couleurs ?"
  },
  AvgCommunicate_134276_Content_4 = {
    Text = "Des cristaux arc-en-ciel ? Du mithril ? De la nacre ? De la poudre de ver de cristal ? Des ailes de papillon lumineux ?"
  },
  AvgCommunicate_134276_Content_5 = {
    Text = "Non, non, non... Ces choses vulgaires et ordinaires ne pourraient jamais les reproduire. Réfléchis plus fort, il faut que je réfléchisse plus fort..."
  },
  AvgCommunicate_134276_Content_6 = {
    Text = "Pickman ? On dirait que vous êtes déjà perdu dans votre propre art..."
  },
  AvgCommunicate_134276_Content_7 = {
    Text = "Chut, à quoi ressemblent selon vous les véritables couleurs de l'univers ? Quelqu'un d'aussi extraordinaire que vous doit pouvoir m'accorder une Clairvoyance différente !"
  },
  AvgCommunicate_134276_Content_8 = {
    Text = "Je pense que le monde pourrait paraître différent à travers les yeux de chacun."
  },
  AvgCommunicate_134276_Content_9 = {
    Text = "Oh ! Vous voulez dire... que je suive mon propre cœur... que je suive mes sentiments, pour dépeindre les différentes couleurs de l'univers..."
  },
  AvgCommunicate_134276_Option_10 = {Text = "Peut-être"},
  AvgCommunicate_134276_Option_8 = {Text = "Je pense"},
  AvgCommunicate_134277_Content_1 = {
    Text = "Gardien —"
  },
  AvgCommunicate_134277_Content_10 = {
    Text = "Je n'ai pas pitié de toi, je ne présume pas de ta logique comportementale avec condescendance. Je souhaite simplement que tu t'amuses dans ce monde."
  },
  AvgCommunicate_134277_Content_11 = {Text = "新增"},
  AvgCommunicate_134277_Content_12 = {
    Text = "Waouh, qui de nous deux est le plus fou, franchement ? Confier un tel niveau de puissance à une cinglée comme moi pour une raison pareille ?"
  },
  AvgCommunicate_134277_Content_13 = {
    Text = "Mon arrivée dans ce monde ne serait-elle pas vraiment un arrangement du destin ?"
  },
  AvgCommunicate_134277_Content_15 = {
    Text = "Bref, grâce à toi, j'ai touché du doigt ce qui constitue ma « limite » dans votre monde."
  },
  AvgCommunicate_134277_Content_16 = {
    Text = "Maintenant, dépêche-toi de me confier une mission, je meurs d'impatience d'aller trancher quelques têtes pour vous montrer de quoi je suis capable～"
  },
  AvgCommunicate_134277_Content_2 = {
    Text = "Une fille échouée dans un monde étranger qui reçoit un cadeau coûteux capable de la rendre plus forte... tu sais à quoi ça ressemble ?"
  },
  AvgCommunicate_134277_Content_3 = {
    Text = "Avant que tu ne sortes une de tes réflexions au raisonnement atypique, je tiens à préciser que tu fais partie de Mithsaga. On s'entraide, et c'est la raison pour laquelle je t'ai donné ces matériaux."
  },
  AvgCommunicate_134277_Content_4 = {
    Text = "Vraiment ? Ce n'est pas un de ces comportements sociaux humains ennuyeux et détournés, une façade de politesse ?"
  },
  AvgCommunicate_134277_Content_5 = {
    Text = "« Elle ne peut plus rentrer chez elle, la pauvre, soyons un peu plus attentionnés avec elle. »"
  },
  AvgCommunicate_134277_Content_6 = {
    Text = "« C'est si dur de se débrouiller toute seule, donnons-lui un coup de main. »... Ce ne sont vraiment pas ces raisons banales qu'on entend si souvent dans une société ordinaire ?"
  },
  AvgCommunicate_134277_Content_7 = {
    Text = "Premièrement, peu importe sous quel angle on te regarde, Mocha, tu n'as absolument rien à voir avec le mot « ordinaire » !"
  },
  AvgCommunicate_134277_Content_8 = {
    Text = "Hmm☆hmm, ce compliment me plaît bien."
  },
  AvgCommunicate_134277_Content_9 = {
    Text = "Deuxièmement, quelle que soit la perception que tu as de toi-même, quelle que soit l'apparence que tu montres, pour moi, comme tu l'as dit, « Mocha » est « Mocha »."
  },
  AvgCommunicate_134277_Option_7 = {
    Text = "Premièrement"
  },
  AvgCommunicate_134278_Content_1 = {
    Text = "Merci, mon cher. Tu m'as apporté tant de bonheur, et m'as permis de préserver à jamais mes ambitions."
  },
  AvgCommunicate_134278_Content_10 = {
    Text = "Quelle que soit la forme de gratitude que vous désirez, je peux la concrétiser."
  },
  AvgCommunicate_134278_Content_11 = {
    Text = "Même si je ne le possède pas encore, même s'il s'agissait des Étoiles et de la Lune, je trouverais un moyen de les obtenir pour vous."
  },
  AvgCommunicate_134278_Content_12 = {
    Text = "Tout ce que je veux ? Vraiment tout ?"
  },
  AvgCommunicate_134278_Content_13 = {
    Text = "Une promesse tenue vaut son pesant d'or — un laissez-passer indispensable dans le monde de la gloire et de la fortune."
  },
  AvgCommunicate_134278_Content_14 = {
    Text = "Alors, j'aimerais que Madame me fasse une promesse. Quant aux détails, j'ai besoin d'un peu plus de temps pour y réfléchir."
  },
  AvgCommunicate_134278_Content_15 = {Text = "新增"},
  AvgCommunicate_134278_Content_16 = {
    Text = "Hahahaha, quel choix rusé. Vous me plaisez vraiment de plus en plus."
  },
  AvgCommunicate_134278_Content_17 = {
    Text = "Bien sûr, mon cher, vous avez tout le temps d'y réfléchir."
  },
  AvgCommunicate_134278_Content_18 = {
    Text = "Si vous avez le temps, pourquoi ne pas venir à mon domaine ce soir ? Peut-être que, quand nous serons seuls tous les deux... vous trouverez plus facilement une «bonne idée» des plus rafraîchissantes."
  },
  AvgCommunicate_134278_Content_2 = {
    Text = "Vous servir, Madame, est mon plaisir."
  },
  AvgCommunicate_134278_Content_3 = {
    Text = "Héhé, sensé, intelligent, courageux, loyal, et avec juste ce qu'il faut de... beauté."
  },
  AvgCommunicate_134278_Content_4 = {
    Text = "Qui pourrait dire que tu n'es pas un parfait..."
  },
  AvgCommunicate_134278_Content_5 = {
    Text = "...Un parfait quoi?"
  },
  AvgCommunicate_134278_Content_6 = {
    Text = "Tu sembles un peu nerveux?"
  },
  AvgCommunicate_134278_Content_7 = {
    Text = "Madame laisse toujours sans voix."
  },
  AvgCommunicate_134278_Content_8 = {
    Text = "Certaines choses n'ont pas besoin d'être exprimées par des mots. Il y a chaque sentiment que tu m'as transmis tout du long que j'ai reçu."
  },
  AvgCommunicate_134278_Content_9 = {
    Text = "Terres, propriétés, trésors rares, œuvres d'art, et la chance de rencontrer tant de célébrités... avec mon pouvoir actuel, tout est à ma portée."
  },
  AvgCommunicate_134278_Option_12 = {
    Text = "Vraiment, n'importe quoi ?"
  },
  AvgCommunicate_134278_Option_14 = {
    Text = "Je veux une promesse de Madame."
  },
  AvgCommunicate_134278_Option_2 = {
    Text = "Avec plaisir"
  },
  AvgCommunicate_134278_Option_5 = {Text = "Parfait?"},
  AvgCommunicate_134278_Option_7 = {Text = "新增"},
  AvgCommunicate_134279_Content_1 = {
    Text = "Gardien, tu es encore éveillé ?"
  },
  AvgCommunicate_134279_Content_10 = {
    Text = "Mais tout ce que tu as déversé en moi... s›est rassemblé en un nouveau lac au fond de moi. Un lac encore plus vaste que cette mer."
  },
  AvgCommunicate_134279_Content_11 = {
    Text = "Il m›a dit : il n›y a plus besoin d›avoir peur."
  },
  AvgCommunicate_134279_Content_12 = {
    Text = "Je comprends que la douleur ne pourra peut-être jamais totalement se Dissoudre, mais peu importe le nombre de fois qu›il le faudra, je te ramènerai toujours sur la rive."
  },
  AvgCommunicate_134279_Content_13 = {
    Text = "...Si Maman et Papa pouvaient t›entendre dire ça, je suis sûre qu›ils seraient en paix."
  },
  AvgCommunicate_134279_Content_14 = {
    Text = "Je pense... qu›ils sont peut-être quelque part dans cette mer, veillant sur ce que je suis devenue."
  },
  AvgCommunicate_134279_Content_15 = {
    Text = "Désormais, je manierai cette Force qui m›a été donnée et deviendrai la marée qui te protège."
  },
  AvgCommunicate_134279_Content_16 = {
    Text = "Peut-être... accepterais-tu de m›accorder une dernière requête audacieuse ?"
  },
  AvgCommunicate_134279_Content_17 = {
    Text = "De quoi s›agit-il ? Tant que c›est en mon pouvoir, ce sera avec plaisir."
  },
  AvgCommunicate_134279_Content_18 = {
    Text = "Quand le temps se dégagera, s›il te plaît, viens te promener au bord de la mer avec moi."
  },
  AvgCommunicate_134279_Content_19 = {
    Text = "Il y a tant de choses que je veux te dire. Seulement un après-midi — c›est tout ce que je demande."
  },
  AvgCommunicate_134279_Content_2 = {
    Text = "Si je dérange ton Repos, je suis désolée..."
  },
  AvgCommunicate_134279_Content_20 = {
    Text = "Bien sûr, absolument."
  },
  AvgCommunicate_134279_Content_3 = {
    Text = "Non, je suis encore debout. Qu›est-ce qu›il y a ?"
  },
  AvgCommunicate_134279_Content_4 = {
    Text = "Après avoir reçu ton cadeau, j›ai sombré dans un profond sommeil et j›ai dérivé dans un Rêve. J›ai Rêvé de cette mer d›autrefois, et du coucher de soleil devant le Sanatorium."
  },
  AvgCommunicate_134279_Content_5 = {
    Text = "Mais cette fois... je ne me suis pas avancée dans la mer."
  },
  AvgCommunicate_134279_Content_6 = {
    Text = "Je me tenais sur le rivage, contemplant cette mer. Elle me rendait toujours Ning, mais je n›avais aucune envie d›avancer."
  },
  AvgCommunicate_134279_Content_7 = {
    Text = "Si ce n›est pas trop présomptueux de deviner — est-ce parce que cette fois, tu avais une raison de rester ?"
  },
  AvgCommunicate_134279_Content_8 = {Text = "Bien."},
  AvgCommunicate_134279_Content_9 = {
    Text = "J›ai été un jour écrasée par la douleur. Rien ne pouvait emporter la lourdeur logée dans ma gorge — rien sauf l›océan, qui submerge et enlace toutes choses."
  },
  AvgCommunicate_134279_Option_12 = {
    Text = "Nymphaea..."
  },
  AvgCommunicate_134279_Option_17 = {Text = "Quoi ?"},
  AvgCommunicate_134279_Option_7 = {
    Text = "Parce que..."
  },
  AvgCommunicate_134280_Content_1 = {
    Text = "%player%, la nuit dernière, j'ai encore fait ce rêve."
  },
  AvgCommunicate_134280_Content_10 = {
    Text = "C›était peut-être l›Effet de la Règle finale."
  },
  AvgCommunicate_134280_Content_11 = {
    Text = "Oui, alors je veux dire — au nom de tous les «24», merci, %player%."
  },
  AvgCommunicate_134280_Content_12 = {
    Text = "Merci de nous avoir permis de nous entendre, de nous voir, de nous comprendre et de nous accepter."
  },
  AvgCommunicate_134280_Content_13 = {
    Text = "Ce n'était pas mon œuvre."
  },
  AvgCommunicate_134280_Content_14 = {
    Text = "Non, les conseils et le réconfort que vous avez offerts ont apaisé chaque esprit agité."
  },
  AvgCommunicate_134280_Content_15 = {
    Text = "C'est votre présence qui a fait converger toutes les rivières en une seule."
  },
  AvgCommunicate_134280_Content_16 = {
    Text = "« Je » — nous tous — n'oublierons jamais votre bonté."
  },
  AvgCommunicate_134280_Content_2 = {
    Text = "Je semblais être revenue au pied des montagnes de Neige du grand nord, à l›intérieur d›une caverne d›un noir absolu."
  },
  AvgCommunicate_134280_Content_3 = {
    Text = "D›innombrables masses de gelée, reflétant d›innombrables ombres de «24»..."
  },
  AvgCommunicate_134280_Content_4 = {
    Text = "Elles... sont toutes toi, toutes une partie de toi."
  },
  AvgCommunicate_134280_Content_5 = {Text = "Je sais."},
  AvgCommunicate_134280_Content_6 = {
    Text = "Au milieu du Chaos, j›ai cru entendre quelqu›un me dire quelque chose."
  },
  AvgCommunicate_134280_Content_7 = {
    Text = "La voix était floue, je n›arrivais pas à la distinguer..."
  },
  AvgCommunicate_134280_Content_8 = {
    Text = "Mais après le départ de cette personne, j›ai senti toute la clameur autour de moi s›apaiser."
  },
  AvgCommunicate_134280_Content_9 = {
    Text = "La cacophonie de murmures dans mes oreilles est devenue harmonieuse et naturelle, Semblant une mélodie en parfait accord..."
  },
  AvgCommunicate_134280_Option_4 = {
    Text = "Elles sont toutes toi."
  },
  AvgCommunicate_134281_Content_1 = {
    Text = "Gardien, crois-tu au Destin ?"
  },
  AvgCommunicate_134281_Content_10 = {
    Text = "...En tant que personne ordinaire, j'ai du mal à imaginer à quel point ça doit être incroyable. Permets-moi de demander en serrant les dents — qu'est-ce que ça fait exactement ?"
  },
  AvgCommunicate_134281_Content_11 = {
    Text = "Comment décrire ça ? Par exemple, j'ai un peu faim en ce moment..."
  },
  AvgCommunicate_134281_Content_12 = {
    Text = "? Et ensuite ?"
  },
  AvgCommunicate_134281_Content_13 = {
    Text = "Oh, désolée pour l'attente. Quelqu'un vient Seulement de frapper à la porte — c'était Mlle Mason qui partageait un cake tout juste sorti du four."
  },
  AvgCommunicate_134281_Content_14 = {Text = "Quoi ???"},
  AvgCommunicate_134281_Content_15 = {
    Text = "Seulement comme ça. Et puis... j'ai un peu soif."
  },
  AvgCommunicate_134281_Content_16 = {
    Text = "Hm ? Le majordome de M. Doresain vient Seulement d'envoyer une invitation, disant qu'il aimerait m'inviter à une Dégustation de sa Collection de vins rouges entreposée dans un restaurant à proximité."
  },
  AvgCommunicate_134281_Content_17 = {
    Text = "...Assez. La prochaine fois, pourriez-vous sincèrement avoir envie de m'aider avec mes devoirs ?"
  },
  AvgCommunicate_134281_Content_18 = {
    Text = "Hahaha, comme vous le souhaitez, %player%. Vous êtes désormais mon plus grand mécène, sponsor, partenaire, et {Male=Mr.,Female=Miss} Watson indispensable."
  },
  AvgCommunicate_134281_Content_19 = {
    Text = "Détective Veinard, à votre entier service."
  },
  AvgCommunicate_134281_Content_2 = {
    Text = "Je crois au Destin, et je crois que je possède le Destin le plus chanceux qui soit."
  },
  AvgCommunicate_134281_Content_3 = {
    Text = "Des aubaines inattendues, des fortunes surprises, des bénédictions tombées du ciel — quand ces choses m'arrivent, je ne sourcille même plus."
  },
  AvgCommunicate_134281_Content_4 = {
    Text = "Une fois qu'on s'est habitué aux faveurs du Destin, toutes ces délicieuses surprises deviennent plutôt banales."
  },
  AvgCommunicate_134281_Content_5 = {
    Text = "Ce que tu viens de dire est vraiment à la fois enviable et rageant."
  },
  AvgCommunicate_134281_Content_6 = {
    Text = "Attends, je n'ai pas fini. Te rencontrer est la chose la plus chanceuse parmi toutes mes fortunes."
  },
  AvgCommunicate_134281_Content_7 = {
    Text = "Ce que tu m'as donné apporte toujours de nouvelles surprises."
  },
  AvgCommunicate_134281_Content_8 = {
    Text = "Seulement comme maintenant — la Force qui est apparue après avoir compris la Règle finale me permet déjà de percevoir clairement chaque coup de chance avant qu'il n'arrive."
  },
  AvgCommunicate_134281_Content_9 = {
    Text = "Les événements chanceux tombent comme des gouttes de pluie, d'une bruine légère à une averse — se déversant en torrents."
  },
  AvgCommunicate_134281_Option_10 = {
    Text = "Qu'est-ce que ça fait ?"
  },
  AvgCommunicate_134281_Option_14 = {Text = "???"},
  AvgCommunicate_134281_Option_5 = {
    Text = "C'est à la fois enviable et rageant"
  },
  AvgCommunicate_137645_Content_1 = {Text = "Gardien."},
  AvgCommunicate_137645_Content_10 = {
    Text = "Mais avec autant de pattes, n'est-ce pas un peu injuste de votre part de participer à une course à pied..."
  },
  AvgCommunicate_137645_Content_11 = {
    Text = "Castor a des ailes, et Nautila a aussi amené Son véhicule."
  },
  AvgCommunicate_137645_Content_12 = {
    Text = "D'ordinaire, je file au théâtre et ne suis guère portée sur l'exercice. Cependant, j'ai déjà inscrit ma Servante."
  },
  AvgCommunicate_137645_Content_13 = {
    Text = "Il est difficile d'imaginer pourquoi vous seriez intéressée par quelque chose comme ça ?"
  },
  AvgCommunicate_137645_Content_14 = {
    Text = "Observer des gens révéler une vitalité si vibrante et une volonté si tenace dans la poursuite d'un objectif est vraiment une chose délicieuse."
  },
  AvgCommunicate_137645_Content_15 = {
    Text = "De plus... je suis plutôt curieuse de savoir quelle sorte de magie possède ce gâteau offert en prix, pour avoir même Tawil aussi envoûté par lui."
  },
  AvgCommunicate_137645_Content_16 = {
    Text = "Tant que ce n'est pas une sorte de choix qui détruit un monde, tout est permis..."
  },
  AvgCommunicate_137645_Content_17 = {
    Text = "Euh, tu n'utiliserais pas le Fil du destin pour manipuler les résultats de la compétition, n'est-ce pas ?"
  },
  AvgCommunicate_137645_Content_18 = {
    Text = "...Arachne ?"
  },
  AvgCommunicate_137645_Content_2 = {
    Text = "Quel est le problème ?"
  },
  AvgCommunicate_137645_Content_20 = {
    Text = "À bientôt dans l'Audience, Gardien."
  },
  AvgCommunicate_137645_Content_3 = {
    Text = "Pensez-vous... quel type de Destin peut vraiment être considéré comme juste et équitable ?"
  },
  AvgCommunicate_137645_Content_4 = {
    Text = "Juste et équitable ?... Probablement protéger les intérêts de la majorité autant que possible."
  },
  AvgCommunicate_137645_Content_5 = {
    Text = "Alors que faire si — les intérêts de quelques-uns sont destinés à être Sacrifiés ? Vous approuvez une telle direction du Destin, n'est-ce pas ?"
  },
  AvgCommunicate_137645_Content_6 = {
    Text = "Vous... pourquoi posez-vous soudainement cette question ? Ne vous méprenez pas sur ce que je veux dire !"
  },
  AvgCommunicate_137645_Content_7 = {
    Text = "Si vous êtes sur le point de faire quelque chose comme détruire un monde encore une fois, veuillez y réfléchir, Arachne !"
  },
  AvgCommunicate_137645_Content_8 = {
    Text = "Pas besoin de s'inquiéter, Gardien. C'est Seulement une course à pied."
  },
  AvgCommunicate_137645_Content_9 = {
    Text = "Ouf... vous m'avez fait peur..."
  },
  AvgCommunicate_137645_Option_2 = {
    Text = "Quel est le problème ?"
  },
  AvgCommunicate_137646_Content_1 = {
    Text = "Gardien, en apprenant que tu allais voyager au loin pour une enquête, j'ai spécialement composé une œuvre pour toi."
  },
  AvgCommunicate_137646_Content_10 = {
    Text = "Tu as vraiment un sens des noms particulier, Arachne..."
  },
  AvgCommunicate_137646_Content_11 = {
    Text = "Chaque fil tissé a son propriétaire désigné. Chaque histoire, aussi, a son lecteur."
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "Un nom qui se répand facilement peut aider ces excellentes histoires à atteindre davantage de personnes auxquelles elles sont destinées."
  },
  AvgCommunicate_137646_Content_13 = {
    Text = "Par exemple, cette œuvre à succès..."
  },
  AvgCommunicate_137646_Content_14 = {
    Text = "« Guide de cuisine des créatures d'Aequor » ? Un best-seller ?"
  },
  AvgCommunicate_137646_Content_15 = {
    Text = "Ne me dis pas que Doresain a acheté un exemplaire pour chaque habitant de Nekropolis..."
  },
  AvgCommunicate_137646_Content_16 = {
    Text = "Tulu est-il au courant ?"
  },
  AvgCommunicate_137646_Content_18 = {
    Text = "C'est précisément cette perspicacité aiguë sur le cœur humain et le Destin qui me pousse à vous admirer sincèrement."
  },
  AvgCommunicate_137646_Content_19 = {
    Text = "«Tout le monde aime le Gardien»."
  },
  AvgCommunicate_137646_Content_2 = {
    Text = "Je voulais à l'origine monter une pièce de théâtre pour toi, mais en tenant compte de la portabilité, je l'ai écrite sous forme de roman à la place."
  },
  AvgCommunicate_137646_Content_20 = {
    Text = "Veuillez emporter cette œuvre avec vous pour Partir."
  },
  AvgCommunicate_137646_Content_3 = {Text = "C'est..."},
  AvgCommunicate_137646_Content_4 = {
    Text = "« Le Grand Gardien » ? « L'Odyssée du Gardien » ? « Le Monde du Gardien » ?"
  },
  AvgCommunicate_137646_Content_5 = {
    Text = "Qu'est-ce que tu écris d'habitude !? Est-ce que quelqu'un lit vraiment ces choses ???"
  },
  AvgCommunicate_137646_Content_6 = {
    Text = "Ne sous-estime pas ta popularité à Mizag. Ce sont toutes des œuvres extrêmement populaires."
  },
  AvgCommunicate_137646_Content_7 = {
    Text = "Un Destin si dramatique mérite naturellement d'être présenté au monde."
  },
  AvgCommunicate_137646_Content_8 = {
    Text = "En réalité, ce n'est pas seulement toi. J'ai également tissé des histoires sur les Destins des autres."
  },
  AvgCommunicate_137646_Content_9 = {
    Text = "« Cinq ans sur le champ de bataille, trois ans de simulations », « Soins postnataux pour les souris », « La Grande Exposition de l'art du goutte-à-goutte de cire »..."
  },
  AvgCommunicate_137646_Option_3 = {Text = "C'est..."},
  AvgCommunicate_137647_Content_1 = {
    Text = "Relier les gens à travers différents temps et espaces avec des fils invisibles..."
  },
  AvgCommunicate_137647_Content_10 = {
    Text = "J'ai hâte, Gardien."
  },
  AvgCommunicate_137647_Content_2 = {
    Text = "La civilisation humaine ne cesse de me surprendre."
  },
  AvgCommunicate_137647_Content_3 = {
    Text = "Surprendre ?"
  },
  AvgCommunicate_137647_Content_4 = {
    Text = "Mais ces destins ne sont-ils pas choisis par vos propres mains ?"
  },
  AvgCommunicate_137647_Content_5 = {
    Text = "Ce que je choisis, c'est Seulement la direction. Toute la civilisation et l'Histoire sont encore créées par vous-mêmes."
  },
  AvgCommunicate_137647_Content_6 = {
    Text = "Le Fil du destin, se prolongeant naturellement, donnera finalement Naissance à de nouvelles créations, aux origines inconnues."
  },
  AvgCommunicate_137647_Content_7 = {
    Text = "C'est en témoignant de tout cela, en ressentant cette joie du tissage, que j'ai pu maintenir cette responsabilité."
  },
  AvgCommunicate_137647_Content_8 = {Text = "Je vois..."},
  AvgCommunicate_137647_Content_9 = {
    Text = "S'il y a de nouvelles créations, permettez-moi également de les apprécier."
  },
  AvgCommunicate_137647_Option_3 = {
    Text = "Surprendre ?"
  },
  AvgCommunicate_140194_Content_1 = {
    Text = "Quelque chose me semble bizarre. Le fait que personne n'ait peur de moi du tout..."
  },
  AvgCommunicate_140194_Content_10 = {
    Text = "Ne t'inquiète pas, tout le monde a été si gentil avec moi ! Ils sont en sécurité !"
  },
  AvgCommunicate_140194_Content_11 = {
    Text = "...Probablement. Pour l'instant."
  },
  AvgCommunicate_140194_Content_12 = {
    Text = "Pour l'instant? ...S'il te plaît, sois plus catégorique !"
  },
  AvgCommunicate_140194_Content_13 = {
    Text = "Pour l'instant～!"
  },
  AvgCommunicate_140194_Content_2 = {
    Text = "Doll a développé une phéromone spéciale. En ce moment, tu ne ressembles à rien de plus qu'une fille humaine ordinaire aux yeux de tout le monde."
  },
  AvgCommunicate_140194_Content_4 = {
    Text = "Pratique, je suppose, mais..."
  },
  AvgCommunicate_140194_Content_5 = {
    Text = "C'est presque un peu décevant de ne plus pouvoir effrayer les gens?"
  },
  AvgCommunicate_140194_Content_6 = {Text = "...?"},
  AvgCommunicate_140194_Content_7 = {
    Text = "Comment dire... hmm... par exemple, ça va rendre ma « chasse » plus difficile..."
  },
  AvgCommunicate_140194_Content_8 = {
    Text = "Je n'ai pas eu de mal à trouver des repas dernièrement, donc la chasse n'est pas un besoin urgent, mais... parfois... ouais..."
  },
  AvgCommunicate_140194_Content_9 = {
    Text = "Je suis presque habitué à ce que tous les Corps éveillés disent des trucs délirants à ce stade, mais je dois quand même te dire... C'est une chose très dangereuse à dire !"
  },
  AvgCommunicate_140195_Content_1 = {
    Text = "Demande d'achat"
  },
  AvgCommunicate_140195_Content_10 = {
    Text = "...Et je vais simplement faire comme si je n'étais absolument au courant de rien. D'accord ?"
  },
  AvgCommunicate_140195_Content_2 = {
    Text = "Quatre grands réfrigérateurs domestiques... Le budget de l'université n'est pas exactement limité, mais à quoi vous serviraient ces frigos ?"
  },
  AvgCommunicate_140195_Content_3 = {
    Text = "Si je me souviens bien, Saya, vous en aviez déjà demandé un pour votre chambre dès le premier jour de votre emménagement."
  },
  AvgCommunicate_140195_Content_4 = {
    Text = "Eh bien, euh... On ne sait jamais quand l'espace de réfrigération peut s'avérer utile..."
  },
  AvgCommunicate_140195_Content_5 = {
    Text = "Et puis, vous savez, la fraîcheur de la viande, c'est important..."
  },
  AvgCommunicate_140195_Content_6 = {Text = "新增"},
  AvgCommunicate_140195_Content_7 = {
    Text = "Désolé, mais je ne peux pas approuver davantage de réfrigérateurs. En revanche, je vous transmettrai les coordonnées de Xu et Doresain."
  },
  AvgCommunicate_140195_Content_9 = {
    Text = "Je pense que vous prendriez plaisir à discuter cuisine et recettes avec eux."
  },
  AvgCommunicate_140196_Content_1 = {Text = "¥%&#...%"},
  AvgCommunicate_140196_Content_10 = {Text = "新增"},
  AvgCommunicate_140196_Content_11 = {
    Text = "Faux ! Tu es censé dire Plouf Plouf !"
  },
  AvgCommunicate_140196_Content_12 = {
    Text = "Apparemment, la phéromone développée par le Professeur Doll ne fonctionne pas sur Mlle Mosk."
  },
  AvgCommunicate_140196_Content_13 = {
    Text = "Mais elle me traite toujours de la même façon. Son attitude n'a pas changé du tout."
  },
  AvgCommunicate_140196_Content_14 = {
    Text = "Je pense que c'est parce que, euh, comment dire..."
  },
  AvgCommunicate_140196_Content_15 = {
    Text = "...Peut-être que Mosk est tout simplement doté de... compétences sociales extraordinaires ?"
  },
  AvgCommunicate_140196_Content_2 = {
    Text = "A... Abandon. Ah, encore un mot appris. Hmm."
  },
  AvgCommunicate_140196_Content_3 = {Text = "?"},
  AvgCommunicate_140196_Content_4 = {
    Text = "J'ai étudié toutes sortes de langues dernièrement. ...C'est fascinant."
  },
  AvgCommunicate_140196_Content_6 = {
    Text = "En plus de la Langue léonienne standard, j'ai aussi appris beaucoup de nouveau vocabulaire. Par exemple..."
  },
  AvgCommunicate_140196_Content_7 = {
    Text = "Glouglou glouglou?"
  },
  AvgCommunicate_140196_Content_8 = {
    Text = "Plop plop !"
  },
  AvgCommunicate_140196_Content_9 = {Text = "Correct !"},
  AvgCommunicate_140196_Option_10 = {Text = "新增"},
  AvgCommunicate_140196_Option_8 = {
    Text = "Plop plop !"
  },
  AvgCommunicate_141374_Content_1 = {
    Text = "Des remerciements solennels semblent peut-être un peu trop formels, mais du fond du cœur, merci à Vous, pour moi-même, et pour tout Ebwynnos."
  },
  AvgCommunicate_141374_Content_10 = {
    Text = "Si je manifeste ces traits, c'est parce que telle est ma nature."
  },
  AvgCommunicate_141374_Content_12 = {
    Text = "Ne dites pas cela avec un ton aussi fier."
  },
  AvgCommunicate_141374_Content_13 = {
    Text = "Alors, m'avoir aidé à toucher cette limite et à me libérer de Son contrôle, c'était vraiment me rendre un immense service."
  },
  AvgCommunicate_141374_Content_14 = {
    Text = "Beaucoup de choses qui étaient difficiles auparavant ne sont plus un problème maintenant."
  },
  AvgCommunicate_141374_Content_15 = {
    Text = "Est-il encore temps pour moi de reprendre ce que j'ai dit ?"
  },
  AvgCommunicate_141374_Content_16 = {
    Text = "Du calme, Pontos, Londinium a un système juridique bien établi !"
  },
  AvgCommunicate_141374_Content_2 = {
    Text = "Être aussi sérieux tout d'un coup, c'est vraiment un peu inhabituel."
  },
  AvgCommunicate_141374_Content_3 = {
    Text = "Vous ne savez probablement pas ce que cela signifie — avant que je sois suffisamment puissant, Ebwynnos ne pouvait en réalité jamais échapper au contrôle de cette ancienne entité."
  },
  AvgCommunicate_141374_Content_4 = {
    Text = "C'est le marché que j'ai conclu avec Elle, et heureusement, Elle n'avait aucune mauvaise intention, on pourrait même la qualifier de généreuse."
  },
  AvgCommunicate_141374_Content_5 = {
    Text = "Cependant, Elle n'appartient pas au monde humain, et sous Son emprise, Ebwynnos serait devenu encore plus imprévisible, et les gens d'Ebwynnos auraient eu des caractères encore plus extrêmes."
  },
  AvgCommunicate_141374_Content_6 = {
    Text = "Dans ce cas, est-ce que Vous étiez aussi auparavant sous Son influence, et c'est pour ça que Vous étiez si, euh..."
  },
  AvgCommunicate_141374_Content_7 = {
    Text = "Laissez-moi deviner, Vous voulez dire Paranoïa, rancunier, ou maniaque du contrôle ?"
  },
  AvgCommunicate_141374_Content_9 = {Text = "Non."},
  AvgCommunicate_141374_Option_2 = {
    Text = "Un peu inhabituel"
  },
  AvgCommunicate_141374_Option_6 = {
    Text = "Alors, est-ce que"
  },
  AvgCommunicate_143429_Content_1 = {
    Text = "Bien que ces adeptes de culte qui vénèrent de faux dieux soient d'une stupidité risible, il faut admettre que certains d'entre eux ont un goût plutôt acceptable."
  },
  AvgCommunicate_143429_Content_10 = {
    Text = "Et en plus, elles ne correspondent même pas à la bonne époque !"
  },
  AvgCommunicate_143429_Content_11 = {
    Text = "Je pense que si vous vous laissiez davantage imprégner par ce genre de choses pour renforcer votre ambition, cela pourrait contribuer à réduire considérablement le nombre de fois où vous vous retrouvez en danger lors de missions de terrain."
  },
  AvgCommunicate_143429_Content_12 = {
    Text = "Bien sûr, si vous m'appelez encore quelques fois « tonton », je serai ravi de continuer à couvrir les petits sans ambition."
  },
  AvgCommunicate_143429_Content_13 = {
    Text = "...Je vais aller avoir une discussion avec Goliath."
  },
  AvgCommunicate_143429_Content_14 = {
    Text = "Je vais les ajouter à la liste des films interdits de Mizag, il n'a pas le droit de les recommander à n'importe qui !"
  },
  AvgCommunicate_143429_Content_2 = {
    Text = "Il y a quelques jours, quand il quittait fréquemment Mizag dans le dos de Miryam, j'étais déjà très stupéfaite..."
  },
  AvgCommunicate_143429_Content_3 = {
    Text = "Vous ne seriez pas en train de parler de Goliath, par hasard..."
  },
  AvgCommunicate_143429_Content_4 = {
    Text = "Eh bien, premièrement, j'admire sa détermination à s'abaisser devant les autres pour parvenir à ses fins."
  },
  AvgCommunicate_143429_Content_5 = {
    Text = "Deuxièmement, les pièces qu'il a recommandées sont vraiment très intéressantes."
  },
  AvgCommunicate_143429_Content_6 = {
    Text = "On aurait du mal à imaginer Goliath fréquenter un théâtre."
  },
  AvgCommunicate_143429_Content_7 = {
    Text = "Il m'a recommandé <Italic:Il était une fois à Leonia> et <Italic:Le Par▼rain> — tout le monde les adorait."
  },
  AvgCommunicate_143429_Content_8 = {
    Text = "Ce soir, Ebwynnos devrait projeter « Le Loup de Londinium »."
  },
  AvgCommunicate_143429_Content_9 = {
    Text = "Non, attendez, Mizag n'autorise pas les chefs de gang, ni la culture du loup !"
  },
  AvgCommunicate_143429_Option_2 = {
    Text = "Vous ne voudriez pas dire"
  },
  AvgCommunicate_143430_Content_1 = {
    Text = "La sixième demande de transfert de résidence ce mois-ci, il semblerait que les règlements du bureau des affaires scolaires ne soient pas toujours efficaces."
  },
  AvgCommunicate_143430_Content_10 = {
    Text = "Ah, dommage."
  },
  AvgCommunicate_143430_Content_11 = {
    Text = "Hein ?? Quoi ?! Pourquoi est-ce qu'un cauchemar a apporté une feuille de réponses d'examen et s'est assis pour commencer à rédiger ma thèse ?"
  },
  AvgCommunicate_143430_Content_12 = {
    Text = "Tu portes un fardeau trop lourd, même si tu dis ça en plaisantant, cela montre que tu devrais vraiment te Détendre un peu, mon petit."
  },
  AvgCommunicate_143430_Content_13 = {
    Text = "Juste pour cette fois, même si cela me fait plaisir, je vais quand même essayer de ne pas devenir ce genre de parent qui gâte ses enfants."
  },
  AvgCommunicate_143430_Content_14 = {
    Text = "Maintenant, ouvre la fenêtre, je t'emmène t'amuser pour une nuit, pour que tu découvres le plaisir d'oublier la réalité sans avoir besoin d'aller à Ebwynnos."
  },
  AvgCommunicate_143430_Content_15 = {
    Text = "......Super !"
  },
  AvgCommunicate_143430_Content_3 = {
    Text = "La moyenne des notes, l'assiduité, le taux de conversion des pratiques effectives, euh, ainsi que la pression de l'emploi qui existe pour la plupart des étudiants ordinaires, même si les Gardiens du secret n'y sont pas soumis."
  },
  AvgCommunicate_143430_Content_4 = {
    Text = "Même quand la Dissolution est imminente, les problèmes du quotidien restent terriblement effrayants."
  },
  AvgCommunicate_143430_Content_5 = {
    Text = "Il est tout à fait normal que tout le monde veuille fuir la réalité, pourquoi ne pas m'accueillir aussi à Ebwynnos..."
  },
  AvgCommunicate_143430_Content_6 = {
    Text = ": Es-tu sérieux ?"
  },
  AvgCommunicate_143430_Content_7 = {
    Text = "Est-ce qu'il y a vraiment un bruit d'ailes qui battent dehors, ou est-ce que j'ai des Illusions après trois nuits de révision consécutives ?"
  },
  AvgCommunicate_143430_Content_8 = {
    Text = "Il ne faut pas laisser passer une telle occasion, avec une si belle opportunité, même si tout Mizag devait s'en prendre à moi ensuite, j'accepterais avec grand plaisir."
  },
  AvgCommunicate_143430_Content_9 = {
    Text = "Non non non non non non je plaisantais je vous en supplie ne faites surtout pas ça."
  },
  AvgCommunicate_143431_Content_1 = {
    Text = "Vous me cherchez ?"
  },
  AvgCommunicate_143431_Content_10 = {
    Text = "Hahahahaha, allez, ne fais pas cette expression."
  },
  AvgCommunicate_143431_Content_11 = {
    Text = "Obtenir son sceau personnel n'est pas une chose difficile, quant à l'adresse du dîner de charité, que dirais-tu de la placer à Ebwynnos ?"
  },
  AvgCommunicate_143431_Content_12 = {
    Text = "L'étape suivante, la police nous arrêtera tous pour violation de propriété privée."
  },
  AvgCommunicate_143431_Content_14 = {
    Text = "Bon, c'est regrettable, je vais Esquiver quelques jours pour l'instant."
  },
  AvgCommunicate_143431_Content_15 = {
    Text = "Le tuer quand il n'est pas sur ses gardes serait peut-être un peu plus amusant."
  },
  AvgCommunicate_143431_Content_16 = {Text = "???!"},
  AvgCommunicate_143431_Content_2 = {
    Text = "Euh, Pontos, vous ne voudriez pas envisager de retourner passer un moment à Ebwynnos ?"
  },
  AvgCommunicate_143431_Content_3 = {
    Text = "Le professeur Dexter n'est pas venu à l'école depuis deux mois entiers."
  },
  AvgCommunicate_143431_Content_4 = {
    Text = "Ha, cette ordure peureuse comme un rat est probablement en train de passer ses nerfs sur l'un de ses malheureux subordonnés en ce moment même."
  },
  AvgCommunicate_143431_Content_5 = {
    Text = "Soyez sans crainte, tant qu'il n'aura pas effectué son Retour à son Origine, il n'aura pas encore la qualité pour devenir mon adversaire."
  },
  AvgCommunicate_143431_Content_6 = {
    Text = "Le problème, c'est qu'une pile de documents attend encore son cachet personnel — que va-t-on faire du banquet de charité de cette année ! Faire venir la directrice Czort et le professeur Doll à ce genre d'événement est encore plus difficile que de leur demander de faire sauter Mizag."
  },
  AvgCommunicate_143431_Content_7 = {
    Text = "Si c'est la professeure Sylvia qui préside, ce sont d'autres problèmes dont il faudra s'inquiéter..."
  },
  AvgCommunicate_143431_Content_8 = {
    Text = "C'est vraiment triste, mon petit, je sais que tu es protégé par beaucoup de monde à Mizag, tu n'as plus besoin de moi, et après tout ce que j'ai fait pour toi, tu as même..."
  },
  AvgCommunicate_145234_Content_1 = {
    Text = "Le silence s'est installé."
  },
  AvgCommunicate_145234_Content_10 = {
    Text = "Alors... vous ne voulez plus vous battre ?"
  },
  AvgCommunicate_145234_Content_11 = {
    Text = "Hé hé hé hé..."
  },
  AvgCommunicate_145234_Content_12 = {
    Text = "Bien sûr que non."
  },
  AvgCommunicate_145234_Content_13 = {
    Text = "Je n'ai plus besoin du combat pour apaiser mon corps, mais..."
  },
  AvgCommunicate_145234_Content_14 = {
    Text = "Maintenant, je peux utiliser ma force plus librement, et défier qui je veux !"
  },
  AvgCommunicate_145234_Content_15 = {
    Text = "Je crois... que je vous dois ma gratitude."
  },
  AvgCommunicate_145234_Content_16 = {
    Text = "Vous m'avez conduit à un sommet que j'ai longtemps désiré. Mais..."
  },
  AvgCommunicate_145234_Content_17 = {
    Text = "La voie de la force n'a pas de fin. N'est-ce pas, Gardien ?"
  },
  AvgCommunicate_145234_Content_2 = {
    Text = "Le silence ? Que voulez-vous dire ?"
  },
  AvgCommunicate_145234_Content_3 = {
    Text = "Mon sang a cessé de bouillir. Mes os, de souffrir. Ma lame ne rugit plus..."
  },
  AvgCommunicate_145234_Content_4 = {
    Text = "Depuis le moment de ma naissance, ils ne se sont jamais arrêtés."
  },
  AvgCommunicate_145234_Content_5 = {
    Text = "Maintenant, ils sont tous silencieux."
  },
  AvgCommunicate_145234_Content_6 = {
    Text = "Est-ce une mauvaise chose ?"
  },
  AvgCommunicate_145234_Content_7 = {Text = "Ça va ?"},
  AvgCommunicate_145234_Content_8 = {
    Text = "Ce bruit d'avant — c'était juste de la faim. Une démangeaison désespérée de ne pas être assez fort, assez rapide."
  },
  AvgCommunicate_145234_Content_9 = {
    Text = "Maintenant, c'est parti. Mon corps se sent... rassasié pour la première fois."
  },
  AvgCommunicate_145234_Option_6 = {
    Text = "Est-ce une mauvaise chose ?"
  },
  AvgCommunicate_145234_Option_7 = {Text = "Ça va ?"},
  AvgCommunicate_146392_Content_1 = {
    Text = "Vous êtes là ?"
  },
  AvgCommunicate_146392_Content_10 = {
    Text = "Je l'ai payée pour prendre le contrat à sa place."
  },
  AvgCommunicate_146392_Content_11 = {
    Text = "Vous l'avez trouvée ?"
  },
  AvgCommunicate_146392_Content_12 = {
    Text = "Elle est juste devant moi. Elle dort profondément."
  },
  AvgCommunicate_146392_Content_13 = {
    Text = "J'attends qu'elle se réveille."
  },
  AvgCommunicate_146392_Content_14 = {
    Text = "...C'est raisonnable."
  },
  AvgCommunicate_146392_Content_15 = {
    Text = "Laissez-moi trouver un moyen de vous faire passer le temps..."
  },
  AvgCommunicate_146392_Content_16 = {
    Text = "Oh, je sais ! Vous pourriez..."
  },
  AvgCommunicate_146392_Content_17 = {
    Text = "Ses yeux tressaillent… Elle se réveille."
  },
  AvgCommunicate_146392_Content_18 = {
    Text = "Je dois y aller."
  },
  AvgCommunicate_146392_Content_19 = {
    Text = "Hé ? Lotan ?"
  },
  AvgCommunicate_146392_Content_2 = {Text = "?"},
  AvgCommunicate_146392_Content_3 = {
    Text = "Lotan ? Je croyais que ces choses ne vous intéressaient pas."
  },
  AvgCommunicate_146392_Content_4 = {
    Text = "Juste l'ennui. Je teste ce gadget que Doll m'a donné."
  },
  AvgCommunicate_146392_Content_5 = {
    Text = "Ça pourrait être utile un jour."
  },
  AvgCommunicate_146392_Content_6 = {
    Text = "Vous ? L'ennui ?"
  },
  AvgCommunicate_146392_Content_7 = {
    Text = "Je pensais que vous étiez soit en train de vous battre, soit à la recherche d'un combat."
  },
  AvgCommunicate_146392_Content_8 = {
    Text = "À ce propos, où êtes-vous ? Je ne vous ai pas vu depuis des jours..."
  },
  AvgCommunicate_146392_Content_9 = {
    Text = "J'ai entendu dire que Daffodil traquait une puissante créature ancienne."
  },
  AvgCommunicate_146392_Option_14 = {
    Text = "...C'est raisonnable."
  },
  AvgCommunicate_146392_Option_6 = {
    Text = "Vous ? L'ennui ?"
  },
  AvgCommunicate_146393_Content_1 = {
    Text = "Cornes. Dents. Griffes. Chair. Globes oculaires. Tentacules."
  },
  AvgCommunicate_146393_Content_10 = {
    Text = "J'espère que tu seras tout aussi coriace."
  },
  AvgCommunicate_146393_Content_11 = {Text = "新增"},
  AvgCommunicate_146393_Content_12 = {
    Text = "Merci du compliment."
  },
  AvgCommunicate_146393_Content_2 = {
    Text = "Choisissez-en un."
  },
  AvgCommunicate_146393_Content_3 = {
    Text = "C'est une sorte de jeu « devinez ce qui vous ferait plaisir »... ?"
  },
  AvgCommunicate_146393_Content_4 = {
    Text = "J'ai rapporté le monstre que j'ai tué la dernière fois."
  },
  AvgCommunicate_146393_Content_5 = {
    Text = "Je n'avais nulle part où le mettre de toute façon, je me suis dit que vous voudriez un souvenir."
  },
  AvgCommunicate_146393_Content_6 = {
    Text = "Aucun de ces choix ne semble attrayant..."
  },
  AvgCommunicate_146393_Content_7 = {
    Text = "Est-ce étrange si je les veux tous..."
  },
  AvgCommunicate_146393_Content_8 = {
    Text = "Difficile à dire... tu peux choisir à ma place..."
  },
  AvgCommunicate_146393_Content_9 = {
    Text = "La corne est bien. Elle a tenu trois coups avant de se briser. Elle te va bien."
  },
  AvgCommunicate_146393_Option_6 = {
    Text = "Aucun de ces choix ne semble attrayant..."
  },
  AvgCommunicate_146393_Option_7 = {
    Text = "Est-ce étrange si je les veux tous..."
  },
  AvgCommunicate_146394_Content_1 = {
    Text = "J'ai un problème."
  },
  AvgCommunicate_146394_Content_10 = {
    Text = "Je suis partie trois fois. À chaque fois, ils commençaient à se sacrifier. Apparemment, ils pensaient que c'était une épreuve divine."
  },
  AvgCommunicate_146394_Content_11 = {
    Text = "Ils sont tous fous."
  },
  AvgCommunicate_146394_Content_12 = {
    Text = "Et pourquoi tu es revenue ??"
  },
  AvgCommunicate_146394_Content_13 = {
    Text = "Je n'ai pas retiré ma lame de son cadavre."
  },
  AvgCommunicate_146394_Content_14 = {
    Text = "Maintenant ils l'ont mise en sanctuaire aussi."
  },
  AvgCommunicate_146394_Content_15 = {Text = "新增"},
  AvgCommunicate_146394_Content_16 = {
    Text = "Je dois récupérer ma lame sans qu'ils se suicident en masse devant moi."
  },
  AvgCommunicate_146394_Content_17 = {
    Text = "Vous comprenez ces petites créatures faibles mieux que moi. Aidez-moi."
  },
  AvgCommunicate_146394_Content_18 = {
    Text = "...Hé, qu'est-ce que ça veut dire ?!"
  },
  AvgCommunicate_146394_Content_2 = {
    Text = "Oh, même toi tu as des ennuis parfois !"
  },
  AvgCommunicate_146394_Content_3 = {
    Text = "J'ai entendu parler d'un ver puissant, alors je l'ai tué."
  },
  AvgCommunicate_146394_Content_4 = {
    Text = "Après sa mort, les gens longtemps piégés dans la planète sous sa masse en sont sortis en rampant."
  },
  AvgCommunicate_146394_Content_5 = {
    Text = "Ils m'ont appelée déesse, se sont prosternés devant moi, et m'ont même érigé une statue en or — hideuse au possible."
  },
  AvgCommunicate_146394_Content_6 = {Text = "HAHAHAHAHA"},
  AvgCommunicate_146394_Content_7 = {
    Text = "Arrête de rire."
  },
  AvgCommunicate_146394_Content_8 = {
    Text = "Tu n'aimes pas être vénérée ?"
  },
  AvgCommunicate_146394_Content_9 = {
    Text = "Tu n'aimes pas être vénérée ?"
  },
  AvgCommunicate_146394_Option_6 = {Text = "HAHAHAHA"},
  AvgCommunicate_146394_Option_8 = {
    Text = "Pourquoi tu n'es pas simplement partie ?"
  },
  AvgCommunicate_146394_Option_9 = {
    Text = "Pourquoi tu n'es pas simplement partie ?"
  },
  AvgCommunicate_148438_Content_1 = {
    Text = "Je suppose que tu es déjà au courant, hmm ?"
  },
  AvgCommunicate_148438_Content_10 = {
    Text = "Hi hi, n'y pense pas trop~ Les gens qui réfléchissent trop deviennent des adultes ennuyeux et sans intérêt~"
  },
  AvgCommunicate_148438_Content_11 = {
    Text = "Cela dit, bien sûr, si le Gardien du secret ne peut tout simplement pas s'empêcher d'être attiré par la Fée — si tu te retrouves à suivre chacun de mes pas, jour et nuit, juste pour gagner ma véritable affection — eh bien, ce serait tout à fait compréhensible~"
  },
  AvgCommunicate_148438_Content_12 = {Text = "Ugh..."},
  AvgCommunicate_148438_Content_13 = {
    Text = "J'ai déjà laissé la plus belle pomme d'amour de toutes sur le bureau de ta chambre."
  },
  AvgCommunicate_148438_Content_14 = {
    Text = "Maintenant tu dois, absolument, la savourer lentement, examiner chaque bouchée, et en profiter tout seul~"
  },
  AvgCommunicate_148438_Content_2 = {
    Text = "Alors tu t'es donné tout ce mal pour obtenir un permis de sortie... juste pour acheter à Aigis, Ogier et Murphy des pommes d'amour en édition limitée qu'ils disaient n'avoir jamais goûtées ?"
  },
  AvgCommunicate_148438_Content_3 = {
    Text = "Ces petits vau— ehem — ces enfants dévoués n'ont peut-être pas payé leurs cotisations en totalité, mais ils jouent un rôle absolument vital dans la diffusion des bénédictions de la Fée."
  },
  AvgCommunicate_148438_Content_4 = {
    Text = "Nourrir mon troupeau, pour qu'il répande la bonne parole avec encore plus d'ardeur — eh bien, c'est juste un fardeau de plus que la Fée porte sur ses épaules~"
  },
  AvgCommunicate_148438_Content_5 = {
    Text = "Même si tu avais une bonne raison cette fois, pourquoi est-ce que c'est TOUJOURS sur MON compte que tu le débites..."
  },
  AvgCommunicate_148438_Content_7 = {
    Text = "Oh, ne t'arrête pas aux petits détails~ Regarde, les enfants sont de vrais croyants maintenant. Alors quand vas-tu enfin venir les rejoindre, hmm ?"
  },
  AvgCommunicate_148438_Content_9 = {
    Text = "Je ne sais vraiment pas si tu laisses parfois transparaître un fragment de ton vrai moi, ou si tu es juste un oignon, cachant éternellement ton vrai but sous une couche de plus..."
  },
  AvgCommunicate_148439_Content_1 = {Text = "[Image]"},
  AvgCommunicate_148439_Content_10 = {
    Text = "[Image chargée avec succès]"
  },
  AvgCommunicate_148439_Content_11 = {Text = "[Image]"},
  AvgCommunicate_148439_Content_12 = {
    Text = "Quoi... c'est vraiment une lettre d'excuses..."
  },
  AvgCommunicate_148439_Content_13 = {
    Text = "Je suis désolée... Caraboo. Je n'aurais pas dû réagir comme ça quand tu étais enfin sincère pour une fois."
  },
  AvgCommunicate_148439_Content_14 = {
    Text = "Je vais retirer la plainte que je viens de déposer immédiatement. Celle qui recommandait de te consigner... de refuser toutes les demandes de sortie... Voilà ! J'ai retiré chaque plainte que j'ai jamais déposée contre toi."
  },
  AvgCommunicate_148439_Content_15 = {
    Text = "Magnifique~ Hi hi, Gardien du secret — je crois bien qu'une fois une plainte retirée, tu ne peux pas en déposer une nouvelle contre le même Éveilleur pendant tout un mois, n'est-ce pas ?"
  },
  AvgCommunicate_148439_Content_17 = {
    Text = "J'ai un très mauvais pressentiment..."
  },
  AvgCommunicate_148439_Content_18 = {
    Text = "Oh là là, la Fée ne serait jamais assez ingrate pour jouer avec le cœur sincère de %player%~ Chaque mot de cette lettre d'excuses était la pure vérité. Quand je rentrerai de ma sortie, je t'apporterai la plus douce des pommes rouges~"
  },
  AvgCommunicate_148439_Content_19 = {
    Text = "Attends ! Pourquoi Aigis vient-elle de me trouver en larmes, disant que même si elle n'a aucune idée de ce qu'elle a mal fait, elle espère que je lui pardonnerai en voyant la lettre d'excuses ?"
  },
  AvgCommunicate_148439_Content_2 = {
    Text = "Chargement..."
  },
  AvgCommunicate_148439_Content_20 = {
    Text = "Et que tu avais promis de la lui transmettre — mais qu'elle a décidé de s'excuser en face à face pour être sûre que je ne lui en veuille plus ?!"
  },
  AvgCommunicate_148439_Content_21 = {
    Text = "Hé, Caraboo. CARABOO !!"
  },
  AvgCommunicate_148439_Content_3 = {Text = "?"},
  AvgCommunicate_148439_Content_4 = {
    Text = "Caraboo, tu as déjà utilisé ce tour une fois. Quoi que tu dises, je n'ouvre PAS cette image."
  },
  AvgCommunicate_148439_Content_5 = {
    Text = "Non, %player%... J'y ai vraiment réfléchi. Toi, et tous ceux de Mizag, avez été si gentils avec moi. Je n'aurais vraiment pas dû apporter mes vieilles habitudes dans cet endroit magnifique."
  },
  AvgCommunicate_148439_Content_6 = {
    Text = "Après tout, je n'ai jamais choisi de devenir ce que je suis, pas au tout début."
  },
  AvgCommunicate_148439_Content_7 = {
    Text = "Alors je me suis assise et je t'ai écrit une vraie lettre d'excuses — manuscrite, chaque mot, de ma propre main~ Mais tu ne devineras jamais, le Communicateur a justement eu un bug à ce moment précis..."
  },
  AvgCommunicate_148439_Content_8 = {
    Text = "Je comprends si tu ne me crois pas. Je vais juste... attendre. Le temps qu'il faudra pour que tu me fasses à nouveau confiance..."
  },
  AvgCommunicate_148439_Content_9 = {
    Text = "...Ugh, pourquoi ma conscience se réveille maintenant ? Bref, il n'est pas question que je..."
  },
  AvgCommunicate_148440_Content_1 = {Text = "[Image]"},
  AvgCommunicate_148440_Content_10 = {
    Text = "De quoi tu parles ? Comme si j'allais jamais te rembourser !"
  },
  AvgCommunicate_148440_Content_11 = {Text = "Huh ?"},
  AvgCommunicate_148440_Content_12 = {
    Text = "Tu ne fais même plus semblant ?"
  },
  AvgCommunicate_148440_Content_13 = {
    Text = "Hihihi. Servir la Fée est en soi ton plus grand honneur. Elle te guidera vers un paradis sans égal. À côté de ça, une récompense terrestre ne vaut guère la peine d'être mentionnée, bien sûr."
  },
  AvgCommunicate_148440_Content_14 = {
    Text = "Assez de tout ça ! Si tu ne vires pas l'argent rapidement, la carte sera perdue à jamais..."
  },
  AvgCommunicate_148440_Content_16 = {
    Text = "J'ai déjà regardé ce truc que tu m'as envoyé. C'était clairement fabriqué avec une vulgaire technologie Cœur d'argent..."
  },
  AvgCommunicate_148440_Content_17 = {
    Text = "Oh ? Tu l'as ouvert ? C'était entièrement ton propre choix, tu sais~ Merveilleux ! *La Fée se souviendra à jamais de l'offrande de %player%.*"
  },
  AvgCommunicate_148440_Content_18 = {
    Text = "Attends, pourquoi est-ce que je reçois une notification indiquant qu'on vient de me déduire 1 000 Léofangs — c'est mon allocation de terrain !"
  },
  AvgCommunicate_148440_Content_2 = {
    Text = "Chargement..."
  },
  AvgCommunicate_148440_Content_20 = {
    Text = "Là, là. Tu es plutôt à l'aise financièrement, n'est-ce pas ? Je ne prendrai que 200 Léofangs cette fois — en guise de paiement pour la gentille leçon que tu ne devrais pas ouvrir des liens inconnus sur ton communicateur. Sois reconnaissant envers la miséricorde de la Fée, hmm ?"
  },
  AvgCommunicate_148440_Content_21 = {
    Text = "[Virement : 800 Léofangs]"
  },
  AvgCommunicate_148440_Content_3 = {
    Text = "[Image corrompue]"
  },
  AvgCommunicate_148440_Content_4 = {
    Text = "...Qu'est-ce que tu m'as envoyé ?"
  },
  AvgCommunicate_148440_Content_5 = {Text = "Oups !"},
  AvgCommunicate_148440_Content_6 = {
    Text = "On est fichus ! Cette image contenait une carte vers l'Est, obtenue au prix du sang, de la sueur et des larmes de mes fidèles disciples — et maintenant l'original est corrompu avec elle ! Ce doit être quelque maléfique @2 qui cherche à nous empêcher d'atteindre l'Est !"
  },
  AvgCommunicate_148440_Content_7 = {
    Text = "%player%, combien de Léofangs as-tu sur toi ? Vite, donne-les moi tous ! Il est encore possible de la récupérer..."
  },
  AvgCommunicate_148440_Content_8 = {
    Text = "Laisse-moi deviner, tu me rembourseras au décuple une fois arrivée à l'Est. Je ne suis pas né de la dernière pluie, tu sais."
  },
  AvgCommunicate_148440_Content_9 = {
    Text = "Une arnaque qui ne se renouvelle pas n'a aucun avenir."
  },
  AvgCommunicate_149803_Content_1 = {
    Text = "La mission de garde que l'académie m'avait confiée est accomplie. Y a-t-il quelque chose que vous souhaitez que je fasse, Seigneur ?"
  },
  AvgCommunicate_149803_Content_10 = {
    Text = "En tout cas, si vous ne souhaitez pas rester inactif, il y aura beaucoup d'activités à l'école dans quelques jours. Voulez-vous y participer ?"
  },
  AvgCommunicate_149803_Content_11 = {
    Text = "…Puisque c'est un ordre de Seigneur, j'obéirai."
  },
  AvgCommunicate_149803_Content_12 = {
    Text = "Je vais aller faire ma ronde maintenant."
  },
  AvgCommunicate_149803_Content_13 = {
    Text = "J'espère que vous obéirez vraiment ensuite !"
  },
  AvgCommunicate_149803_Content_2 = {
    Text = "Ne voulez-vous pas vous reposer un peu ?"
  },
  AvgCommunicate_149803_Content_3 = {
    Text = "Ce n'est pas nécessaire."
  },
  AvgCommunicate_149803_Content_4 = {
    Text = "De plus… je n'ai pas le droit de jouir d'une telle tranquillité."
  },
  AvgCommunicate_149803_Content_5 = {
    Text = "Cette ombre continue de me perturber de temps à autre, murmurant à mon oreille."
  },
  AvgCommunicate_149803_Content_6 = {
    Text = "Peut-être que lorsque j'ai quelque chose à faire, je me sens en réalité plus serein."
  },
  AvgCommunicate_149803_Content_7 = {
    Text = "C'est tout, Seigneur, ne vous en faites pas."
  },
  AvgCommunicate_149803_Content_8 = {
    Text = "Il faudrait peut-être que je vous enseigne l'art de la flemme."
  },
  AvgCommunicate_149803_Content_9 = {
    Text = "Se détendre davantage permet de mieux combattre."
  },
  AvgCommunicate_149803_Option_8 = {
    Text = "Il faudrait peut-être que je vous enseigne l'art de la flemme."
  },
  AvgCommunicate_149803_Option_9 = {
    Text = "Se détendre davantage permet de mieux combattre."
  },
  AvgCommunicate_149950_Content_10 = {
    Text = "Hmph...... tu te moques de moi ? C'est déjà la limite de ce que je peux contrôler de ce corps en ce moment !"
  },
  AvgCommunicate_149950_Content_11 = {
    Text = "Que comptes-tu faire ? Continuer à l'inciter, à le manipuler ?"
  },
  AvgCommunicate_149950_Content_12 = {
    Text = "Si j'en étais capable, j'aurais déjà......"
  },
  AvgCommunicate_149950_Content_13 = {
    Text = "Laisse tomber, plutôt que de devenir une lame, être un bouclier ou un rempart ne semble pas si mal non plus......"
  },
  AvgCommunicate_149950_Content_14 = {
    Text = "Quant au maître en qui il a confiance et qu'il sert — toi — au fil des échanges, tu s'avères plutôt intéressant."
  },
  AvgCommunicate_149950_Content_15 = {
    Text = "Je comprends maintenant, c'est Ogier qui t'a influencé en retour."
  },
  AvgCommunicate_149950_Content_17 = {Text = "???"},
  AvgCommunicate_149950_Content_18 = {
    Text = "Maître, je suis vraiment désolé. Je viens d'avoir un blanc pendant quelques minutes."
  },
  AvgCommunicate_149950_Content_19 = {
    Text = "En reprenant mes esprits, j'ai vu le communicateur allumé."
  },
  AvgCommunicate_149950_Content_2 = {
    Text = "Je t'ai enfin trouvé......"
  },
  AvgCommunicate_149950_Content_20 = {
    Text = "J'ai l'impression d'avoir entendu à nouveau, après longtemps, cette voix agaçante......"
  },
  AvgCommunicate_149950_Content_21 = {
    Text = "Comment dire...... il semble que toi et la force qui est en toi puissiez désormais coexister en parfaite harmonie."
  },
  AvgCommunicate_149950_Content_22 = {
    Text = "...... J'ai lu les enregistrements."
  },
  AvgCommunicate_149950_Content_23 = {
    Text = "Je craignais qu'Il ne tienne, comme avant, des propos maléfiques et agressifs."
  },
  AvgCommunicate_149950_Content_24 = {
    Text = "C'est vraiment surprenant. Autrefois, c'était toujours moi qui subissais Son érosion, mais maintenant, on dirait que c'est l'inverse."
  },
  AvgCommunicate_149950_Content_25 = {
    Text = "C'est une bonne chose, je suppose. Du moins... cela prouve que je L'ai complètement vaincu."
  },
  AvgCommunicate_149950_Content_26 = {
    Text = "Bien sûr, serait-ce parce que la puissance d'Ogier s'est accrue, que je peux désormais maîtriser cette entité invisible à ce point ?"
  },
  AvgCommunicate_149950_Content_27 = {
    Text = "Oui, c'est sûrement le cas. Tout cela est certainement dû aux changements que vous avez apportés."
  },
  AvgCommunicate_149950_Content_28 = {
    Text = "De plus, la «Loi Ultime» que j'ai comprise ne se résume pas seulement à la puissance..."
  },
  AvgCommunicate_149950_Content_29 = {
    Text = "Il y a aussi cette conviction de protéger les autres, qui brûle dans ma poitrine avec plus d'ardeur que jamais. Je pense que c'est là la véritable source."
  },
  AvgCommunicate_149950_Content_3 = {
    Text = "Tu n'es pas Ogier, qui es-tu ?"
  },
  AvgCommunicate_149950_Content_4 = {
    Text = "Rends vite le communicateur à son propriétaire !"
  },
  AvgCommunicate_149950_Content_5 = {
    Text = "Ridicule. Sans ma présence, comment cet enfant aurait-il pu survivre, et rester ici en tant qu'Éveilleur ?"
  },
  AvgCommunicate_149950_Content_6 = {
    Text = "Tu es...... cette entité invisible attachée à lui ?"
  },
  AvgCommunicate_149950_Content_7 = {
    Text = "Exactement. Gardien du secret de Mizag, tu ne me reconnais donc pas."
  },
  AvgCommunicate_149950_Content_8 = {
    Text = "Euh...... parce que tu as toujours été sévèrement réprimé par Ogier, je ne t'ai tout simplement jamais vu."
  },
  AvgCommunicate_149950_Option_3 = {
    Text = "Tu n'es pas Ogier, qui es-tu ?"
  },
  AvgCommunicate_149950_Option_4 = {
    Text = "Rends vite le communicateur à son propriétaire !"
  },
  AvgCommunicate_149986_Content_1 = {
    Text = "Mon Seigneur, je suis venu vous adresser une invitation."
  },
  AvgCommunicate_149986_Content_10 = {
    Text = "... Un arbre."
  },
  AvgCommunicate_149986_Content_11 = {Text = "Huh ?"},
  AvgCommunicate_149986_Content_12 = {
    Text = "C'est peut-être parce que j'ai reçu un entraînement professionnel — peu importe le chaos, je peux rester fermement planté sur scène."
  },
  AvgCommunicate_149986_Content_13 = {
    Text = "Mais qu'est-ce qui va bien pouvoir se passer dans votre pièce !"
  },
  AvgCommunicate_149986_Content_14 = {
    Text = "Je ne sais pas, je ne suis qu'un arbre."
  },
  AvgCommunicate_149986_Content_15 = {
    Text = "... Bon, dans le spectacle, Jenkin qui joue la princesse doit tomber du ciel, et Lily qui joue le prince doit la rattraper."
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "Aigis qui joue le roi démon doit même descendre dans le public pour interagir avec les spectateurs."
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "Je n'ai même plus envie de commenter cette répartition des rôles..."
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "Mais là, tu ne viens pas de tout spoiler ?"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "Parce que je ne veux rien vous dissimuler."
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "Le club de théâtre va monter une pièce de conte de fées, et a réuni les Éveilleurs mineurs de Mizag pour y jouer ensemble."
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "Et puis, d'après ce que j'ai vu aux répétitions, chaque fois il se produit des imprévus différents — je ne peux pas non plus garantir ce que Mon Seigneur verra réellement."
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "... Ça, c'est effectivement très intrigant."
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "Ces actions dans le spectacle comportent toutes une certaine part de danger."
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "C'est pourquoi, tout en jouant le rôle de l'arbre, je dois surveiller autant que possible la situation sur scène et dans le public, afin de garantir la sécurité des acteurs et des spectateurs."
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "Alors en réalité, tu y allais pour faire le garde du corps à temps partiel... Ça a l'air vraiment éprouvant."
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "En effet. Quoi qu'il en soit, soyez sans crainte. Tant que je serai sur scène, je ne laisserai plus personne se blesser."
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "C'est un peu difficile à dire... moi aussi je monterai sur scène. J'espère que vous viendrez nous regarder."
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "! J'ai hâte."
  },
  AvgCommunicate_149986_Content_5 = {
    Text = "Cela dit, je ne m'attendais pas à ce que tu acceptes de participer à ce genre d'activité."
  },
  AvgCommunicate_149986_Content_6 = {
    Text = "Hmm, je ne suis plus un enfant depuis longtemps, et il ne me convient guère d'y prendre part."
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "Mais elles ont insisté..."
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "Je ne voulais pas gâcher leur enthousiasme, et j'ai réalisé que ce rôle ne pouvait effectivement être joué que par moi."
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "Alors, quel rôle Ogier va-t-il jouer ? Un chevalier ?"
  },
  AvgCommunicate_149987_Content_1 = {
    Text = "Seigneur, y a-t-il récemment des cours portant sur le Phénomène d'érosion ?"
  },
  AvgCommunicate_149987_Content_10 = {
    Text = "Quelle soif d'apprendre... Si j'étais aussi studieux que toi, je n'aurais certainement pas à me soucier des examens."
  },
  AvgCommunicate_149987_Content_11 = {
    Text = "Je vous en prie, ne me flattez pas ainsi. Les responsabilités que vous portez sont bien plus lourdes que les miennes."
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "De plus, ce n'est que le travail nécessaire que j'accomplis pour expier mes fautes."
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "Mais tu apprends vite. Qui sait, Ogier a peut-être le potentiel pour devenir un érudit."
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "Comme chacun y pense dans son enfance, parlons de l'avenir."
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "Ogier, as-tu déjà pensé à ce que tu voudrais faire en grandissant ?"
  },
  AvgCommunicate_149987_Content_16 = {
    Text = "Vous savez que je suis devenu un Éveilleur. Il n'y a plus de possibilité que je grandisse."
  },
  AvgCommunicate_149987_Content_17 = {
    Text = "On peut quand même rêver à l'avenir ! Ne sois pas si pessimiste."
  },
  AvgCommunicate_149987_Content_18 = {
    Text = "Ogier n'a-t-il rien d'autre qu'il souhaite faire en dehors de «protéger les autres» ?"
  },
  AvgCommunicate_149987_Content_19 = {
    Text = "Je vous remercie de vos encouragements."
  },
  AvgCommunicate_149987_Content_2 = {
    Text = "Je souhaite approfondir mes connaissances dans ce domaine."
  },
  AvgCommunicate_149987_Content_20 = {
    Text = "Quant à d'autres choses que je voudrais faire... Désolé, je n'arrive vraiment pas à en trouver."
  },
  AvgCommunicate_149987_Content_21 = {
    Text = "Lorsque ce corps ne sera plus souillé par le péché, j'y réfléchirai alors."
  },
  AvgCommunicate_149987_Content_3 = {
    Text = "Bien sûr, bien sûr, je t'y emmènerai avec moi plus tard."
  },
  AvgCommunicate_149987_Content_4 = {
    Text = "Mais pourquoi Ogier s'intéresse-t-il soudainement à ce sujet ?"
  },
  AvgCommunicate_149987_Content_5 = {
    Text = "Parce que quelqu'un m'a demandé aujourd'hui si la force qui m'enveloppe était liée à la Lave corrodée."
  },
  AvgCommunicate_149987_Content_6 = {
    Text = "Je vois, en se fiant uniquement à la forme, il y a effectivement une certaine ressemblance."
  },
  AvgCommunicate_149987_Content_7 = {
    Text = "En effet, j'ai toujours été préoccupé par la nature de cette chose invisible. Peut-être qu'en la comprenant suffisamment, je pourrai mieux la contrôler."
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "Bien que depuis mon arrivée à Mizag, j'aie réalisé que les existences difficiles à comprendre sont bien plus nombreuses que je ne l'imaginais..."
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "C'est pourquoi j'ai décidé d'abord d'en apprendre davantage sur la corrosion, car c'est aussi l'ennemi auquel mon seigneur s'oppose depuis longtemps."
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "Ah, mon petit chiot désobéissant, toujours à courir aux quatre coins du globe."
  },
  AvgCommunicate_149988_Content_10 = {
    Text = "Personne ne se soucie de ton William."
  },
  AvgCommunicate_149988_Content_11 = {
    Text = "N'oublie pas : tu es mon petit chiot personnel. Toute menace pesant sur ta misérable vie n'est qu'une perte de mes actifs."
  },
  AvgCommunicate_149988_Content_12 = {
    Text = "De plus, j'ai moi-même choisi ce monde en particulier — une petite faille, à l'abri de la Dissolution."
  },
  AvgCommunicate_149988_Content_13 = {
    Text = "Alors surveille où tu mets les pieds. Essaie de ne pas le briser."
  },
  AvgCommunicate_149988_Content_2 = {
    Text = "Ton signal coupe encore. Dans quel coin perdu de l'enfer t'es-tu encore fourré cette fois ?"
  },
  AvgCommunicate_149988_Content_3 = {
    Text = "Je suis au Continent du Nord de la Fin."
  },
  AvgCommunicate_149988_Content_4 = {
    Text = "Je suis tout là-haut dans les hautes terres."
  },
  AvgCommunicate_149988_Content_5 = {
    Text = "Nous nous préparons à escalader une montagne ensuite. Honnêtement, je m'inquiète un peu pour mon endurance."
  },
  AvgCommunicate_149988_Content_6 = {
    Text = "L'air est incroyablement rare ici. J'ai l'impression que je vais m'évanouir si je cours plus de quelques pas."
  },
  AvgCommunicate_149988_Content_7 = {
    Text = "Et tu crois vraiment pouvoir escalader une montagne dans cet état ? Quel petit chiot imprudent et sans cervelle, totalement ignorant de ses propres limites."
  },
  AvgCommunicate_149988_Content_8 = {
    Text = "Je sais que tu t'inquiètes, mais j'ai des choses que je dois terminer."
  },
  AvgCommunicate_149988_Content_9 = {
    Text = "Ne t'inquiète pas, le Sénior William est avec moi. Tout ira bien."
  },
  AvgCommunicate_149988_Option_3 = {
    Text = "Continent du Nord de la Fin."
  },
  AvgCommunicate_149988_Option_4 = {
    Text = "Une région de haute altitude."
  },
  AvgCommunicate_150103_Content_1 = {
    Text = "Un léger frémissement se propage aux confins de la tapisserie du destin."
  },
  AvgCommunicate_150103_Content_10 = {
    Text = "Est-ce là un autre fil dans votre tapisserie du destin ?"
  },
  AvgCommunicate_150103_Content_11 = {
    Text = "Sur ce point, le métier à tisser doit garder le silence."
  },
  AvgCommunicate_150103_Content_12 = {
    Text = "Et les gens qui vivent dans ce monde ? Qu'advient-il d'eux maintenant ?"
  },
  AvgCommunicate_150103_Content_13 = {
    Text = "Ils retourneront à leur essence la plus pure — les Cœurs d'argent."
  },
  AvgCommunicate_150103_Content_14 = {
    Text = "Et le Dieu-Roi recueillera ces fragments dans la pluie sans fin, remodelant le monde après un long et paisible sommeil."
  },
  AvgCommunicate_150103_Content_15 = {
    Text = "Ce témoignage silencieux sera partagé."
  },
  AvgCommunicate_150103_Content_2 = {
    Text = "Le seuil critique a été franchi. La terre promise si longtemps recherchée est enfin atteinte."
  },
  AvgCommunicate_150103_Content_3 = {
    Text = "Je n'arrive pas à y croire."
  },
  AvgCommunicate_150103_Content_4 = {
    Text = "Le monde disparaît."
  },
  AvgCommunicate_150103_Content_5 = {
    Text = "Le ciel fond, la neige s'effondre, les sommets des montagnes s'écroulent."
  },
  AvgCommunicate_150103_Content_6 = {
    Text = "Ce monde entier... il était tout faux."
  },
  AvgCommunicate_150103_Content_7 = {
    Text = "L'avez-vous toujours su ? Avez-vous toujours été capable de voir cela ?"
  },
  AvgCommunicate_150103_Content_8 = {
    Text = "Se tenir en dehors de la grande scène du monde, c'est tisser pour l'éternité."
  },
  AvgCommunicate_150103_Content_9 = {
    Text = "Cela incluait-il le vœu de Caraboo ? Le monde n'aurait pas disparu sans lui."
  },
  AvgCommunicate_150103_Option_3 = {
    Text = "Je peux le voir..."
  },
  AvgCommunicate_150103_Option_4 = {
    Text = "Le monde est en train de disparaître..."
  },
