  AvgCommunicate_57901_Content_1 = {Text = "?!#¥%&*()"},
  AvgCommunicate_57901_Content_10 = {
    Text = "Ah ! Désolé, Gardien !"
  },
  AvgCommunicate_57901_Content_11 = {
    Text = "Cette fois, je ne vais définitivement pas oublier. Définitivement !"
  },
  AvgCommunicate_57901_Content_2 = {Text = "??"},
  AvgCommunicate_57901_Content_3 = {
    Text = "Désolé, désolé, je ne suis toujours pas très familier avec le clavier."
  },
  AvgCommunicate_57901_Content_4 = {
    Text = "C'est bien. J'ai aussi trébuché au début quand j'ai commencé à l'utiliser. Pratique quelques fois de plus et tu t'en sortiras."
  },
  AvgCommunicate_57901_Content_5 = {
    Text = "Soupir, même ainsi, j'ai peur d'oublier d'ici demain."
  },
  AvgCommunicate_57901_Content_6 = {
    Text = "Alors essaie juste encore quelques fois. Ça devrait aller !"
  },
  AvgCommunicate_57901_Content_7 = {
    Text = "Tu as raison ! Merci, Alva !"
  },
  AvgCommunicate_57901_Content_8 = {
    Text = "...Ça, je ne suis pas Alva."
  },
  AvgCommunicate_57901_Content_9 = {
    Text = "Je suis le Gardien."
  },
  AvgCommunicate_57901_Option_2 = {Text = "??"},
  AvgCommunicate_57901_Option_4 = {
    Text = "Pratiquez davantage, et vous vous y habituerez."
  },
  AvgCommunicate_57901_Option_6 = {
    Text = "Alors faites-le plusieurs fois !"
  },
  AvgCommunicate_57901_Option_8 = {
    Text = "Je ne suis pas Alva."
  },
  AvgCommunicate_57901_Option_9 = {
    Text = "Je suis le Gardien."
  },
  AvgCommunicate_57903_Content_1 = {
    Text = "Bonjour, pâle messager."
  },
  AvgCommunicate_57903_Content_10 = {
    Text = "Je dois dire, c'est plutôt ingénieux."
  },
  AvgCommunicate_57903_Content_2 = {
    Text = "Bonjour, Évêque Salvador."
  },
  AvgCommunicate_57903_Content_3 = {
    Text = "On dirait que vous avez reçu le dernier communicateur. Que pensez-vous ?"
  },
  AvgCommunicate_57903_Content_4 = {
    Text = "C'est assez intéressant et pratique. Même si nous sommes à des centaines de kilomètres l'un de l'autre, nous pouvons toujours communiquer comme si nous étions face à face."
  },
  AvgCommunicate_57903_Content_5 = {
    Text = "Si le monde entier avait de tels dispositifs, la distance entre les gens ne serait pas aussi vaste qu'elle l'est maintenant."
  },
  AvgCommunicate_57903_Content_6 = {
    Text = "Mais je comprends l'unicité de cette technologie—tu sais qu'elle transmet des informations en se liant à d'autres esprits, n'est-ce pas ?"
  },
  AvgCommunicate_57903_Content_7 = {
    Text = "Je sais seulement qu'il y a de l'Argent à l'intérieur."
  },
  AvgCommunicate_57903_Content_8 = {
    Text = "L'as-tu vu ?"
  },
  AvgCommunicate_57903_Content_9 = {
    Text = "C'est vrai, nos esprits sont liés à l'Argent, qui est lié aux Argents dans d'autres dispositifs similaires."
  },
  AvgCommunicate_57903_Option_2 = {
    Text = "Bonjour, Évêque Salvador."
  },
  AvgCommunicate_57903_Option_7 = {
