  AvgCommunicate_57903_Option_8 = {
    Text = "L'as-tu vu ?"
  },
  AvgCommunicate_57904_Content_1 = {
    Text = "Gardien, merci d'avoir apporté l'inventaire au sanatorium hier, et s'il te plaît remercie Noble Dexter pour son soutien continu."
  },
  AvgCommunicate_57904_Content_10 = {
    Text = "C'est tout ce que je peux faire pour l'enfant."
  },
  AvgCommunicate_57904_Content_2 = {
    Text = "C'est ce que nous devrions faire."
  },
  AvgCommunicate_57904_Content_3 = {
    Text = "Le sanatorium n'aurait pas survécu sans vous."
  },
  AvgCommunicate_57904_Content_4 = {
    Text = "Le doyen te sera sûrement reconnaissant."
  },
  AvgCommunicate_57904_Content_5 = {
    Text = "Gérer le sanatorium toute seule, vous avez travaillé dur."
  },
  AvgCommunicate_57904_Content_6 = {
    Text = "Ce que je fais ne représente rien."
  },
  AvgCommunicate_57904_Content_7 = {
    Text = "J'espère simplement que les patients du sanatorium pourront avoir un moment de paix."
  },
  AvgCommunicate_57904_Content_8 = {
    Text = "Si tu as le temps, s'il te plaît, ramène Lily plus souvent."
  },
  AvgCommunicate_57904_Content_9 = {
    Text = "Je vais nettoyer le bureau du principal et t'attendre."
  },
  AvgCommunicate_57904_Option_2 = {
    Text = "C'est ce que nous devrions faire."
  },
  AvgCommunicate_57904_Option_5 = {
    Text = "Gérer le sanatorium toute seule, vous avez travaillé dur."
  },
  AvgCommunicate_57905_Content_1 = {
    Text = "Ding-ding~ Rappel attentionné de la servante Karen : ton petit-déjeuner a été déposé à la porte !"
  },
  AvgCommunicate_57905_Content_10 = {
    Text = "Laisse-moi ! Karen est une femme de ménage polyvalente, capable de gérer tout, du linge au changement de serrure et au-delà !"
  },
  AvgCommunicate_57905_Content_11 = {
    Text = "Non ! Restez en arrière !"
  },
  AvgCommunicate_57905_Content_12 = {
    Text = "Ne sois pas timide ! J'arriverai dans un instant~"
  },
  AvgCommunicate_57905_Content_2 = {
    Text = "Toi ! As-tu pris mes vêtements ?"
  },
  AvgCommunicate_57905_Content_3 = {
    Text = "Oh chérie, Maître, pourquoi es-tu levé si tôt ? Tes vêtements ne sont pas encore secs !"
  },
  AvgCommunicate_57905_Content_4 = {
    Text = "Pas encore sec ? L'avez-vous emporté pour le laver ?"
  },
  AvgCommunicate_57905_Content_5 = {
    Text = "Bien sûr ! Une bonne servante ne pourrait jamais laisser son maître sortir vêtu de vêtements sales et froissés."
  },
  AvgCommunicate_57905_Content_6 = {
    Text = "Alors j'ai veillé toute la nuit et j'ai lavé chaque pièce de tes vêtements, propre, propre, impeccable, impeccable, oh."
  },
  AvgCommunicate_57905_Content_7 = {
    Text = "Vous ne pouvez pas tout laver ! Laissez-en un pour moi !"
  },
  AvgCommunicate_57905_Content_8 = {
    Text = "Le Maître avait encore un autre. Pour être honnête, je voulais vraiment le subtiliser, mais le Maître entoure si bien la couverture en dormant que je n'avais aucune chance."
  },
  AvgCommunicate_57905_Content_9 = {
