  AvgCommunicate_57906_Content_3 = {
    Text = "Pas vraiment..."
  },
  AvgCommunicate_57906_Content_4 = {
    Text = "Ne sois pas timide, ne cache pas les désirs les plus profonds de ton cœur."
  },
  AvgCommunicate_57906_Content_5 = {
    Text = "Cède-le, libère-le, embrase-le !"
