  AvgCommunicate_57906_Content_6 = {
    Text = "Crie de douleur !"
  },
  AvgCommunicate_57906_Content_7 = {
    Text = "Je m'éteins maintenant."
  },
  AvgCommunicate_57906_Content_8 = {
    Text = "C'est rare de trouver un moyen aussi pratique et privé de contacter. N'aie pas peur ; personne ne saura."
  },
  AvgCommunicate_57906_Content_9 = {
    Text = "Tu peux m'appeler pour un service à domicile à tout moment !"
