  AvgCommunicate_57956_Content_4 = {
    Text = "La dame qui est toujours assise sur un étrange dispositif et boit de grandes quantités de liquide sombre a séjourné dans ma chambre pendant trois jours."
  },
  AvgCommunicate_57956_Content_5 = {
    Text = "Je sais qu'elle craint l'obscurité, et je comprends la douleur de ne jamais pouvoir rentrer chez soi tout en suivant la guidance, mais..."
