  },
  AvgCommunicate_57958_Content_10 = {
    Text = "Pas de soucis. Pour répandre la grâce de mon Seigneur, je ne renoncerai à aucune âme obstinée."
  },
  AvgCommunicate_57958_Content_11 = {
    Text = "Demain à 3 heures du matin, je tiendrai une cérémonie dans la Salle de Mythag pour raconter les grands actes de mon maître."
  },
  AvgCommunicate_57958_Content_12 = {
