  },
  AvgCommunicate_57991_Content_6 = {
    Text = "{Male=Mr.,Female=Miss} Gardien, je pense aussi !"
  },
  AvgCommunicate_57991_Content_7 = {
    Text = "Après être revenu, j'ai réfléchi longuement et sérieusement."
  },
  AvgCommunicate_57991_Content_8 = {
    Text = "Bien que vu par des yeux traditionnels, ce vers manque de la connexion esthétique nécessaire."
  },
  AvgCommunicate_57991_Content_9 = {
    Text = "Mais l'harmonie, l'ironie et les erreurs devraient également faire partie de la poésie."
  },
  AvgCommunicate_57991_Option_13 = {
