  },
  AvgCommunicate_66973_Content_12 = {
    Text = "Bien sûr, ma sœur sera toujours la personne la plus importante pour moi, et je continuerai à prendre soin d›elle."
  },
  AvgCommunicate_66973_Content_13 = {
    Text = "On dirait que c›est à mon tour de guider ma sœur lors du prochain rassemblement."
  },
  AvgCommunicate_66973_Content_14 = {
