  AvgCommunicate_66975_Content_10 = {
    Text = "C›est plutôt joli."
  },
  AvgCommunicate_66975_Content_11 = {
    Text = "Hmph, Karen grimaça, vida toutes ses économies pour acheter ces ornements, et les porta tous."
  },
  AvgCommunicate_66975_Content_12 = {
    Text = "Mm... C›est pas trop lourd pour toi?"
  },
  AvgCommunicate_66975_Content_13 = {
    Text = "Quand Karen est allée servir Madame Sorel, la dame a immédiatement déclaré d›un seul coup d›œil que les pierres étaient fausses! C›étaient des contrefaçons!"
  },
  AvgCommunicate_66975_Content_14 = {
    Text = "Que s›est–il passé? Combien t›a–t–elle escroqué?"
  },
  AvgCommunicate_66975_Content_15 = {
    Text = "Un total de 500 Crocs de Lion!!"
  },
  AvgCommunicate_66975_Content_16 = {
    Text = "500 balles pour du vrai? Ridicule! Et les économies dont tu parlais??"
  },
  AvgCommunicate_66975_Content_17 = {
    Text = "Comme Karen adore les choses brillantes, elle dépense tout son argent pour ça, alors elle n›a pas beaucoup économisé..."
  },
  AvgCommunicate_66975_Content_18 = {
    Text = "Laisse tomber... Si tu aimes simplement les pierres brillantes, celles–ci sont effectivement assez brillantes et méticuleusement travaillées."
  },
  AvgCommunicate_66975_Content_19 = {
    Text = "Tu as beaucoup économisé en n›achetant pas les vraies. Pourquoi être triste?"
  },
  AvgCommunicate_66975_Content_2 = {
    Text = "?? Qu'est–ce qui se passe?"
  },
  AvgCommunicate_66975_Content_20 = {
    Text = "Oh, tu marques un bon point."
  },
  AvgCommunicate_66975_Content_21 = {
    Text = "Karen a immédiatement l'impression d›avoir pris l›avantage. Merci, Maître !"
  },
  AvgCommunicate_66975_Content_3 = {
    Text = "Daffodil, cette femme fourbe! Elle a escroqué toutes les économies durement gagnées par Karen au fil des années!"
  },
  AvgCommunicate_66975_Content_4 = {
    Text = "Daffodil t›a arnaquée? Qu›est–ce que tu lui as acheté?"
  },
  AvgCommunicate_66975_Content_5 = {
    Text = "Karen ne faisait que soupirer devant les prix des bijoux dans les magazines, et cette vilaine femme l›a remarqué!"
  },
  AvgCommunicate_66975_Content_6 = {
