  AvgCommunicate_66976_Content_10 = {
    Text = "Ah, désolé, j'ai encore causé des problèmes à tout le monde."
  },
  AvgCommunicate_66976_Content_11 = {
    Text = "Je rendrai le chapeau et j'apporterai du poisson séché pour compenser le chat de l'école."
  },
  AvgCommunicate_66976_Content_12 = {
    Text = "Le chat de l'école préfère peut-être le Fragment d'Argent plutôt que les poissons séchés..."
  },
  AvgCommunicate_66976_Content_13 = {
    Text = "Est-ce vraiment le cas ? Merci beaucoup pour votre aide ! Je ferai de mon mieux pour en rassembler davantage !"
  },
  AvgCommunicate_66976_Content_2 = {
