  },
  AvgCommunicate_66976_Content_3 = {
    Text = "Cette taille ne semble pas convenir aux adultes, mais je ne me souviens pas avoir vu d'enfant portant un tel haut-de-forme."
  },
  AvgCommunicate_66976_Content_4 = {
    Text = "Un petit haut-de-forme noir ? Pourrait-il être le chapeau du chat de l'école ?!"
