  AvgCommunicate_66976_Content_6 = {
    Text = "Chat Scolaire ? Pas étonnant que mon persona de chat soit apparu un moment tout à l'heure."
  },
  AvgCommunicate_66976_Content_7 = {
    Text = "Je peux à peine me souvenir, mais il semble qu'elle se soit battue avec quelqu'un."
  },
  AvgCommunicate_66976_Content_8 = {
