  },
  AvgCommunicate_66977_Content_10 = {
    Text = "Que faire ? Je t'ai encore mis dans l'embarras, je, je vais maintenant contacter Madame Sylva !"
  },
  AvgCommunicate_66977_Content_11 = {
    Text = "Attends, un instant, peu importe... Je sais ce qu'elle a mis..."
  },
  AvgCommunicate_66977_Content_12 = {
    Text = "Quoi ? Quel est le problème, Gardien ?"
  },
  AvgCommunicate_66977_Content_13 = {
    Text = "C'est un laxatif... Je dois aller aux toilettes tout de suite..."
  },
  AvgCommunicate_66977_Content_14 = {
    Text = "Le papier dans ma chambre risque de manquer. N'oublie pas d'en apporter plus tard..."
  },
  AvgCommunicate_66977_Content_15 = {
    Text = "D'accord, d'accord, je vais le faire ! Désolé !!"
  },
  AvgCommunicate_66977_Content_2 = {
    Text = "Uh, n'est-ce pas ? Je viens juste de finir de manger. C'était délicieux. Vos compétences s'améliorent vraiment."
  },
  AvgCommunicate_66977_Content_3 = {
    Text = "Ah ! Mon Dieu ! Je suis venu te dire de ne pas manger ces biscuits ! Ils n'ont pas été faits par moi !"
  },
  AvgCommunicate_66977_Content_4 = {
    Text = "Quoi ? Pas fait par toi ?"
  },
  AvgCommunicate_66977_Content_5 = {
    Text = "Oui, celle qui t'a donné des cookies plus tôt est ma personnalité nouvellement émergente. Elle adore les méfaits..."
  },
  AvgCommunicate_66977_Content_6 = {
    Text = "Je me souviens vaguement qu'elle a ajouté quelque chose en faisant des cookies... Quoi qu'il en soit, vous ne vous sentez pas bien en ce moment ?"
