  AvgCommunicate_66978_Content_10 = {
    Text = "C'est la tâche ménagère la plus simple. Vous avez vraiment perdu le contact avec la vie."
  },
  AvgCommunicate_66978_Content_11 = {
    Text = "Hmph... Je traiterai les esclaves avec plus de douceur dorénavant. Maintenant, va m'en trouver des travailleurs !"
  },
  AvgCommunicate_66978_Content_12 = {
    Text = "Je te l'ai déjà dit, Rome est tombée !"
  },
  AvgCommunicate_66978_Content_13 = {
    Text = "Vous devez rêver dans cette société respectueuse de la loi !"
  },
  AvgCommunicate_66978_Content_14 = {
    Text = "Je me fiche ! Je m'en fiche ! Je préfère mourir que de faire ces tâches ménagères tous les jours !"
  },
  AvgCommunicate_66978_Content_15 = {
    Text = "Heh, pas seulement des corvées, mais aussi des devoirs."
  },
  AvgCommunicate_66978_Content_16 = {
    Text = "Je vais te jeter dans le labyrinthe pour nourrir ma progéniture !"
  },
  AvgCommunicate_66978_Content_2 = {
    Text = "? Mordu par quoi??"
  },
  AvgCommunicate_66978_Content_3 = {
    Text = "C'est entièrement de ta faute de ne pas m'avoir assigné de serviteurs !! Qui aurait cru que ce maudit drap serait si difficile à changer ?!"
  },
  AvgCommunicate_66978_Content_4 = {
    Text = "Peu importe combien j'ai essayé, je n'ai pas pu comprendre, et dans ma frustration, j'ai fini par me battre avec la couverture !"
  },
  AvgCommunicate_66978_Content_5 = {Text = "新增"},
