  AvgCommunicate_66979_Content_1 = {
    Text = "Gardien, le gâteau que vous venez d'envoyer à la Mare noire, c'était pour l'anniversaire de l'employé vétéran responsable de la fabrication de la Clé d'argent, n'est-ce pas ?"
  },
  AvgCommunicate_66979_Content_10 = {
    Text = "Pfff, je comprends. Je vous en envoie un autre tout de suite !"
  },
  AvgCommunicate_66979_Content_11 = {Text = "Merci."},
  AvgCommunicate_66979_Content_2 = {
    Text = "Mm ! Même s'ils savent que vous ne mangez pas, ils voulaient que vous participiez à la fête, alors ils ont laissé passer."
  },
  AvgCommunicate_66979_Content_3 = {
    Text = "Merci pour votre gentillesse. Veuillez transmettre mes vœux d'anniversaire et demander si un autre gâteau peut être envoyé ?"
  },
  AvgCommunicate_66979_Content_4 = {
    Text = "Hmm ? Vous l'avez vraiment mangé ?!"
  },
  AvgCommunicate_66979_Content_5 = {
    Text = "Sur un coup de tête. Cet employé travaille avec moi depuis de nombreuses années sans avoir commis la moindre erreur."
  },
  AvgCommunicate_66979_Content_6 = {
    Text = "Bien que je possède un savoir infini et comprenne tous les principes, en réalité, je n'ai jamais mangé de gâteau."
  },
  AvgCommunicate_66979_Content_7 = {
    Text = "Alors, vous n'avez que des connaissances théoriques sur les gâteaux ?"
  },
  AvgCommunicate_66979_Content_8 = {
    Text = "Oui, je connais tous les ingrédients de ce gâteau et son arôme sucré de graisse animale."
