  },
  AvgCommunicate_66980_Content_1 = {
    Text = "Excusez-moi, à quoi sert cette boîte mécanique complexe ?"
  },
  AvgCommunicate_66980_Content_10 = {
    Text = "Arrête de chercher ! Ce n'est pas important. Si ça casse, ce sera très coûteux !"
  },
  AvgCommunicate_66980_Content_11 = {
    Text = "D'accord, alors à quoi sert cette boîte ?"
  },
  AvgCommunicate_66980_Content_12 = {
    Text = "Ceci est le communicateur délivré par l'école pour la communication à distance. Il peut également être utilisé pour appeler à l'aide dans des situations dangereuses."
  },
  AvgCommunicate_66980_Content_13 = {
    Text = "Je vois, quelle invention intéressante. Merci, Gardien."
  },
  AvgCommunicate_66980_Content_14 = {
    Text = "Te souviens-tu vraiment qui je suis ?"
  },
  AvgCommunicate_66980_Content_15 = {
    Text = "Je me souviens. J'ai promis que je n'oublierais pas."
  },
  AvgCommunicate_66980_Content_16 = {
    Text = "Tu es %player%, mon ami !"
  },
  AvgCommunicate_66980_Content_2 = {
    Text = "? Avez-vous tout oublié ?"
  },
  AvgCommunicate_66980_Content_3 = {
    Text = "Oublié ? Je ne me souviens pas d'où vient cette boîte."
  },
  AvgCommunicate_66980_Content_4 = {
    Text = "Mais j'ai vu les journaux de chat. Je pense que je l'ai utilisé auparavant, mais j'ai oublié comment."
  },
  AvgCommunicate_66980_Content_5 = {
    Text = "Comment l'utilisez-vous maintenant ?!"
