  AvgCommunicate_66980_Content_7 = {
    Text = "Ne ris pas de moi parce que j'ai peur !"
  },
  AvgCommunicate_66980_Content_8 = {
    Text = "Je l'ai démonté et remonté, et maintenant j'ai une compréhension générale de son fonctionnement."
  },
  AvgCommunicate_66980_Content_9 = {
    Text = "Bien que les principes de conduite à l'intérieur soient très complexes, je ne les ai pas encore complètement compris. Ils peuvent nécessiter plus de recherche."
  },
  AvgCommunicate_66980_Option_10 = {
