  AvgCommunicate_66981_Content_1 = {
    Text = "Gardien, quelles sont tes pensées sur les émotions humaines ?"
  },
  AvgCommunicate_66981_Content_10 = {
    Text = "Que dire de vous ? En tant que Corps Intellectuel, n'êtes-vous pas censé être absolument rationnel ?"
  },
  AvgCommunicate_66981_Content_11 = {
    Text = "Tu es perspicace, Gardien, ce qui est une des raisons pour lesquelles j'ai toujours essayé de minimiser mes contacts avec le monde."
  },
  AvgCommunicate_66981_Content_12 = {
    Text = "Lorsque je me distance du monde et évite d'entretenir des liens trop étroits avec les humains, je reste lucide et indépendant."
  },
  AvgCommunicate_66981_Content_13 = {
    Text = "C'est comme si je n'avais jamais goûté à la douceur du gâteau, je ne penserais pas constamment à cela dans mon esprit."
  },
  AvgCommunicate_66981_Content_14 = {
    Text = "Je vois... Alors, tu veux manger des petits gâteaux maintenant ?"
  },
  AvgCommunicate_66981_Content_15 = {
    Text = "Ce n'est pas une nécessité, mais si cela t'est pratique, je t'en serais très reconnaissant."
  },
  AvgCommunicate_66981_Content_2 = {
    Text = "Un sujet si profond dès le départ !"
  },
  AvgCommunicate_66981_Content_3 = {
    Text = "Émotions... tout le monde en a, après tout, nous ne sommes qu'humains."
  },
  AvgCommunicate_66981_Content_4 = {
    Text = "Exactement, les humains existent en se reposant sur leur chair, et les émotions surgissent des réactions instinctives."
  },
  AvgCommunicate_66981_Content_5 = {
    Text = "La plupart des choix humains sont influencés par des émotions plutôt que par une pensée rationnelle, ce qui nécessite de la retenue et des efforts."
  },
  AvgCommunicate_66981_Content_6 = {
    Text = "En effet, maintenir une rationalité absolue en tout temps semble possible seulement pour le Gardien Poupée."
  },
  AvgCommunicate_66981_Content_7 = {
    Text = "Non, Doll ne peut pas le faire non plus. Elle a encore des attaches émotionnelles et prendra de grands risques en prenant des décisions."
  },
  AvgCommunicate_66981_Content_8 = {
    Text = "Est-ce comme ça ? Toutes les personnes sont-elles comme ça, y compris ces individus tordus et fous ?"
