  },
  AvgCommunicate_66982_Content_11 = {
    Text = "Comment pourrais-je me permettre de tels bibelots luxueux pour femmes fortunées, même si j›avais l›argent !"
  },
  AvgCommunicate_66982_Content_12 = {
    Text = "Je m›en fiche ! Trouve une solution ! Ce lapin doit vouloir être avec moi aussi."
  },
  AvgCommunicate_66982_Content_13 = {
    Text = "J›ai choisi un nom : Ivy !"
  },
  AvgCommunicate_66982_Content_14 = {
    Text = "Il rejoindra Jenny, Oliver et moi pour le goûter."
  },
  AvgCommunicate_66982_Content_15 = {
    Text = "D›accord, d›accord, j›irai demander à Madame Sorel, et je m›assurerai de le rapporter pour nos retrouvailles."
  },
  AvgCommunicate_66982_Content_16 = {
    Text = "Hehe, c'est plus comme ça !"
  },
  AvgCommunicate_66982_Content_2 = {
    Text = "Quel gâteau en édition limitée veux-tu cette fois ?"
  },
  AvgCommunicate_66982_Content_3 = {
    Text = "Tu crois vraiment que je ne pense qu'à manger !"
  },
  AvgCommunicate_66982_Content_4 = {
    Text = "Sinon... Quoi d›autre ?"
  },
  AvgCommunicate_66982_Content_5 = {
    Text = "Hmph, les gâteaux c›est bien, mais cette fois il ne s›agit pas de nourriture."
  },
  AvgCommunicate_66982_Content_6 = {
    Text = "Dans le magazine que tu as rapporté la dernière fois, j›ai vu que le grand magasin de Londinium a lancé une peluche artisanale."
  },
  AvgCommunicate_66982_Content_7 = {
    Text = "Il y a une peluche lapin noire et rose à l›intérieur !"
  },
  AvgCommunicate_66982_Content_8 = {
    Text = "C›est pratiquement fait pour moi ! Le magazine dit que c›est un chef-d›œuvre d›un grand maître. Dépêche-toi de me l›acheter !"
  },
  AvgCommunicate_66982_Content_9 = {
    Text = "Un chef-d›œuvre ?"
  },
  AvgCommunicate_66982_Option_10 = {
    Text = "Seulement, vendez-moi déjà."
  },
  AvgCommunicate_66982_Option_15 = {
    Text = "D›accord, d›accord, d›accord..."
  },
  AvgCommunicate_66982_Option_2 = {
    Text = "Quel gâteau en édition limitée veux-tu cette fois ?"
  },
  AvgCommunicate_66982_Option_4 = {
    Text = "Sinon... Quoi d›autre ?"
  },
  AvgCommunicate_66982_Option_9 = {
    Text = "Un chef-d›œuvre ?"
  },
  AvgCommunicate_66983_Content_1 = {
    Text = "Hey, tu n'as pas besoin de m'apporter de gâteaux ces jours-ci."
  },
  AvgCommunicate_66983_Content_10 = {
    Text = "Et avec une brillante variété d'ingrédients, tu peux ajouter autant que tu veux—c'est absolument délicieux !"
  },
  AvgCommunicate_66983_Content_11 = {
    Text = "C'est le point clé ! N'ajouterait-il pas plus pour le rendre écrasant ?"
  },
  AvgCommunicate_66983_Content_12 = {
    Text = "Vous ne comprendriez pas—mes nouvelles créations ont reçu d'innombrables éloges de la part de ces chefs !"
  },
  AvgCommunicate_66983_Content_13 = {
    Text = "La production a commencé hier et c'est déjà en rayon dans la cafétéria. Il y a beaucoup de gens en ligne !"
  },
  AvgCommunicate_66983_Content_14 = {
    Text = "Alors c'est toi qui as fait ces nouveaux mini gâteaux que tout le monde s'est précipité d'acheter hier !"
  },
  AvgCommunicate_66983_Content_15 = {
    Text = "Hahahahaha, suis-je incroyable ou pas ? Appelez-moi un génie !"
  },
  AvgCommunicate_66983_Content_16 = {Text = "Genius !"},
  AvgCommunicate_66983_Content_17 = {
    Text = "Mais je me suis soudain rendu compte que les gâteaux faits maison pourraient avoir meilleur goût. Continuer ainsi à partir de maintenant n'est pas une mauvaise idée."
  },
  AvgCommunicate_66983_Content_18 = {
    Text = "Comme c'est agréable, la jeune dame a enfin expérimenté la joie du travail."
  },
  AvgCommunicate_66983_Content_2 = {
    Text = "Que suis-je en train de voir ? Qu'est-ce qui t'a frappé ?"
  },
  AvgCommunicate_66983_Content_3 = {
    Text = "Quel attaque ? Je vais très bien !"
  },
  AvgCommunicate_66983_Content_4 = {
    Text = ": Qui êtes-vous ?"
  },
  AvgCommunicate_66983_Content_5 = {
    Text = "Soupir, c'est juste que je me suis lassé des petits gâteaux de la cafétéria récemment, et ces chefs tête vide n'ont aucune intention d'introduire de nouveaux !"
  },
  AvgCommunicate_66983_Content_6 = {
    Text = "En effet, personne n'a autant de désir pour les cupcakes que toi..."
  },
  AvgCommunicate_66983_Content_7 = {
    Text = "C'est entièrement de leur faute d'être si incompétents, alors j'ai fait irruption dans la cuisine et leur ai demandé de m'apprendre à faire un gâteau."
  },
  AvgCommunicate_66983_Content_8 = {
    Text = "Huh ? Toi, cuisiner ?"
