  AvgCommunicate_66984_Content_10 = {
    Text = "Mais j'ai répondu que j'avais déjà un cavalier."
  },
  AvgCommunicate_66984_Content_11 = {
    Text = "En réalité, c'est seulement maintenant que je cherche mon charmant cavalier."
  },
  AvgCommunicate_66984_Content_12 = {
    Text = "Je pense que {Male=he,Female=she} ne supporterait pas de me laisser assister au bal toute seule, n'est-ce pas ?"
  },
  AvgCommunicate_66984_Content_13 = {
    Text = "Que dis-tu ?"
  },
  AvgCommunicate_66984_Content_14 = {
    Text = "C'est un honneur, madame."
  },
  AvgCommunicate_66984_Content_15 = {
    Text = "Je devrais me dépêcher d'apprendre l'étiquette de la danse, pour ne pas marcher sur les pieds de Madame."
  },
  AvgCommunicate_66984_Content_16 = {
    Text = "Vous êtes toujours si fiable et attentionné, mon chevalier."
  },
  AvgCommunicate_66984_Content_2 = {
    Text = "Qu'est-ce qui a laissé Mme Sorel perplexe ?"
  },
  AvgCommunicate_66984_Content_3 = {
    Text = "Je suis tout ouïe."
  },
  AvgCommunicate_66984_Content_4 = {
    Text = "Dans quelques jours, j›assiste à un dîner mondain, vous savez, un rassemblement de gens raffinés mais prétentieux qui ne font rien."
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "C›est agaçant, récemment un individu grossier n›arrête pas de m›importuner ; il assiste aussi au bal et a même eu l›audace de m›inviter à être sa cavalière."
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "Quelle personne agaçante. Voulez-vous que je m›occupe de lui pour vous, madame ?"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "Hé hé, vous devenez de plus en plus doué pour plaisanter."
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "Malheureusement, pas maintenant. Le monde des adultes est toujours si compliqué. Cependant, j›ai déjà décliné son invitation."
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "Alors le problème est résolu ?"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "C'est un honneur, madame."
  },
  AvgCommunicate_66984_Option_2 = {
