  AvgCommunicate_66984_Option_9 = {
    Text = "Alors le problème est résolu ?"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "Mon petit chevalier, grâce à votre aide lors du dernier bal, j›ai enfin réussi à me débarrasser de cette personne agaçante."
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "Envie de faire un vœu ? Alors souhaitez un grand dîner aux chandelles avec la belle Madame Sorel."
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "Juste vous et moi. Pas besoin de socialiser avec qui que ce soit d›autre."
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "À vos souhaits, petit malin."
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "Qu›aimeriez-vous manger ? Dites-le-moi, et je le dégusterai avec vous."
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "Ça met vraiment à l›épreuve l›imagination de quelqu›un qui mange à la cantine tous les jours. Laissez-moi goûter le plat que madame préfère."
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "Hé, vous êtes un enfant tellement charmant."
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "Je vous attendrai dans mon manoir."
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "Pour exprimer ma gratitude envers votre gentillesse et votre générosité, j›aimerais faire quelque chose pour vous en guise de remerciement."
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "Vous êtes trop aimable, Madame Sorel. Je pensais que notre relation n›exigeait plus de telles expressions de gratitude."
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "Je n›aime vraiment pas exprimer ma gratitude verbalement ; la plupart du temps, ce ne sont que des politesses hypocrites."
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "Mais une occasion de me faire n›importe quelle demande — cela ne vous intéresse pas ?"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "Oh, n›importe quelle demande ? Si ces nobles messieurs l›apprennent, ils seront tellement jaloux."
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "Vous mériterez toujours un traitement spécial de ma part."
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "Ça me laisse vraiment perplexe... Je suis tellement indécis. Si je me lance et demande un manoir, est-ce que l›école le découvrira ?"
  },
  AvgCommunicate_66985_Content_9 = {
