  AvgCommunicate_66985_Option_8 = {
    Text = "Ça me laisse vraiment perplexe..."
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "Je viens de combattre Lotan. C›était un match nul."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Hahaha... Je pense que je n›ai pas autant de pensées parasites, alors laissons les choses comme ça pour l›instant."
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "Alors, tu es aussi très forte."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "C›est dommage qu›il y ait toujours quelqu›un qui pêche près de la cascade. C›est un peu bruyant."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "Une fois, je suis sortie de la cascade et je lui ai demandé de faire moins de bruit. Il a eu tellement peur qu›il m›a jeté le poisson au visage et s›est enfui."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "Je ne sais pas s›il reviendra."
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Mm... Je ne pense pas..."
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "Qu›est-ce qui t›arrive ?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "Pas de disputes, n›est-ce pas ?"
  },
  AvgCommunicate_66986_Content_4 = {
    Text = "Rien, juste un combat amical entre guerriers."
  },
  AvgCommunicate_66986_Content_5 = {
    Text = "Avant, elle disait que mon combat n›était pas assez pur. Maintenant, je crois que je comprends."
