  AvgCommunicate_66987_Content_10 = {
    Text = "Quelle vieille dame gentille et douce."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Mm, alors je veux aussi apprendre à cuisiner le poisson. La prochaine fois, je le préparerai pour elle."
