  AvgCommunicate_66987_Content_12 = {
    Text = "C'est si touchant ! Il faut absolument faire ça ! Je vais interroger le chef de la cantine tout de suite !"
  },
  AvgCommunicate_66987_Content_13 = {Text = "Merci."},
  AvgCommunicate_66987_Content_2 = {
    Text = "Une recette ?? Vous allez cuisiner ?"
  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Mm, les alentours de la cascade sont restés calmes pendant longtemps depuis que j'ai fait fuir le dernier pêcheur."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "Une vieille dame vient pêcher ici ces derniers temps. Elle est discrète, alors je ne me suis pas montré(e)."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Ensuite, elle a allumé un feu pour griller le poisson qu'elle avait attrapé."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "Comme ça sentait si bon, mon estomac a un peu gargouillé, et elle l'a remarqué."
