  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Récemment, j›ai gagné pas mal d›argent, mais j›ai failli mourir. Heureusement, la Déesse de la Chance est toujours à mes côtés."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "Résultat, pendant notre combat, le piège déclenché l'a accidentellement touché."
  },
  AvgCommunicate_66988_Content_11 = {Text = "Huh ?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "Je lui ai fait un garrot d'urgence pour stopper l'hémorragie, puis je l'ai amené vivant au poste de police."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "La police m'a donné une prime, et le criminel a été renvoyé en prison. J'ai entendu dire que sa peine a été changée en réclusion à perpétuité."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "Il aurait pu être libéré dans quelques années. Pourquoi faire quelque chose d'aussi stupide ? Pfff..."
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Difficile de dire qui de vous deux a le plus souffert..."
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "Mais je me souviens qu'hier, tu étais poursuivi par les gens de la salle de jeux pour recouvrer des dettes. Où est passé ton argent de la prime ?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "Hahaha... Après tout, ma chance est limitée, et si je l'épuise trop tôt, il se peut que je me plante quelques fois à la table de jeu..."
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "En entendant ça, je me suis soudainement senti beaucoup plus serein."
  },
  AvgCommunicate_66988_Content_2 = {
    Text = "Que s'est-il passé ??"
  },
  AvgCommunicate_66988_Content_3 = {
    Text = "Tu sais, j›accepte des missions de détective en parallèle, et mon taux de réussite élevé fait que je suis très demandée."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "Mais inversement, ceux que j›ai envoyés en prison me détestent au point d›en grincer des dents."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Parce qu›ils ont vraiment perdu d›une manière si inexplicable."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "L›autre jour, un criminel s›est évadé de prison et s›est caché dans mon tripot habituel pendant plusieurs jours. Finalement, il m›a trouvée."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "C›est une vengeance contre moi ?!"
  },
  AvgCommunicate_66988_Content_8 = {
    Text = "Exactement, il me suivait depuis longtemps et m'a finalement coincé dans une ruelle."
  },
  AvgCommunicate_66988_Content_9 = {
    Text = "Il avait posé un piège dans la ruelle, avec l'intention de me tuer."
  },
  AvgCommunicate_66988_Option_11 = {Text = "Huh ?"},
  AvgCommunicate_66988_Option_15 = {
    Text = "Difficile de dire qui de vous deux a le plus souffert..."
  },
  AvgCommunicate_66988_Option_18 = {
    Text = "En entendant ça, je me suis soudainement senti beaucoup plus serein."
  },
  AvgCommunicate_66988_Option_2 = {
    Text = "Que s'est-il passé ??"
  },
  AvgCommunicate_66988_Option_5 = {
    Text = "Parce qu›ils ont vraiment perdu d›une manière si inexplicable."
  },
  AvgCommunicate_66988_Option_7 = {
    Text = "C›est une vengeance contre moi ?!"
  },
  AvgCommunicate_66989_Content_1 = {
    Text = "Gardien, la question que vous m'avez posée sur les solutions de gestion de crise pour les enquêteurs a été organisée."
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "Je prendrai soin de vos besoins plus que Ramona ne l'a fait, mais n'oubliez pas, j'étais elle aussi."
  },
  AvgCommunicate_66989_Content_11 = {
    Text = "Si vous voulez me duper, vous feriez mieux de continuer à vous entraîner."
  },
  AvgCommunicate_66989_Content_12 = {
    Text = "Pfff... Mes sentiments sincères ont été mal interprétés !"
  },
  AvgCommunicate_66989_Content_13 = {
    Text = "Alors, le devoir — ah, non, je veux dire la question — tu peux me donner quelques indices sur comment l'aborder ?"
  },
  AvgCommunicate_66989_Content_14 = {Text = "Ramona ?"},
  AvgCommunicate_66989_Content_15 = {Text = "Ramona—"},
  AvgCommunicate_66989_Content_2 = {
    Text = "Génial ! Je savais que tu étais la plus fiable."
  },
  AvgCommunicate_66989_Content_3 = {
    Text = "Merci, mais le résultat ne serait–il pas le même si vous posiez ces questions à Ramona dans votre monde ? Pourquoi venir me voir ?"
  },
  AvgCommunicate_66989_Content_4 = {
    Text = "Tu sais, Ramona est très méticuleuse. Si je lui demande directement, elle me forcera à trouver la réponse par moi–même."
