  },
  AvgCommunicate_66990_Content_12 = {
    Text = "Bien sûr, leurs noms sont Aigis et Lily. Ce sont des amis. Les amis ne peuvent pas avoir le même nom !"
  },
  AvgCommunicate_66990_Content_13 = {
    Text = "Alors pourquoi m'appelle-t-on le Gardien..."
  },
  AvgCommunicate_66990_Content_14 = {
