  AvgCommunicate_66997_Content_1 = {
    Text = "Hé, j'ai entendu dire que Murphy n'a pas assisté aux cours récemment. Que se passe-t-il ?"
  },
  AvgCommunicate_66997_Content_10 = {
    Text = "Bien sûr, il suffit de le reprendre."
  },
  AvgCommunicate_66997_Content_11 = {
    Text = "Bonjour, est-ce la police ? Quelqu'un est sur le point de commettre un crime encore une fois."
  },
  AvgCommunicate_66997_Content_12 = {
    Text = "D'accord, je vais l'acheter, d'accord ? Curieux."
  },
  AvgCommunicate_66997_Content_13 = {
    Text = "Souviens-toi, je te surveille. Si tu essaies quoi que ce soit de louche avec Murphy... Hmph."
  },
  AvgCommunicate_66997_Content_2 = {
    Text = "Elle a mangé trop de petits gâteaux et a eu mal au ventre. Mais pourquoi ne pas lui demander vous-même ?"
