  AvgCommunicate_66998_Content_3 = {
    Text = "Quelle blague ! Semblant que ces imbéciles pourraient un jour me piéger."
  },
  AvgCommunicate_66998_Content_4 = {
    Text = "Après le dernier incident, j›ai désormais conquis avec succès la moitié du monde souterrain de Londinium."
  },
  AvgCommunicate_66998_Content_5 = {
