  },
  AvgCommunicate_66998_Content_6 = {
    Text = "Un gang ?? Dans quel genre d›activités illégales t›es-tu impliquée ?"
  },
  AvgCommunicate_66998_Content_7 = {
    Text = "Quoi ? Si combattre la pègre est considéré comme mal, alors il ne reste probablement plus de bonnes personnes dans ce monde."
  },
  AvgCommunicate_66998_Content_8 = {
    Text = "Pour être honnête, le Mizag ou ce commissariat me doit une médaille d'honneur."
  },
  AvgCommunicate_66998_Content_9 = {
    Text = "Maintenant, ce groupe a été maté par mes soins. Vous n'avez pas remarqué que la sécurité de la ville s'est améliorée ?"
  },
  AvgCommunicate_66998_Option_10 = {
    Text = "Pour le moment, il est difficile de dire si vous avez fait quelque chose de bien ou de mal..."
  },
  AvgCommunicate_66998_Option_13 = {
    Text = "Quoi que vous prépariez, je préviendrai la police de vous surveiller de près."
  },
  AvgCommunicate_66998_Option_2 = {
    Text = "Un voyage ? Qu›est-ce que tu as fait ? Tu es encore au poste de police ?"
  },
  AvgCommunicate_66998_Option_6 = {
    Text = "Un gang ?? Dans quel genre d›activités illégales t›es-tu impliquée ?"
  },
  AvgCommunicate_66999_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%, j'ai récemment été invité par l'Université de Misargh à aider à enregistrer la musique de transition entre les cours."
  },
  AvgCommunicate_66999_Content_10 = {
    Text = "S'il y a quelque chose de spécial, c'est probablement débordant de mes sentiments de protection envers vous."
  },
  AvgCommunicate_66999_Content_11 = {
    Text = "J'ai toujours eu un peu de mal à me lever. Peut-être qu'une musique revigorante faciliterait cela !"
  },
  AvgCommunicate_66999_Content_12 = {
    Text = "Excitant, n'est-ce pas ? Je comprends."
  },
  AvgCommunicate_66999_Content_13 = {
    Text = "Bien que je pense que le sommeil suffisant et de qualité est plus important, étant donné les nombreuses responsabilités que vous portez, être occupé est inévitable."
  },
  AvgCommunicate_66999_Content_14 = {
    Text = "J'espère que cette marche te donnera du pouvoir."
  },
  AvgCommunicate_66999_Content_2 = {
    Text = "Dans l'enregistrement, le professeur Poupée a également mentionné que l'école avait développé un nouveau type d'enregistreur. Il est de petite taille, avec une qualité audio claire, et peut même être transporté lors des missions, offrant à la fois des fonctions d'enregistrement et de lecture."
  },
  AvgCommunicate_66999_Content_3 = {
    Text = "Quand je l'ai vu, j'ai pensé à toi. Si nécessaire, je peux enregistrer la pièce musicale que tu aimes pour toi."
  },
  AvgCommunicate_66999_Content_4 = {
    Text = "Même quand je ne suis pas à tes côtés, il y aura de la musique pour apaiser ton âme."
  },
  AvgCommunicate_66999_Content_5 = {
    Text = "Hameln... Je suis profondément ému !"
  },
  AvgCommunicate_66999_Content_6 = {
    Text = "C'est toute partie de mon devoir. Alors, y a-t-il quelque chose que vous aimeriez entendre ?"
  },
  AvgCommunicate_66999_Content_7 = {
    Text = "En parlant de cela, je dors toujours bien chaque fois que tu joues la berceuse."
  },
  AvgCommunicate_66999_Content_8 = {
    Text = "Qu'est-ce qui est spécial dans cette mélodie ?"
  },
  AvgCommunicate_66999_Content_9 = {
    Text = "Celui-ci ? Je vois."
  },
  AvgCommunicate_66999_Option_11 = {
    Text = "Musique pour aider à se réveiller"
  },
  AvgCommunicate_66999_Option_5 = {
    Text = "Hameln... Je suis profondément ému !"
  },
  AvgCommunicate_66999_Option_7 = {
    Text = "Musique qui aide à dormir"
  },
  AvgCommunicate_67000_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%. J'ai récemment composé un nouveau morceau et j'aimerais vous inviter à l'écouter et à le critiquer quand vous aurez un moment de libre."
  },
  AvgCommunicate_67000_Content_10 = {
    Text = "Ah, de telles exigences sont en effet sévères. Je m'excuse de ne pas avoir pris cela en compte plus soigneusement."
  },
  AvgCommunicate_67000_Content_11 = {
    Text = "Peut-être que la prochaine fois, je jouerai à votre chevet et enregistrerai soigneusement votre sommeil."
  },
  AvgCommunicate_67000_Content_12 = {
    Text = "J'espère ma vigilance t'apporte la paix dans chaque sommeil."
  },
  AvgCommunicate_67000_Content_2 = {
    Text = "Tu es trop gentil, Hameln. En tant qu'amateur à moitié cuit, je ne suis guère qualifié pour critiquer ton travail."
  },
  AvgCommunicate_67000_Content_3 = {
    Text = "Non, ne te sous-estime pas ; tes suggestions sont ma plus grande source de motivation."
  },
  AvgCommunicate_67000_Content_4 = {
    Text = "Est-ce vraiment si exagéré ? Cependant, je dois honteusement admettre, je m'endors toujours en écoutant tes nouvelles compositions..."
  },
  AvgCommunicate_67000_Content_5 = {
    Text = "Votre musique est belle et jouée à la perfection, mais elle me fait toujours tomber instantanément dans le sommeil. Peut-être que je manque vraiment de talent musical."
  },
  AvgCommunicate_67000_Content_6 = {
    Text = "Non, c'est exactement ce que je veux."
  },
  AvgCommunicate_67000_Content_7 = {
    Text = "Mon mission et devoir est de vous apporter un sommeil paisible."
  },
  AvgCommunicate_67000_Content_8 = {
    Text = "Au contraire, veuillez décrire en détail les sentiments que vous apportent différentes pièces, ainsi que la qualité de votre sommeil, le temps qu'il vous faut pour vous endormir et la durée de votre sommeil."
  },
  AvgCommunicate_67000_Content_9 = {Text = "Huh ?"},
  AvgCommunicate_67000_Option_2 = {
    Text = "Tu es vraiment trop poli."
  },
  AvgCommunicate_67000_Option_4 = {
    Text = "Est-ce vraiment si exagéré ?"
  },
  AvgCommunicate_67000_Option_9 = {Text = "Huh ?"},
  AvgCommunicate_67001_Content_1 = {
    Text = "Gardien, les nouvelles chaussures de danse devant ma porte, c›est vous qui les avez envoyées ?"
  },
  AvgCommunicate_67001_Content_10 = {
    Text = "Non, pas du tout. Les chaussures de danse que vous m›avez offertes inspirent mon âme."
  },
  AvgCommunicate_67001_Content_11 = {
    Text = "Savoir que quelqu›un attend ma danse avec impatience me motive à continuer de danser."
  },
  AvgCommunicate_67001_Content_2 = {
    Text = "Haha, c›est si évident que ça ? Je pensais n›avoir laissé aucune trace ?"
  },
  AvgCommunicate_67001_Content_3 = {
    Text = "Au Mizag, il y a en effet peu de personnes qui se soucient de moi et qui pensent autant aux autres."
  },
  AvgCommunicate_67001_Content_4 = {
    Text = "J›ai toujours été reconnaissante pour tout ce que vous avez fait pour moi, merci, Gardien."
  },
  AvgCommunicate_67001_Content_5 = {
    Text = "Vous me faites rougir. En fait, j›ai remarqué que les chaussures de danse que vous portiez lors de votre dernière représentation étaient un peu usées, alors j›ai pensé à vous en préparer une nouvelle paire."
  },
  AvgCommunicate_67001_Content_6 = {
    Text = "Ah, en effet, ces chaussures de danse m›accompagnent depuis longtemps. Cependant, pour une danseuse, plus neuf ne signifie pas toujours mieux."
  },
  AvgCommunicate_67001_Content_7 = {
    Text = "Oh ? Pourquoi donc ?"
  },
  AvgCommunicate_67001_Content_8 = {
    Text = "Une paire de chaussures de danse doit passer par d›innombrables ajustements pour s›adapter progressivement aux pieds. L›usure des chaussures reflète souvent les mouvements habituels de la danseuse."
  },
  AvgCommunicate_67001_Content_9 = {
    Text = "Je vois, il semble que mes bonnes intentions aient mené au mauvais résultat."
  },
  AvgCommunicate_67001_Option_2 = {
    Text = "Haha, c›est si évident que ça ? Je pensais n›avoir laissé aucune trace ?"
  },
  AvgCommunicate_67001_Option_5 = {
    Text = "Vous me mettez mal à l›aise..."
  },
  AvgCommunicate_67001_Option_7 = {
    Text = "Oh ? Pourquoi donc ?"
  },
  AvgCommunicate_67001_Option_9 = {
    Text = "Je vois, il semble que mes bonnes intentions aient mené au mauvais résultat."
  },
  AvgCommunicate_67002_Content_1 = {
    Text = "Gardien, est-ce vous qui avez envoyé cette invitation à la représentation ?"
  },
  AvgCommunicate_67002_Content_10 = {
    Text = "Tu m'as convaincu, Gardien."
  },
  AvgCommunicate_67002_Content_11 = {
    Text = "Je vais bien me préparer. Merci."
  },
  AvgCommunicate_67002_Content_2 = {
    Text = "Vous savez, je ne danse plus en public..."
  },
  AvgCommunicate_67002_Content_3 = {
    Text = "Je sais, c›est pourquoi cette représentation ne nécessite pas de danser devant un public."
  },
  AvgCommunicate_67002_Content_4 = {
    Text = "Pas nécessaire... devant les autres ?"
  },
  AvgCommunicate_67002_Content_5 = {
    Text = "Exactement, nous avons construit un écran pour vous et l›avons conçu avec des effets de lumière derrière."
  },
  AvgCommunicate_67002_Content_6 = {
    Text = "Pendant que vous dansez derrière l›écran, les gens ne voient qu›une ombre en mouvement, pas votre apparence."
  },
  AvgCommunicate_67002_Content_7 = {
    Text = "Votre performance incarne la danse elle-même, pas simplement vous."
  },
  AvgCommunicate_67002_Content_8 = {
    Text = "La danse elle-même..."
  },
  AvgCommunicate_67002_Content_9 = {
