  AvgCommunicate_67003_Content_1 = {
    Text = "Gardien, il y a une tâche personnelle que j'ai pour vous."
  },
  AvgCommunicate_67003_Content_10 = {
    Text = "Compris, mais je ne sais pas réparer les machines. Les pièces de la poupée doivent être complexes."
  },
  AvgCommunicate_67003_Content_11 = {
    Text = "Les corps qui s'y trouvent sont inutilisés et ne nécessitent pas d'entretien complexe."
