  },
  AvgCommunicate_67003_Content_5 = {
    Text = "Parfait, plusieurs de mes expériences ont atteint des stades critiques. Je suis coincée dans le laboratoire depuis longtemps et je n'ai pas pu en sortir."
  },
  AvgCommunicate_67003_Content_6 = {
