  },
  AvgCommunicate_67003_Content_8 = {
    Text = "L'entrepôt de Doll ?"
  },
  AvgCommunicate_67003_Content_9 = {
    Text = "Oui, c'est ma réserve secrète. Seulement ceux en qui j'ai pleinement confiance peuvent s'y rendre."
  },
  AvgCommunicate_67003_Option_10 = {
