  },
  AvgCommunicate_67003_Option_8 = {
    Text = "L'entrepôt de Doll ?"
  },
  AvgCommunicate_67004_Content_1 = {
    Text = "J'ai remarqué que tes notes pour les récents travaux ont été faibles et que certaines soumissions sont en retard."
  },
  AvgCommunicate_67004_Content_10 = {
    Text = "Les Assignments ne sont qu'un moyen de vous aider à maîtriser les connaissances des enquêteurs, et ne déterminent pas la capacité ou la valeur de quiconque."
  },
  AvgCommunicate_67004_Content_11 = {
    Text = "Si surmener le seul Gardien dans Mythag affecte votre État à cause de quelques missions, cela reviendrait à mettre la charrue avant les bœufs."
  },
  AvgCommunicate_67004_Content_12 = {
    Text = "Doll... Je suis tellement touché !"
  },
  AvgCommunicate_67004_Content_13 = {
    Text = "Si vous sentez que vous n'avez absolument pas besoin de faire vos devoirs, vous pouvez continuer à appliquer cette méthode."
  },
  AvgCommunicate_67004_Content_14 = {
    Text = "Y a-t-il vraiment une si bonne chose ?!"
  },
  AvgCommunicate_67004_Content_15 = {
    Text = "Bien sûr, vous n'êtes plus un enfant, et vous pouvez assumer la responsabilité de vos décisions."
  },
  AvgCommunicate_67004_Content_16 = {
    Text = "Je crois que vous ferez le jugement le plus rationnel."
  },
  AvgCommunicate_67004_Content_17 = {
    Text = "Pour l'instant, reposez-vous."
  },
  AvgCommunicate_67004_Content_2 = {
    Text = "Est-ce que quelque chose s'est passé ? Ou fais-tu face à des difficultés dans tes études ?"
