  AvgCommunicate_67005_Content_1 = {
    Text = "Yu a en fait été de bonne humeur ces deux derniers jours."
  },
  AvgCommunicate_67005_Content_10 = {
    Text = "Je n'aime pas sortir la nuit."
  },
  AvgCommunicate_67005_Content_11 = {
