  AvgCommunicate_67006_Content_1 = {
    Text = "Je trouve que, bien que le progrès technologique et le développement commercial restent ternes, de nombreux nouveaux types d'oreillers ont émergé."
  },
  AvgCommunicate_67006_Content_10 = {
    Text = "Ce vendeur a dit à Yu que Yu était un testeur de sommeil né et a insisté pour que Yu teste des oreillers pour eux à long terme."
  },
  AvgCommunicate_67006_Content_11 = {
    Text = "Ils te font travailler ? Si Miryam l'apprend, elle pourrait bien les tuer."
  },
  AvgCommunicate_67006_Content_12 = {
    Text = "Je voulais refuser, mais il a dit que les dormeurs de test pouvaient emporter tous les nouveaux produits chez eux gratuitement pour les essayer."
  },
  AvgCommunicate_67006_Content_13 = {
    Text = "Voyant sa sincérité, j'ai accepté."
  },
  AvgCommunicate_67006_Content_14 = {
    Text = "Je ne m'attendais pas à ce que tu sois soudoyé par un oreiller... Je veux dire, quel roi aimable."
  },
  AvgCommunicate_67006_Content_2 = {
    Text = "L'autre jour, je suis passé devant le grand magasin à Londinium et j'ai vu qu'ils promouvaient une série de nouveaux oreillers."
  },
  AvgCommunicate_67006_Content_3 = {
    Text = "Je n'ai jeté qu'un coup d'œil deux fois, et le vendeur m'a traîné pour essayer un lit d'échantillon. Comme c'est impoli."
  },
  AvgCommunicate_67006_Content_4 = {
    Text = "Uh, ça ressemble vraiment à leur style de vente."
  },
  AvgCommunicate_67006_Content_5 = {
    Text = "Mais le soi-disant oreiller nuage est effectivement extraordinairement doux. Ce n'est pas comme du duvet ou du coton ; je ne peux pas comprendre de quoi il est fait."
  },
  AvgCommunicate_67006_Content_6 = {
    Text = "Probablement des produits industriels ? Des choses qui n'existaient définitivement pas dans l'ancien temps."
  },
  AvgCommunicate_67006_Content_7 = {
    Text = "C'est parce que l'oreiller était trop confortable. J'ai eu sommeil et je me suis effectivement endormi là—comme c'est embarrassant."
  },
  AvgCommunicate_67006_Content_8 = {
    Text = "Est-ce vraiment aussi confortable ?!"
  },
  AvgCommunicate_67006_Content_9 = {
    Text = "À mon réveil, j'ai discuté de certaines questions concernant la forme de l'oreiller avec le vendeur."
  },
  AvgCommunicate_67006_Option_11 = {
    Text = "Ils te font travailler ? Si Miryam l'apprend, elle pourrait bien les tuer."
  },
  AvgCommunicate_67006_Option_14 = {
    Text = "Je ne m'attendais pas à ce que tu sois soudoyé par un oreiller..."
  },
  AvgCommunicate_67006_Option_4 = {
    Text = "Uh, ça ressemble vraiment à leur style de vente."
  },
  AvgCommunicate_67006_Option_6 = {
    Text = "Probablement des produits industriels ? Des choses qui n'existaient définitivement pas dans l'ancien temps."
  },
  AvgCommunicate_67006_Option_8 = {
    Text = "Est-ce vraiment aussi confortable ?!"
  },
  AvgCommunicate_67007_Content_1 = {
    Text = "Maître, aujourd'hui Aigis a parlé des jouets de l'orphelinat à Jenkin et moi."
  },
  AvgCommunicate_67007_Content_10 = {
    Text = "Non, Gardien, n'écoutez pas Jenkin. Ma poupée va très bien, et on n'a pas besoin d'une nouvelle !"
  },
  AvgCommunicate_67007_Content_11 = {
    Text = "D'accord, d'accord, je vais tout acheter !"
  },
  AvgCommunicate_67007_Content_12 = {
    Text = "Maître, le communicateur a été arraché et est tombé à l'instant ; il semble avoir perdu un composant."
  },
  AvgCommunicate_67007_Content_13 = {
    Text = "Est-ce qu'on peut aussi en acheter un nouveau ?"
  },
  AvgCommunicate_67007_Content_14 = {Text = "Huh ???"},
  AvgCommunicate_67007_Content_2 = {
    Text = "Elle a dit qu'il y a un jouet appelé tangram, composé de sept pièces plates qui peuvent former divers motifs puis être réassemblées en un carré."
  },
  AvgCommunicate_67007_Content_3 = {
    Text = "Jenkin a dit qu'on pouvait en fabriquer un avec du papier, mais après une longue discussion, nous n'avons toujours pas réussi à trouver le motif de ce tangram."
  },
  AvgCommunicate_67007_Content_4 = {
    Text = "Maître, avez-vous déjà vu à quoi ressemble un tangram ?"
  },
  AvgCommunicate_67007_Content_5 = {
    Text = "J'en ai déjà vu un, mais maintenant que tu en parles, j'ai oublié à quoi il ressemblait exactement..."
  },
  AvgCommunicate_67007_Content_6 = {
    Text = "Pas de souci. En tant qu'adulte, j'ai un pouvoir spécial avec l'argent. Je vous emmène acheter des jouets tout de suite."
  },
  AvgCommunicate_67007_Content_7 = {
    Text = "Merci, Maître ! Je vais prévenir Jenkin et Aigis !"
