  },
  AvgCommunicate_67016_Content_5 = {
    Text = "Vous savez à quel point j'aime l'eau. Les jours de travail chargés, je me glisse discrètement dans l'étang la nuit, savourant un moment de tranquillité sous l'eau."
  },
  AvgCommunicate_67016_Content_6 = {
    Text = "Mm... Compréhensible. Il n'y a pas de travail sans stress."
  },
  AvgCommunicate_67016_Content_7 = {
    Text = "J'y suis peut-être allée trop souvent, et les toxines en moi se sont propagées dans l'étang et aux poissons qui s'y trouvent."
  },
  AvgCommunicate_67016_Content_8 = {
    Text = "Cet étang ne se trouvait pas dans la zone d'activité des patients, mais deux patients gourmands s'y sont faufilés pour pêcher et griller leurs prises il y a deux jours."
  },
  AvgCommunicate_67016_Content_9 = {
    Text = "Quand le personnel médical les a trouvés, ils avaient déjà de l'écume à la bouche et s'étaient évanouis au sol..."
  },
  AvgCommunicate_67016_Option_10 = {
    Text = "Hum... Bien que ce soit tragique, ce n'est pas votre faute. Ne vous blâmez pas."
  },
  AvgCommunicate_67016_Option_3 = {
    Text = "Huh ? Que s'est-il passé ?"
  },
  AvgCommunicate_67016_Option_6 = {
    Text = "Mm... Compréhensible. Il n'y a pas de travail sans stress."
  },
  AvgCommunicate_67017_Content_1 = {
    Text = "Gardien, un visiteur du Mizag m›a entendue chanter par hasard pendant que je m›entraînais."
  },
  AvgCommunicate_67017_Content_10 = {
    Text = "Tu aimes chanter et te produire sur scène. Pourquoi ne pas laisser plus de gens entendre ta voix ?"
  },
  AvgCommunicate_67017_Content_11 = {
    Text = "L›amour... Je comprends. Merci, Gardien."
  },
  AvgCommunicate_67017_Content_12 = {
    Text = "Je vais essayer de briller une fois de plus sur cette planète."
  },
  AvgCommunicate_67017_Content_2 = {
    Text = "Maintenant, cette personne m›invite à collaborer avec sa compagnie pour sortir quelques disques. Devrais-je accepter ?"
  },
  AvgCommunicate_67017_Content_3 = {
    Text = "Je pense que c›est possible. Je me souviens que vous étiez autrefois une chanteuse célèbre, n›est-ce pas ?"
  },
  AvgCommunicate_67017_Content_4 = {
    Text = "Oui, mes chansons étaient autrefois à la mode sur l'Étoile Sauvage, mais la plupart du temps, c'était simplement pour échanger avec la noblesse."
  },
  AvgCommunicate_67017_Content_5 = {
    Text = "Maintenant que j›ai retrouvé ma sœur, je n›ai plus besoin de rien."
  },
  AvgCommunicate_67017_Content_6 = {
    Text = "Et vous ? Quand vous chantez, ressentez-vous encore du bonheur ?"
  },
  AvgCommunicate_67017_Content_7 = {
    Text = "Du bonheur... Peut-être est-ce du bonheur, après tout, tout ce que je peux faire maintenant, c›est chanter."
  },
  AvgCommunicate_67017_Content_8 = {
    Text = "Non, Tinct. Sans un amour véritable, personne ne s›entraînerait à chanter chaque jour."
  },
  AvgCommunicate_67017_Content_9 = {
    Text = "Il est tout naturel de s›accrocher à ce que l›on aime."
  },
  AvgCommunicate_67017_Option_3 = {
    Text = "Je pense que c›est possible. Je me souviens que vous étiez autrefois une chanteuse célèbre, n›est-ce pas ?"
  },
  AvgCommunicate_67017_Option_6 = {
    Text = "Et vous ? Quand vous chantez, ressentez-vous encore du bonheur ?"
  },
  AvgCommunicate_67017_Option_8 = {
    Text = "Sans véritable passion, personne ne persisterait à s›entraîner à chanter chaque jour."
  },
  AvgCommunicate_67018_Content_1 = {
    Text = "Pâle Héraut, je voulais vous informer que je m›apprête à visiter le Mizag."
  },
  AvgCommunicate_67018_Content_2 = {
    Text = "Une visite précédente a semblé apporter une aide modeste, et j›ai été invité à revenir pour discuter avec tout le monde dans le hall."
  },
  AvgCommunicate_67018_Content_3 = {
    Text = "Si vous avez un peu de temps libre, j›espère vous voir sur le campus."
  },
  AvgCommunicate_67018_Content_4 = {
    Text = "J'adorerais !"
  },
  AvgCommunicate_67018_Content_5 = {
    Text = "Parfait, je réserverai du temps rien que pour vous afin d›écouter tout ce que vous souhaitez me dire."
  },
  AvgCommunicate_67018_Content_6 = {
    Text = "On se retrouve en tête-à-tête ?"
  },
  AvgCommunicate_67018_Content_7 = {
    Text = "Oui, après tout, ce n›est pas un office religieux, juste une réunion entre amis, n›est-ce pas ?"
  },
  AvgCommunicate_67018_Content_8 = {
    Text = "Pas de problème, je vous ferai visiter les lieux du Mizag. Peut-être aimeriez-vous essayer la cafétéria du Corps éveillé ?"
  },
  AvgCommunicate_67018_Content_9 = {
    Text = "Tout dépend de votre organisation. J›ai hâte d›y être."
  },
  AvgCommunicate_67018_Option_4 = {
    Text = "J'adorerais !"
  },
  AvgCommunicate_67018_Option_6 = {
    Text = "On se retrouve en tête-à-tête ?"
  },
  AvgCommunicate_67018_Option_8 = {
    Text = "Pas de problème !"
  },
  AvgCommunicate_67019_Content_1 = {
    Text = "Pâle Héraut, une grande messe sera bientôt célébrée dans le quartier du Sanctuaire."
  },
  AvgCommunicate_67019_Content_10 = {
    Text = "Votre cœur sincère me touche, aussi je ne refuserai plus."
  },
  AvgCommunicate_67019_Content_11 = {
    Text = "Venez quand vous aurez du temps libre et aidez-moi avec quelques tâches simples de nettoyage et d'aménagement."
  },
  AvgCommunicate_67019_Content_12 = {
    Text = "Pas de problème, à bientôt alors !"
  },
  AvgCommunicate_67019_Content_13 = {
    Text = "Merci encore une fois, L'Envoyé Pâle. Que le Père Dieu protège votre chemin."
  },
  AvgCommunicate_67019_Content_2 = {
    Text = "Je présiderai la cérémonie et partagerai les enseignements du Père."
  },
  AvgCommunicate_67019_Content_3 = {
    Text = "Des Croyants de Londinium et des environs viendront, et vous êtes le bienvenu pour vous joindre à l'action de grâce si cela vous intéresse."
  },
  AvgCommunicate_67019_Content_4 = {
    Text = "J'adorerais ! Mais vu le nombre de Croyants, la préparation de cette messe a dû être un véritable défi."
  },
  AvgCommunicate_67019_Content_5 = {
    Text = "Vous êtes toujours si attentionné, bienveillant et prévenant."
  },
  AvgCommunicate_67019_Content_6 = {
    Text = "En effet, préparer tout le nécessaire pour que chacun ressente la grâce du Père représente beaucoup de travail."
  },
  AvgCommunicate_67019_Content_7 = {
    Text = "Mais ne vous inquiétez pas, j'ai une grande expérience dans la présidence des messes et je peux gérer ces détails avec aisance."
  },
  AvgCommunicate_67019_Content_8 = {
    Text = "Aussi expérimenté que l'on soit, personne n'a trois têtes et six bras. Si possible, laissez-moi vous aider en amont !"
  },
  AvgCommunicate_67019_Content_9 = {
    Text = "Après tout, pour un événement d'une telle envergure, plus la préparation est minutieuse, mieux c'est."
  },
  AvgCommunicate_67019_Option_12 = {
    Text = "Pas de problème, à bientôt alors !"
  },
  AvgCommunicate_67019_Option_4 = {
    Text = "J'adorerais !"
  },
  AvgCommunicate_67019_Option_8 = {
    Text = "Si possible, laissez-moi vous aider en amont !"
  },
  AvgCommunicate_67020_Content_1 = {
    Text = "Pfff, depuis que Mizag a émis l'ordre de restriction, plus aucune petite douceur ne vient discuter avec moi."
  },
  AvgCommunicate_67020_Content_10 = {
    Text = "Eh bien, je n›ai plus qu›à prier pour que le soleil se couche vite."
  },
  AvgCommunicate_67020_Content_11 = {
    Text = "Ah, j›ai tellement hâte de voir le clair de lune ce soir."
  },
  AvgCommunicate_67020_Content_2 = {
    Text = "C›est quoi cette règle qui interdit les visiteurs sauf si tu es avec moi ?"
  },
  AvgCommunicate_67020_Content_3 = {
    Text = "Toi, allez, avoue. C›est toi qui as fait ça — par jalousie, tu as fait un rapport à l›école ?"
  },
  AvgCommunicate_67020_Content_4 = {
    Text = "C›est toi qui as d›abord piégé les étudiants en leur faisant boire des trucs bizarres..."
  },
  AvgCommunicate_67020_Content_5 = {
    Text = "C›était une bénédiction d›amour. Tu penses vraiment que je suis aussi méprisable ?"
  },
  AvgCommunicate_67020_Content_6 = {
    Text = "Je t›ai attendu chaque jour dans la solitude... Je ne m›attendais pas à ce que tu me voies ainsi."
  },
  AvgCommunicate_67020_Content_7 = {
    Text = "Ça suffit ! J›ai compris. Je passerai plus de temps avec toi."
  },
  AvgCommunicate_67020_Content_8 = {
    Text = "Tu es un enfant si attentionné, mais je veux te voir à chaque instant, maintenant, sans attendre ne serait-ce qu›une seconde."
  },
  AvgCommunicate_67020_Content_9 = {
    Text = "Ce soir, j›irai. D›accord !"
  },
  AvgCommunicate_67020_Option_4 = {
    Text = "C›est toi qui as d›abord piégé les étudiants en leur faisant boire des trucs bizarres..."
