  AvgCommunicate_67020_Option_9 = {
    Text = "Ce soir, j›irai. D›accord !"
  },
  AvgCommunicate_67021_Content_1 = {
    Text = "Gardien, désolé de te déranger. As-tu du temps libre récemment ?"
  },
  AvgCommunicate_67021_Content_10 = {
    Text = "Alors, est-ce que tu pourrais venir avec moi, s›il te plaît ?"
  },
  AvgCommunicate_67021_Content_11 = {
    Text = "Mm, ça te va ?"
  },
  AvgCommunicate_67021_Content_12 = {
    Text = "Bien sûr, pas de problème. Ça a l'air amusant !"
  },
  AvgCommunicate_67021_Content_13 = {
    Text = "Merci, Gardien ! Je me sens bien plus en sécurité avec vous à mes côtés."
  },
  AvgCommunicate_67021_Content_14 = {
    Text = "J'ai entendu dire que les poèmes créés sur le moment pouvaient remporter des prix. Si j'ai la chance d'en obtenir un, je vous l'offrirai en guise de remerciement."
  },
  AvgCommunicate_67021_Content_2 = {
    Text = "Qu›est-ce qu›il y a ? C›est rare que tu viennes me chercher."
  },
  AvgCommunicate_67021_Content_3 = {
    Text = "Oui, il y aura bientôt un marché de poésie à Londinium. Beaucoup de livres neufs et anciens seront vendus au marché, et de nombreux poètes se rassembleront pour échanger des idées."
  },
  AvgCommunicate_67021_Content_4 = {
    Text = "Les organisateurs m›ont aussi invitée à tenir un stand pour partager mes poèmes."
  },
  AvgCommunicate_67021_Content_5 = {
    Text = "Ils ont chaleureusement insisté, et j›ai accepté sans réfléchir, mais..."
  },
  AvgCommunicate_67021_Content_6 = {
    Text = "Mais tenir un stand toute seule me rend trop nerveuse."
  },
  AvgCommunicate_67021_Content_7 = {
    Text = "Mm... Tu comprends toujours ma situation."
  },
  AvgCommunicate_67021_Content_8 = {
    Text = "Mais je ne veux pas rompre ma promesse, et cet événement a l›air intéressant ! Il paraît qu›il y aurait un relais créatif en direct."
  },
  AvgCommunicate_67021_Content_9 = {Text = "Alors..."},
