  AvgCommunicate_67022_Content_12 = {
    Text = "Attends, ne me dis pas que je suis la personne de confiance dont tu parles."
  },
  AvgCommunicate_67022_Content_13 = {
    Text = "Bien sûr, tu es le Gardien le plus doux, le plus fiable et le plus puissant de Misargh ! Ce rôle te revient sans aucun doute !"
  },
  AvgCommunicate_67022_Content_14 = {
    Text = "Je prévois de déplacer la boule de sommeil ce soir. Si tu veux, je peux aussi discuter avec toi avant de dormir～"
