  AvgCommunicate_67022_Content_2 = {
    Text = "Félicitations ! Quelle est la solution ?"
  },
  AvgCommunicate_67022_Content_3 = {
    Text = "J'ai conçu un orbe de sommeil qui reste illuminé la nuit, donc pas besoin de lumières fortes et pas de coins sombres."
  },
  AvgCommunicate_67022_Content_4 = {
    Text = "Ça a l'air génial. Maintenant tu n'as enfin plus besoin de te faufiler dans les dortoirs des autres et de te faire expulser tous les jours."
  },
  AvgCommunicate_67022_Content_5 = {
    Text = "Non ! Pour prévenir tout dysfonctionnement du pod de sommeil et éviter les dangers extérieurs, je dois le placer dans un endroit peuplé."
  },
