  AvgCommunicate_67023_Content_1 = {
    Text = "Gardien, j'ai des taches étranges devant les yeux ces derniers temps, et j'ai souvent des vertiges, des palpitations, une oppression thoracique et des acouphènes... Est-ce que je suis en train de mourir ?!"
  },
  AvgCommunicate_67023_Content_10 = {
    Text = "Non, vous ne comprenez pas. L'obscurité est partout ; elle me trouvera où que je sois ! Je ne peux pas dormir, je ne peux pas fermer les yeux..."
  },
  AvgCommunicate_67023_Content_11 = {
    Text = "Euh... et si vous engagiez quelqu'un pour vous assommer ? Comme ça, vous n'aurez pas peur quand vous serez inconscient(e)."
  },
  AvgCommunicate_67023_Content_12 = {
    Text = "Oh ? Ça semble logique, en fait."
  },
  AvgCommunicate_67023_Content_13 = {
    Text = "Puisque la destruction est inévitable, laissez-moi mourir paisiblement dans une bienheureuse ignorance..."
  },
  AvgCommunicate_67023_Content_14 = {
    Text = "Seulement assommé(e), on est encore loin de la mort !"
  },
  AvgCommunicate_67023_Content_15 = {
    Text = "Merci, Gardien. Alors je vous confie cette affaire, à vous, la personne en qui j'ai le plus confiance."
  },
  AvgCommunicate_67023_Content_16 = {
    Text = "...Je n'aurais jamais dû en parler !!"
  },
  AvgCommunicate_67023_Content_2 = {
    Text = "Euh, à en juger par votre rythme de vie, vous vous êtes couché(e) trop tard. Il est recommandé d'aller au lit plus tôt."
  },
  AvgCommunicate_67023_Content_3 = {
    Text = "Quoi ? Ce corps a aussi atteint ses limites..."
  },
  AvgCommunicate_67023_Content_4 = {
    Text = "Mais affronter cette terrifiante obscurité serait tout aussi mortel pour moi !"
  },
  AvgCommunicate_67023_Content_5 = {
    Text = "Ah, zut, souffrance à long terme ou à court terme, survie ou destruction... Que devrais-je choisir..."
  },
  AvgCommunicate_67023_Content_6 = {
    Text = "C'est vraiment si exagéré que ça ? On en est au niveau de la philosophie !"
  },
  AvgCommunicate_67023_Content_7 = {
    Text = "Mais rien de grave ne s'est jamais produit à cause du sommeil, n'est-ce pas ? Cette terreur n'est que le fruit de votre imagination. Vous devriez peut-être essayer la désensibilisation."
