  AvgCommunicate_67024_Content_11 = {
    Text = "Oh, ce sont les compétences exclusives de Maître Casiah. Bien sûr, vous ne pouvez pas les apprendre."
  },
  AvgCommunicate_67024_Content_12 = {
    Text = "Mais l'enseignant Casiah peut t'apprendre à rendre tes mains agiles. De cette façon, lorsque tu rencontreras des cordes qui ne peuvent pas être dénouées ou des serrures qui ne peuvent pas être ouvertes, tu maîtriseras également les techniques de crochetage et de vol !"
