    Text = "En effet, pour favoriser le travail d'équipe parmi les étudiants, j'ai choisi de jeunes chiots."
  },
  AvgCommunicate_67025_Content_5 = {
    Text = "Bien que j'adore ces petites créatures autant que tout le monde, elles nécessitent beaucoup plus de soins et d'entraînement que les chiens adultes."
  },
  AvgCommunicate_67025_Content_6 = {
    Text = "Maintenant que le nombre d'inscrits a augmenté, le nombre de chiots doit également augmenter, et il devient vraiment difficile pour moi de gérer cela."
  },
  AvgCommunicate_67025_Content_7 = {
    Text = "C'est simple. Si l'instructeur Alva donne l'ordre, plus de gens seront prêts à s'inscrire pour s'occuper des chiots. À ce moment-là, il se pourrait même qu'il n'y ait pas assez de chiots à distribuer."
  },
  AvgCommunicate_67025_Content_8 = {
    Text = "Suggères-tu que nous recrutons des bénévoles ? C'est une bonne idée."
