  AvgCommunicate_67027_Content_1 = {
    Text = "Gardien, pourquoi personne de Mythag ne vient plus me faire de vœux ?"
  },
  AvgCommunicate_67027_Content_10 = {
    Text = "Plutôt que de faire un vœu, il semble que tout le monde espère plutôt de la chance et des bénédictions."
  },
  AvgCommunicate_67027_Content_11 = {
    Text = "Même si les souhaits ne peuvent pas se réaliser immédiatement, les garder dans nos cœurs apporte réconfort et anticipation."
  },
  AvgCommunicate_67027_Content_12 = {
    Text = "Des vœux non exaucés... sont-ils vraiment si précieux ?"
  },
  AvgCommunicate_67027_Content_13 = {
    Text = "Je pense comprendre. À partir de demain, je vais donner à tout le monde mes bénédictions à la fontaine de l'école."
  },
  AvgCommunicate_67027_Content_14 = {
    Text = "Attendez, pourquoi la fontaine de l'école ?"
  },
  AvgCommunicate_67027_Content_15 = {
    Text = "J'ai entendu dire que les puits à souhaits sont populaires dans beaucoup d'endroits, alors j'ai transformé la fontaine de l'école en un puits à souhaits. Maintenant, tout le monde peut venir faire des vœux pour recevoir des bénédictions."
  },
  AvgCommunicate_67027_Content_16 = {
    Text = "Il semble logique, mais cela reste étrange !"
  },
  AvgCommunicate_67027_Content_2 = {
    Text = "Mm... Peut-être parce que tout le monde à Mythag est pragmatique."
  },
  AvgCommunicate_67027_Content_3 = {
    Text = "Face à d'innombrables dangers chaque jour, mon esprit est devenu suffisamment stable pour ne pas compter sur le vœu de solutions."
  },
  AvgCommunicate_67027_Content_4 = {
    Text = "...On dirait que je suis toujours inutile."
  },
  AvgCommunicate_67027_Content_5 = {
    Text = "Non, non ! En fait, tout le monde ne croit pas complètement à ces choses."
  },
  AvgCommunicate_67027_Content_6 = {
