  AvgCommunicate_67028_Content_1 = {
    Text = "Bonjour, {Male=Mr.,Female=Miss} Gardien. Désolé(e) de vous déranger à nouveau après tout ce temps."
  },
  AvgCommunicate_67028_Content_10 = {
    Text = "C'est super. Je choisirai un moment pratique pour te rendre visite."
  },
  AvgCommunicate_67028_Content_11 = {
    Text = "Gardons cela secret pour Lily pour l'instant. Je veux la surprendre."
  },
  AvgCommunicate_67028_Content_2 = {
    Text = "Récemment, j'ai obtenu deux magnifiques poisons rouges."
  },
  AvgCommunicate_67028_Content_3 = {
    Text = "Heureusement, sous mes soins, ils ont réussi à pondre de nombreux œufs, et maintenant ils ont éclot en d'innombrables petits poissons."
  },
  AvgCommunicate_67028_Content_4 = {
    Text = "C'est vraiment bien. Je me souviens que tu aimes le poisson."
  },
  AvgCommunicate_67028_Content_5 = {
    Text = "Oui, j'ai un profond attachement au monde sous-marin."
  },
  AvgCommunicate_67028_Content_6 = {
    Text = "Les poissons, les herbes marines et les coraux dans l'eau sont un endroit chaud, comme à la maison, dans ma Mémoire."
  },
  AvgCommunicate_67028_Content_7 = {
    Text = "Désolé, je me suis laissé distraire. Je voulais demander si tu es intéressé à garder des poissons rouges ?"
  },
  AvgCommunicate_67028_Content_8 = {
    Text = "La façon dont ils agitent leurs nageoires en queue dans l'eau est tellement mignonne. Si Lily les voyait, elle les aimerait probablement."
  },
  AvgCommunicate_67028_Content_9 = {
    Text = "Bien sûr ! Nous pouvons les mettre dans ma chambre et celle de Lily."
  },
  AvgCommunicate_67028_Option_4 = {
