  },
  AvgCommunicate_67029_Content_10 = {
    Text = "Alors Casiah eut une grande idée : commencer les recherches à partir des animaux ! Cela rend les choses beaucoup plus faciles !"
  },
  AvgCommunicate_67029_Content_11 = {
    Text = "...Alors, où sont ces poules maintenant ?"
  },
  AvgCommunicate_67029_Content_12 = {
    Text = "La chambre de Casiah est maintenant animée de nombreux poussins nouvellement éclot ! Chaque jour est vivant !"
  },
  AvgCommunicate_67029_Content_13 = {
    Text = "Rendez correctement la cafétéria !!"
  },
  AvgCommunicate_67029_Content_14 = {
    Text = "Oh, séparer cruellement ces mères et ces enfants, quelle dureté ! Vous qui manquez d'amour maternel !"
  },
  AvgCommunicate_67029_Content_15 = {
    Text = "Pourquoi est-ce que je ressens une affection maternelle pour les poules !"
  },
  AvgCommunicate_67029_Content_16 = {
    Text = "Et je ne veux vraiment pas être traité de cœur froid par vous !"
  },
  AvgCommunicate_67029_Content_2 = {
    Text = "Exactement, Casiah, quelqu'un a rapporté qu'après ton spectacle de magie improvisé à la cafétéria de l'école hier, trois poules et vingt œufs ont disparu du stockage."
  },
  AvgCommunicate_67029_Content_3 = {
    Text = "Quoi ? Il y a quelque chose comme ça ? Casiah n'en savait rien."
  },
  AvgCommunicate_67029_Content_4 = {
