  },
  AvgCommunicate_67029_Content_5 = {
    Text = "Oh, il semble que oui. Ces poules ont peut-être fui d'elles-mêmes."
  },
  AvgCommunicate_67029_Content_6 = {
    Text = "Peut-être qu'ils ont perdu leur chemin dans le monde infini des chapeaux. Comme c'est pitoyable !"
  },
  AvgCommunicate_67029_Content_7 = {
    Text = "Si vous ne commencez pas à envisager de dire la vérité, je contacterai Dame Jonquille pour gérer ses employés."
