  AvgCommunicate_67032_Content_3 = {
    Text = "...Je ne tomberai plus dans tes pièges."
  },
  AvgCommunicate_67032_Content_4 = {
    Text = "N'est-il pas naturel de se soucier de son mentor ? Comment cela peut-il être considéré comme une arnaque ?"
  },
  AvgCommunicate_67032_Content_5 = {
