  AvgCommunicate_67033_Content_1 = {
    Text = "Watson, la vie est vraiment ennuyeuse."
  },
  AvgCommunicate_67033_Content_10 = {
    Text = "Ne me dis pas que tu as réellement perdu contre lui ?"
  },
  AvgCommunicate_67033_Content_11 = {
    Text = "Non, aucun de nous deux ne voulait céder. Les mises n›ont cessé d›augmenter, et on a failli perdre la tête."
  },
  AvgCommunicate_67033_Content_12 = {
    Text = "À la fin, ce vieil homme s›est tellement emporté qu›il a révélé sa faille, et j›ai découvert qu›il trichait depuis le début."
  },
  AvgCommunicate_67033_Content_13 = {
    Text = "Donc tu as fait jeu égal avec un tricheur depuis le début ?"
  },
  AvgCommunicate_67033_Content_14 = {
    Text = "Oui, c›était vraiment décevant. Et pour couronner le tout, le vieil homme est devenu tellement furieux qu›il s›est jeté sur moi et a commencé à se battre."
  },
  AvgCommunicate_67033_Content_15 = {
    Text = "Il me soupçonne en fait d›être un tricheur comme lui ! Quelle insulte."
  },
  AvgCommunicate_67033_Content_16 = {
    Text = "Au final, on a tous les deux été jetés dehors par les gens de la maison de jeu, et j›ai atterri si fort que j›ai encore mal aux fesses. Quelle malchance."
  },
  AvgCommunicate_67033_Content_17 = {
    Text = "Je ne sais pas pourquoi, mais je n›arrive tout simplement pas à éprouver de la compassion..."
  },
  AvgCommunicate_67033_Content_2 = {
    Text = "? Tu as encore joué, n›est-ce pas? Tu as gagné jusqu›au pantalon de tout le monde?"
  },
  AvgCommunicate_67033_Content_3 = {
    Text = "Cette fois, vraiment non! Je m›amusais seulement au Fang de jeu comme d›habitude... hum."
  },
  AvgCommunicate_67033_Content_4 = {
    Text = "C›est bon. Continue."
  },
  AvgCommunicate_67033_Content_5 = {
    Text = "J›écoute tes autres excuses."
  },
  AvgCommunicate_67033_Content_6 = {
    Text = "Soupir... Aujourd›hui, j›ai soudainement rencontré un adversaire de taille égale."
  },
  AvgCommunicate_67033_Content_7 = {
    Text = "Après avoir rejoint cette partie, j›étais presque à égalité avec ce vieil homme quelconque."
  },
  AvgCommunicate_67033_Content_8 = {
    Text = "C›est assez choquant. Pour gagner avec ta chance, il doit être un expert."
  },
  AvgCommunicate_67033_Content_9 = {
    Text = "J›ai pensé la même chose, alors je me suis concentré complètement et j›ai continué à jouer contre lui, en me redressant même le dos!"
  },
  AvgCommunicate_67033_Option_10 = {
    Text = "Ne me dis pas que tu as réellement perdu contre lui ?"
  },
  AvgCommunicate_67033_Option_13 = {
    Text = "Donc tu as fait jeu égal avec un tricheur depuis le début ?"
  },
  AvgCommunicate_67033_Option_17 = {
    Text = "Je ne sais pas pourquoi, mais je n›arrive tout simplement pas à éprouver de la compassion..."
  },
  AvgCommunicate_67033_Option_2 = {
    Text = "? Tu as encore joué, n›est-ce pas? Tu as gagné jusqu›au pantalon de tout le monde?"
  },
  AvgCommunicate_67033_Option_4 = {
    Text = "C›est bon. Continue."
  },
  AvgCommunicate_67033_Option_5 = {
    Text = "J›écoute tes autres excuses."
  },
  AvgCommunicate_67033_Option_8 = {
    Text = "C›est assez choquant."
  },
  AvgCommunicate_67034_Content_1 = {
    Text = "Bonjour, Gardien du Secret."
  },
  AvgCommunicate_67034_Content_10 = {
    Text = "Ah oui ? Alors comment tu expliques cette copie ratée ? Tu as fait des erreurs sur du contenu aussi basique. Je pense que tu vas devoir recopier les bonnes réponses cent fois."
  },
  AvgCommunicate_67034_Content_11 = {
    Text = "Cent fois ?! Pas question... Attends, j'avais presque oublié que tu es Erica !"
  },
  AvgCommunicate_67034_Content_12 = {
    Text = "Pourquoi maudire de manière aussi réaliste ? C'était fait exprès ? Je laisse un avis négatif !"
  },
  AvgCommunicate_67034_Content_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Content_14 = {
    Text = "Très bien, simulation de personnalité basculée sur : Ramona."
  },
  AvgCommunicate_67034_Content_15 = {
    Text = "Partenaire, un professeur vient de me dire que tu aurais oublié de rendre un devoir ?"
  },
  AvgCommunicate_67034_Content_16 = {
    Text = "Hein ? Vraiment ? Je me souviens clairement avoir fini tous mes devoirs..."
  },
  AvgCommunicate_67034_Content_17 = {
    Text = "Quand est-ce que tu changeras cette habitude de paresser ?"
  },
  AvgCommunicate_67034_Content_18 = {
    Text = "Tant pis. Viens seulement dans ma chambre tous les jours. Je te superviserai pour que tu finisses tes devoirs avant de partir. Au fait, pas le droit de chercher les réponses ou les références."
  },
  AvgCommunicate_67034_Content_19 = {
    Text = "Quoi ?! Non ! Comment je suis censé faire mes devoirs sans références ?!"
  },
  AvgCommunicate_67034_Content_2 = {
    Text = "Vous êtes invité à essayer notre tout dernier système de simulation de personnalité. Il peut imiter les membres absents pour communiquer et déduire leur logique d'action pendant les missions."
  },
  AvgCommunicate_67034_Content_20 = {
    Text = "Attends... J›ai failli oublier que tu es Erica ! Tu essaies de me faire peur ?! Je mets un avis négatif !!"
  },
  AvgCommunicate_67034_Content_21 = {
    Text = "D›accord, j›ai bien reçu votre retour. Évaluation initiale : simulation qualifiée."
  },
  AvgCommunicate_67034_Content_22 = {
    Text = "Au plaisir de vous revoir lors du prochain test système."
  },
  AvgCommunicate_67034_Content_3 = {
    Text = "Veuillez partager vos retours et suggestions une fois l'essai terminé."
  },
  AvgCommunicate_67034_Content_4 = {
    Text = "C'est quoi ce truc bizarre ?"
  },
  AvgCommunicate_67034_Content_5 = {
    Text = "Vous pouvez choisir l'un des deux personnages initiaux pour la simulation de personnalité : Doll, Ramona."
  },
  AvgCommunicate_67034_Content_6 = {Text = "Doll."},
  AvgCommunicate_67034_Content_7 = {
    Text = "Très bien, simulation de personnalité basculée sur : Doll."
  },
  AvgCommunicate_67034_Content_8 = {
    Text = "Gardien, les résultats de ton dernier examen sont sortis. J'espère que tu es conscient de ce que tu as fait ces derniers temps."
  },
  AvgCommunicate_67034_Content_9 = {
    Text = "Hein ? J'ai rendu mes devoirs à temps récemment. J'ai juste somnolé quelques fois en cours..."
  },
  AvgCommunicate_67034_Option_11 = {
    Text = "Cent fois ?! Pas question..."
  },
  AvgCommunicate_67034_Option_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Option_16 = {
