  AvgCommunicate_67035_Content_1 = {
    Text = "Cher Gardien ! Aidez-moi s'il vous plaît !"
  },
  AvgCommunicate_67035_Content_10 = {
    Text = "Quel genre de travail c›est ?!"
  },
  AvgCommunicate_67035_Content_11 = {
    Text = "Peu importe... Récemment, le cours d›entraînement d›Alva apprend aux chiots à poursuivre les ennemis."
  },
  AvgCommunicate_67035_Content_12 = {
    Text = "Si ça ne te dérange pas de te faire mordre par un chien, va jouer le méchant là-bas."
  },
  AvgCommunicate_67035_Content_13 = {
    Text = "Quoi ? Vous dites qu›un adorable chiot peut me malmener ?"
  },
  AvgCommunicate_67035_Content_14 = {
    Text = "Je suis partante ! Vous êtes si gentil, Gardien !"
  },
  AvgCommunicate_67035_Content_2 = {
    Text = "Pas de réprimande, pas de combat, et pas de rester dans la chambre."
  },
  AvgCommunicate_67035_Content_3 = {
    Text = "Oh, cette fois je n›étais vraiment pas devant l›entrée de votre chambre."
  },
  AvgCommunicate_67035_Content_4 = {
    Text = "Grâce à votre aide la dernière fois, j'ai passé beaucoup de temps à frapper joyeusement le sac de sable dans la salle d'entraînement. C'était comme être chez moi—je n'ai jamais été aussi heureux auparavant."
  },
  AvgCommunicate_67035_Content_5 = {
    Text = "Mm... Pas de problème, tant que tu es content."
  },
  AvgCommunicate_67035_Content_6 = {
    Text = "Hélas, mais récemment, j›ai été découvert. Je ne sais pas comment Uvhash a reconnu que c›était moi à l›intérieur."
  },
  AvgCommunicate_67035_Content_7 = {
    Text = "Après que tout le monde a découvert que j›étais dans le sac de frappe, ils m›ont tous grondé."
  },
  AvgCommunicate_67035_Content_8 = {
    Text = "Même si cette partie est amusante, je ne peux plus faire semblant d›être un sac de frappe."
  },
  AvgCommunicate_67035_Content_9 = {
    Text = "Que dois-je faire ? Être au chômage, c›est terrible, Gardien ! Trouvez-moi un autre travail comme celui-ci, s›il vous plaît !"
  },
  AvgCommunicate_67035_Option_10 = {
    Text = "Quel genre de travail c›est ?!"
  },
  AvgCommunicate_67035_Option_2 = {
    Text = "Pas de réprimande, pas de combat, et pas de rester dans la chambre."
  },
  AvgCommunicate_67035_Option_5 = {
    Text = "Mm... Pas de problème, tant que tu es content."
  },
  AvgCommunicate_67036_Content_1 = {
    Text = "Gardien ! Ma dernière modification a réussi !"
  },
  AvgCommunicate_67036_Content_10 = {
    Text = "Comme ça, je n›aurai plus à m›inquiéter d›oublier de consulter mon journal et de perdre mes souvenirs à nouveau."
  },
  AvgCommunicate_67036_Content_11 = {
    Text = "Excellente idée ! Mais avant, ça ne vous dérangeait pas d›être oublieux, non ?"
  },
  AvgCommunicate_67036_Content_12 = {
    Text = "C›est facile à dire, mais je ne veux pas oublier mes amis."
  },
  AvgCommunicate_67036_Content_13 = {
    Text = "Je me souviendrai bien de vous, Gardien !"
  },
  AvgCommunicate_67036_Content_2 = {
    Text = "Félicitations ! Vous parlez de votre Nautilus ? Mais vous vous souvenez encore de moi."
  },
  AvgCommunicate_67036_Content_3 = {
    Text = "Non, il s›agit de cette boîte de dialogue."
  },
  AvgCommunicate_67036_Content_4 = {
    Text = "? Ça s›appelle un communicateur. Quelles modifications avez-vous apportées ??"
  },
  AvgCommunicate_67036_Content_5 = {
    Text = "Je peux programmer des messages à envoyer plus tard, avec un délai que je contrôle moi-même."
  },
  AvgCommunicate_67036_Content_6 = {
    Text = "Par exemple, la première phrase que je viens de vous envoyer a été écrite il y a cinq minutes, en guise de test."
  },
  AvgCommunicate_67036_Content_7 = {
    Text = "Waouh, incroyable ?! On dirait que ça pourrait servir à planifier à l›avance pendant les missions, facilitant l›exécution de plans de secours."
  },
  AvgCommunicate_67036_Content_8 = {
    Text = "Ah, je n›y ai pas autant réfléchi que vous le pensez."
  },
  AvgCommunicate_67036_Content_9 = {
    Text = "Je me disais juste que si j›envoie à l›avance ce dont je me souviens aujourd›hui vers demain, je n›oublierai pas."
  },
  AvgCommunicate_67036_Option_11 = {
