  },
  AvgCommunicate_67037_Content_15 = {Text = "Parfum."},
  AvgCommunicate_67037_Content_16 = {
    Text = "Mm, ça me semble bien. Laissez-moi essayer de les assembler en vers."
  },
  AvgCommunicate_67037_Content_17 = {
    Text = "L›amour du rossignol pour la Lune éclot dans son chant mélodieux chaque nuit, mais la Lune reste froide."
  },
  AvgCommunicate_67037_Content_18 = {
