  AvgCommunicate_67038_Content_1 = {
    Text = "Gardien, la statue de Tulu que tu m'as demandé de faire pour Miryam a été livrée dans ta chambre."
  },
  AvgCommunicate_67038_Content_10 = {
    Text = "Sa compréhension de Tulu est même moindre que ma compréhension de vous ; comme c'est incompétent."
  },
  AvgCommunicate_67038_Content_11 = {
    Text = "Assez, ne dis pas ça. Ne la laisse pas voir ça."
  },
  AvgCommunicate_67038_Content_12 = {
    Text = "De toute façon, merci pour ton travail acharné. Laisse-moi réfléchir à comment dire à Miryam..."
  },
  AvgCommunicate_67038_Content_2 = {
    Text = "Je l'ai vu, mais cette image... n'est-elle pas un peu trop mignonne ?"
  },
  AvgCommunicate_67038_Content_3 = {
    Text = "Est-ce à cela que Tulu ressemble ? Est-ce que Miryam va m'étrangler"
  },
  AvgCommunicate_67038_Content_4 = {
    Text = "Quoi ? Es-tu aussi un fervent adepte du jeune roi ?"
  },
  AvgCommunicate_67038_Content_5 = {
    Text = "À mes yeux, il n'était qu'un enfant, contraint de porter une couronne et des chaînes par d'autres."
  },
  AvgCommunicate_67038_Content_6 = {
    Text = "Ne trouves-tu pas son air somnolent et paresseux chaque jour adorable ? Cela me rappelle le chat à poils longs que j'avais quand j'étais enfant."
  },
  AvgCommunicate_67038_Content_7 = {
    Text = "C'est vrai, ceux qui désirent la statue seront satisfaits..."
  },
  AvgCommunicate_67038_Content_8 = {
    Text = "La seule mauvaise nouvelle pourrait être la naissance d'un monde où seule Miryam se blesse..."
  },
  AvgCommunicate_67038_Content_9 = {
    Text = "Cela signifie juste qu'elle est une prêtresse aveugle qui ne comprend pas son propre Dieu."
  },
  AvgCommunicate_67038_Option_11 = {
    Text = "Assez, ne dis pas ça. Ne la laisse pas voir ça."
  },
  AvgCommunicate_67038_Option_2 = {
    Text = "Je l'ai vu, mais cette image... n'est-elle pas un peu trop mignonne ?"
  },
  AvgCommunicate_67038_Option_7 = {
    Text = "C'est vrai, ceux qui désirent la statue seront satisfaits..."
  },
  AvgCommunicate_67039_Content_1 = {
    Text = "Cher Gardien, avez-vous reçu ma dernière œuvre ?"
  },
  AvgCommunicate_67039_Content_10 = {
    Text = "Vos éloges soudains me mettent tellement mal à l›aise..."
  },
  AvgCommunicate_67039_Content_11 = {
    Text = "Ne sois pas timide. Tu as toujours été ma muse. Quand tu auras le temps, pourrais-tu passer à mon atelier ?"
  },
  AvgCommunicate_67039_Content_12 = {
    Text = "J'ai encore tant d'œuvres que je veux achever, et j'ai besoin de dépeindre ton âme avec soin."
  },
  AvgCommunicate_67039_Content_13 = {
    Text = "Je t'attendrai ici, en quête de plus d'inspiration."
  },
  AvgCommunicate_67039_Content_2 = {
    Text = "C›est... moi pendant mon sommeil ?"
  },
  AvgCommunicate_67039_Content_3 = {
    Text = "Dans mon inspiration, c›est vous sombrant dans un beau rêve."
  },
  AvgCommunicate_67039_Content_4 = {
    Text = "Choisir entre un bonheur aveugle et factice, ou une chute lucide et douloureuse."
  },
  AvgCommunicate_67039_Content_5 = {
    Text = "Les dilemmes sont toujours les thèmes de l›art et de la philosophie."
  },
  AvgCommunicate_67039_Content_6 = {
    Text = "Ne puis-je pas atteindre un bonheur lucide et authentique ?"
  },
  AvgCommunicate_67039_Content_7 = {
    Text = "Hé, quel être avide."
  },
  AvgCommunicate_67039_Content_8 = {
    Text = "Rien n›est parfait, pas même les sculptures peut-être."
  },
  AvgCommunicate_67039_Content_9 = {
    Text = "Mais vous pouvez toujours emprunter le chemin en quête d›un tel bonheur. C›est là que réside votre charme."
  },
  AvgCommunicate_67039_Option_10 = {
    Text = "Vos éloges soudains me mettent tellement mal à l›aise..."
