  },
  AvgCommunicate_67040_Content_1 = {
    Text = "Hé, mon chou, comment as-tu trouvé notre dernier moment de douceur ? Tu le revis chaque jour ?"
  },
  AvgCommunicate_67040_Content_10 = {
    Text = "Parle, qu'est-ce que tu comptes faire maintenant..."
  },
  AvgCommunicate_67040_Content_11 = {
    Text = "Ne sois pas si tendu, notre lien est déjà devenu si fort～"
  },
  AvgCommunicate_67040_Content_12 = {
    Text = "Fais-moi confiance, suis-moi, et je te guiderai vers un nouveau genre de bonheur."
  },
  AvgCommunicate_67040_Content_13 = {
    Text = "Cette fois, aimerais-tu expérimenter personnellement l'usage des bougies et des fouets ?"
  },
  AvgCommunicate_67040_Content_14 = {
    Text = "Je t'apprendrai tout étape par étape, mon cher."
