  AvgCommunicate_67040_Content_2 = {
    Text = "Quel moment ?"
  },
  AvgCommunicate_67040_Content_3 = {
    Text = "Je ne me souviens pas."
  },
  AvgCommunicate_67040_Content_4 = {
    Text = "Quelle personne sans cœur, alors que j'ai été si doux la dernière fois～"
  },
  AvgCommunicate_67040_Content_5 = {
    Text = "Je te conseille de surveiller tes paroles et tes actes..."
  },
  AvgCommunicate_67040_Content_6 = {
    Text = "Hmph, jouer les innocents ne marchera pas. J'ai déjà enregistré tes contours, tes courbes et toutes tes formes dans la cire !"
  },
  AvgCommunicate_67040_Content_7 = {
    Text = "J'ai vraiment envie de les montrer à tout le monde～"
