  },
  AvgCommunicate_67041_Content_1 = {
    Text = "Mon seigneur, vous venez de me faire signe de vous contacter?"
  },
  AvgCommunicate_67041_Content_10 = {
    Text = "Pfff, il faut que je t'apprenne à identifier les mauvaises filles à l'école et quelques mesures préventives."
  },
  AvgCommunicate_67041_Content_11 = {
    Text = "Écoute-moi, quitte le pas de sa porte immédiatement, va aussi loin que possible, et dis plus tard que c›est moi qui t›ai appelé !"
  },
  AvgCommunicate_67041_Content_12 = {
    Text = "Mais j›ai promis à Dame Pandia. Je ne peux pas manquer à ma parole."
  },
  AvgCommunicate_67041_Content_13 = {
    Text = "Tout va bien, monseigneur. Il y a assez de force en moi pour me protéger !"
  },
  AvgCommunicate_67041_Content_14 = {
    Text = "Toi, je... Tant pis. Si tu dois rester là, souviens-toi de ne pas entrer dans sa chambre."
  },
  AvgCommunicate_67041_Content_15 = {
    Text = "Bien sûr que non ! Jamais je n›entrerais dans la chambre d›une dame !"
  },
  AvgCommunicate_67041_Content_16 = {
    Text = "Quoi qu›elle dise, n›entre pas. Appel-moi s›il se passe quoi que ce soit. Et quoi que tu fasses, ne respire pas ses bougies !"
  },
  AvgCommunicate_67041_Content_17 = {
    Text = "Compris, monseigneur. Mais pourquoi ne puis-je pas sentir la bougie ?"
  },
  AvgCommunicate_67041_Content_18 = {
    Text = "Ne demande pas... Ce sont les larmes et le sang que j›ai épargnés pour toi."
  },
  AvgCommunicate_67041_Content_2 = {
    Text = "Exactement, pourquoi es-tu devant la porte de Pandia??"
  },
  AvgCommunicate_67041_Content_3 = {
    Text = "Ah, c'est une demande de Dame Pandia. Elle a dit qu'elle avait quelque chose d'important à faire et m'a demandé de garder la porte pour elle."
  },
  AvgCommunicate_67041_Content_4 = {
    Text = "Une affaire importante? Ne la crois pas ! Ses histoires... laisse tomber, tu as certainement été dupé par elle !"
  },
  AvgCommunicate_67041_Content_5 = {
    Text = "Hein? Mais son expression à l'instant était si solennelle, et elle m'a tenu la main avec tant de sincérité..."
  },
  AvgCommunicate_67041_Content_6 = {
    Text = "Elle t'a aussi tenu la main en disant que tu es le chevalier le plus fiable et le plus doux, pas vrai?"
  },
  AvgCommunicate_67041_Content_7 = {
    Text = "Comment le savez-vous, mon seigneur?!"
  },
  AvgCommunicate_67041_Content_8 = {
    Text = "Ogier, ne fais pas confiance aux paroles d'une mauvaise femme ! Tu te feras facilement avoir !"
  },
  AvgCommunicate_67041_Content_9 = {
    Text = "Eh bien, je pense simplement que personne n'a de mauvaises intentions..."
  },
  AvgCommunicate_67041_Option_10 = {
    Text = "Je ferais mieux de t'apprendre à identifier les mauvaises femmes à l'école..."
  },
  AvgCommunicate_67041_Option_14 = {
    Text = "Tant pis..."
  },
  AvgCommunicate_67041_Option_16 = {
    Text = "Peu importe ce qu'elle dit, n'entre pas. Appelle-moi si quelque chose se passe."
  },
  AvgCommunicate_67041_Option_18 = {
    Text = "Ne demande pas... Ce sont les larmes et le sang que j›ai épargnés pour toi."
  },
  AvgCommunicate_67041_Option_2 = {
    Text = "Exactement, pourquoi es-tu devant la porte de Pandia??"
  },
  AvgCommunicate_67041_Option_4 = {
    Text = "Quelque chose d'important? Ne la crois pas !"
  },
  AvgCommunicate_67041_Option_6 = {
    Text = "Elle t'a aussi tenu la main en disant que tu es le chevalier le plus fiable et le plus doux, pas vrai?"
  },
  AvgCommunicate_67041_Option_8 = {
    Text = "Ogier, ne fais pas confiance aux paroles d'une mauvaise femme !"
  },
  AvgCommunicate_67042_Content_1 = {
    Text = "Ding dong, vous avez un cadeau du fond du cœur. Veuillez vérifier～"
  },
  AvgCommunicate_67042_Content_10 = {
    Text = "Ça sent bon effectivement, mais pourquoi j›ai un peu le vertige..."
  },
  AvgCommunicate_67042_Content_11 = {
    Text = "Tu es peut-être déjà sous leur charme. Quoi qu›il en soit, je suis en bas comme tu l›as demandé."
  },
  AvgCommunicate_67042_Content_12 = {
    Text = "Tu veux prendre une bougie en forme de cœur et sortir t›amuser avec moi～?"
  },
  AvgCommunicate_67042_Content_13 = {
    Text = "Vous usez de ruse..."
  },
  AvgCommunicate_67042_Content_14 = {
    Text = "Comment cela serait-il possible ? C›est un contrat doux et mutuel."
  },
  AvgCommunicate_67042_Content_2 = {
    Text = "Tu parles de l›étrange boîte devant la porte qui n›indique que le destinataire ?"
  },
  AvgCommunicate_67042_Content_3 = {
    Text = "Alors tu peux venir la récupérer dans la poubelle devant le dortoir maintenant."
  },
  AvgCommunicate_67042_Content_4 = {
    Text = "Ne sois pas si insensible ! Au moins jette un œil, juste un rapide coup d›œil !"
  },
  AvgCommunicate_67042_Content_5 = {
    Text = "Tu ne voudrais pas que l›entrée soit envahie par mes cadeaux tous les jours, n›est-ce pas ?"
  },
  AvgCommunicate_67042_Content_6 = {
    Text = "D›accord, je regarde, et ensuite tu pourras la jeter à la poubelle."
  },
  AvgCommunicate_67042_Content_7 = {
    Text = "Qu'est-ce que c'est... une bougie rose ?"
  },
  AvgCommunicate_67042_Content_8 = {
    Text = "C›est une bougie en forme de cœur spécialement fabriquée ! La température de fusion est parfaite～"
  },
  AvgCommunicate_67042_Content_9 = {
    Text = "Alors ? Sens un peu. Elle n›est pas parfumée ? Ça donne envie de la sentir encore et encore..."
  },
  AvgCommunicate_67042_Option_10 = {
    Text = "Ça sent bon effectivement, mais pourquoi j›ai un peu le vertige..."
  },
  AvgCommunicate_67042_Option_13 = {
    Text = "Vous usez de ruse..."
  },
  AvgCommunicate_67042_Option_2 = {
    Text = "Tu parles de l›étrange boîte devant la porte qui n›indique que le destinataire ?"
  },
  AvgCommunicate_67042_Option_6 = {
    Text = "D›accord, je regarde, et ensuite tu pourras la jeter à la poubelle."
  },
  AvgCommunicate_67043_Content_1 = {
    Text = "Après avoir passé tant de temps à Mizag, j'ai soudain commencé à regretter la lune du désert."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Venez créer de nouveaux souvenirs avec moi : parmi les fleurs, dans la nature sauvage, pour voir l'océan et les vallées, les villes et la campagne."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "Je veux créer de beaux souvenirs avec vous dans chaque bel endroit. Vous m'accompagnerez, n'est-ce pas ?"
  },
  AvgCommunicate_67043_Content_2 = {
    Text = "Alors vous aussi, vous avez le mal du pays ?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "Plutôt que le mal du pays, peut-être que les souvenirs partagés avec les autres me manquent simplement, ainsi que ces émotions intenses."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "Je ne m'attendais pas à ce que vous soyez si nostalgique."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "Quoi ? Vous pensez que je suis insouciante et insensible ? Non, je me souviens de chaque personne, de chaque souvenir chaleureux et doux."
  },
  AvgCommunicate_67043_Content_6 = {
    Text = "Y compris le vôtre."
  },
  AvgCommunicate_67043_Content_7 = {
    Text = "Devrais-je me sentir honoré ou jaloux ?"
  },
  AvgCommunicate_67043_Content_8 = {
    Text = "J'adore vous voir si troublé(e) ; c'est adorable."
  },
  AvgCommunicate_67043_Content_9 = {
    Text = "Bien que les jours passés éveillent la nostalgie, la joie de ce soir est la plus précieuse."
  },
  AvgCommunicate_67043_Option_2 = {
    Text = "Alors vous aussi, vous avez le mal du pays ?"
  },
  AvgCommunicate_67043_Option_4 = {
    Text = "Je ne m'attendais pas à ce que vous soyez si nostalgique."
  },
  AvgCommunicate_67043_Option_7 = {
    Text = "Devrais-je me sentir honoré ou jaloux ?"
  },
  AvgCommunicate_67044_Content_1 = {
    Text = "J'ai conceptualisé quelques décorations récemment pour embellir mes collections."
  },
  AvgCommunicate_67044_Content_10 = {
    Text = "Si possible, veuillez accepter les colliers que j'ai soigneusement choisis pour vous. Ce sont des cadeaux gratuits cette fois."
  },
  AvgCommunicate_67044_Content_11 = {
    Text = "Si l'un d'entre eux vous plaît après l'avoir essayé, n'hésitez pas à me le faire savoir."
  },
  AvgCommunicate_67044_Content_12 = {
    Text = "Même si votre tête ne m'appartient pas encore, le simple fait de vous voir le porter suffit à me ravir."
  },
  AvgCommunicate_67044_Content_2 = {
    Text = "Il y a pas mal de styles au choix, et je suis un peu indécise. Je suis venue te demander conseil."
  },
  AvgCommunicate_67044_Content_3 = {
    Text = "Collection ?"
  },
  AvgCommunicate_67044_Content_4 = {
    Text = "Vous ne voulez pas dire..."
  },
  AvgCommunicate_67044_Content_5 = {
    Text = "Ah, bien sûr, mes précieux crânes."
  },
  AvgCommunicate_67044_Content_6 = {
    Text = "J'ai lu beaucoup de magazines de mode, ainsi que des designs de bijouteries."
  },
  AvgCommunicate_67044_Content_7 = {
    Text = "Les colliers colorés ont chacun leurs propres caractéristiques uniques, incluant même certains designs de colliers de niche, rendant le choix vraiment difficile."
  },
  AvgCommunicate_67044_Content_8 = {
    Text = "Mm... Je pense que votre collection mérite la décoration la plus raffinée."
  },
  AvgCommunicate_67044_Content_9 = {
    Text = "Vraiment? Ça me fait tellement plaisir."
  },
  AvgCommunicate_67044_Option_3 = {
    Text = "Collection ?"
  },
  AvgCommunicate_67044_Option_4 = {
    Text = "Vous ne voulez pas dire..."
  },
  AvgCommunicate_67044_Option_8 = {
    Text = "Mm... Je pense que votre collection mérite la décoration la plus raffinée."
  },
  AvgCommunicate_67045_Content_1 = {
    Text = "Soupir, les affaires de ma petite boutique ont été mauvaises dernièrement ; cela fait longtemps que je n'ai pas trouvé un crâne qui me plaise."
  },
  AvgCommunicate_67045_Content_10 = {
    Text = "Si vous pouvez faire équipe pour traquer de grands fugitifs, peut–être créerez–vous une légende de rangers urbains éradiquant le mal."
  },
  AvgCommunicate_67045_Content_11 = {
    Text = "Bonne suggestion, mais un individu aussi malin ne se laissera pas facilement duper."
  },
  AvgCommunicate_67045_Content_12 = {
    Text = "En parlant de ça, sa tête si particulière ferait un excellent objet de collection, mais il n›y a aucune occasion de conclure un marché — quel dommage."
  },
  AvgCommunicate_67045_Content_13 = {
    Text = "Espoir que Ryker n›éternue pas en ce moment..."
  },
  AvgCommunicate_67045_Content_2 = {
    Text = "Mm... Les crânes sont en effet des trouvailles rares."
  },
  AvgCommunicate_67045_Content_3 = {
    Text = "Alors, j'ai récemment conclu une coopération avec le Comité de révision. Je les aide à traquer des fugitifs, et en retour, ils me fournissent secrètement les têtes des condamnés à mort."
  },
  AvgCommunicate_67045_Content_4 = {
    Text = "Une personne vivante échangée contre le crâne d'un mort ; c'est un marché profitable pour les deux parties."
  },
  AvgCommunicate_67045_Content_5 = {
    Text = "Hein ? Je n›aurais jamais pensé que le Comité de révision approuverait une telle collaboration."
  },
  AvgCommunicate_67045_Content_6 = {
    Text = "Bien sûr, ce n›est pas une collaboration officielle, mais il y a toujours des gens malins partout."
  },
  AvgCommunicate_67045_Content_7 = {
    Text = "J›ai aussi essayé de contacter le commissariat de Londinium, mais ils semblent faire davantage confiance à ce détective à tête de chien."
  },
  AvgCommunicate_67045_Content_8 = {
    Text = "Puisque quelqu›un a déjà saisi l›opportunité, je vais devoir chercher d›autres perspectives."
  },
  AvgCommunicate_67045_Content_9 = {
    Text = "Mm... Même si je pense que Ryker ne se soucie pas vraiment de ce marché."
  },
  AvgCommunicate_67045_Option_13 = {
    Text = "Espoir que Ryker n›éternue pas en ce moment..."
  },
  AvgCommunicate_67045_Option_2 = {
