  AvgCommunicate_67045_Option_9 = {
    Text = "Mm... Même si je pense que Ryker ne se soucie pas vraiment de ce marché."
  },
  AvgCommunicate_67046_Content_1 = {
    Text = "Mon seigneur ! La jument de sang chaud nommée Flocon dans l'écurie est sur le point de donner naissance !"
  },
  AvgCommunicate_67046_Content_10 = {
    Text = "La pensée d'être impliqué dans la croissance de Pony depuis son plus jeune âge m'excite !"
  },
  AvgCommunicate_67046_Content_11 = {
    Text = "Alors il faut commencer à élever des chevaux si jeune?"
  },
  AvgCommunicate_67046_Content_12 = {
    Text = "Un cheval est le plus proche compagnon du chevalier ! Plus la confiance entre eux est grande, mieux c'est."
  },
  AvgCommunicate_67046_Content_13 = {
    Text = "J'ai toujours voulu posséder un cheval que j'ai élevé depuis un poulain !"
  },
  AvgCommunicate_67046_Content_14 = {
    Text = "Je peux voir que tu attends vraiment cela avec impatience."
  },
  AvgCommunicate_67046_Content_15 = {
    Text = "Si j'ai du temps alors, j'irai vous aider."
  },
  AvgCommunicate_67046_Content_16 = {
    Text = "Je suis également curieux de savoir quel genre de motif le poney aura."
  },
  AvgCommunicate_67046_Content_17 = {
    Text = "!! Je serai bien préparé !"
  },
  AvgCommunicate_67046_Content_2 = {
    Text = "Je me souviens que ce cheval était d'un noir pur. Je suis curieux de connaître la couleur de leur progéniture—peut-être noir et blanc ?"
  },
  AvgCommunicate_67046_Content_3 = {
    Text = "Ils pourraient ressembler aux rayures d'un zèbre."
  },
  AvgCommunicate_67046_Content_4 = {
    Text = "Alors, donc il y a cette possibilité ? C'est vraiment incroyable..."
  },
  AvgCommunicate_67046_Content_5 = {
    Text = "Haha, je rigole ! C'est dangereux de croire tout ce que les autres disent."
  },
  AvgCommunicate_67046_Content_6 = {
    Text = "Je-je serai plus prudent la prochaine fois ! Mais si c'est pour toi, mon seigneur, il n'y a pas besoin de méfiance !"
  },
  AvgCommunicate_67046_Content_7 = {
    Text = "Ugh, cette lumière éblouissante..."
  },
  AvgCommunicate_67046_Content_8 = {
    Text = "Quelle est cette sensation de culpabilité..."
  },
  AvgCommunicate_67046_Content_9 = {
    Text = "Hmm ? Au fait, mon seigneur, je prévois d'apprendre des connaissances pertinentes et de livrer personnellement Snow."
  },
  AvgCommunicate_67046_Option_11 = {
    Text = "Alors il faut commencer à élever des chevaux si jeune?"
  },
  AvgCommunicate_67046_Option_14 = {
    Text = "Je peux voir que tu attends vraiment cela avec impatience."
  },
  AvgCommunicate_67046_Option_3 = {
    Text = "Ils pourraient ressembler aux rayures d'un zèbre."
  },
  AvgCommunicate_67046_Option_5 = {
    Text = "Haha, je rigole !"
  },
  AvgCommunicate_67046_Option_7 = {
    Text = "Ugh, cette lumière éblouissante..."
  },
  AvgCommunicate_67046_Option_8 = {
    Text = "Quelle est cette sensation de culpabilité..."
  },
  AvgCommunicate_67047_Content_1 = {
    Text = "Gardien, j›aimerais vous demander une faveur."
  },
  AvgCommunicate_67047_Content_10 = {
    Text = "Avec vous à ses côtés, je suis convaincu qu›elle se sentira plus à l›aise et rassurée."
  },
  AvgCommunicate_67047_Content_11 = {
    Text = "Je devrais rester avec elle...? Je comprends."
  },
  AvgCommunicate_67047_Content_12 = {
    Text = "Alors je compte sur vous. Merci beaucoup, Gardien."
  },
  AvgCommunicate_67047_Content_2 = {
    Text = "Quel est le problème ?"
  },
  AvgCommunicate_67047_Content_3 = {
    Text = "Pourrais-tu emmener Teinture à quelques rassemblements pour qu'elle puisse se faire de nouveaux amis ?"
  },
  AvgCommunicate_67047_Content_4 = {
    Text = "Depuis nos retrouvailles, elle s›accroche à moi tous les jours, complètement coupée du monde extérieur."
  },
  AvgCommunicate_67047_Content_5 = {
    Text = "Bien que je chérisse nos retrouvailles, je ne veux pas la lier entièrement à moi."
  },
  AvgCommunicate_67047_Content_6 = {
    Text = "Ce n›est pas difficile, mais avez-vous pris en compte les sentiments de Tinct ?"
  },
  AvgCommunicate_67047_Content_7 = {
    Text = "Je la comprends... Mais elle ne peut pas continuer à rejeter tout le monde à cause de moi."
  },
  AvgCommunicate_67047_Content_8 = {
    Text = "Peut-être n›avez-vous pas besoin de la repousser aussi résolument."
  },
  AvgCommunicate_67047_Content_9 = {
    Text = "Et si je vous emmenais, vous et Tinct, à une fête ? Je m›occuperai des mesures de protection."
  },
  AvgCommunicate_67047_Option_2 = {
