  AvgCommunicate_67048_Content_1 = {
    Text = "Gardien, merci pour ta suggestion la dernière fois."
  },
  AvgCommunicate_67048_Content_10 = {
    Text = "On dirait que c'est moi qui dois m'améliorer, pas ma petite sœur."
  },
  AvgCommunicate_67048_Content_2 = {
    Text = "Depuis que Tinct et moi avons assisté à cette fête, Tinct adore discuter avec de nouveaux amis."
  },
  AvgCommunicate_67048_Content_3 = {
    Text = "De rien. Je suis content de vous voir toutes les deux heureuses."
  },
  AvgCommunicate_67048_Content_4 = {
    Text = "Mm... J'ai réalisé pour la première fois à quel point Tinct aime socialiser quand il n'y a aucune contrainte."
  },
  AvgCommunicate_67048_Content_5 = {
    Text = "Même si à chaque fois elle reste près de moi, me tirant parfois dans les conversations."
  },
  AvgCommunicate_67048_Content_6 = {
    Text = "Mais cela faisait si longtemps que je ne l'avais pas vue sourire aussi joyeusement à quelqu'un d'autre."
  },
  AvgCommunicate_67048_Content_7 = {
    Text = "C'est merveilleux."
  },
  AvgCommunicate_67048_Content_8 = {
    Text = "Soupir, comparé à son enthousiasme, j'ai encore du mal avec ces occasions sociales fréquentes."
  },
  AvgCommunicate_67048_Content_9 = {
    Text = "Après chaque fête, j'ai besoin de bien me reposer dans ma coquille pendant un moment pour récupérer."
  },
  AvgCommunicate_67048_Option_3 = {
    Text = "De rien. Je suis content de vous voir toutes les deux heureuses."
