  AvgCommunicate_67049_Content_1 = {
    Text = "Keeper, tu me cherchais ?"
  },
  AvgCommunicate_67049_Content_10 = {
    Text = "Tu essaies clairement de tromper les gens pour des sacrifices en mer à nouveau !!"
  },
  AvgCommunicate_67049_Content_11 = {
    Text = "Bien sûr que non, ce n'étaient que des accidents. Reposant éternellement dans leur patrie, leurs âmes trouveront le salut."
  },
  AvgCommunicate_67049_Content_12 = {
    Text = "Tu as complètement abandonné le jeu ! Suspension ! Suspend-le immédiatement !!"
  },
  AvgCommunicate_67049_Content_2 = {
    Text = "Exactement, je t'avais demandé de gérer le trafic de Mythag récemment. Comment cela s'est-il passé ?"
  },
  AvgCommunicate_67049_Content_3 = {
    Text = "Je me sens bien. Guider les perdus a toujours été mon devoir, mon destin et mon but."
  },
  AvgCommunicate_67049_Content_4 = {
    Text = "Guidé par ma lumière, le trafic de Mythag circule plus harmonieusement que jamais."
  },
  AvgCommunicate_67049_Content_5 = {
    Text = "Oh, vraiment ? Alors pourquoi toutes ces plaintes ?"
  },
  AvgCommunicate_67049_Content_6 = {
    Text = "Impossible, mon guidage ne peut pas être faux."
  },
  AvgCommunicate_67049_Content_7 = {
    Text = "Laisse-moi voir, distribuant des flyers pendant le feu rouge, lisant des annonces, y compris..."
  },
  AvgCommunicate_67049_Content_8 = {
    Text = "Journée de Plongée au Trésor de Récif ? Groupe de Croisière de Luxe ? Fête de Pêche et Cuisine en Mer ?"
  },
  AvgCommunicate_67049_Content_9 = {
    Text = "Y a-t-il un problème ? La mer est si envoûtante. Je pense que tout le monde devrait s'en approcher."
