  AvgCommunicate_67050_Content_1 = {
    Text = "Gardien, que signifie cet avis m'interdisant de sortir la nuit ? Je ne crois pas avoir fait quoi que ce soit contre les règles."
  },
  AvgCommunicate_67050_Content_10 = {
    Text = "Restez calme, reposez-vous bien ce soir."
  },
  AvgCommunicate_67050_Content_11 = {
    Text = "Si vous le souhaitez, je suggérerai à l›école de vous confier la gestion de la circulation sur les routes du campus."
  },
  AvgCommunicate_67050_Content_2 = {
    Text = "C›est exact..."
  },
  AvgCommunicate_67050_Content_3 = {
    Text = "Auparavant, lorsque vous erriez sur le campus la nuit à plusieurs reprises, vous ressembliez à un œil flottant vu de loin, effrayant les étudiants qui se promenaient dans la nuit."
  },
  AvgCommunicate_67050_Content_4 = {
    Text = "Absurde ! Ma lumière a toujours guidé les égarés. Comment pourrait-elle effrayer qui que ce soit ?"
  },
  AvgCommunicate_67050_Content_5 = {
    Text = "Les étudiants qui ont signalé l›incident ont dit que vous vous êtes soudainement approché d›eux en les apercevant."
  },
  AvgCommunicate_67050_Content_6 = {
    Text = "Ils ont fui de peur, et vous n›avez cessé de les poursuivre."
  },
  AvgCommunicate_67050_Content_7 = {
    Text = "La nuit est sombre, mais j›espérais simplement les guider sur le droit chemin."
  },
  AvgCommunicate_67050_Content_8 = {
    Text = "Bel effort pour les attirer, mais évitez de recommencer."
  },
  AvgCommunicate_67050_Content_9 = {
    Text = "Eux, même eux, aucun d›entre vous ne comprend mon devoir..."
