  AvgCommunicate_67050_Option_5 = {
    Text = "Les étudiants qui ont signalé l›incident ont dit que vous vous êtes soudainement approché d›eux en les apercevant."
  },
  AvgCommunicate_67050_Option_8 = {
    Text = "Bel effort pour les attirer, mais évitez de recommencer."
  },
  AvgCommunicate_67051_Content_1 = {
    Text = "J›ai soudainement perdu tout intérêt pour le simple combat."
  },
  AvgCommunicate_67051_Content_10 = {
    Text = "Si vite ? Tu as vraiment du talent. As-tu joué contre d'autres ?"
  },
  AvgCommunicate_67051_Content_11 = {
    Text = "Eh bien, j'ai frappé à toutes les portes des Corps éveillés, même si tout le monde n'a pas répondu."
  },
  AvgCommunicate_67051_Content_12 = {
    Text = "Alors, tu as juste trouvé un autre moyen de troubler la tranquillité !"
  },
  AvgCommunicate_67051_Content_13 = {
    Text = "Passons... quel est ton palmarès ?"
  },
  AvgCommunicate_67051_Content_14 = {
    Text = "Jusqu'à présent, je n'ai battu qu'Aurita, mais je suis convaincu qu'en continuant à m'entraîner, je deviendrai de plus en plus fort !"
  },
  AvgCommunicate_67051_Content_2 = {
    Text = "?? Quiconque vous êtes, dégagez Lotan immédiatement !"
  },
  AvgCommunicate_67051_Content_3 = {
    Text = "Qu›est-ce qui te prend ? J›ai récemment découvert un combat bien plus intéressant."
  },
  AvgCommunicate_67051_Content_4 = {
    Text = "Qu'est-ce que c'est ?"
  },
  AvgCommunicate_67051_Content_5 = {
    Text = "Jouer aux échecs ! Dexter m›a dit que les vrais maîtres en arts martiaux sont tous doués aux échecs."
  },
  AvgCommunicate_67051_Content_6 = {
    Text = "Seulement en percevant l›intention de l›adversaire et en prédisant ses coups peut-on remporter la victoire sur l›échiquier."
  },
  AvgCommunicate_67051_Content_7 = {
