  AvgCommunicate_70487_Content_11 = {
    Text = "Je ne l'aime pas, elle ni toi. Mais je déteste encore plus cette Montagne de Neige auto-proclamée juste, ainsi que ceux qui souhaitent m'utiliser et me trahir."
  },
  AvgCommunicate_70487_Content_12 = {
    Text = "C'est tout."
  },
  AvgCommunicate_70487_Content_2 = {
    Text = "Après être revenue de la Montagne de Neige, elle a reçu des soins, et ses blessures ont très bien guéri."
  },
  AvgCommunicate_70487_Content_3 = {
    Text = "J'ai entendu parler de la montagne enneigée par une autre version de vous."
  },
  AvgCommunicate_70487_Content_4 = {
    Text = "Merci, Hilote. C'est toi qui nous as aidés."
  },
  AvgCommunicate_70487_Content_5 = {
    Text = "Merci ? Quel mot faible."
  },
  AvgCommunicate_70487_Content_6 = {
    Text = "Je ne cherche que le pouvoir de la Montagne de Neige. Cela n'a rien à voir avec le fait de vous aider."
  },
  AvgCommunicate_70487_Content_7 = {
    Text = "Les vies d'une bande de fourmis ne me concernent pas."
  },
  AvgCommunicate_70487_Content_8 = {
    Text = "Dans la montagne de neige, vous aviez la chance de tuer une autre version de vous-même, soit pour dévorer le pouvoir de la montagne de neige seul, soit permettre à la montagne de neige de nous dévorer."
  },
  AvgCommunicate_70487_Content_9 = {
    Text = "Mais tu ne l'as pas fait, n'est-ce pas ?"
  },
  AvgCommunicate_70487_Option_3 = {
    Text = "Merci de m'avoir parlé de la Montagne de Neige."
  },
  AvgCommunicate_70487_Option_8 = {
    Text = "Mais tu as choisi de ne pas tuer une autre version de toi-même."
  },
  AvgCommunicate_70488_Content_1 = {
    Text = "Capitaine, le corps s'est affaibli..."
  },
  AvgCommunicate_70488_Content_10 = {
    Text = "Gardien, je ferai de mon mieux pour t'aider."
  },
  AvgCommunicate_70488_Content_11 = {
    Text = "S'il y a une chance, veuillez sauver le capitaine."
  },
  AvgCommunicate_70488_Content_12 = {
    Text = "C'est... mon souhait."
  },
  AvgCommunicate_70488_Content_2 = {
    Text = "Puis-je demander, y a-t-il un moyen de l'aider ?"
  },
  AvgCommunicate_70488_Content_3 = {
    Text = "Cela peut être difficile, Céleste."
  },
  AvgCommunicate_70488_Content_4 = {
    Text = "Même pour les Enquêteurs, se lier aux Réveilleurs est un fardeau énorme."
  },
  AvgCommunicate_70488_Content_5 = {
    Text = "De plus, le Capitaine Elton n'est qu'une personne ordinaire à cet égard."
  },
  AvgCommunicate_70488_Content_6 = {
    Text = "Le fait qu'il ait pu maintenir un lien avec vous aussi longtemps est déjà un miracle."
  },
  AvgCommunicate_70488_Content_7 = {
    Text = "Mais soyez assuré, je trouverai certainement un moyen de vous aider."
  },
  AvgCommunicate_70488_Content_8 = {
    Text = "Ce que Miryam peut faire, Mythag peut certainement le faire aussi."
  },
  AvgCommunicate_70488_Content_9 = {
    Text = "Les gens me font des souhaits, mais je suis impuissant à aider ceux qui m'entourent..."
  },
  AvgCommunicate_70488_Option_3 = {
    Text = "Cela peut être difficile, mais Mythag trouvera sûrement un moyen."
  },
  AvgCommunicate_70489_Content_1 = {
    Text = "Désolé pour l'interruption, pâle Œil Aveugle."
  },
  AvgCommunicate_70489_Content_10 = {
    Text = "Mon contact avec vous est purement basé sur un intérêt personnel."
  },
  AvgCommunicate_70489_Content_11 = {
