    Text = "Chut, ce n'est pas quelque chose que tu devrais savoir en ce moment."
  },
  AvgCommunicate_70489_Content_8 = {
    Text = "Fais-moi confiance, tu le sauras — quand le moment sera venu."
  },
  AvgCommunicate_70489_Content_9 = {
    Text = "Quoi qu›il en soit, je ne vous veux aucun mal, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgCommunicate_70489_Option_15 = {
    Text = "Mon avenir ?"
  },
  AvgCommunicate_70489_Option_2 = {
    Text = "Es-tu... le psychologue ?!"
  },
  AvgCommunicate_70489_Option_3 = {
    Text = "Que nous as-tu fait dans l'atelier ?"
  },
  AvgCommunicate_70489_Option_6 = {
    Text = "Que signifie exactement \"Œil Aveugle\" ?"
  },
  AvgCommunicate_70490_Content_1 = {
    Text = "Lorsque le Corps artificiel s'est auto-détruit, j'ai laissé à Herbert un petit morceau d'Argent avec des capacités d'enregistrement et de transmission d'information."
  },
  AvgCommunicate_70490_Content_10 = {
    Text = "Exactement le même que le symbole que vous avez dessiné dans votre rêve."
  },
  AvgCommunicate_70490_Content_11 = {
    Text = "Quel est ce symbole exactement ?"
  },
  AvgCommunicate_70490_Content_12 = {
    Text = "Église de la lumière du temple."
  },
  AvgCommunicate_70490_Content_13 = {
    Text = "C'est en fait eux..."
  },
  AvgCommunicate_70490_Content_14 = {
    Text = "L'association des sculpteurs, Elwes... Ce n'est pas la première fois que la lumière du temple apparaît."
  },
  AvgCommunicate_70490_Content_15 = {
    Text = "Les véritables ennemis de Mythag s'approchent de nous."
  },
  AvgCommunicate_70490_Content_16 = {
    Text = "Préparez-vous, %player%."
  },
  AvgCommunicate_70490_Content_2 = {
    Text = "Grâce à la cupidité de Herbert, ce petit appareil a réussi à recueillir pas mal d'informations."
  },
  AvgCommunicate_70490_Content_3 = {
    Text = "Si puissant, Professeur Poupée!"
  },
  AvgCommunicate_70490_Content_4 = {
    Text = "C'est juste qu'il n'était pas assez prudent."
  },
  AvgCommunicate_70490_Content_5 = {
    Text = "Un prétendu génie dont l'arrogance le fera baisser sa garde."
  },
  AvgCommunicate_70490_Content_6 = {
    Text = "Avais-tu prévu ce mouvement depuis longtemps ?!"
  },
  AvgCommunicate_70490_Content_7 = {
    Text = "Même en manipulant des corps artificiels, sortir est assez problématique."
  },
  AvgCommunicate_70490_Content_8 = {
    Text = "Si je ne peux rien obtenir, je ferais mieux de profiter du thé de l'après-midi dans le salon."
  },
  AvgCommunicate_70490_Content_9 = {
    Text = "En résumé, l'information la plus cruciale dans les renseignements rassemblés est un symbole."
  },
  AvgCommunicate_70490_Option_11 = {
    Text = "Quel est ce symbole exactement ?"
  },
  AvgCommunicate_70490_Option_3 = {
    Text = "Si puissant, Professeur Poupée!"
  },
  AvgCommunicate_70490_Option_6 = {
    Text = "Avais-tu prévu ce mouvement depuis longtemps ?!"
  },
  AvgCommunicate_70491_Content_1 = {
    Text = "La première tâche sur le terrain après avoir assumé le rôle de Gardien est terminée."
  },
  AvgCommunicate_70491_Content_10 = {
    Text = "Je ne m'attendais jamais à ce que ma première mission officielle sur le terrain implique cela."
  },
  AvgCommunicate_70491_Content_11 = {
    Text = "Parce que tu es le Gardien."
  },
  AvgCommunicate_70491_Content_12 = {
    Text = "Beaucoup sont partis, mais plus ont été sauvés grâce à vous."
  },
  AvgCommunicate_70491_Content_13 = {
    Text = "Nous sommes sur la bonne voie."
  },
  AvgCommunicate_70491_Content_14 = {
    Text = "Tu as raison, Ramona."
  },
  AvgCommunicate_70491_Content_15 = {
    Text = "Plus de gens sont sauvés grâce à nous."
  },
  AvgCommunicate_70491_Content_16 = {
    Text = "Nous allons marcher le long de ce chemin jusqu'à la fin."
  },
  AvgCommunicate_70491_Content_17 = {
    Text = "Certainement !"
  },
  AvgCommunicate_70491_Content_2 = {
    Text = "Félicitations."
  },
  AvgCommunicate_70491_Content_3 = {
    Text = "Je ne m'attendais jamais à ce que ma première mission officielle sur le terrain implique cela."
  },
  AvgCommunicate_70491_Content_4 = {
    Text = "Mais quoi qu'il en soit, nous avons réussi."
  },
  AvgCommunicate_70491_Content_5 = {
    Text = "Nous sommes sur la bonne voie."
  },
  AvgCommunicate_70491_Content_6 = {
    Text = "C'est correct, Gardien."
  },
  AvgCommunicate_70491_Content_7 = {
    Text = "Nous allons marcher le long de ce chemin jusqu'à la fin."
  },
  AvgCommunicate_70491_Content_8 = {
    Text = "Je n'ai pas l'impression d'avoir réussi à accomplir quoi que ce soit, Ramona."
  },
  AvgCommunicate_70491_Content_9 = {
    Text = "Senior Anderson, Sarah, Aigis..."
  },
  AvgCommunicate_70491_Option_14 = {
    Text = "Tu as absolument raison..."
  },
  AvgCommunicate_70491_Option_3 = {
    Text = "Il y a de nombreux regrets, mais nous sommes sur la bonne voie."
  },
  AvgCommunicate_70491_Option_8 = {
    Text = "Le problème est temporairement résolu, mais certains regrets ne pourront jamais être réparés."
  },
  AvgCommunicate_70492_Content_1 = {
    Text = "Je veux récemment organiser un événement commémoratif, mais je manque de poissons vivants et de bateaux."
  },
  AvgCommunicate_70492_Content_10 = {
    Text = "Puisque vous êtes conscient de mon passé, vous devriez également connaître ma réponse."
  },
  AvgCommunicate_70492_Content_11 = {
    Text = "Si on me donnait une autre chance, je ferais encore ce que j'ai fait autrefois."
  },
  AvgCommunicate_70492_Content_12 = {
    Text = "Le passé, le présent et l'avenir. Le Grand Prêtre de Lémurie ne regrette jamais."
  },
  AvgCommunicate_70492_Content_13 = {
    Text = "Je... n'ai jamais eu d'autre choix, Gardien."
  },
  AvgCommunicate_70492_Content_2 = {
    Text = "Puis Mythag peut-il en emprunter quelques-uns pour un moment ? Je garantis, en tant que Grand Prêtre de Lémurie, qu'ils seront retournés à temps."
  },
  AvgCommunicate_70492_Content_3 = {
    Text = "Pas de problème. Je vais t'aider à communiquer avec l'école, et le comité scolaire devrait l'approuver."
  },
  AvgCommunicate_70492_Content_4 = {
    Text = "Ces objets sont-ils pour votre famille ou pour Deborah ?"
  },
  AvgCommunicate_70492_Content_5 = {
    Text = "...Sais-tu tout ?"
  },
  AvgCommunicate_70492_Content_6 = {
    Text = "Selon les coutumes de Lémurie, vous envoyiez des salutations à vos défunts les plus chéris en utilisant des poissons vivants et des bateaux."
  },
  AvgCommunicate_70492_Content_7 = {
    Text = "Vous ne pouvez toujours pas les oublier. Vous les aimez toujours profondément."
  },
  AvgCommunicate_70492_Content_8 = {
    Text = "Alors... regrettes-tu vraiment cela, Miryam ?"
  },
  AvgCommunicate_70492_Content_9 = {Text = "新增"},
  AvgCommunicate_70492_Option_3 = {
    Text = "Pas de problème."
  },
  AvgCommunicate_70492_Option_4 = {
    Text = "Est-ce pour ta famille, ou est-ce préparé pour Deborah ?"
  },
  AvgCommunicate_70492_Option_8 = {
    Text = "Regrettez-vous cela ?"
  },
  AvgCommunicate_70493_Content_1 = {
    Text = "J'ai fini de lire votre testament."
  },
  AvgCommunicate_70493_Content_10 = {
    Text = "Je vais également raconter fièrement vos exploits aux autres jusqu'au jour où ma Mémoire subira sa Dissolution."
  },
  AvgCommunicate_70493_Content_11 = {
    Text = "Mais alors que je récite ma volonté, à ce moment, le regret consume toutes mes pensées."
  },
  AvgCommunicate_70493_Content_12 = {
    Text = "Vous avez dit que vous étiez un lâche. Vous avez dit que vous ne voudriez jamais nous abandonner."
  },
  AvgCommunicate_70493_Content_13 = {
    Text = "Mais à la fin, tu as tout de même emprunté ce chemin."
  },
  AvgCommunicate_70493_Content_14 = {
    Text = "Père est parti. Toi aussi es parti."
  },
  AvgCommunicate_70493_Content_15 = {
    Text = "Je ne me dérange pas des mensonges que tu dis. J'aimerais que tu puisses continuer à me tromper encore un peu plus longtemps. Un an, un mois..."
  },
  AvgCommunicate_70493_Content_16 = {
    Text = "Même si ce n'est que pour un jour, les mots restés inexprimés ont au moins une chance d'être dits..."
  },
  AvgCommunicate_70493_Content_17 = {
    Text = "J'ai vraiment peur, %player%."
  },
  AvgCommunicate_70493_Content_18 = {
    Text = "J'ai peur qu'un jour je perde ton visage et ton nom."
  },
  AvgCommunicate_70493_Content_19 = {
    Text = "J'ai peur qu'un jour, tu disparaisses complètement de ma mémoire..."
  },
  AvgCommunicate_70493_Content_2 = {
    Text = "J'ai essayé de réciter ces mots d'un ton réconfortant, comme vous le souhaitiez."
  },
  AvgCommunicate_70493_Content_20 = {
    Text = "Mais tu sais, je ne suis pas le genre de personne qui abandonne facilement."
  },
  AvgCommunicate_70493_Content_21 = {
    Text = "Je ne peux pas croire que tu disparaisse comme ça."
  },
  AvgCommunicate_70493_Content_22 = {
    Text = "Peu importe combien j'attends, je serai ici, me rappelant. Jusqu'au jour où vous vous éveillerez du Bassin Noir, ouvrirez cette porte et retournerez sur ce campus."
  },
  AvgCommunicate_70493_Content_23 = {
    Text = "Quand ce moment viendra, je te dirai tout ce qui s'est passé pendant que tu étais parti, ainsi que ces mots non dits, un par un..."
  },
  AvgCommunicate_70493_Content_24 = {
    Text = "Je sais que vous devez être très fatigué maintenant, trop fatigué pour répondre... Ça va, reposez-vous bien."
  },
  AvgCommunicate_70493_Content_25 = {
    Text = "Je t'attends... %player%."
  },
  AvgCommunicate_70493_Content_3 = {
    Text = "J'ai fait de mon mieux. Mais je ne peux pas le faire, %player%..."
  },
  AvgCommunicate_70493_Content_4 = {
    Text = "Le tombeau clé est rempli de gens ; je ne vois personne."
  },
  AvgCommunicate_70493_Content_5 = {
    Text = "Le monde entier est tombé silencieux. Seul le bruit de la pluie persiste, seulement toi et moi."
  },
  AvgCommunicate_70493_Content_6 = {
    Text = "Lorsque cette porte s'est fermée devant moi et que ces mots défilaient ligne par ligne devant mes yeux, je n'ai ressenti que des regrets."
  },
  AvgCommunicate_70493_Content_7 = {
    Text = "Je regrette de t'avoir inculqué ces idéaux d'Enquêteur, je regrette de t'avoir appris ces Connaissances d'Investigation, je regrette de t'avoir éloigné d'Akut..."
  },
  AvgCommunicate_70493_Content_8 = {
    Text = "Je sais que je ne devrais pas penser de cette façon."
  },
  AvgCommunicate_70493_Content_9 = {
    Text = "Je suis un Enquêteur. Vous avez sauvé notre monde de la Dissolution. Je devrais me sentir soulagé pour vous."
  },
  AvgCommunicate_70494_Content_1 = {
    Text = "Bonne journée, Gardien de Mythag."
  },
  AvgCommunicate_70494_Content_10 = {
    Text = "J'ai entendu dire que Mythag a produit un Gardien exceptionnel."
  },
  AvgCommunicate_70494_Content_11 = {
    Text = "Je ne devrais pas m'introduire, mais je ne peux tout simplement pas contenir ma curiosité et je souhaite vous voir en personne."
  },
  AvgCommunicate_70494_Content_12 = {
    Text = "Vous ne m'avez pas déçu, %player%."
  },
  AvgCommunicate_70494_Content_13 = {
    Text = "Que comptes-tu faire exactement ?"
  },
  AvgCommunicate_70494_Content_14 = {
    Text = "Si j'ai la chance, j'aimerais vous inviter dans mon laboratoire en tant qu'invité."
  },
  AvgCommunicate_70494_Content_15 = {
    Text = "Un Gardien qui peut relier d'innombrables Réveilleurs... Les secrets à votre sujet m'intriguent beaucoup."
  },
  AvgCommunicate_70494_Content_16 = {
    Text = "Si tu amènes les membres de l'Association des Sculpteurs à se confessent à Mythag, la coopération pourrait valoir la peine d'être envisagée."
  },
  AvgCommunicate_70494_Content_17 = {
    Text = "Heh... Je pensais que je me ferais gronder."
  },
  AvgCommunicate_70494_Content_18 = {
    Text = "Vous êtes plus intéressant que je ne l'imaginais."
  },
  AvgCommunicate_70494_Content_19 = {
    Text = "Les jours à venir sont longs, et dans le futur, nous aurons de nombreuses occasions de communiquer."
  },
  AvgCommunicate_70494_Content_2 = {
    Text = "C'est toi... Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Content_20 = {
    Text = "Attendez-vous à cela, %player%."
  },
  AvgCommunicate_70494_Content_3 = {
    Text = "Oh, il semble que quelqu'un m'ait déjà présenté à vous."
  },
  AvgCommunicate_70494_Content_4 = {
    Text = "Cela m'a en fait sauvé beaucoup de tracas."
  },
  AvgCommunicate_70494_Content_5 = {
    Text = "Les communications en argent nécessitent un lien bidirectionnel. Comment m'as-tu contacté ?"
  },
  AvgCommunicate_70494_Content_6 = {Text = "Hmm..."},
  AvgCommunicate_70494_Content_7 = {
    Text = "Pour ceux qui ont la chance de participer au développement, la technologie de communication en Argent n'a aucun secret."
  },
  AvgCommunicate_70494_Content_8 = {
    Text = "Es-tu le développeur de la Communication en Argent ?"
  },
  AvgCommunicate_70494_Content_9 = {
    Text = "Les vieilles histoires peuvent être discutées à loisir quand nous aurons le temps."
  },
  AvgCommunicate_70494_Option_13 = {
    Text = "Que comptes-tu faire exactement ?"
  },
  AvgCommunicate_70494_Option_16 = {
    Text = "À moins que vous ne confessiez à Mythag"
  },
  AvgCommunicate_70494_Option_2 = {
    Text = "Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Option_5 = {
    Text = "Comment avez-vous pris contact avec moi ?"
  },
  AvgCommunicate_70495_Content_1 = {
    Text = "Les restes d'Anderson ont été détruits par les sculpteurs, il est désormais impossible de reconstituer une forme humaine complète."
  },
  AvgCommunicate_70495_Content_10 = {
    Text = "Peut-être qu'un jour nous le ferons..."
  },
  AvgCommunicate_70495_Content_11 = {
    Text = "Allez-vous ressentir la peur, Senior William ?"
  },
  AvgCommunicate_70495_Content_12 = {Text = "新增"},
  AvgCommunicate_70495_Content_13 = {
    Text = "Peut-être que quelqu'un peut transcender la vie et la mort, mais pas moi."
  },
  AvgCommunicate_70495_Content_14 = {
    Text = "J'ai peur tout le temps, %player%."
  },
  AvgCommunicate_70495_Content_15 = {
    Text = "Mais je n'ai jamais vu la moindre trace de peur en toi."
  },
  AvgCommunicate_70495_Content_16 = {
    Text = "Parce que je n'ai pas le temps. Parce que la Dissolution est juste devant moi."
  },
  AvgCommunicate_70495_Content_17 = {
    Text = "Beaucoup ont péri, pourtant je suis toujours en vie."
  },
  AvgCommunicate_70495_Content_18 = {
    Text = "Que ce soit la peur ou le souvenir, l'Enquêteur de Mythag n'a pas le droit de s'arrêter pour cela."
  },
  AvgCommunicate_70495_Content_19 = {Text = "新增"},
  AvgCommunicate_70495_Content_2 = {
    Text = "Ces Argents extraits de force ont également été presque complètement détruits."
  },
  AvgCommunicate_70495_Content_20 = {
    Text = "Une nouvelle tâche est arrivée."
  },
  AvgCommunicate_70495_Content_21 = {
    Text = "Nous allons survivre, %player%. Jusqu'au jour où la Dissolution sera résolue."
  },
  AvgCommunicate_70495_Content_3 = {
    Text = "Nous avons fouillé le laboratoire dans l'hospice et ne l'avons trouvé que là."
  },
  AvgCommunicate_70495_Content_4 = {
    Text = "Clé en argent, ID L-1463, appartient à l'Enquêteur Anderson—appartenait autrefois à lui."
  },
  AvgCommunicate_70495_Content_5 = {
    Text = "Que va faire l'école avec cette clé en argent... ?"
  },
  AvgCommunicate_70495_Content_6 = {
    Text = "Recycler, placer dans la <Piscine noire> pour le remodelage, puis distribuer aux nouveaux <Enquêteurs> lors de la <cérémonie des tombes clés> de l'année prochaine."
  },
  AvgCommunicate_70495_Content_7 = {
    Text = "Il accompagnera le nouveau enquêteur, se rendant constamment dans les endroits les plus dangereux."
  },
  AvgCommunicate_70495_Content_8 = {
    Text = "Jusqu'à ce que cet enquêteur démissionne ou meure."
  },
  AvgCommunicate_70495_Content_9 = {
    Text = "Peut-être qu'un jour nous le ferons..."
  },
  AvgCommunicate_70495_Option_10 = {
    Text = "Ressentirez-vous la peur ?"
  },
  AvgCommunicate_70495_Option_15 = {
    Text = "Je n'ai jamais ressenti ta peur."
  },
  AvgCommunicate_70495_Option_5 = {
    Text = "Que va faire l'école avec cette clé en argent... ?"
  },
  AvgCommunicate_70495_Option_9 = {
    Text = "Finirons-nous comme Anderson ?"
  },
  AvgCommunicate_70496_Content_1 = {
    Text = "Le rituel de ces gens d'Aram... est vraiment choquant."
  },
  AvgCommunicate_70496_Content_10 = {
    Text = "Suis-je ce genre de personne ?"
  },
  AvgCommunicate_70496_Content_11 = {
    Text = "Je posais juste une question par ci par là, pourquoi tant de tension ?"
  },
  AvgCommunicate_70496_Content_12 = {
    Text = "Faire cela fera de vous un livre ouvert à la table de cartes. Votre force mentale a besoin d'amélioration, Gardien."
  },
  AvgCommunicate_70496_Content_13 = {
    Text = "En bref, les secrets de ce désert sont probablement bien plus complexes que nous ne l'avions anticipé."
  },
  AvgCommunicate_70496_Content_14 = {
    Text = "L'enquête qui a suivi nécessite une prudence accrue."
  },
  AvgCommunicate_70496_Content_2 = {
    Text = "Je pensais que tu accepterais l'invitation de cette femme arlanaise."
  },
  AvgCommunicate_70496_Content_3 = {Text = "新增"},
  AvgCommunicate_70496_Content_4 = {
    Text = "Quelle image ai-je réellement dans ton cœur..."
  },
  AvgCommunicate_70496_Content_5 = {
    Text = "Je ne m'attendais jamais à ce que Ryker, qui est généralement si charmant, ait aussi des choses qu'il ne pouvait pas accepter."
  },
  AvgCommunicate_70496_Content_6 = {
    Text = "Il n'y a pas d'histoires avec des fleurs et du vin, seulement les désirs les plus primitifs et sauvages."
  },
  AvgCommunicate_70496_Content_7 = {
    Text = "Ce type de rituel n'est effectivement pas à mon goût."
  },
  AvgCommunicate_70496_Content_8 = {
    Text = "En parlant de cela, tu n'as pas accepté d'invitations étranges, n'est-ce pas ?"
  },
  AvgCommunicate_70496_Content_9 = {
    Text = "Quand... bien sûr que non... comment ça pourrait être !"
  },
  AvgCommunicate_70496_Option_2 = {
    Text = "Je pensais que vous accepteriez l'invitation de cette femme Aylan."
  },
  AvgCommunicate_70496_Option_5 = {
    Text = "Je ne m'attendais pas à ce qu'il y ait des choses que tu ne pouvais pas accepter non plus."
  },
  AvgCommunicate_70496_Option_9 = {
    Text = "Quand... bien sûr que non... comment ça pourrait être !"
  },
  AvgCommunicate_70497_Content_1 = {
    Text = "Bonjour, Gardien du Secret {Male=monsieur,Female=madame}."
  },
  AvgCommunicate_70497_Content_2 = {
    Text = "T'es-tu amusé à jouer avec les jouets de Juliette ?"
  },
  AvgCommunicate_70497_Content_3 = {
    Text = "Es-tu... la taupe ?!"
  },
  AvgCommunicate_70497_Content_4 = {
    Text = "Je pensais que vous auriez compris qui je suis plus tôt. Quel dommage."
  },
  AvgCommunicate_70497_Content_5 = {
    Text = "Mais ça va ; ce n'est après tout que le dernier jeu."
  },
  AvgCommunicate_70497_Content_6 = {
    Text = "Maintenant, le jeu est sur le point de se terminer."
  },
  AvgCommunicate_70497_Content_7 = {
    Text = "Avant que la destruction fatidique n'arrive, je ne suis curieux que d'une seule chose."
  },
  AvgCommunicate_70497_Content_8 = {
    Text = "La vérité éternelle du Chaos, le Gardien audacieux dont nous parlons sans honte, Mythag, le brave Sauveur, peut-il vraiment y faire face avec courage ?"
  },
  AvgCommunicate_70497_Option_3 = {
    Text = "Es-tu... la taupe ?!"
  },
  AvgCommunicate_70498_Content_1 = {
    Text = "Je ne suis pas un marchand insensé, mais après mûre réflexion, il semble que j'ai fait un mauvais marché..."
  },
  AvgCommunicate_70498_Content_10 = {
    Text = "Être toujours méfiant envers les mensonges est une qualité de base d'un homme d'affaires qualifié."
  },
  AvgCommunicate_70498_Content_11 = {
    Text = "Donc... c'était vraiment le véritable visage de Madame Davincity ?"
  },
  AvgCommunicate_70498_Content_12 = {
    Text = "Il n'y a pas de coût plus cher que la réalité, petit Gardien."
  },
  AvgCommunicate_70498_Content_13 = {
    Text = "Merci, Dame Jonquille."
  },
  AvgCommunicate_70498_Content_14 = {
    Text = "Ce que je viens de dire était une blague. Je sais ce que cela signifie pour quelqu'un comme toi de révéler son vrai soi."
  },
  AvgCommunicate_70498_Content_15 = {
    Text = "C'est un cadeau précieux, et je vais bien le chérir."
  },
  AvgCommunicate_70498_Content_16 = {
    Text = "Ne pense pas que tu peux me balayer d'un simple mot, petit."
  },
  AvgCommunicate_70498_Content_17 = {
    Text = "En retour, ne devrais-tu pas aussi me donner un cadeau ?"
  },
  AvgCommunicate_70498_Content_18 = {
    Text = "Ai-je été percé à jour...?"
  },
  AvgCommunicate_70498_Content_19 = {
    Text = "Madame Davincity, que désirez-vous ?"
  },
  AvgCommunicate_70498_Content_2 = {Text = "?"},
  AvgCommunicate_70498_Content_20 = {
    Text = "Puisque tu as déjà vu ma vraie forme, quand seras-tu prêt à me montrer ta vraie personne ?"
  },
  AvgCommunicate_70498_Content_21 = {
    Text = "Mon vrai moi ? Que signifie cela... Je ne comprends pas tout à fait, Dame Jonquille."
  },
  AvgCommunicate_70498_Content_22 = {
    Text = "On dirait que Mythag ne t'a pas encore dit quoi que ce soit..."
  },
  AvgCommunicate_70498_Content_23 = {
    Text = "Le moment n'est pas encore venu. Pas de soucis."
  },
  AvgCommunicate_70498_Content_24 = {
    Text = "Souviens-toi de notre accord aujourd'hui, petit."
  },
  AvgCommunicate_70498_Content_25 = {
    Text = "J'attends avec impatience le jour où tu révéleras ton vrai visage."
  },
  AvgCommunicate_70498_Content_3 = {
    Text = "N'avez-vous pas déjà obtenu la tête que vous désiriez ?"
  },
  AvgCommunicate_70498_Content_4 = {
    Text = "Cette mer vibrante de matière grise est devenue un autre morceau chéri de votre collection."
  },
  AvgCommunicate_70498_Content_5 = {
    Text = "En effet, c'était une belle tête ; cet échange ne peut pas être considéré comme une perte."
  },
  AvgCommunicate_70498_Content_6 = {
    Text = "Cependant, le coût que j'ai payé est encore un peu trop élevé."
  },
  AvgCommunicate_70498_Content_7 = {
    Text = "Vous ne m'avez montré qu'un aperçu de votre véritable forme..."
  },
  AvgCommunicate_70498_Content_8 = {
    Text = "Et s'il est difficile de dire si c'est vraiment comme cela que tu es."
  },
  AvgCommunicate_70498_Content_9 = {
    Text = "Hehe... Pas mal, petit."
  },
  AvgCommunicate_70498_Option_11 = {
    Text = "Donc... c'était vraiment le véritable visage de Madame Davincity ?"
  },
  AvgCommunicate_70498_Option_13 = {
    Text = "Merci, Dame Jonquille."
  },
  AvgCommunicate_70498_Option_18 = {
    Text = "Ai-je été percé à jour...?"
  },
  AvgCommunicate_70498_Option_2 = {
    Text = "N'avons-nous pas déjà obtenu la tête ?"
  },
  AvgCommunicate_70498_Option_21 = {
    Text = "Mon vrai moi ? Que signifie cela"
  },
  AvgCommunicate_70498_Option_7 = {
    Text = "Je viens d'apercevoir ta véritable forme..."
  },
  AvgCommunicate_70499_Content_1 = {
    Text = "En éliminant les dissidents, elle s'est libérée des contraintes de Longbel et du Contrat. Sans ces entraves, en seulement quelques semaines, elle est devenue la chasseuse la plus féroce du monde des affaires de Londinium."
  },
  AvgCommunicate_70499_Content_10 = {
    Text = "Ne vous inquiétez pas, Professeur Dexter. Nous ne vous laisserons pas faire de telles choses dangereuses la prochaine fois... Je veux dire, nous essaierons de ne pas le faire."
  },
  AvgCommunicate_70499_Content_11 = {
    Text = "L'existence cachée dans la conscience de Sorel semble s'appeler \"N\". En sais-tu quelque chose à son sujet ?"
  },
  AvgCommunicate_70499_Content_12 = {
    Text = "Pas très clair. On dirait soit un escroc soit un fou, probablement les deux."
  },
  AvgCommunicate_70499_Content_13 = {
    Text = "Mais peu importe à quel point il est odieux, au moins ce gars a du goût. On peut le dire par son chant."
  },
  AvgCommunicate_70499_Content_14 = {
    Text = "La prochaine fois qu'il y aura une opportunité, nous devons mieux nous connaître. Peut-être que nous pourrions même partager un verre ou deux."
  },
  AvgCommunicate_70499_Content_15 = {
    Text = "...Bien sûr, dans un environnement sûr. Le vieux monsieur ne peut plus supporter aucune frayeur."
  },
  AvgCommunicate_70499_Content_2 = {
    Text = "Je pense qu'il ne faudra pas longtemps avant que toute la terre de Londinium porte son nom de famille."
  },
  AvgCommunicate_70499_Content_3 = {
    Text = "Dame Sorel, quelle personne fascinante. Heureusement, Mythag est de son côté."
  },
  AvgCommunicate_70499_Content_4 = {
    Text = "Je dois cette affaire à votre aide, Professeur Dexter."
  },
  AvgCommunicate_70499_Content_5 = {
    Text = "Merci d'avoir aidé à débusquer le suspect ; sinon, cela aurait pris beaucoup plus de temps pour résoudre cette affaire."
  },
  AvgCommunicate_70499_Content_6 = {
    Text = "Simplement accomplir les devoirs d'un gentleman."
  },
  AvgCommunicate_70499_Content_7 = {
    Text = "La proposition avancée par Ramona, cet ancien père à moi n'a aucun droit de refuser."
  },
  AvgCommunicate_70499_Content_8 = {
    Text = "Cependant, si quelque chose comme ça se reproduit la prochaine fois, j'espère que vous pourrez agir un peu plus rapidement."
  },
  AvgCommunicate_70499_Content_9 = {
    Text = "N'attends pas que le couteau de ce gars soit à seulement cinq centimètres de mon cou pour te montrer ; c'est vraiment effrayant."
  },
  AvgCommunicate_70499_Option_10 = {
    Text = "Il n'y aura pas de prochaine fois... Je ferai de mon mieux."
  },
  AvgCommunicate_70499_Option_11 = {
    Text = "Savez-vous quelque chose sur \"N\" ?"
  },
  AvgCommunicate_70499_Option_4 = {
    Text = "Merci d'avoir aidé à attirer le suspect"
  },
  AvgCommunicate_70500_Content_1 = {
    Text = "La conversation au café était fort agréable, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgCommunicate_70500_Content_10 = {
    Text = "Puis, si cette situation se reproduit, tirerais-tu toujours sur le vrai moi pour sauver les autres ? Le ferais-tu ?"
  },
  AvgCommunicate_70500_Content_11 = {
    Text = "Hmm... bien sûr."
  },
  AvgCommunicate_70500_Content_12 = {
    Text = "Sois rassuré, {Male=Mr.,Female=Miss} Gardien. La fortune continuera de me sourire."
  },
  AvgCommunicate_70500_Content_13 = {
    Text = "À ce moment-là, mon arme n'avait définitivement pas de munitions."
  },
  AvgCommunicate_70500_Content_14 = {Text = "70% non."},
  AvgCommunicate_70500_Content_2 = {
    Text = "C'est un honneur d'être témoin du passé d'un joueur."
  },
  AvgCommunicate_70500_Content_3 = {
    Text = "Ma partie préférée est quand le joueur perd tout et a son Âme volée par d'autres."
  },
  AvgCommunicate_70500_Content_4 = {
    Text = "Ha... il y a des victoires et des défaites, c'est la vie."
  },
  AvgCommunicate_70500_Content_5 = {
    Text = "Regarde, n'avons-nous pas gagné un avantage cette fois ?"
  },
  AvgCommunicate_70500_Content_6 = {
    Text = "Alors le coup que tu m'as tiré était aussi un pari ?"
  },
  AvgCommunicate_70500_Content_7 = {
    Text = "Comment cela pourrait-il être ? J'ai 70 % de certitude quant à mon jugement."
  },
  AvgCommunicate_70500_Content_8 = {
    Text = "Qu'en est-il des 30 % restants ?"
  },
  AvgCommunicate_70500_Content_9 = {
    Text = "Il ne reste plus 30 %. 70 % égale 100 %."
  },
  AvgCommunicate_70500_Option_2 = {
    Text = "C'est un honneur d'être témoin du passé d'un joueur."
  },
  AvgCommunicate_70500_Option_6 = {
    Text = "Alors le tir qui m'a été destiné était aussi un pari ?"
  },
  AvgCommunicate_70500_Option_8 = {
    Text = "Qu'en est-il des 30 % restants ?"
  },
  AvgCommunicate_70501_Content_1 = {
    Text = "Est-ce que c'est beau ?"
  },
  AvgCommunicate_70501_Content_10 = {
    Text = "Cependant... l'histoire narrée par cet ensemble de sculptures est un peu trop cruelle."
  },
  AvgCommunicate_70501_Content_11 = {
    Text = "Vous l'avez compris, Gardien..."
  },
  AvgCommunicate_70501_Content_12 = {
    Text = "Toute création est cruelle."
  },
  AvgCommunicate_70501_Content_13 = {
    Text = "C'est précisément dans cette cruauté que l'art figé a pris vie."
  },
  AvgCommunicate_70501_Content_14 = {
    Text = "Si c'était moi, je trouverais ce processus créatif assez épuisant..."
  },
  AvgCommunicate_70501_Content_15 = {
    Text = "Mais tu es différente, Sanga. Je comprends ton choix."
  },
  AvgCommunicate_70501_Content_16 = {
    Text = "Des œuvres comme « Décès de Mme Coral » représentent le sens que tu poursuis."
  },
  AvgCommunicate_70501_Content_17 = {
    Text = "J'ai hâte de voir la « cruauté » fleurir à nouveau dans les lignes que tu sculptes."
  },
  AvgCommunicate_70501_Content_18 = {Text = "新增"},
  AvgCommunicate_70501_Content_19 = {
    Text = "Je pensais que tu allais me suggérer de rendre mon art plus « normal », comme ces individus ordinaires."
  },
  AvgCommunicate_70501_Content_2 = {
    Text = "Quoi... votre visage ?"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "Ces mots comptent beaucoup pour moi... Merci, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "En retour, laisse-moi te confier un petit secret : quand tu entres dans un rêve, je me tiens juste à côté de toi."
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "J'ai capturé tes expressions affolées. D'un réalisme saisissant."
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "Lorsque tu as le temps, viens visiter ma petite salle d'exposition~"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "Sanga ! Je te donnerai cinquante Crocs de Leo, alors s'il te plaît, jette ces Sculptures..."
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "Ce que tu appelles un art vivant et « cruel », n'est-ce pas, Gardien?"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "Bien sûr, c'est la sculpture que vous avez vue dans votre rêve."
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "Les lignes du corps sont naturellement harmonieuses, mais manquent de quiétude et de beauté éternelle, ainsi que de thème et de créativité, ce qui rend la comparaison avec des œuvres sculpturales difficile."
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "Cet ensemble de sculptures se fait rare de nos jours. J'aimerais connaître votre avis à leur sujet..."
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "Quoi... ma sculpture ?"
  },
  AvgCommunicate_70501_Content_7 = {
    Text = "Bien sûr. Ce groupe de sculptures n'est plus guère vu par quiconque désormais, et je veux connaître votre opinion..."
  },
  AvgCommunicate_70501_Content_8 = {
    Text = "C'était le plus bel ensemble de sculptures que j'aie jamais vu."
  },
  AvgCommunicate_70501_Content_9 = {
    Text = "Bien que clairement statiques, les lignes dépeignent un dynamisme et une vitalité que les créatures vivantes n'ont pas."
  },
  AvgCommunicate_70501_Option_14 = {
    Text = "Je comprends votre choix"
  },
  AvgCommunicate_70501_Option_2 = {
    Text = "Votre visage ?"
  },
  AvgCommunicate_70501_Option_24 = {Text = "Non !!!"},
  AvgCommunicate_70501_Option_6 = {
    Text = "Votre sculpture ?"
  },
  AvgCommunicate_70501_Option_8 = {
    Text = "Beauté... et cruauté."
  },
  AvgCommunicate_70502_Content_1 = {
    Text = "Ennuyeux. Ennuyeux, ennuyeux, ennuyeux..."
  },
  AvgCommunicate_70502_Content_10 = {
    Text = "Londinium n'autorise pas l'esclavage, cet endroit barbare."
  },
  AvgCommunicate_70502_Content_11 = {
    Text = "Il y a pas d›autre choix que de t›écouter et de les commander dans le Labyrinthe."
  },
  AvgCommunicate_70502_Content_12 = {
    Text = "La façon dont ils se battaient dans l'arène était exactement comme ce que j'avais vu auparavant !"
  },
  AvgCommunicate_70502_Content_13 = {
    Text = "Alors le Labyrinthe est utilisé à cette fin..."
  },
  AvgCommunicate_70502_Content_14 = {
    Text = "C'est exact, c'est exact ! Comme c'est fascinant !"
  },
  AvgCommunicate_70502_Content_15 = {
    Text = "Allez, allons faire un tour ! C'est le plus haut honneur !"
  },
  AvgCommunicate_70502_Content_16 = {
    Text = "Ce n'est pas impossible ; en apprendre davantage sur l'histoire n'est pas une mauvaise chose..."
  },
  AvgCommunicate_70502_Content_17 = {
    Text = "Uvhash va probablement vraiment aimer votre arène. Pourquoi ne pas l'inviter également ?"
  },
  AvgCommunicate_70502_Content_18 = {
    Text = "Pas question ! Gardez ce démon loin de moi !!!"
  },
  AvgCommunicate_70502_Content_2 = {
    Text = "Être coincée dans cet endroit maudit tous les jours me rend folle !"
  },
  AvgCommunicate_70502_Content_3 = {
    Text = "J'ai reconstruit mon labyrinthe, toute une arène construite selon mes souvenirs !"
  },
  AvgCommunicate_70502_Content_4 = {
    Text = "Allons nous amuser ! Tout de suite !"
  },
  AvgCommunicate_70502_Content_5 = {
    Text = "Quand changeras-tu ce ton que tu utilises pour commander des esclaves... ?"
  },
  AvgCommunicate_70502_Content_6 = {
    Text = "Hmph, qu'est-ce qu'il y a à changer à propos de ça ?"
  },
  AvgCommunicate_70502_Content_7 = {
    Text = "J'ai déjà cédé dix mille fois ! Maintenant, je ne commande plus que ces esclaves dans le Labyrinthe."
  },
  AvgCommunicate_70502_Content_8 = {
    Text = "As-tu peur de te rappeler ces choses maintenant ?"
  },
  AvgCommunicate_70502_Content_9 = {
    Text = "En effet. Qu'est-ce qu'il y a à craindre !"
  },
  AvgCommunicate_70502_Option_16 = {
    Text = "Alors je vais aussi appeler Uvhash."
  },
  AvgCommunicate_70502_Option_5 = {
    Text = "Quand changeras-tu ton ton..."
  },
  AvgCommunicate_70502_Option_8 = {
    Text = "As-tu peur de te rappeler ces choses maintenant ?"
  },
  AvgCommunicate_70503_Content_1 = {
    Text = "L'incident qui s'est produit dans l'église... Si vous n'aviez pas été là, plus de personnes innocentes auraient été blessées..."
  },
  AvgCommunicate_70503_Content_10 = {
    Text = "Mais maintenant, elle est devenue la dirigeante actuelle de l'église de la lumière du temple."
  },
  AvgCommunicate_70503_Content_11 = {
    Text = "Quoi ? Le chef de l'église de la lumière du temple ?!!"
  },
  AvgCommunicate_70503_Content_12 = {
    Text = "Dans le monde religieux, l'Église de la lumière du temple est l'ennemi juré de votre Église... Comment se fait-il que vos étudiants..."
  },
  AvgCommunicate_70503_Content_13 = {
    Text = "Un long conte, Messager."
  },
  AvgCommunicate_70503_Content_14 = {
    Text = "Elle a autrefois travaillé avec moi pour la cause du Père Dieu, consacrant tout ce que nous avions aux gens du Père Dieu."
  },
  AvgCommunicate_70503_Content_15 = {
    Text = "Mais, comme vous pouvez le voir, il n'est pas si facile pour les égarés de se détourner du Dieu Père. Ces atrocités et préjugés ne peuvent pas être dissipés avec juste quelques Bénir."
  },
  AvgCommunicate_70503_Content_16 = {
    Text = "À cause des tribulations que j'ai endurées, elle a emprunté un chemin duquel il serait difficile de revenir."
  },
  AvgCommunicate_70503_Content_17 = {
    Text = "Alors c'est comme ça..."
  },
  AvgCommunicate_70503_Content_18 = {
    Text = "Je comprends. Tout comme ce qui s'est passé auparavant dans l'église, ceux qui n'ont pas changé à cause de vos bonnes actions ont causé sa transformation..."
  },
  AvgCommunicate_70503_Content_19 = {
    Text = "Le Père Dieu nous a un jour enseigné que les choses dans ce monde ne sont pas toujours noires ou blanches. De bonnes actions peuvent parfois aussi être une erreur."
  },
  AvgCommunicate_70503_Content_2 = {
    Text = "Au nom de l'Église et des innocents survivants, j'exprime ma sincère gratitude à vous, le Messager Pâle."
  },
  AvgCommunicate_70503_Content_20 = {
    Text = "J'ai consacré tout à la victime, mais j'ai oublié que mon élève en est également une."
  },
  AvgCommunicate_70503_Content_21 = {
    Text = "L'église et mes croyances ont peut-être sauvé de nombreuses personnes, mais elles n'ont pas pu la sauver."
  },
  AvgCommunicate_70503_Content_22 = {
    Text = "Je ne suis pas un enseignant qualifié, Messager."
  },
  AvgCommunicate_70503_Content_23 = {
    Text = "Je continuerai à suivre le chemin du Dieu Père. Mais je me demande si j'aurai un jour la chance de rattraper ce regret envers cet étudiant..."
  },
  AvgCommunicate_70503_Content_3 = {
    Text = "De rien, évêque Salvador. C'est tout dans mon devoir."
  },
  AvgCommunicate_70503_Content_4 = {
    Text = "Bishop, concernant votre passé, j'ai une question que j'aimerais vous poser..."
  },
  AvgCommunicate_70503_Content_5 = {
    Text = "Parle sans réserve, Émissaire."
  },
  AvgCommunicate_70503_Content_6 = {
    Text = "Mon passé sera ouvert à chaque personne sous la protection du Père Dieu."
  },
  AvgCommunicate_70503_Content_7 = {
    Text = "Quand je me suis lié à toi, à part Sophia, j'ai vu une femme qui avait une conversation avec toi."
  },
  AvgCommunicate_70503_Content_8 = {
    Text = "Ce souvenir occupe une grande partie de votre Esprit... Êtes-vous tous très familiers avec lui ?"
  },
  AvgCommunicate_70503_Content_9 = {
    Text = "En effet, très familier. Une fois, elle était ma plus brillante élève."
  },
  AvgCommunicate_70503_Option_11 = {
    Text = "Le chef de l'église de la lumière du temple ?!"
  },
  AvgCommunicate_70503_Option_17 = {
    Text = "Alors c'est comme ça..."
  },
  AvgCommunicate_70503_Option_3 = {
    Text = "C'est tout ce que je devrais faire."
  },
  AvgCommunicate_70503_Option_7 = {
    Text = "Qui est la dernière femme qui est apparue dans tes souvenirs ?"
  },
  AvgCommunicate_70504_Content_1 = {
    Text = "As-tu passé une agréable nuit, cher invité ?"
  },
  AvgCommunicate_70504_Content_10 = {
    Text = "Rassurez-vous, j'ai atteint un accord avec un certain gentleman et je ne prendrai aucune action outrageante."
  },
  AvgCommunicate_70504_Content_11 = {
    Text = "L'intégrité est très importante pour un marchand."
  },
  AvgCommunicate_70504_Content_12 = {
    Text = "De plus, vous avez autant de secrets que moi, n'est-ce pas ?"
  },
  AvgCommunicate_70504_Content_13 = {
    Text = "Quel est mon secret ? À quoi cela fait-il référence ?"
  },
  AvgCommunicate_70504_Content_14 = {
    Text = "Maintenant n'est pas le moment. Mais rassurez-vous, le commerce impliquant le nouveau Secret commencera bientôt."
  },
  AvgCommunicate_70504_Content_15 = {
    Text = "Le vent et la neige sur le chemin sont plus féroces que tu ne l'imagines."
  },
  AvgCommunicate_70504_Content_16 = {
    Text = "Tant qu'il y a du temps, profite de la chaleur de la cheminée, petit."
  },
  AvgCommunicate_70504_Content_2 = {
    Text = "Une si petite boutique chaleureuse est bien rare par une journée de neige et de vent, merci beaucoup de m'accueillir, Madame Davincity."
  },
  AvgCommunicate_70504_Content_3 = {
    Text = "Mais il semble que votre boutique cache de nombreux secrets."
  },
  AvgCommunicate_70504_Content_4 = {
    Text = "Ces objets de collection ne sont probablement pas aussi simples qu'ils en ont l'air."
  },
  AvgCommunicate_70504_Content_5 = {
    Text = "Observation très aiguë. Cependant, fouiller dans les secrets des autres n'est pas un comportement gentleman !"
  },
  AvgCommunicate_70504_Content_6 = {
    Text = "Je suis désolé, Dame Jonquille."
  },
  AvgCommunicate_70504_Content_7 = {
    Text = "Nous sommes venus dans cet endroit inconnu pour une Investigation, et devons d'abord assurer notre sécurité."
  },
  AvgCommunicate_70504_Content_8 = {
    Text = "J'espère que tu peux comprendre."
  },
  AvgCommunicate_70504_Content_9 = {
    Text = "Bien sûr. Si l'on pouvait s'endormir imprudemment dans la maison d'un étranger, alors l'éducation de Mythag pour les Gardiens est manifestement insuffisante."
  },
  AvgCommunicate_70504_Option_13 = {
    Text = "Mon secret ?"
  },
  AvgCommunicate_70504_Option_2 = {
    Text = "Il semble y avoir beaucoup de secrets ici."
  },
  AvgCommunicate_70504_Option_6 = {
    Text = "Je suis désolé, mais je dois assurer la sécurité de l'opération."
  },
  AvgCommunicate_70505_Content_1 = {
    Text = "Miryam, c'était le grand prêtre en qui j'avais le plus confiance."
  },
  AvgCommunicate_70505_Content_10 = {
    Text = "Je porte la responsabilité des Marins."
  },
  AvgCommunicate_70505_Content_11 = {
    Text = "Personne n'aurait pu prévoir le développement de la situation ; cela ne devrait pas être appelé un crime."
  },
  AvgCommunicate_70505_Content_12 = {
    Text = "Ce que vous avez fait était le meilleur choix à ce moment-là."
  },
  AvgCommunicate_70505_Content_13 = {
    Text = "Ce n'est pas de ta faute, Tulu."
  },
  AvgCommunicate_70505_Content_14 = {
    Text = "Peut-être. Mais tu as personnellement résolu cette affaire."
  },
  AvgCommunicate_70505_Content_15 = {
    Text = "Personne n'aurait pu prévoir le tournant des événements."
  },
  AvgCommunicate_70505_Content_16 = {
    Text = "Même s'il y avait des erreurs, tu les as corrigées."
  },
  AvgCommunicate_70505_Content_17 = {
    Text = "Vous avez accompli votre devoir en tant que Roi de Lémurie, Tulu."
  },
  AvgCommunicate_70505_Content_18 = {Text = "新增"},
  AvgCommunicate_70505_Content_19 = {
    Text = "Des paroles réconfortantes quelque peu maladroites, mais je les accepte."
  },
  AvgCommunicate_70505_Content_2 = {
    Text = "Elle et moi avons un jour apporté une brève période de prospérité à Lémurie."
  },
  AvgCommunicate_70505_Content_20 = {
    Text = "J'ai besoin de me reposer maintenant."
  },
  AvgCommunicate_70505_Content_21 = {
    Text = "Quand le moment sera venu, je me réveillerai."
  },
  AvgCommunicate_70505_Content_22 = {
    Text = "Mon devoir ne réside pas seulement dans Lémurie mais aussi dans Mythag."
  },
  AvgCommunicate_70505_Content_3 = {
    Text = "Elle et les habitants de Lémurie croient tous que je restaurerai la gloire du Royaume divin en Lémurie."
  },
  AvgCommunicate_70505_Content_4 = {
    Text = "Mais... c'est un mensonge, n'est-ce pas ?"
  },
  AvgCommunicate_70505_Content_5 = {
    Text = "Dans le Rêve, j'ai reçu une révélation."
  },
  AvgCommunicate_70505_Content_6 = {
    Text = "La fin de Lémurie est inévitable."
  },
  AvgCommunicate_70505_Content_7 = {
    Text = "Depuis le tout début jusqu'à la fin, Lémurie a vécu dans des mensonges."
  },
  AvgCommunicate_70505_Content_8 = {
    Text = "J'ai lié Lémurie et Miryam avec des mensonges."
