  AvgCommunicate_70512_Content_1 = {
    Text = "Depuis notre dernière rencontre à Lemwahi, cela fait longtemps, Gardien des Secrets {Male=monsieur,Female=madame}."
  },
  AvgCommunicate_70512_Content_10 = {
    Text = "La décomposition en ruines de ce monde est quelque chose que vous, gens gâtés, ne comprendrez jamais."
  },
  AvgCommunicate_70512_Content_11 = {
    Text = "La volonté suprême, la Relique originale, apportera une purification ultime au monde."
  },
  AvgCommunicate_70512_Content_12 = {
    Text = "Je n'ai aucune intention de cibler Mythag, mais Mythag bloque le chemin vers l'Arrivée du Nouveau Monde."
  },
  AvgCommunicate_70512_Content_13 = {
    Text = "Soyez rassuré, {Male=Mr.,Female=Miss} Gardien, mon Seigneur ne vous abandonnera pas pour cela."
