  },
  AvgCommunicate_70512_Content_3 = {
    Text = "À Lemwashi, je te l'ai déjà dit."
  },
  AvgCommunicate_70512_Content_4 = {
    Text = "Notre Dieu créera un avenir meilleur pour le monde."
  },
  AvgCommunicate_70512_Content_5 = {
    Text = "Vous vous souvenez, Gardien ?"
  },
  AvgCommunicate_70512_Content_6 = {
    Text = "Bien sûr, je n'oublierai pas cette information importante."
  },
  AvgCommunicate_70512_Content_7 = {
    Text = "Quel rapport cela a-t-il avec Mythag ?"
  },
  AvgCommunicate_70512_Content_8 = {
    Text = "Je ne me rappelle pas des mots séduisants de l'ennemi."
  },
  AvgCommunicate_70512_Content_9 = {
    Text = "J'ai vu beaucoup de gens désespérément têtus, et je ne suis pas surpris."
