  AvgCommunicate_70512_Option_17 = {
    Text = "Je t'arrêterai."
  },
  AvgCommunicate_70512_Option_2 = {
    Text = "Que voulez-vous faire ?!"
  },
  AvgCommunicate_70512_Option_6 = {
    Text = "Je me souviens"
  },
  AvgCommunicate_70512_Option_8 = {
    Text = "Je ne me rappelle pas des mots insidieux de l'ennemi"
  },
  AvgCommunicate_70513_Content_1 = {
    Text = "Je suis allé enquêter sur le son de la flûte que vous avez entendue pendant que vous étiez inconscient."
