  AvgCommunicate_70515_Content_1 = {
    Text = "Je viens de jeter un coup d'œil autour du musée de cire... C'est vraiment le désordre."
  },
  AvgCommunicate_70515_Content_10 = {
    Text = "Pour éviter ces chiens fous du Comité, je n'ai pas joué à mon jeu depuis longtemps..."
  },
  AvgCommunicate_70515_Content_11 = {
    Text = "Vous pourriez envisager de vous rendre à Mythag avec Rogers."
  },
  AvgCommunicate_70515_Content_12 = {
    Text = "Vous devriez connaître les conséquences d'être attrapé par le Comité."
  },
  AvgCommunicate_70515_Content_13 = {
    Text = "Votre bouche sait vraiment comment tromper, chérie."
  },
  AvgCommunicate_70515_Content_14 = {
    Text = "Cependant, j'ai passé un bon moment à jouer avec vous tous au musée de cire."
  },
  AvgCommunicate_70515_Content_15 = {
    Text = "Peut-être que je vais y réfléchir sérieusement."
  },
  AvgCommunicate_70515_Content_16 = {
    Text = "Peut-être qu'un jour nous nous reverrons. J'ai hâte d'y être, {Male=Mr.,Female=Miss} Gardien～"
  },
  AvgCommunicate_70515_Content_2 = {
    Text = "Vous ne savez vraiment pas comment chérir !"
  },
  AvgCommunicate_70515_Content_3 = {Text = "Pandia ?"},
  AvgCommunicate_70515_Content_4 = {
    Text = "Où êtes-vous partis, vous et Rogers ?"
  },
  AvgCommunicate_70515_Content_5 = {
