  },
  AvgCommunicate_70516_Content_13 = {
    Text = "Votre situation est la plus périlleuse en ce moment ; vous devez faire attention, %player%..."
  },
  AvgCommunicate_70516_Content_2 = {
    Text = "Ramona ?! Ça va ?"
  },
  AvgCommunicate_70516_Content_3 = {
    Text = "Hmm, je vais bien."
  },
  AvgCommunicate_70516_Content_4 = {
    Text = "Je viens de croiser quelques membres du Comité et j'ai déjà réglé ça."
  },
  AvgCommunicate_70516_Content_5 = {
    Text = "Je voulais venir et vous rejoindre, mais j'ai vu un groupe de membres du Comité se diriger vers le bâtiment d'enseignement..."
  },
  AvgCommunicate_70516_Content_6 = {
    Text = "De nombreux enseignants et étudiants sont en cours là-bas ; je crains que les gens du Comité ne leur fassent du mal."
