  AvgCommunicate_70516_Content_8 = {
    Text = "Je viens de confronter Clementine ; je vais m'occuper des choses ici."
  },
  AvgCommunicate_70516_Content_9 = {
    Text = "Je te laisse le bâtiment de l'enseignement."
  },
  AvgCommunicate_70516_Option_2 = {
    Text = "Ramona ?! Ça va ?"
  },
  AvgCommunicate_70516_Option_8 = {
    Text = "Prends soin de toi, Ramona !"
  },
  AvgCommunicate_70517_Content_1 = {
    Text = "Désolé. Pédant. Manquant de la passion que la vie devrait avoir..."
