  AvgCommunicate_70517_Content_14 = {
    Text = "On dirait que vous avez mal compris ma question..."
  },
  AvgCommunicate_70517_Content_15 = {
    Text = "Il n'importe pas. Demain soir, je vais organiser un banquet dans la salle."
  },
  AvgCommunicate_70517_Content_16 = {
    Text = "Un banquet passionnant, nouveau et véritablement vibrant, débordant de la vitalité de la vie, tout comme ceux dans un ancien château."
  },
  AvgCommunicate_70517_Content_17 = {
    Text = "Les articles à préparer sont désormais entièrement prêts."
  },
  AvgCommunicate_70517_Content_18 = {
    Text = "J'ai déjà contourné les obstacles que posent les règles à l'avance. Personne ne nous dérangera."
  },
  AvgCommunicate_70517_Content_19 = {
    Text = "Peux-tu trouver le chemin vers le hall, Gardien ?"
  },
  AvgCommunicate_70517_Content_2 = {
    Text = "De quoi parles-tu..."
  },
  AvgCommunicate_70517_Content_3 = {
    Text = "Je veux dire, nous n'avons pas organisé de banquet depuis longtemps."
  },
  AvgCommunicate_70517_Content_4 = {
    Text = "N'y avait-il pas un dîner dans le hall le week-end dernier ?"
  },
  AvgCommunicate_70517_Content_5 = {
    Text = "Un groupe d'individus bien habillés assis ensemble, maintenant une distance sociale polie, se comportant courtoisement, tout en veillant toujours à dissimuler les pensées sordides dans leurs cœurs..."
  },
  AvgCommunicate_70517_Content_6 = {
    Text = "Cette activité sociale épuisante ne peut pas être qualifiée de banquet."
