  AvgCommunicate_70517_Content_8 = {
    Text = "Madame Wanda, après tout, c'est Londinium, pas votre château..."
  },
  AvgCommunicate_70517_Content_9 = {
    Text = "Certaines des règles les plus élémentaires sont encore celles que nous devons respecter..."
