  AvgCommunicate_70522_Content_1 = {
    Text = "Plusieurs consolidations foncières au sein de Londinium se déroulent sans accroc, et ces contrats problématiques ont été résolus."
  },
  AvgCommunicate_70522_Content_10 = {
    Text = "Quoi ? Le Gardien de Mythag, pourrait-il être une personne qui rompt sa parole ?"
