  },
  AvgCommunicate_70522_Content_4 = {
    Text = "Quand tu as un peu de temps libre, viens prendre un verre avec moi ?"
  },
  AvgCommunicate_70522_Content_5 = {
    Text = "Il est interdit aux étudiants de Mythag de boire..."
  },
  AvgCommunicate_70522_Content_6 = {
    Text = "Est-ce que c'est ça ? Le professeur Dexter ne m'a pas dit cela de cette façon."
  },
  AvgCommunicate_70522_Content_7 = {
    Text = "Qui a établi cette règle ? Elle doit être changée."
  },
  AvgCommunicate_70522_Content_8 = {Text = "Ah, ça..."},
  AvgCommunicate_70522_Content_9 = {
    Text = "Vous me devez encore un verre. Vous vous souvenez ?"
  },
  AvgCommunicate_70522_Option_11 = {
    Text = "Certainement pas ! C'est juste..."
  },
  AvgCommunicate_70522_Option_16 = {
    Text = "C'est mon honneur, Dame Sorel."
  },
  AvgCommunicate_70522_Option_5 = {
    Text = "Il est interdit aux étudiants de Mythag de boire..."
  },
  AvgCommunicate_70523_Content_1 = {
    Text = "Dans la précipitation, je n'ai pas eu l'occasion de vous présenter les coutumes et la culture locales."
  },
  AvgCommunicate_70523_Content_10 = {
    Text = "Comme je l'ai mentionné auparavant, je ne suis qu'un messager proclamant les enseignements de mon Seigneur."
  },
  AvgCommunicate_70523_Content_11 = {
    Text = "Notre Dieu créera un avenir meilleur pour le monde."
  },
  AvgCommunicate_70523_Content_12 = {
    Text = "Des groupes primitifs comme l'Aram font également partie de cet avenir et restent nos amis les plus loyaux."
  },
  AvgCommunicate_70523_Content_13 = {
    Text = "Bien sûr, je comprends aussi les doutes du {Male=Mr.,Female=Miss} Gardien."
  },
  AvgCommunicate_70523_Content_14 = {
    Text = "Je crois que tant que nous passons un peu plus de temps ensemble, ces doutes disparaîtront naturellement."
  },
  AvgCommunicate_70523_Content_15 = {
    Text = "Tout le monde a parcouru un long chemin, veuillez bien vous reposer."
  },
  AvgCommunicate_70523_Content_16 = {
    Text = "Je vous souhaite la bienvenue au nom de Lemwahi, Gardien du Secret {Male=monsieur,Female=madame}."
  },
  AvgCommunicate_70523_Content_2 = {
    Text = "Je me demande si le {Male=Mr.,Female=Miss} Gardien a des questions à me poser ?"
  },
  AvgCommunicate_70523_Content_3 = {
    Text = "Je suis un peu curieux des coutumes ici."
  },
  AvgCommunicate_70523_Content_4 = {
    Text = "Bien que les gens d'Aram vivent de l'élevage depuis des générations, loin de la société industrielle, ne les considérez pas comme des tribus barbares non civilisées."
  },
  AvgCommunicate_70523_Content_5 = {
    Text = "Il n'y a pas de règles ici ; sentez-vous libre d'interagir avec eux."
  },
  AvgCommunicate_70523_Content_6 = {
    Text = "L'enthousiasme du peuple Aram, que tout le monde pourra bientôt ressentir."
  },
  AvgCommunicate_70523_Content_7 = {
    Text = "C'est assez étrange qu'une personne comme Juliette existe dans une tribu aussi primitive, n'est-ce pas ?"
  },
  AvgCommunicate_70523_Content_8 = {
    Text = "Guidée par les rêves pour mener Arlan, cette raison semble un peu tirée par les cheveux."
  },
  AvgCommunicate_70523_Content_9 = {
    Text = "{Male=Mr.,Female=Miss} Gardien, veuillez ne pas trop y réfléchir."
  },
  AvgCommunicate_70523_Option_3 = {
    Text = "Je suis un peu curieux des coutumes ici."
  },
  AvgCommunicate_70523_Option_7 = {
    Text = "Je suis très curieux au sujet de la messagère Juliette."
  },
  AvgCommunicate_70524_Content_1 = {
    Text = "En parlant de cela, cela fait longtemps que nous n'avons pas collaboré depuis le musée de cire."
  },
  AvgCommunicate_70524_Content_10 = {
    Text = "J'espère que cette collaboration se déroulera sans accroc."
  },
  AvgCommunicate_70524_Content_11 = {
    Text = "Avec l'aide de Senior William, cela se déroulera certainement sans accroc !"
  },
  AvgCommunicate_70524_Content_2 = {
    Text = "Senior William a également beaucoup aidé lors du dernier incident impliquant le Marin !"
  },
  AvgCommunicate_70524_Content_3 = {
    Text = "...C'était juste de la conduite, rien de particulièrement utile à cela."
  },
  AvgCommunicate_70524_Content_4 = {
    Text = "Après tout, assigner deux atouts à la même mission semble un peu gaspilleur."
  },
  AvgCommunicate_70524_Content_5 = {Text = "新增"},
  AvgCommunicate_70524_Content_6 = {
    Text = "Vous ne vous souciez vraiment pas de l'embarras de dire cela."
  },
  AvgCommunicate_70524_Content_7 = {
    Text = "Vous m'avez sauvé une fois au musée de cire. Je vais rembourser cette dette de gratitude."
  },
  AvgCommunicate_70524_Content_8 = {
    Text = "Pour cette tâche, toi et Ramona êtes à découvert, ce qui rend inconvenant de faire certaines choses."
  },
  AvgCommunicate_70524_Content_9 = {
    Text = "Je gérerai l'enquête dans l'ombre."
  },
  AvgCommunicate_70524_Option_11 = {
    Text = "Certainement !"
  },
  AvgCommunicate_70524_Option_2 = {
    Text = "La dernière fois, avec le Marin, le Senior William a beaucoup aidé."
  },
  AvgCommunicate_70524_Option_4 = {
    Text = "Après tout, assigner deux atouts à la même mission est un peu gaspilleur."
  },
  AvgCommunicate_70525_Content_1 = {
    Text = "Ding ding ding !"
  },
  AvgCommunicate_70525_Content_10 = {
    Text = "Je vois. Ça marche aussi."
  },
  AvgCommunicate_70525_Content_11 = {
    Text = "J'espère qu'à ce moment, tu pourras montrer un peu de respect pour la performance et éviter de parler de quelque chose comme \"la fille vécut heureuse avec sa mère à partir de ce moment-là\" !"
  },
  AvgCommunicate_70525_Content_2 = {
    Text = "Alors, Gardien, es-tu émerveillé par la mise en scène d’Andy Johnson !"
  },
  AvgCommunicate_70525_Content_3 = {
    Text = "Lorsque le grand réalisateur devient vraiment accro..."
  },
  AvgCommunicate_70525_Content_4 = {
    Text = "Cependant, la scène que vous avez arrangée est vraiment impressionnante."
  },
  AvgCommunicate_70525_Content_5 = {
    Text = "La programmation de la performance est également bien exécutée."
  },
  AvgCommunicate_70525_Content_6 = {
    Text = "Nous préparons le prochain projet."
  },
  AvgCommunicate_70525_Content_7 = {
    Text = "Alors, le décor et le réalisateur du prochain épisode dépendent de toi !"
  },
  AvgCommunicate_70525_Content_8 = {
    Text = "Quoi ? Cela n'inclut-il pas le scénariste ?"
  },
  AvgCommunicate_70525_Content_9 = {
    Text = "Heu, Jenkin a quelques petites pensées sur l'histoire du Vagabond Nocturne..."
  },
  AvgCommunicate_70525_Option_3 = {
    Text = "En effet, plutôt bon !"
  },
  AvgCommunicate_70525_Option_6 = {
    Text = "Le prochain travail dépendra de toi !"
  },
  AvgCommunicate_70525_Option_9 = {
    Text = "Jenkin a quelques pensées sur l'histoire de l'Éternel Ranger de la Nuit..."
  },
  AvgCommunicate_70526_Content_1 = {
    Text = "Ma collaboration avec Herbert a pris fin."
  },
  AvgCommunicate_70526_Content_10 = {
    Text = "En bref, je veux voir un monde plus vaste."
  },
  AvgCommunicate_70526_Content_11 = {
    Text = "Lotan m'a vaincu trois fois. Je me demande, qu'est-ce qui, au-delà de la haine, peut conférer à quelqu'un un tel pouvoir immense."
  },
  AvgCommunicate_70526_Content_12 = {
    Text = "Après avoir trouvé la réponse, je reviendrai."
  },
  AvgCommunicate_70526_Content_13 = {
    Text = "D'ici là, j'espère que toi et Lotan serez prêts à être mes adversaires une fois de plus."
  },
  AvgCommunicate_70526_Content_14 = {
    Text = "Tant que tu n'es plus un ennemi, que ce soit en tant qu'adversaire ou coéquipier, tu es le bienvenu."
  },
  AvgCommunicate_70526_Content_15 = {
    Text = "Je vais transmettre cela à Lotan. Je pense qu'elle serait très impatiente de voir le nouveau vous."
  },
  AvgCommunicate_70526_Content_16 = {
    Text = "Le navire a pris la mer."
  },
  AvgCommunicate_70526_Content_17 = {
    Text = "Nous aurons un jour pour nous retrouver. Adieu, Hilote."
  },
  AvgCommunicate_70526_Content_2 = {
    Text = "Je ne m'opposerai plus à vous. C'est ma promesse."
  },
  AvgCommunicate_70526_Content_3 = {
    Text = "Après cette bataille, tu as simplement disparu sans laisser de trace..."
  },
  AvgCommunicate_70526_Content_4 = {
    Text = "Herbert est notre ennemi commun, et nous sommes plus que disposés à transformer des ennemis en amis avec vous."
  },
  AvgCommunicate_70526_Content_5 = {
    Text = "Si vous souhaitez venir, Mythag vous accueille à tout moment."
  },
  AvgCommunicate_70526_Content_6 = {
    Text = "Je vous remercie. Mais je me prépare à partir."
  },
  AvgCommunicate_70526_Content_7 = {
    Text = "Partir ? Où vas-tu ?"
  },
  AvgCommunicate_70526_Content_8 = {
    Text = "Flou. Peut-être est-ce une certaine mer."
  },
  AvgCommunicate_70526_Content_9 = {
    Text = "Peut-être que c'est une certaine montagne. J'entends toujours son appel."
  },
  AvgCommunicate_70526_Option_14 = {
    Text = "Je le transmettrai à elle"
  },
  AvgCommunicate_70526_Option_17 = {
    Text = "Adieu, Hilote."
  },
  AvgCommunicate_70526_Option_3 = {
    Text = "Vous pourriez envisager de venir à Mythag."
  },
  AvgCommunicate_70526_Option_7 = {
    Text = "Où vas-tu ?"
  },
  AvgCommunicate_70527_Content_1 = {
    Text = "Aurita a montré à Lily la méduse qu'elle avait élevée."
  },
  AvgCommunicate_70527_Content_10 = {
    Text = "Parce qu'elle a réalisé son plus grand souhait — te laisser mener une vie heureuse."
  },
  AvgCommunicate_70527_Content_11 = {
    Text = "Lily veut voir sa mère sourire comme ça."
  },
  AvgCommunicate_70527_Content_12 = {
    Text = "Pour rendre Mère heureuse, Lily continuera d'être joyeuse !"
  },
  AvgCommunicate_70527_Content_13 = {
    Text = "C'est exact !"
  },
  AvgCommunicate_70527_Content_14 = {
    Text = "Lily veut-elle encore prendre le métro ? Si oui, je peux l'y amener tout de suite."
  },
  AvgCommunicate_70527_Content_15 = {
    Text = "Vraiment ?! Merci, Maître !"
  },
  AvgCommunicate_70527_Content_2 = {
    Text = "Jenkin a emmené Lily grimper au clocher."
  },
  AvgCommunicate_70527_Content_3 = {
    Text = "Sister Ramona brought Lily a great deal of delicious food... -> Soeur Ramona a apporté à Lily beaucoup de nourriture délicieuse..."
  },
  AvgCommunicate_70527_Content_4 = {
    Text = "Lily, comment te sens-tu maintenant ? Ça va mieux ?"
  },
  AvgCommunicate_70527_Content_5 = {
    Text = "...D'accord !"
  },
  AvgCommunicate_70527_Content_6 = {
    Text = "Lily a rêvé la nuit dernière, rêvant de sa mère..."
  },
  AvgCommunicate_70527_Content_7 = {
    Text = "Mère dit qu'elle me regarde."
  },
  AvgCommunicate_70527_Content_8 = {
    Text = "Me voir heureux rend aussi Mère heureuse."
  },
  AvgCommunicate_70527_Content_9 = {
    Text = "Mère sourit. Lily n'a pas vu sa mère sourire comme ça depuis longtemps."
  },
  AvgCommunicate_70527_Option_10 = {
    Text = "Parce qu'elle a réalisé son souhait"
  },
  AvgCommunicate_70527_Option_14 = {
    Text = "Voulez-vous toujours prendre le métro ?"
  },
  AvgCommunicate_70527_Option_4 = {
    Text = "Lily, comment te sens-tu maintenant ?"
  },
  AvgCommunicate_70528_Content_1 = {
    Text = "Depuis mon retour, j'ai également exploré quelques nouvelles possibilités."
  },
  AvgCommunicate_70528_Content_10 = {
    Text = "Survis, Gardien... avec Ramona, trouve un moyen de lutter contre la Dissolution."
  },
  AvgCommunicate_70528_Content_11 = {
    Text = "S'il y a quelque chose que vous avez besoin que je fasse, n'hésitez pas à me le faire savoir."
  },
  AvgCommunicate_70528_Content_12 = {
    Text = "Ne laisse pas ce monde devenir comme le mien."
  },
  AvgCommunicate_70528_Content_13 = {
    Text = "C'est mon seul espoir, et seul toi peux le réaliser."
  },
  AvgCommunicate_70528_Content_2 = {
    Text = "Sans exception, tous ces choix sont mauvais."
  },
  AvgCommunicate_70528_Content_3 = {
    Text = "Vous êtes sur le seul chemin correct, Gardien."
  },
  AvgCommunicate_70528_Content_4 = {
    Text = "Merci pour votre travail acharné, Ramona..."
  },
  AvgCommunicate_70528_Content_5 = {
    Text = "La situation de votre côté s'améliore-t-elle maintenant ?"
  },
  AvgCommunicate_70528_Content_6 = {
    Text = "Toujours le même... Tout est submergé dans la Dissolution, le seul refuge restant."
  },
  AvgCommunicate_70528_Content_7 = {
    Text = "Le professeur Alistair maintient cet endroit, et son état n'est pas bon non plus..."
  },
  AvgCommunicate_70528_Content_8 = {
    Text = "Ramona... y a-t-il quelque chose que je puisse faire pour toi ?"
  },
  AvgCommunicate_70528_Content_9 = {
    Text = "C'est bon. Nous nous sommes déjà habitués à cela."
  },
  AvgCommunicate_70528_Option_4 = {
    Text = "Merci pour votre travail acharné, Ramona..."
  },
  AvgCommunicate_70528_Option_8 = {
    Text = "Y a-t-il quelque chose que je peux faire pour vous ?"
  },
  AvgCommunicate_70529_Content_1 = {
    Text = "Bonjour, Gardien {Male=Mr.,Female=Miss}."
  },
  AvgCommunicate_70529_Content_10 = {
    Text = "Bien sûr. À cet instant précis, l'état d'un patient s'est soudainement détérioré, et je dois m'en occuper immédiatement."
  },
  AvgCommunicate_70529_Content_11 = {
    Text = "Merci d'avoir ramené Lily à la maison. Le salon et les rafraîchissements ont été préparés pour tout le monde."
  },
  AvgCommunicate_70529_Content_12 = {
    Text = "Bienvenue au Sanatorium Rye, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgCommunicate_70529_Content_2 = {
    Text = "C'est grâce à Madame Davincity que Missaga m'a transmis vos coordonnées."
  },
  AvgCommunicate_70529_Content_3 = {
    Text = "Puis-je demander, où êtes-vous tous avec Lily ?"
  },
  AvgCommunicate_70529_Content_4 = {
    Text = "Nous sommes arrivés au Pont en Acier Fowler et atteindrons bientôt le sanatorium."
  },
  AvgCommunicate_70529_Content_5 = {
    Text = "Est-ce que Lily a causé des problèmes à tout le monde durant ce voyage ?"
  },
  AvgCommunicate_70529_Content_6 = {
    Text = "Veuillez ne pas vous inquiéter ; Lily a toujours été très obéissante."
  },
  AvgCommunicate_70529_Content_7 = {
    Text = "Mademoiselle Francis, concernant le sanatorium, j'aimerais..."
  },
  AvgCommunicate_70529_Content_8 = {
    Text = "Désolé, Gardien. L'état d'un patient s'est soudainement aggravé, je dois m'en occuper immédiatement."
  },
  AvgCommunicate_70529_Content_9 = {
    Text = "Alors, devons-nous nous rencontrer au sanatorium ?"
  },
  AvgCommunicate_70529_Option_4 = {
    Text = "C'est presque ici."
  },
  AvgCommunicate_70529_Option_6 = {
    Text = "Lily est très obéissante."
  },
  AvgCommunicate_70529_Option_7 = {
    Text = "Demandez à Francis au sujet des anomalies au sanatorium"
  },
  AvgCommunicate_70529_Option_9 = {
    Text = "Endurez pour l'instant, afin de ne pas éveiller son alerte."
  },
  AvgCommunicate_70530_Content_1 = {
    Text = "Ma précieuse Graine a été rejetée... C'est vraiment triste, {Male=Mr.,Female=Miss} Gardien."
  },
  AvgCommunicate_70530_Content_10 = {
    Text = "Plus quelque chose est précieux, plus elle doit être accueillie avec une cérémonie solennelle."
  },
  AvgCommunicate_70530_Content_11 = {
    Text = "Cette graine des plus précieuses appartiendra, tôt ou tard, à vous."
  },
  AvgCommunicate_70530_Content_12 = {
    Text = "Ne t'inquiète pas, Gardien. Ce jour-là ne te fera pas attendre longtemps."
  },
  AvgCommunicate_70530_Content_2 = {
    Text = "Thais, ce n'est pas ce que je voulais dire..."
  },
  AvgCommunicate_70530_Content_3 = {
    Text = "Oh ? Que veut dire le Gardien alors ?"
  },
  AvgCommunicate_70530_Content_4 = {Text = "Je..."},
  AvgCommunicate_70530_Content_5 = {
    Text = "Je suis désolé, mais la situation à l'époque était juste trop précipitée. Je n'avais pas le temps de réfléchir..."
  },
  AvgCommunicate_70530_Content_6 = {
    Text = "Alors, que se passe-t-il si la situation n'est pas urgente ?"
  },
  AvgCommunicate_70530_Content_7 = {Text = "Je..."},
  AvgCommunicate_70530_Content_8 = {
    Text = "D'accord, d'accord, je ne vais plus te taquiner."
  },
  AvgCommunicate_70530_Content_9 = {
    Text = "Je comprends, Gardien."
  },
  AvgCommunicate_70530_Option_2 = {
    Text = "Thais, ce n'est pas ce que je voulais dire..."
  },
  AvgCommunicate_70530_Option_5 = {
    Text = "Je suis désolé, mais la situation à l'époque était juste trop précipitée..."
  },
  AvgCommunicate_70531_Content_1 = {
    Text = "Gardien, puis-je demander"
  },
  AvgCommunicate_70531_Content_10 = {
    Text = "Bienvenue à Mythag."
  },
  AvgCommunicate_70531_Content_11 = {
    Text = "...Hannah est venue me voir juste maintenant."
  },
  AvgCommunicate_70531_Content_12 = {
    Text = "La création de l'Éveilleur de Jenkin a été réussie."
  },
  AvgCommunicate_70531_Content_13 = {Text = "!!!"},
  AvgCommunicate_70531_Content_14 = {
    Text = "Allons-y et rencontrons notre petit héros."
  },
  AvgCommunicate_70531_Content_2 = {
    Text = "Comment progresse l'éveil de Jenkin ?"
  },
  AvgCommunicate_70531_Content_3 = {
    Text = "La bibliothèque de matériaux de l'école a préparé les objets nécessaires pour son Corps, et le processus de création de l'Éveillé est actuellement en cours."
  },
  AvgCommunicate_70531_Content_4 = {
    Text = "Bientôt, nous pourrons la voir à nouveau !"
  },
  AvgCommunicate_70531_Content_5 = {
    Text = "Excellent ! Excellent..."
  },
  AvgCommunicate_70531_Content_6 = {
    Text = "Merci, Gardien. Merci à vous tous..."
  },
  AvgCommunicate_70531_Content_7 = {
    Text = "Vous et Jenkin nous avez sauvés."
  },
  AvgCommunicate_70531_Content_8 = {
    Text = "Elle est morte pour sauver Mythag ; c'est ce que nous devons faire."
  },
  AvgCommunicate_70531_Content_9 = {
    Text = "Le comité de l'école a discuté et approuvé, donc vous deux n'avez plus à vous inquiéter d'être laissés derrière."
  },
  AvgCommunicate_70531_Option_11 = {
    Text = "J'ai reçu un message..."
  },
  AvgCommunicate_70531_Option_3 = {
    Text = "Presque là"
  },
  AvgCommunicate_70531_Option_7 = {
    Text = "Nous devrions te remercier, ainsi que Jenkin."
  },
  AvgCommunicate_70532_Content_1 = {Text = "Gardien !"},
  AvgCommunicate_70532_Content_2 = {
    Text = "Quand allons-nous filmer de nouveau !"
  },
  AvgCommunicate_70532_Content_3 = {
    Text = "Quoi, es-tu devenu accro aux applaudissements ?"
  },
  AvgCommunicate_70532_Content_4 = {
    Text = "Ce n'est pas que je sois accro ; c'est que cette ville a besoin de nous !"
  },
  AvgCommunicate_70532_Content_5 = {
    Text = "Cette ville est pleine des plus affamés, ayant besoin des Rôdeurs de la Nuit et de leurs assistants !"
  },
  AvgCommunicate_70532_Content_6 = {
    Text = "Je demanderai à Poupée si je peux emprunter la caméra à nouveau."
  },
  AvgCommunicate_70532_Content_7 = {
    Text = "Au fait, as-tu correctement assisté aux cours d'alphabétisation ? Combien de fautes as-tu faites !"
  },
  AvgCommunicate_70532_Content_8 = {
    Text = "Mêle-toi de tes affaires, gars du Westside !"
  },
  AvgCommunicate_70532_Content_9 = {
    Text = "Cette ville a besoin de nous ; les Errants de la Nuit et leur assistant sont extrêmement occupés !"
  },
  AvgCommunicate_70532_Option_3 = {
    Text = "Accro aux photos?"
  },
  AvgCommunicate_70532_Option_6 = {
    Text = "Laisse-moi aller demander à la Poupée..."
  },
  AvgCommunicate_70533_Content_1 = {
    Text = "Gardien, Gardien !"
  },
  AvgCommunicate_70533_Content_10 = {
    Text = "Mais pourquoi Aurita ne s'en souvient-elle pas ?"
  },
  AvgCommunicate_70533_Content_11 = {
    Text = "Chiot, Poney, Petite Méduse... Ils étaient tous autrefois des amis d'Aurita."
  },
  AvgCommunicate_70533_Content_12 = {
    Text = "Plus tard, ils doivent aller dans un endroit éloigné."
  },
  AvgCommunicate_70533_Content_13 = {
    Text = "Ils avaient peur de causer de la douleur à Aurita, alors ils effacèrent les souvenirs d'Aurita à leur sujet."
  },
  AvgCommunicate_70533_Content_14 = {
    Text = "Mais ils souhaitaient toujours rester aux côtés d'Aurita, alors ils ont laissé leurs corps derrière."
  },
  AvgCommunicate_70533_Content_15 = {
    Text = "Ces corps se sont transformés en petites poupées en argile et ont été laissés dans le Palais de l'Eau d'Aurita."
  },
  AvgCommunicate_70533_Content_16 = {
    Text = "...Ils ont toujours pris soin et accompagné Aurita, et cela n'a jamais changé."
  },
  AvgCommunicate_70533_Content_17 = {
    Text = "Il semble que je comprenne, pourtant j'ai aussi l'impression de ne pas..."
  },
  AvgCommunicate_70533_Content_18 = {
    Text = "Mais, Aurita le sait ! Ceux du Palais des Eaux sont tous de bons amis d'Aurita."
  },
  AvgCommunicate_70533_Content_19 = {
    Text = "Aurita s'occupera bien d'eux et jouera avec eux chaque jour !"
  },
  AvgCommunicate_70533_Content_2 = {
    Text = "Tu sais ce qu'il y a à l'intérieur du Palais des Eaux d'Aurita ?"
  },
  AvgCommunicate_70533_Content_3 = {
    Text = "Que pense Aurita de tout cela ?"
  },
