  AvgCommunicate_72037_Content_1 = {
    Text = "Hier, j'ai rêvé de mon enfance et de nombreuses personnes du passé de Limoria."
  },
  AvgCommunicate_72037_Content_10 = {
    Text = "Rien n'échappe à votre attention."
  },
  AvgCommunicate_72037_Content_11 = {
    Text = "Ce qui hantait le rêve était une sensation particulièrement chaleureuse et familière, et j'ai d'abord pensé que c'était Noé qui l'avait apportée."
  },
  AvgCommunicate_72037_Content_12 = {
    Text = "Plus tard, j'ai découvert que, durant ces longues années, ce que j'avais de plus familier n'était plus une personne, mais un objet froid et inanimé."
  },
  AvgCommunicate_72037_Content_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Content_14 = {
    Text = "Retiens ta compassion, j'étais prêt dès le moment où j'ai posé la couronne sur ma tête."
  },
  AvgCommunicate_72037_Content_15 = {
    Text = "Le Roi de Lémurie n'a pas besoin que quelqu'un verse des larmes pour lui."
  },
  AvgCommunicate_72037_Content_16 = {
    Text = "Donc... Roi de Lémurie, es-tu intéressé à goûter à nouveau cette confiserie de riz ? Je pense que le chef de Mythag devrait être capable de la recréer dans une certaine mesure."
  },
  AvgCommunicate_72037_Content_17 = {Text = "新增"},
  AvgCommunicate_72037_Content_18 = {
    Text = "Hmm, tu es plutôt attentionné."
  },
  AvgCommunicate_72037_Content_19 = {
    Text = "Alors, considérez cela comme votre hommage."
  },
  AvgCommunicate_72037_Content_2 = {
    Text = "Ce sont des souvenirs dont je n'aimais jamais parler, mais, dans le rêve d'hier, c'était vous, n'est-ce pas ?"
  },
  AvgCommunicate_72037_Content_3 = {
    Text = "?! Comment le savais-tu ?"
  },
  AvgCommunicate_72037_Content_4 = {
    Text = "Le temps que j'ai passé dans le Rêve dépasse de loin celui dans le monde ordinaire ; remettez-vous en question la perception de quelqu'un qui vit dans un rêve ?"
  },
  AvgCommunicate_72037_Content_5 = {
    Text = "En plus des prophéties, j'ai parfois des rêves comme les gens ordinaires, mais aucun de ces rêves n'est aussi vivant et continu que celui d'hier..."
  },
  AvgCommunicate_72037_Content_6 = {
    Text = "Comme si quelqu'un était assis aux côtés de Yu, revivant avec lui tous les événements passés depuis le début."
  },
  AvgCommunicate_72037_Content_7 = {
    Text = "Ce sentiment de ne pas être seul... c'est plutôt agréable."
  },
  AvgCommunicate_72037_Content_8 = {
    Text = "J'ai effectivement toujours été à tes côtés."
  },
  AvgCommunicate_72037_Content_9 = {
    Text = "Laisse-moi deviner, tu dois posséder la couronne, n'est-ce pas ?"
  },
  AvgCommunicate_72037_Option_10 = {Text = "Oui"},
  AvgCommunicate_72037_Option_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Option_16 = {
    Text = "Alors... pourquoi est–ce que tu..."
  },
  AvgCommunicate_72037_Option_3 = {Text = "?!"},
  AvgCommunicate_72037_Option_8 = {
    Text = "J'ai effectivement toujours été à tes côtés."
  },
  AvgCommunicate_80100_Content_1 = {
    Text = "%player%, si cela vous convient, pourriez-vous venir passer un test psychologique ?"
  },
  AvgCommunicate_80100_Content_10 = {
    Text = "Ramona, Lotan, Ogier... quand je suis seul, leurs figures flottent toujours dans mon esprit."
  },
  AvgCommunicate_80100_Content_11 = {
    Text = "Pas besoin de tenir seul. Quels que soient les soucis et les confusions que vous avez, vous pouvez me les dire."
  },
  AvgCommunicate_80100_Content_12 = {
    Text = "J'ai même préparé du thé chaud et des snacks pour vous, afin que nous puissions discuter tranquillement."
  },
  AvgCommunicate_80100_Content_13 = {
    Text = "...J'y vais maintenant."
  },
  AvgCommunicate_80100_Content_2 = {
    Text = "...Un test psychologique ?"
  },
  AvgCommunicate_80100_Content_3 = {
    Text = "C'est simple, il suffit de dessiner une maison, un arbre et une personne sur une feuille blanche."
  },
  AvgCommunicate_80100_Content_4 = {
    Text = "Croyez-moi, cela ne prendra pas trop de votre temps."
  },
  AvgCommunicate_80100_Content_5 = {
    Text = "...Mais j'ai l'impression que mon esprit est en bonne santé."
  },
  AvgCommunicate_80100_Content_6 = {
    Text = "Le but ultime du test n'est pas de juger la santé mais d'observer les problèmes psychologiques potentiels."
  },
  AvgCommunicate_80100_Content_7 = {
    Text = "%player%, après être venu ici, ressens-tu la solitude ? Tes amis de ce monde te manquent-ils ?"
  },
  AvgCommunicate_80100_Content_8 = {
    Text = "Cette solitude et cet isolement resteront profondément enfouis dans votre cœur et continueront de fermenter avec le temps, produisant des effets inconnus."
  },
  AvgCommunicate_80100_Content_9 = {
    Text = "Peut-être avez-vous raison, ils me manquent vraiment"
  },
  AvgCommunicate_80100_Option_13 = {
    Text = "...J'y vais maintenant."
  },
  AvgCommunicate_80100_Option_2 = {
    Text = "...Un test psychologique ?"
  },
  AvgCommunicate_80100_Option_5 = {
    Text = "...Mais j'ai l'impression que mon esprit est en bonne santé."
  },
  AvgCommunicate_80100_Option_9 = {Text = "新增"},
  AvgCommunicate_80101_Content_1 = {
    Text = "J'ai entendu que tu étais un peu déprimé dernièrement ; si cela ne te dérange pas, tu peux venir me voir pour une consultation."
  },
  AvgCommunicate_80101_Content_10 = {
    Text = "Ah, rien que d'en parler ainsi, mon cœur d'argent tremble sans cesse..."
  },
  AvgCommunicate_80101_Content_11 = {
    Text = "%player%, j'ai hâte de plonger dans ton cœur et de goûter à tes souvenirs."
  },
  AvgCommunicate_80101_Content_12 = {
    Text = "Alors vous serez déçu. Je suis déjà parti."
  },
  AvgCommunicate_80101_Content_13 = {
    Text = "Je sais. Un de mes patients m'a envoyé un message pour m'informer de cette affaire."
  },
  AvgCommunicate_80101_Content_14 = {
    Text = "Elle a même pensé à attacher soigneusement ta position actuelle, alors..."
  },
  AvgCommunicate_80101_Content_15 = {
    Text = "J'y serai bientôt."
  },
  AvgCommunicate_80101_Content_2 = {
    Text = "Pas besoin de se vanter, Gardien. Les suggestions des professionnels peuvent vous aider à ajuster votre stress plus rapidement."
  },
  AvgCommunicate_80101_Content_3 = {
    Text = "Comment pourrais-tu savoir cela...?"
  },
  AvgCommunicate_80101_Content_4 = {Text = "Secret~"},
  AvgCommunicate_80101_Content_5 = {
    Text = "Alors, quelle est ta réponse ?"
  },
  AvgCommunicate_80101_Content_6 = {
    Text = "Je promets cette fois de ne donner aucune autre orientation."
  },
  AvgCommunicate_80101_Content_7 = {
    Text = "Vous avez dit la même chose la dernière fois et la fois d'avant..."
  },
  AvgCommunicate_80101_Content_8 = {
    Text = "Ce n'est pas ma faute, mais plutôt que votre conscience est remplie de souvenirs agréables."
  },
  AvgCommunicate_80101_Content_9 = {
    Text = "Ces souvenirs dépassent de loin la douleur qu'une personne ordinaire peut endurer, et portent l'aura de cette grande existence, qui est la douceur la plus suprême."
  },
  AvgCommunicate_80101_Option_12 = {
    Text = "...Alors tu seras déçu"
  },
  AvgCommunicate_80101_Option_3 = {
    Text = "Comment pourrais-tu savoir cela...?"
  },
  AvgCommunicate_80101_Option_7 = {
    Text = "Vous avez dit la même chose la dernière fois et la fois d'avant..."
  },
  AvgCommunicate_80102_Content_1 = {
    Text = "%player%, si cela ne te dérange pas, puis-je m'occuper de ta psychothérapie ?"
  },
  AvgCommunicate_80102_Content_10 = {
    Text = "Mais je n'adopterai pas de mesures excessives. Crois-moi."
  },
  AvgCommunicate_80102_Content_11 = {
    Text = "……Vraiment ?"
  },
  AvgCommunicate_80102_Content_12 = {
    Text = "Bien sûr. Après tout, je ne suis qu'un psychologue."
  },
  AvgCommunicate_80102_Content_2 = {
    Text = "Je pense que tu as besoin d'un psychologue attitré."
  },
  AvgCommunicate_80102_Content_3 = {
    Text = "……Je ne vois pas l'utilité."
  },
  AvgCommunicate_80102_Content_4 = {
    Text = "Non, en tant que seul Gardien du Secret, ton existence mérite d'être prise au sérieux."
  },
  AvgCommunicate_80102_Content_5 = {
    Text = "Je voulais simplement utiliser mes compétences professionnelles pour t'aider."
  },
  AvgCommunicate_80102_Content_6 = {
    Text = "C'est vraiment comme ça ? Pourquoi ai-je l'impression que tu as un autre but... ?"
  },
  AvgCommunicate_80102_Content_7 = {
    Text = "Par exemple, sous prétexte d'être mon psychologue personnel, espionner mes souvenirs."
  },
  AvgCommunicate_80102_Content_8 = {
    Text = "Ah, je suis découvert ? Puisque c'est ainsi, tant pis."
  },
  AvgCommunicate_80102_Content_9 = {
    Text = "Je suis effectivement très, très intéressé par ta mémoire. Surtout après que tu aies parlé de ce monde."
  },
  AvgCommunicate_80102_Option_11 = {
    Text = "……Vraiment ?"
  },
  AvgCommunicate_80102_Option_3 = {
    Text = "……Je ne pense pas que ce soit nécessaire."
  },
  AvgCommunicate_80102_Option_6 = {
    Text = "……C'est vraiment comme ça ?"
  },
  AvgCommunicate_80104_Content_1 = {
    Text = "Merci de m'avoir envoyé ce rapport."
  },
  AvgCommunicate_80104_Content_10 = {
    Text = "Et il est clair que, pour retourner dans ce monde, la force de moi seul et de Fondu·poupée ne suffirait pas."
  },
  AvgCommunicate_80104_Content_11 = {
    Text = "As-tu besoin de mon pouvoir...? Je comprends."
  },
  AvgCommunicate_80104_Content_12 = {
    Text = "J'ai accepté ce cadeau. Et le cadeau de retour est une consultation psychologique gratuite."
  },
  AvgCommunicate_80104_Content_13 = {
    Text = "%player%, quand as-tu du temps libre ?"
  },
  AvgCommunicate_80104_Content_14 = {
    Text = "Que ce soit en tant que Docteur ou ami, j'ai le devoir de comprendre profondément votre être intérieur."
  },
  AvgCommunicate_80104_Content_15 = {
