  },
  AvgCommunicate_80104_Content_16 = {Text = "%player% ?"},
  AvgCommunicate_80104_Content_17 = {Text = "%player% ?"},
  AvgCommunicate_80104_Content_18 = {
    Text = "Heh, je sais que tu es toujours ici. Mais ça va, nous avons encore beaucoup de temps."
  },
  AvgCommunicate_80104_Content_2 = {
    Text = "C'est un rapport sur les espèces d'insectes, recopié à la main et censuré, sans problèmes de fuite, n'hésitez pas à le garder."
  },
  AvgCommunicate_80104_Content_3 = {
    Text = "Est-ce la \"récompense\" payée à l'avance ?"
