  },
  AvgCommunicate_80104_Content_5 = {
    Text = "Ce n'est pas une récompense, mais un cadeau."
  },
  AvgCommunicate_80104_Content_6 = {
    Text = "Félicitations pour ta renaissance, et merci de m'avoir choisi."
  },
  AvgCommunicate_80104_Content_7 = {
    Text = "Parce que je ne me tiens pas en face de vous comme \"elle\" de ce monde?"
  },
  AvgCommunicate_80104_Content_8 = {
    Text = "Tu peux le penser ainsi"
  },
  AvgCommunicate_80104_Content_9 = {
    Text = "En tant que Gardien, je crois toujours que moi et le Réveil sommes amis, pas ennemis."
  },
  AvgCommunicate_80104_Option_15 = {
    Text = "...Le signal est mauvais"
  },
  AvgCommunicate_80104_Option_2 = {
