  AvgCommunicate_81323_Content_1 = {
    Text = "Mon bienfaiteur, quand me remettras-tu le nouveau manuel ?"
  },
  AvgCommunicate_81323_Content_10 = {
    Text = "Je comprends, alors, le bienfaiteur a-t-il d'autres enseignants compétents dans ces deux matières que vous pouvez recommander ?"
  },
  AvgCommunicate_81323_Content_11 = {
    Text = "Si c'est absolument nécessaire, je peux lire d'autres livres et essayer d'apprendre un peu par moi-même."
  },
  AvgCommunicate_81323_Content_12 = {
    Text = "Il y a... il y en a, mais elle n'a pas très bon caractère."
  },
  AvgCommunicate_81323_Content_13 = {
    Text = "C'est bon, je n'ai pas peur."
  },
  AvgCommunicate_81323_Content_14 = {
    Text = "J'ai peur ! Eh bien, si je vais chercher Bigorneau... euh, elle deviendrait probablement folle en premier."
  },
  AvgCommunicate_81323_Content_15 = {
    Text = "Fou ? Ce Maître Winkle a-t-il une sorte de maladie ?"
  },
  AvgCommunicate_81323_Content_16 = {
    Text = "Non... je ne peux pas dire qu'il n'y en a pas, ah ah ah ! En bref, laissez-moi d'abord vous enseigner une vérité de l'apprentissage !"
  },
  AvgCommunicate_81323_Content_17 = {
    Text = "D'accord, bienfaiteur, je suis tout ouïe."
  },
  AvgCommunicate_81323_Content_18 = {
    Text = "C'est-à-dire, ne posez pas de questions sur tout !!!"
  },
  AvgCommunicate_81323_Content_19 = {
    Text = "Pourquoi cela arrive-t-il encore ? Bienfaiteur, je ne comprends pas tout à fait. Si je ne demande pas clairement, comment puis-je apprendre complètement..."
  },
  AvgCommunicate_81323_Content_2 = {
    Text = "Et concernant les deux derniers livres, je les ai lus soigneusement et j'ai fait un total de 107 notes de questions ; j'espère que le bienfaiteur pourra fournir quelques conseils dans ses moments de libre."
  },
  AvgCommunicate_81323_Content_20 = {
    Text = "N'es-tu pas fatigué ! Avec un esprit aussi diligent entrant dans la mer de la connaissance, tu réussiras tout ce que tu entreprends..."
  },
  AvgCommunicate_81323_Content_21 = {
    Text = "Merci, bienfaiteur. Avoir la liberté d'apprendre ce qui m'intéresse est vraiment une chose précieuse et joyeuse."
  },
  AvgCommunicate_81323_Content_22 = {
    Text = "C'est bien de prendre une pause quand on se sent vraiment somnolent ; comment peut-on être fatigué ?"
  },
  AvgCommunicate_81323_Content_23 = {
    Text = "Alors, quand mon bienfaiteur pourra-t-il me présenter le nouveau professeur ? Je ferai de mon mieux pour ne pas être trop intrusif."
  },
  AvgCommunicate_81323_Content_24 = {
    Text = "Euh... que dirais-je de poser 97 questions ?"
  },
  AvgCommunicate_81323_Content_3 = {Text = "J'ai tort"},
  AvgCommunicate_81323_Content_4 = {
    Text = "J'avais vraiment tort"
  },
  AvgCommunicate_81323_Content_6 = {
    Text = "Je n'aurais pas dû faire vos devoirs pour vous ; on devrait s'occuper de ses propres affaires..."
  },
  AvgCommunicate_81323_Content_7 = {
    Text = "S'il vous plaît, arrêtez de me demander ! Si cela continue, je vais faire des cauchemars la nuit !"
  },
  AvgCommunicate_81323_Content_8 = {
    Text = "Ah... désolé, je ne m'attendais pas à ce que mon intrusion dérange autant mon bienfaiteur ; je suis vraiment trop lent d'esprit."
  },
  AvgCommunicate_81323_Content_9 = {
    Text = "Non, pas du tout, peut-être que je ne suis tout simplement pas fait pour être enseignant..."
  },
  AvgCommunicate_81323_Option_12 = {
    Text = "Il y a... il y en a."
  },
  AvgCommunicate_81323_Option_14 = {
    Text = "J'ai peur !"
  },
  AvgCommunicate_81323_Option_16 = {
    Text = "Non... je ne peux pas dire qu'il n'y en a pas..."
  },
  AvgCommunicate_81323_Option_18 = {
    Text = "C'est-à-dire, ne posez pas de questions sur tout !!!"
  },
  AvgCommunicate_81323_Option_20 = {
    Text = "N'es-tu pas fatigué !"
  },
  AvgCommunicate_81323_Option_3 = {Text = "J'ai tort"},
  AvgCommunicate_81323_Option_4 = {
    Text = "J'avais vraiment tort"
  },
  AvgCommunicate_81323_Option_9 = {
    Text = "Non, pas du tout, peut-être que je ne suis tout simplement pas fait pour être enseignant..."
  },
  AvgCommunicate_81324_Content_1 = {
    Text = "Mon bienfaiteur, j'ai de nouvelles questions depuis que j'ai lu récemment."
  },
  AvgCommunicate_81324_Content_10 = {
    Text = "Veux-tu dire... cela dépend des pensées en faisant cela ?"
  },
  AvgCommunicate_81324_Content_11 = {
    Text = "C'est exact, réfléchis-y, quand je t'ai demandé d'écrire ces deux devoirs, voulais-je t'exploiter pour un travail gratuit, ou espérais-je que tu gagnes une opportunité d'apprentissage ?"
  },
  AvgCommunicate_81324_Content_12 = {
    Text = "Je ne sais pas."
  },
  AvgCommunicate_81324_Content_13 = {
    Text = "Comment cela pourrait-il être inconnu ? Bien sûr, c'est pour t'aider à mieux apprendre les connaissances !"
  },
  AvgCommunicate_81324_Content_14 = {
    Text = "Alors c'est comme ça. J'ai mal compris ; je pensais que le bienfaiteur voulait juste que je vous aide avec vos devoirs."
  },
  AvgCommunicate_81324_Content_16 = {
    Text = "Coup de toussotements... Eh bien, réfléchissons à nouveau. Lorsque nous effectuons une action avec une personne comme but final, en considérant sincèrement l'autre, cela peut être appelé moral."
  },
  AvgCommunicate_81324_Content_17 = {
    Text = "Si vous traitez les humains comme de pures outils, c'est certainement immoral."
  },
  AvgCommunicate_81324_Content_18 = {
    Text = "Je pense que je comprends, c'est comme utiliser une lanterne pour nous traiter, moi et Polyx, comme des outils de sacrifice, sans vraiment tenir compte de nos sentiments. C'est immoral."
  },
  AvgCommunicate_81324_Content_19 = {
    Text = "C'est vrai, c'est vrai, votre perspicacité est formidable !"
  },
  AvgCommunicate_81324_Content_2 = {
    Text = "Vous avez dit auparavant que les missions servent à tester et affiner vos connaissances, tant que la connaissance est maîtrisée, il n'est pas nécessaire d'être entravé par la question de savoir si la mission est complète."
  },
  AvgCommunicate_81324_Content_20 = {
    Text = "Je comprends, bienfaiteur, vous êtes vraiment une personne morale ! Alors, s'il vous plaît, bienfaiteur, donnez-moi quelques missions supplémentaires, je les accomplirai avec soin et reviendrai pour consulter !"
  },
  AvgCommunicate_81324_Content_21 = {
    Text = "Bienfaiteur ?"
  },
  AvgCommunicate_81324_Content_22 = {
    Text = "Eh bien, j'ai soudain quelque chose à faire. Tu devrais directement parler à Poupée au sujet des devoirs !"
  },
  AvgCommunicate_81324_Content_3 = {
    Text = "Euh... il semble que j'ai déjà dit quelque chose comme ça auparavant."
  },
  AvgCommunicate_81324_Content_4 = {
    Text = "Mais les récents livres que j'ai lus mentionnent que faire faire le travail par d'autres semble être un acte contraire à l'éthique."
  },
  AvgCommunicate_81324_Content_6 = {
    Text = "Alors, comment juges-tu si cette affaire est morale ?"
  },
  AvgCommunicate_81324_Content_7 = {
    Text = "Uh... à propos de cette affaire, tu devrais la voir de manière dialectique."
  },
  AvgCommunicate_81324_Content_8 = {
    Text = "Nous ne pouvons pas dire avec certitude oui ou non."
  },
  AvgCommunicate_81324_Content_9 = {
    Text = "Quand vous jugez quelque chose, vous ne pouvez pas juste regarder le résultat, mais aussi considérer le but derrière l'action."
  },
  AvgCommunicate_81324_Option_11 = {
    Text = "Ouais. Exactement!"
  },
  AvgCommunicate_81324_Option_13 = {
    Text = "Comment cela pourrait-il être inconnu ?"
  },
  AvgCommunicate_81324_Option_19 = {
    Text = "C'est vrai, c'est vrai, votre perspicacité est formidable !"
  },
  AvgCommunicate_81324_Option_22 = {
    Text = "Eh bien, j'ai soudain quelque chose à faire..."
  },
  AvgCommunicate_81324_Option_3 = {
    Text = "Euh... il semble que j'ai déjà dit quelque chose comme ça auparavant."
  },
  AvgCommunicate_81324_Option_7 = {
    Text = "Uh... à propos de cette affaire, tu devrais la voir de manière dialectique."
  },
  AvgCommunicate_81324_Option_8 = {
    Text = "Nous ne pouvons pas dire avec certitude oui ou non."
  },
  AvgCommunicate_81325_Content_1 = {
    Text = "Quelle boîte magique, bienfaiteur, n'est-ce pas alimentée par une sorte de magie ou de formation rituelle ?"
  },
  AvgCommunicate_81325_Content_10 = {
    Text = "Ce n'est pas le cas, c'est juste que ces deux sujets sont actuellement également en développement, et de nombreux chercheurs élargiront et approfondiront ces études, créant de nouvelles connaissances."
  },
  AvgCommunicate_81325_Content_11 = {
    Text = "Si vous prenez cette discipline florissante comme votre objectif d'apprentissage, bien sûr, vous devriez apprendre jusqu'à que vous vieillissiez."
  },
  AvgCommunicate_81325_Content_12 = {
    Text = "Alors c'est ça, une connaissance qui continue à se développer... vraiment magnifique."
  },
  AvgCommunicate_81325_Content_13 = {
    Text = "Quand nous étudions les écritures de la lanterne, nous ne pouvons pas changer un seul mot ; tout le contenu est sécurisé, répété et reste inchangé."
  },
  AvgCommunicate_81325_Content_14 = {
    Text = "Mais chaque fois que j'étudie les Écritures, je ressens un sentiment d'être dans une boîte, regardant la fin d'un coup d'œil."
  },
  AvgCommunicate_81325_Content_15 = {
    Text = "En effet, seule la connaissance en constante croissance correspond à la véritable essence de la vie !"
  },
  AvgCommunicate_81325_Content_16 = {
    Text = "Sentir soudainement la transcendance..."
  },
  AvgCommunicate_81325_Content_17 = {
    Text = "À propos, j'ai une excellente opportunité d'apprentissage que je peux généreusement te donner gratuitement."
  },
  AvgCommunicate_81325_Content_18 = {
    Text = "Vraiment, bienfaiteur ! Ma gratitude dépasse les mots."
  },
  AvgCommunicate_81325_Content_19 = {
    Text = "Bien sûr, c'est vrai, cet exercice de technologie argentée et ce principe de maintenance, ainsi que ce manuel obligatoire pour les stratégies psychologiques des enquêteurs, lequel aimeriez-vous écrire en premier..."
  },
  AvgCommunicate_81325_Content_2 = {
    Text = "Non, c'est de la technologie de copeaux d'argent pure, et juste pour vous rappeler, le communicateur est cher, donc je vous suggère de ne pas le démonter imprudemment."
  },
  AvgCommunicate_81325_Content_20 = {
    Text = "Ah non, par lequel devrais-je commencer à apprendre ?"
  },
  AvgCommunicate_81325_Content_3 = {
    Text = "Ah, quel dommage... comment le bienfaiteur savait-il que j'étais sur le point de le démonter ? Est-ce de la lecture d'esprit ?"
  },
  AvgCommunicate_81325_Content_4 = {
    Text = "Pas vraiment... Je suppose que tes pensées ne s'appliquent même pas à la psychologie !"
  },
  AvgCommunicate_81325_Content_5 = {
    Text = "La psychologie doit être une autre connaissance profonde ; malheureusement, ma compréhension est en effet stérile..."
  },
  AvgCommunicate_81325_Content_6 = {
    Text = "Mon bienfaiteur, combien de temps faut-il pour apprendre cette technologie de puce argentée et la psychologie ?"
  },
  AvgCommunicate_81325_Content_7 = {
    Text = "Apprendre ? Hmm..."
  },
  AvgCommunicate_81325_Content_8 = {
    Text = "Il faut quatre à cinq ans pour obtenir l'entrée, et l'apprendre peut prendre toute une vie d'étude."
  },
  AvgCommunicate_81325_Content_9 = {
    Text = "Une vie ! Pourrait-il vraiment y avoir des milliers de ces volumes de Connaissance ?"
  },
  AvgCommunicate_81325_Option_10 = {
    Text = "Ce n'est pas le cas..."
  },
  AvgCommunicate_81325_Option_16 = {
    Text = "Sentir soudainement la transcendance..."
  },
  AvgCommunicate_81325_Option_19 = {
    Text = "Bien sûr, c'est vrai."
  },
  AvgCommunicate_81325_Option_2 = {Text = "Non"},
  AvgCommunicate_81325_Option_4 = {
    Text = "Pas vraiment..."
  },
  AvgCommunicate_81325_Option_7 = {
    Text = "Apprendre ? Hmm..."
  },
  AvgCommunicate_84107_Content_1 = {
    Text = "Quand se termine cette période de vacances ?"
  },
  AvgCommunicate_84107_Content_10 = {
    Text = "Ces facteurs combinés permettent, après avoir pesé le pour et le contre, de planifier un itinéraire aussi efficace et rationnel que possible."
  },
  AvgCommunicate_84107_Content_11 = {
    Text = "……J'ai compris. Il semble que chaque travail ait sa raison d'être."
  },
  AvgCommunicate_84107_Content_12 = {
    Text = "Oui, puisque j'ai fait mon choix, je dois assumer mes responsabilités."
  },
  AvgCommunicate_84107_Content_13 = {
    Text = "Dès maintenant, je ferai également des rondes nocturnes quotidiennes pour m'assurer qu'il ne se produise aucun incident pendant les vacances."
  },
  AvgCommunicate_84107_Content_14 = {
    Text = "Gardien du Secret, nous en parlerons plus tard. Je dois aller travailler."
  },
  AvgCommunicate_84107_Content_2 = {
    Text = "...Les vacances ne viennent-elles pas de commencer ?"
  },
  AvgCommunicate_84107_Content_4 = {
    Text = "Je me prépare simplement pour la suite."
  },
  AvgCommunicate_84107_Content_5 = {
    Text = "La carte de l'académie a été mise à jour, l'horloge a été calibrée et les drapeaux ainsi que les mâts ont également été nettoyés."
  },
  AvgCommunicate_84107_Content_6 = {
    Text = "Chaque jour qui vient, je continuerai l'entretien pour m'assurer de pouvoir commencer à travailler à tout moment."
  },
  AvgCommunicate_84107_Content_7 = {
    Text = "...Juste la gestion du trafic à la pause déjeuner à l'Académie des指挥, il faut vraiment autant de préparatifs ?"
  },
  AvgCommunicate_84107_Content_8 = {
    Text = "Bien sûr. Le choix de la cantine la plus populaire, le nombre d'élèves dans chaque académie, ainsi que les étudiants souhaitant se rendre à la cantine en priorité influenceront l'ensemble de la planification de l'itinéraire."
  },
  AvgCommunicate_84107_Content_9 = {
    Text = "...quelle autre plate-bande a été adoptée par les nouveaux chats errants comme lieu de vie, quelle zone a vu les étudiants y tracer un nouveau chemin, quelle route nécessite des travaux de maintenance..."
  },
  AvgCommunicate_84107_Option_11 = {
    Text = "……Compris."
  },
  AvgCommunicate_84107_Option_2 = {
    Text = "...Les vacances ne viennent-elles pas de commencer ?"
  },
  AvgCommunicate_84107_Option_7 = {
    Text = "Juste la gestion du trafic à la pause déjeuner à l'Académie des指挥..."
  },
  AvgCommunicate_84108_Content_1 = {
    Text = "Gardien, je suis sincèrement désolée pour le dernier incident."
  },
  AvgCommunicate_84108_Content_10 = {
    Text = "Mais ici, ce n'est pas la mer après tout, alors j'ai fait des ajustements en fonction de la situation."
  },
  AvgCommunicate_84108_Content_11 = {
    Text = "L'ajustement en question ne va quand même pas nous attacher ensemble, toi et moi..."
  },
  AvgCommunicate_84108_Content_12 = {
    Text = "Si. De cette façon, si je rencontre le moindre problème, vous pourrez le détecter et intervenir immédiatement."
  },
  AvgCommunicate_84108_Content_13 = {
    Text = "......Puis-je refuser ?"
  },
  AvgCommunicate_84108_Content_14 = {
    Text = "Tu peux certainement refuser."
  },
  AvgCommunicate_84108_Content_15 = {
    Text = "Mais je suis déjà arrivé devant la porte."
  },
  AvgCommunicate_84108_Content_2 = {
    Text = "......Tu fais référence à l'incident du feu de Saint-Elme causé par l'insomnie ?"
  },
  AvgCommunicate_84108_Content_3 = {
    Text = "Bien que Fondu·Dole m'ait assommé à temps, je ressens néanmoins un profond sentiment de culpabilité."
  },
  AvgCommunicate_84108_Content_4 = {
    Text = "J'y ai longuement réfléchi et j'ai estimé que je devais être punie."
  },
  AvgCommunicate_84108_Content_5 = {
    Text = "Ce n'est pas nécessaire. Le dernier incident n'a pas eu de conséquences graves."
  },
  AvgCommunicate_84108_Content_6 = {
    Text = "Non, si on commet une faute, on doit être puni. C'est la règle."
  },
  AvgCommunicate_84108_Content_7 = {
    Text = "Je me suis menottée d'un côté, et l'autre côté nécessite votre coopération."
  },
  AvgCommunicate_84108_Content_8 = {
    Text = "Ma coopération ?"
  },
  AvgCommunicate_84108_Content_9 = {
    Text = "En général, les contrevenants sur le navire sont entravés aux jambes et exposés au soleil sur le pont pendant plusieurs heures."
  },
  AvgCommunicate_84108_Option_11 = {
    Text = "L'ajustement en question ne va quand même pas..."
  },
  AvgCommunicate_84108_Option_13 = {
    Text = "......Puis-je refuser ?"
  },
  AvgCommunicate_84108_Option_2 = {
    Text = "Vous voulez dire..."
  },
  AvgCommunicate_84108_Option_5 = {
    Text = "Ce n'est pas nécessaire."
  },
  AvgCommunicate_84108_Option_8 = {
    Text = "Ma coopération ?"
  },
  AvgCommunicate_84109_Content_1 = {
    Text = "Gardien, merci."
  },
  AvgCommunicate_84109_Content_10 = {Text = "新增"},
  AvgCommunicate_84109_Content_11 = {Text = "En fait..."},
  AvgCommunicate_84109_Content_12 = {
    Text = "En fait ? Pourquoi bégayez-vous soudainement en parlant, ce n'est pas comme vous."
  },
  AvgCommunicate_84109_Content_13 = {
    Text = "En fait, vous n'avez pas besoin de visiter le musée maritime ; un peu de \"détente\" devrait suffire."
  },
  AvgCommunicate_84109_Content_14 = {
    Text = "Bien que je ne comprenne pas ce que tu entends par \"relaxation\" normale, je me sens calme lorsque je suis avec toi."
  },
  AvgCommunicate_84109_Content_15 = {
    Text = "On a l'impression d'être dans une mer calme, sans tempêtes, et sans rencontrer de tempêtes, juste en suivant le cap, nous pouvons atteindre notre destination en toute sécurité."
  },
  AvgCommunicate_84109_Content_16 = {
    Text = "......Bien que cette métaphore soit difficile à comprendre, je comprends à peu près ce que tu veux dire."
  },
  AvgCommunicate_84109_Content_17 = {
    Text = "À l'avenir, nous pourrons explorer différents endroits. Ce monde est vaste, au-delà des océans, il y a de nombreux paysages magnifiques."
  },
  AvgCommunicate_84109_Content_18 = {
    Text = "......Je comprends. J'essaierai."
  },
  AvgCommunicate_84109_Content_19 = {
    Text = "Regarde... le paysage magnifique qui est différent de l'océan."
  },
  AvgCommunicate_84109_Content_2 = {
    Text = "Pourquoi exprimer soudainement de la gratitude ?"
  },
  AvgCommunicate_84109_Content_3 = {
    Text = "Lors de ce voyage au Musée Maritime de Londres, j'ai beaucoup appris."
  },
  AvgCommunicate_84109_Content_4 = {
    Text = "Les horloges maritimes exposées, les cartes nautiques dessinées à la main et les fragments de journaux de navigation contribuent tous à l'amélioration des compétences en navigation."
  },
  AvgCommunicate_84109_Content_5 = {
    Text = "Je mettrai tout cela à profit lors du prochain voyage, en veillant à ce que tout le monde retourne sain et sauf au port."
  },
  AvgCommunicate_84109_Content_6 = {
    Text = "Je me souviens que le but d'aller au Musée maritime de Londres ce jour-là était de \"se détendre\"..."
  },
  AvgCommunicate_84109_Content_7 = {
    Text = "Oublie ça, tant que tu es heureux."
  },
  AvgCommunicate_84109_Content_8 = {
    Text = "Oui, je suis très heureux, et j'espère sortir souvent et me détendre avec toi à l'avenir."
  },
  AvgCommunicate_84109_Content_9 = {
    Text = "Pas de problème, je vérifierai quels musées maritimes à Londres je peux visiter."
  },
  AvgCommunicate_84109_Option_12 = {Text = "En fait ?"},
  AvgCommunicate_84109_Option_16 = {
    Text = "......Quelle métaphore complexe"
  },
  AvgCommunicate_84109_Option_2 = {
    Text = "Pourquoi exprimer soudainement de la gratitude ?"
  },
  AvgCommunicate_84109_Option_6 = {Text = "...?"},
  AvgCommunicate_84109_Option_9 = {
    Text = "Pas de problème"
  },
  AvgCommunicate_84110_Content_1 = {
    Text = "Pourriez-vous m'envoyer le prochain lot de fournitures en caféine à l'avance, Gardien ?"
  },
  AvgCommunicate_84110_Content_10 = {
    Text = "Attendez, comment cela pourrait-il devenir plus absurde !"
  },
  AvgCommunicate_84110_Content_11 = {
    Text = "Où est Winkle maintenant ?"
  },
  AvgCommunicate_84110_Content_12 = {
    Text = "Juste ici, réalisant des expériences sur le dispositif de conduction, testant si l'énergie de @2<AvgCommunicateConfuseColor.Lumière> peut être transformée en énergie lumineuse."
  },
  AvgCommunicate_84110_Content_13 = {
    Text = "Pourquoi ne refuses-tu pas ?"
  },
  AvgCommunicate_84110_Content_14 = {
    Text = "Pourquoi refuser ? Servir les passagers fait partie de mes devoirs."
  },
  AvgCommunicate_84110_Content_15 = {Text = "新增"},
  AvgCommunicate_84110_Content_16 = {
    Text = "J'y vais maintenant. Tiens le Bigorneau pour moi."
  },
  AvgCommunicate_84110_Content_17 = {
    Text = "Reçu, juré d'exécuter ton ordre."
  },
  AvgCommunicate_84110_Content_2 = {
    Text = "Vos provisions ont également été prises par un Bigorneau ?"
  },
  AvgCommunicate_84110_Content_3 = {
    Text = "Pour être précis, ce n'était pas \"pris\", mais plutôt je l'ai donné à ce passager."
  },
  AvgCommunicate_84110_Content_4 = {
    Text = "......Encore une fois avec la raison de \"Je rejoindrai le voyage la prochaine fois\" ?"
  },
  AvgCommunicate_84110_Content_5 = {
    Text = "Je m'acquitte simplement de mes devoirs. Servir les passagers fait également partie de mes responsabilités."
  },
  AvgCommunicate_84110_Content_6 = {
    Text = "......La demande de fournitures a été approuvée. C'est la dernière fois."
  },
  AvgCommunicate_84110_Content_7 = {
    Text = "Au fait, est-ce que Winkle essaie encore d'extraire le @2 de ta poitrine récemment ?"
  },
  AvgCommunicate_84110_Content_8 = {
    Text = "Plus maintenant ; ce passager a changé la façon dont la recherche est menée."
  },
  AvgCommunicate_84110_Content_9 = {
    Text = "Par exemple, tester l'intensité de @2<AvgCommunicateConfuseColor.Light> avec un milliampèremètre, scanner les lignes spectrales de @2<AvgCommunicateConfuseColor.Light> avec un prisme, utiliser une plateforme de test humain pour vérifier la connexion de @2<AvgCommunicateConfuseColor.Light> avec les fibres nerveuses..."
  },
  AvgCommunicate_84110_Option_10 = {
    Text = "Attendez, comment cela pourrait-il devenir plus absurde !"
  },
  AvgCommunicate_84110_Option_13 = {
    Text = "Pourquoi ne refuses-tu pas ?"
  },
  AvgCommunicate_84110_Option_15 = {Text = "新增"},
  AvgCommunicate_84110_Option_2 = {
    Text = "Vos provisions ont également été prises par un Bigorneau ?"
  },
  AvgCommunicate_84110_Option_4 = {
    Text = "Encore une fois, c'est à cause de..."
  },
  AvgCommunicate_84110_Option_6 = {
    Text = "La demande d'approvisionnement a été approuvée..."
  },
  AvgCommunicate_94500_Content_1 = {
    Text = "Merci à votre introduction, après avoir rencontré Lord Ogier, il nous a présenté à plus d'amis."
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "Seigneur Ogier a également mentionné que l'entraînement des chevaliers est encore plus complexe et fastidieux que cela, il semble que comme indiqué dans les livres, chaque chevalier soit effectivement une personne digne de respect."
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "Oui, Ogier est certainement le plus assidu dans l'entraînement parmi les Réveillés !"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "Nous avons également découvert qu'en dépit d'un handicap, l'instructeur Alva fait le même entraînement que nous."
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "Nous pensions à l'origine que l'instructeur Alva était aussi un chevalier, mais elle a dit qu'elle avait été soldat. Je ne sais pas quel genre de profession est celle d'un soldat, mais cela doit être tout aussi respectable que celle d'un chevalier."
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "Les soldats sont ceux qui se battent pour le pays, ce qui peut également être considéré comme un type de chevalier ; cependant, comparé aux stricts codes moraux des chevaliers, les actions des soldats ne représentent pas nécessairement la justice."
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "Alva ne s'en est rendu compte qu'après avoir quitté l'armée ; peut-être que la vie maintenant est plus confortable pour elle."
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "Je comprends, ce que tu veux dire, c'est qu'un chevalier ne représente pas le pouvoir, mais un esprit de justice, comme l'instructeur Alva et les gens justes comme toi, tous possèdent l'âme d'un chevalier."
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "Bien que vous ayez très bien parlé, c'est assez embarrassant..."
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "C'est une bonne nouvelle ; je suis vraiment heureux pour vous."
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "Nous avons déjà rencontré de nombreux Éveillés, et effectivement, comme vous l'avez dit, la plupart d'entre eux sont des personnes bienveillantes."
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "J'ai honte en repensant à mon arrivée ici, j'éprouvais souvent des doutes suspicieux envers les autres."
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "En fait, ce n'est pas si mal car il y a beaucoup de gens qui méritent de la prudence..."
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "Maintenant je suis avec Castor, assistant au cours de formation de l'Instructeur Alva avec Lord Ogier"
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "La posture de combat du Seigneur Ogier est vraiment éblouissante, mais lui-même semble peu accoutumé aux éloges, quelle personne humble."
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "Ha ha, l'Ogier est juste facile à éviter, il suffit de lui parler normalement."
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "Il s'est avéré que Castor et moi n'avons jamais reçu d'entraînement au combat à l'église ; un tel entraînement intensif est vraiment difficile, pourtant Lord Ogier dit qu'il le fait tous les jours ; quelle grande persévérance."
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "En effet, Ogier est le réveilleur le plus assidu en entraînement !"
  },
  AvgCommunicate_94500_Option_14 = {
    Text = "Je suppose..."
  },
  AvgCommunicate_94500_Option_2 = {
    Text = "C'est une bonne nouvelle ; je suis vraiment heureux pour vous."
  },
  AvgCommunicate_94500_Option_5 = {
    Text = "En fait, ce n'est pas si mal car il y a beaucoup de gens qui méritent de la prudence..."
  },
  AvgCommunicate_94500_Option_8 = {
    Text = "Ogier est simplement facilement timide."
  },
  AvgCommunicate_94501_Content_1 = {
    Text = "Monsieur respectueux, merci d'avoir préparé un abri pour moi et Castor."
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "Ce gars, Castor, aimait se laver cinq fois par jour, mais après que je l'ai arrêté, cela s'est transformé en trois fois par jour."
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "Se laver le visage trop souvent peut causer des dommages !!"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "Mais vous n'avez jamais utilisé ce genre de choses auparavant ? Je n'aurais pas pensé que l'église de la lumière du temple soit aussi avare."
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "En effet non, mais pas parce que l'église est avare, mais en tant que Fils, nous avons toujours été tenus de réfréner nos désirs et de nous concentrer sur la pratique."
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "Nous avons à peine été en contact avec ces produits technologiques, et il y a de nombreuses règles concernant notre vie quotidienne et nos repas."
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "Bien que les vêtements et la nourriture soient généralement luxueux, on ne peut manger qu'aux heures des repas, et il faut quitter les dortoirs une fois qu'il est temps de se lever."
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "Enfant, j'imaginais souvent quand je pourrais arrêter de me lever tôt et manger tout ce que je voulais toute la journée."
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "Ces jours-ci, j'ai vu à plusieurs reprises une jeune fille portant de la nourriture passer l'après-midi ; il semble que la vie dont je rêvais ici soit déjà devenue routine."
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "Ah, il est probable que Murphy soit allé chercher les petits gâteaux... en effet, ta vie semble vraiment fatigante."
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "J'ai entendu Castor dire qu'un lit avait été spécialement ajouté à la maison, donc je savais que cela devait être votre initiative."
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "Tout est passé, ces erreurs et distorsions resteront dans le passé. Nous allons emprunter le bon chemin avec un tout nouvel aspect, veuillez être témoin."
  },
  AvgCommunicate_94501_Content_21 = {
    Text = "Ne soyez pas si poli, si vous avez des questions, n'hésitez pas à me demander. Votre attitude est déjà des dizaines de fois plus rassurante que certains éveillés !"
  },
  AvgCommunicate_94501_Content_3 = {
    Text = "Nous avons l'habitude de vivre ensemble dans le palais depuis notre jeunesse, et entendre que les quartiers de sommeil ici nécessitent une chambre par personne nous inquiète toujours."
  },
  AvgCommunicate_94501_Content_4 = {
    Text = "En voyant que vous considérez soigneusement pour nous maintenant, je réalise vraiment que la suggestion de Dame Thais de chercher refuge auprès de vous à l'époque était correcte."
  },
  AvgCommunicate_94501_Content_5 = {
    Text = "Ha, ce n'est rien, êtes-vous tous à l'aise ici après être venus ?"
  },
  AvgCommunicate_94501_Content_6 = {
    Text = "Merci à votre soin, tout va bien. Bien que le palais ici soit aussi petit que la chambre d'une demoiselle, il est complètement meublé et après adaptation, il est assez chaleureux."
  },
  AvgCommunicate_94501_Content_7 = {
    Text = "Ahaha, est-ce vrai, alors c'est bon, c'est bon..."
  },
  AvgCommunicate_94501_Content_8 = {
    Text = "Nous avons lentement appris à vivre sans être servis ; vous n'avez pas besoin de vous inquiéter pour nous. En fait, c'est quelque chose que nous avons tous les deux rêvé pendant des années."
  },
  AvgCommunicate_94501_Content_9 = {
    Text = "Surtout le nettoyant pour le visage fourni dans la chambre est vraiment magique. Après l'avoir utilisé selon les instructions, il produit de nombreuses bulles ressemblant à des nuages, et le goût de ce dentifrice est également très rafraîchissant."
  },
  AvgCommunicate_94501_Option_19 = {
    Text = "Ah, il est probable que Murphy soit allé chercher les petits gâteaux..."
  },
  AvgCommunicate_94501_Option_21 = {Text = "Trop poli."},
  AvgCommunicate_94501_Option_5 = {
    Text = "Pas d'inquiétude, pas d'inquiétude."
  },
  AvgCommunicate_94501_Option_7 = {
    Text = "Ahaha, est-ce vrai, alors c'est bon, c'est bon..."
  },
  AvgCommunicate_94502_Content_1 = {
    Text = "Je m'excuse pour l'intrusion, mais pourriez-vous nous donner une brève introduction..."
  },
  AvgCommunicate_94502_Content_10 = {
    Text = "Oh ! Ça devrait être Ogier et Lotan."
  },
  AvgCommunicate_94502_Content_11 = {
    Text = "Ogier... J'ai noté ce nom, cette attitude jeune est droite et héroïque, faisant battre nos cœurs. Castor et moi voulions initialement avancer, mais ils sont rapidement passés et partis."
  },
  AvgCommunicate_94502_Content_12 = {
    Text = "Après être retournés au dortoir, nous avons tourné et retourné, voulant vraiment rencontrer ce chevalier, mais ne sachant pas par où commencer, nous sommes donc venus demander votre introduction, espérant que vous pourriez consacrer du temps et des efforts pour faciliter notre rencontre."
  },
  AvgCommunicate_94502_Content_13 = {
    Text = "Je comprends ; en fait, tu n'as pas besoin d'être si poli. Ogier est une personne très chaleureuse ; tant que tu parles, il sera très heureux de se faire des amis avec toi."
  },
  AvgCommunicate_94502_Content_14 = {
    Text = "Vraiment admirable en tant que véritable chevalier, cette ouverture d'esprit est louable, prête à nous accepter, nous qui étions autrefois ennemis."
  },
  AvgCommunicate_94502_Content_15 = {
    Text = "Non, non, cela n'a rien à voir avec être ouvert d'esprit ! C'est comme ça que les gens normaux se font des amis !"
  },
  AvgCommunicate_94502_Content_16 = {
    Text = "Bien que tous les Éveillés ne soient pas des personnes ordinaires... la plupart d'entre eux ici sont tout de même très sympathiques. Vous pouvez donc interagir librement et normalement."
  },
  AvgCommunicate_94502_Content_17 = {
    Text = "Je m'excuse, pourriez-vous m'éclairer, qu'est-ce que... la communication normale ?"
  },
  AvgCommunicate_94502_Content_19 = {
    Text = "Je comprends, laisse-moi te dire le secret pour se faire des amis !"
  },
  AvgCommunicate_94502_Content_2 = {
    Text = "Depuis que vous avez suggéré que nous nous fassions plus d'amis, Castor et moi avons souvent traîné dans des endroits animés."
  },
  AvgCommunicate_94502_Content_20 = {
    Text = "C'est de l'initiative ! La sincérité et l'initiative sont les plus émouvantes !"
  },
  AvgCommunicate_94502_Content_21 = {
    Text = "Souviens-toi, tu pourrais être rejetée ou trompée, mais c'est le problème de ceux qui te nuisent ; ne doute jamais que la sincérité est fausse."
  },
  AvgCommunicate_94502_Content_22 = {
    Text = "Entraîne un cœur fort, puis vis courageusement l'amitié !"
